// Dida Master v1.1.0：文字型 Applied / Selected 入口共用唯一 Indicator Label Primitive。
// 业务 button 只拥有状态；指示线只由 label 的 CSS Owner 绘制。
export function setIndicatorLabel(button, text) {
    if (!isDomHTMLElement(button)) return null;
    let label = button.querySelector(":scope > .ui-indicator-label");
    if (!label) label = button.createSpan({ cls: "ui-indicator-label" });
    label.setText(String(text ?? ""));
    return label;
}

// 结果名称与路径共用同一排序合同；不在 O(N log N) 比较热路径反复建立 locale/options。
export const RESULT_TEXT_COLLATOR = new Intl.Collator("zh-Hans-CN", {
    numeric: true,
    sensitivity: "base"
});

/*
 * ===== Master Template Boundary =====
 * Foundation：纯函数、状态 Primitive、Picker / Dialog / Sort / Swipe / Virtual List、
 * 生命周期与设置规范化。Foundation 不读取具体搜索视图的局部 DOM 状态。
 * Search Domain：Query / Filter / Facet / Result / Create / Selection，只组合 Foundation；
 * 同一能力不得在业务 Controller 内复制第二套实现。单文件只是交付形态。
 */

// 结果列表采用“可见区 + 缓冲区”的动态窗口化 DOM。
// 挂载数量只由 viewport / 当前行高估算决定，不再固定 16 张；
// 极端超高视口优先保证完整覆盖可见区，安全上限只约束额外缓冲。
export const RESULT_WINDOW_MOUNT_MIN = 12;

// 完整 Markdown 正文只服务当前可见结果的摘要回填，不再承担索引缓存职责。
// 两个最大虚拟窗口覆盖常见双宿主工作集；其它视图按同一 LRU 上限淘汰；
// BodyIndex 继续保存搜索所需的净化正文，避免全库完整正文常驻内存。
export const FULL_CONTENT_CACHE_LIMIT = RESULT_WINDOW_MOUNT_MAX * 2;

// 可变高度虚拟列表只保存“已测量行相对基准高度的差值”。
// 未测量行继续使用同一视图的稳定估算值；Fenwick 前缀高度为 O(log n)，
// scrollTop → position 使用 Fenwick binary lifting 为 O(log n)，不做按行扫描。
export class SparseHeightIndex {
    constructor() {
        this.reset(0, RESULT_ROW_HEIGHT_ESTIMATE);
    }

    reset(size, estimate = RESULT_ROW_HEIGHT_ESTIMATE) {
        this.size = Math.max(0, Number(size) || 0);
        this.estimate = Math.max(1, Number(estimate) || RESULT_ROW_HEIGHT_ESTIMATE);
        this.tree = new Float64Array(this.size + 1);
        this.measured = new Map();
    }

    _add(index, delta) {
        for (let i = index + 1; i <= this.size; i += i & -i) {
            this.tree[i] += delta;
        }
    }

    set(index, height) {
        if (!Number.isInteger(index) || index < 0 || index >= this.size) return false;
        const next = Math.max(1, Number(height) || this.estimate);
        const previous = this.measured.has(index)
            ? this.measured.get(index)
            : this.estimate;
        if (Math.abs(next - previous) < 0.5) return false;
        this.measured.set(index, next);
        this._add(index, next - previous);
        return true;
    }

    rebaseEstimate(estimate) {
        const next = Math.max(1, Number(estimate) || RESULT_ROW_HEIGHT_ESTIMATE);
        if (Math.abs(next - this.estimate) < 0.5) return false;
        this.estimate = next;
        this.tree = new Float64Array(this.size + 1);
        for (const [index, height] of this.measured) {
            this._add(index, height - next);
        }
        return true;
    }

    _deltaPrefix(count) {
        let sum = 0;
        for (let i = Math.max(0, Math.min(this.size, Number(count) || 0)); i > 0; i -= i & -i) {
            sum += this.tree[i];
        }
        return sum;
    }

    prefix(count) {
        const n = Math.max(0, Math.min(this.size, Number(count) || 0));
        return n * this.estimate + this._deltaPrefix(n);
    }

    total() {
        return this.prefix(this.size);
    }

    positionAt(offset) {
        if (!this.size) return -1;
        const target = Math.max(0, Math.min(this.total() - 1, Number(offset) || 0));
        // Dida Master：Fenwick binary lifting 直接定位前缀位置，O(log n)。
        // 不再对 prefix() 做外层二分，滚动热路径由 O(log² n) 收口为 O(log n)。
        let index = 0;
        let sum = 0;
        let step = 1;
        while (step * 2 <= this.size) step *= 2;
        for (; step >= 1; step = Math.floor(step / 2)) {
            const next = index + step;
            if (next > this.size) continue;
            const value = sum + this.tree[next] + step * this.estimate;
            if (value <= target) {
                index = next;
                sum = value;
            }
        }
        return Math.min(index, this.size - 1);
    }
}

export const SORT_FIELD_DEFS = Object.freeze({
    relevance: { label: "最佳匹配", icon: "sparkles" },
    opened: { label: "最近打开", icon: "history" },
    created: { label: "创建时间", icon: "calendar-plus" },
    contentModified: { label: "正文修改", icon: "file-clock" },
    fileModified: { label: "文件修改", icon: "clock-3" },
    name: { label: "文件名称", icon: "type" }
});

export function normalizeSortFieldOrder(value) {
    const allowed = new Set(SORT_FIELD_IDS);
    const ordered = normalizeUniqueStringList(value)
        .filter(id => allowed.has(id));
    const seen = new Set(ordered);
    for (const id of DEFAULT_SORT_FIELD_ORDER) {
        if (!seen.has(id)) {
            seen.add(id);
            ordered.push(id);
        }
    }
    return ordered;
}

export function normalizeHiddenSortFields(value, order = DEFAULT_SORT_FIELD_ORDER) {
    const allowed = new Set(SORT_FIELD_IDS);
    const hidden = new Set(
        normalizeUniqueStringList(value).filter(id => allowed.has(id))
    );

    // 空搜索至少保留一个真实排序字段；避免用户把全部字段关闭后形成无排序状态。
    const nonQueryFields = normalizeSortFieldOrder(order)
        .filter(id => id !== "relevance");
    if (nonQueryFields.length && nonQueryFields.every(id => hidden.has(id))) {
        hidden.delete(nonQueryFields[0]);
    }
    return [...hidden];
}

export function selectableSortFieldsForQuery(hasQuery, settings = null) {
    return normalizeSortFieldOrder(settings?.resultSortOrder)
        .filter(id => Boolean(hasQuery) || id !== "relevance");
}

// 快捷循环只消费 View Composer 中 eye 开启的字段；
// 全量 Picker 仍可直接选择 eye 关闭的字段，因此“当前字段有效性”不能再由循环成员决定。
export function sortFieldsForQuery(hasQuery, settings = null) {
    const order = normalizeSortFieldOrder(settings?.resultSortOrder);
    const hidden = new Set(
        normalizeHiddenSortFields(
            settings?.hiddenResultSortFields,
            order
        )
    );
    return order.filter(id =>
        !hidden.has(id)
        && (Boolean(hasQuery) || id !== "relevance")
    );
}

export function normalizeSortDirection(value) {
    return value === "asc" ? "asc" : "desc";
}

export function defaultSortField(hasQuery, settings = null) {
    return sortFieldsForQuery(Boolean(hasQuery), settings)[0]
        || (hasQuery ? "relevance" : "opened");
}

export function normalizeSortField(value, hasQuery, settings = null) {
    const fields = selectableSortFieldsForQuery(Boolean(hasQuery), settings);
    return fields.includes(value)
        ? value
        : defaultSortField(Boolean(hasQuery), settings);
}

export function migrateLegacySortState(value, hasQuery = false) {
    if (value === "name-asc") return { field: "name", direction: "asc" };
    if (value === "name-desc") return { field: "name", direction: "desc" };
    if (value === "opened") return { field: "opened", direction: "desc" };
    if (value === "modified") return { field: "contentModified", direction: "desc" };
    return { field: defaultSortField(Boolean(hasQuery)), direction: "desc" };
}

export function normalizeModalSearchQuery(value) {
    return String(value ?? "");
}

export function normalizeModalViewportAnchor(value, legacyScrollTop = 0) {
    const source = value && typeof value === "object" ? value : {};
    const path = String(source.path || "").trim();
    const fallbackPath = String(source.fallbackPath || "").trim();
    const rawOffset = Number(source.offset);
    const rawFallbackOffset = Number(source.fallbackOffset);
    const scrollTop = Math.max(
        0,
        Math.round(Number(source.scrollTop ?? legacyScrollTop) || 0)
    );

    const anchor = {
        path,
        offset: Number.isFinite(rawOffset) ? rawOffset : 0,
        fallbackPath,
        fallbackOffset: Number.isFinite(rawFallbackOffset)
            ? rawFallbackOffset
            : 0,
        scrollTop
    };

    return anchor.path || anchor.fallbackPath || anchor.scrollTop > 0
        ? anchor
        : null;
}

export const GLS_MANAGED_TIME_KEYS = new Set([
    "gls_created_at", "gls_created_source", "gls_body_modified_at", "gls_body_fingerprint",
    "gls_file_modified_at", "gls_file_fingerprint"
]);

export function indexedFileProperties(frontmatter) {
    const properties = frontmatter && typeof frontmatter === "object" && !Array.isArray(frontmatter)
        ? { ...frontmatter } : {};
    delete properties.position;
    for (const internal of GLS_MANAGED_TIME_KEYS) {
        delete properties[internal];
    }
    return properties;
}

// “正文修改时间”只排除文件头部 YAML frontmatter；
// 正文里的标签、格式、空白、代码、Callout 等都属于真实正文变化。
// 这里不复用摘要净化逻辑，避免把用户实际编辑的格式变化误判成“正文未变”。
export function markdownBodyForContentTracking(content) {
    let text = String(content || "")
        .replace(/^\uFEFF/, "")
        .replace(/\r\n?/g, "\n");

    return text.replace(
        /^---[ \t]*\n(?:[\s\S]*?\n)?---[ \t]*(?:\n|$)/,
        ""
    );
}

// 轻量 53-bit 风格双 32-bit 指纹；非加密用途，只用于判断同一文件正文是否变化。
// length 一并进入结果，进一步降低碰撞概率。
export function fastContentFingerprint(text) {
    const source = String(text || "");
    let h1 = 0xdeadbeef ^ source.length;
    let h2 = 0x41c6ce57 ^ source.length;

    for (let i = 0; i < source.length; i++) {
        const ch = source.charCodeAt(i);
        h1 = Math.imul(h1 ^ ch, 2654435761);
        h2 = Math.imul(h2 ^ ch, 1597334677);
    }

    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507)
        ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507)
        ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);

    return `${source.length}:${
        (h2 >>> 0).toString(36)
    }:${
        (h1 >>> 0).toString(36)
    }`;
}

export function markdownBodyFingerprint(content) {
    return fastContentFingerprint(
        markdownBodyForContentTracking(content)
    );
}

// 排除 GLS 自身时间字段；普通属性按值比较，YAML 重排/时间补写不制造业务修改。
export function stableTimeProperties(value, stack = new Set()) {
    if (!value || typeof value !== "object") return JSON.stringify(value) ?? "null";
    try { return JSON.stringify(new Date(Date.prototype.getTime.call(value)).toISOString()); } catch (_) {}
    if (stack.has(value)) throw new Error("时间属性不支持循环 YAML");
    stack.add(value);
    const result = Array.isArray(value)
        ? `[${value.map(item => stableTimeProperties(item, stack)).join(",")}]`
        : `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${stableTimeProperties(value[key], stack)}`).join(",")}}`;
    stack.delete(value);
    return result;
}

export function markdownTimePayload(content) {
    const text = String(content ?? "").replace(/^\uFEFF/, "");
    const header = /^---[ \t]*\r?\n(?:([\s\S]*?)\r?\n)?---[ \t]*(?=\r?\n|$)/.exec(text);
    // 非法 YAML 不可当成“没有时间”，保留上一份有效记录等下次成功读取。
    const parsed = header ? parseYaml(header[1] || "") : {};
    const frontmatter = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
    const fingerprint = markdownBodyFingerprint(content);
    const fileFingerprint = fastContentFingerprint(fingerprint + "\n" + stableTimeProperties(indexedFileProperties(frontmatter)));
    return { frontmatter, fingerprint, fileFingerprint };
}

export function binaryTimeFingerprint(data) {
    const bytes = new Uint8Array(data);
    let a = 0x811c9dc5, b = 0x01000193;
    for (const value of bytes) {
        a = Math.imul(a ^ value, 16777619);
        b = Math.imul(b ^ value, 2246822519);
    }
    return `${bytes.length}:${(a >>> 0).toString(36)}:${(b >>> 0).toString(36)}`;
}

// 一个时间决策用于正文与整个文件：有效同步记录可读，本机实写可更新；观察到达不造时钟。
export function resolveTrackedModification({ fingerprint, previousFingerprint, previousAt, previousSource,
    storedFingerprint, storedAt, localAt, initialAt }) {
    const prior = parseGLSDate(previousAt), stored = parseGLSDate(storedAt);
    const changed = Boolean(fingerprint && previousFingerprint && fingerprint !== previousFingerprint);
    const matches = Boolean(fingerprint && storedFingerprint === fingerprint && stored);
    if (parseGLSDate(localAt) && changed) {
        if (matches && stored > prior) return { at: stored, source: "file-yaml" };
        return { at: localAt, source: "local-edit" };
    }
    if (matches && (!prior || !previousSource || stored >= prior)) return { at: stored, source: "file-yaml" };
    if (prior) return { at: prior, source: previousSource || "stored-history" };
    return { at: stored || parseGLSDate(initialAt), source: stored ? "file-yaml" : "initial-value" };
}

// 只允许仓库内普通文件夹：不接受绝对路径、上级跳转或 .obsidian 配置目录。
// 路径在真正写入前再次验证；不允许把元数据放在被 GLS 搜索的业务目录根层。
export function parseGLSDate(value) {
    let parsed = 0;
    if (typeof value === "number") parsed = value;
    else if (typeof value === "string" && value.trim()) parsed = Date.parse(value);
    else if (value && typeof value === "object") {
        try { parsed = Date.prototype.getTime.call(value); } catch (_) { return 0; }
    }
    return Number.isFinite(parsed) && parsed > 0 && parsed <= 8640000000000000 ? parsed : 0;
}

export function isGLSTimeSidecarPath(path) {
    return /(?:^|\/)(?:(?:recent-opened-|content-times-|file-times-)[a-zA-Z0-9_-]+|content-time-cache)\.json$/.test(String(path || ""));
}

export function normalizeGLSMetadataDirectory(rawPath) {
    const raw = String(rawPath || "").trim().replace(/\\/g, "/");
    if (!raw || raw.startsWith("/") || /^[a-z]:\//i.test(raw)
        || /[<>:\"|?*\x00-\x1f]/.test(raw)) return null;
    const parts = raw.split("/");
    if (parts.some(part => !part.trim() || part === "." || part === ".." || part.startsWith("."))) return null;
    const result = parts.join("/");
    if (parts[0].toLowerCase() === ".obsidian" || parts[0] === ".") return null;
    return result;
}

 // Excalidraw _绘图.md 命名与类型识别统一，重建旧显示名称缓存。

// Obsidian 标准属性类型；新增属性时统一从这里生成类型选择。
export const PROPERTY_TYPE_OPTIONS = Object.freeze([
    { value: "text", label: "文本" },
    { value: "multitext", label: "列表" },
    { value: "number", label: "数字" },
    { value: "checkbox", label: "复选框" },
    { value: "date", label: "日期" },
    { value: "datetime", label: "日期和时间" }
]);

export function normalizeMetadataPropertyType(type) {
    const value = String(type || "").toLowerCase();
    if (["multitext", "list", "tags", "aliases"].includes(value)) return "multitext";
    if (value === "number") return "number";
    if (value === "checkbox" || value === "boolean") return "checkbox";
    if (value === "date") return "date";
    if (value === "datetime" || value === "date-time") return "datetime";
    return "text";
}

export function metadataPropertySample(source, key) {
    for (const meta of source || []) {
        if (!Object.prototype.hasOwnProperty.call(meta?.properties || {}, key)) continue;
        return meta.properties[key];
    }
    return undefined;
}

export function resolveMetadataPropertyType(app, key, sample, fallbackType = "") {
    const manager = app?.metadataTypeManager;
    try {
        const info = typeof manager?.getPropertyInfo === "function"
            ? manager.getPropertyInfo(key)
            : null;
        const registered = info?.widget || info?.type;
        if (registered) return normalizeMetadataPropertyType(registered);

        const assigned = typeof manager?.getAssignedWidget === "function"
            ? manager.getAssignedWidget(key)
            : null;
        if (assigned) return normalizeMetadataPropertyType(assigned);
    } catch (_) {}

    if (fallbackType) return normalizeMetadataPropertyType(fallbackType);
    if (Array.isArray(sample)) return "multitext";
    if (typeof sample === "number") return "number";
    if (typeof sample === "boolean") return "checkbox";
    return "text";
}

export function metadataPropertyValuePlaceholder(type) {
    const normalized = normalizeMetadataPropertyType(type);
    if (normalized === "number") return "输入数字";
    if (normalized === "checkbox") return "输入 true 或 false";
    if (normalized === "date") return "输入日期（YYYY-MM-DD）";
    if (normalized === "datetime") return "输入日期和时间";
    return normalized === "multitext" ? "输入列表值" : "输入文本";
}

export function parseMetadataPropertyInput(rawValue, type = "text") {
    const normalized = normalizeMetadataPropertyType(type);
    const input = String(rawValue ?? "").trim();
    if (!input) throw new Error("请输入新的属性值");
    if (normalized === "number") {
        const value = Number(input);
        if (!Number.isFinite(value)) throw new Error("请输入有效数字");
        return value;
    }
    if (normalized === "checkbox") {
        if (!/^(true|false)$/i.test(input)) {
            throw new Error("复选框值只能是 true 或 false");
        }
        return input.toLowerCase() === "true";
    }
    return input;
}

// Only explicitly added standalone options live here. Indexed file properties
// remain authoritative and are never copied into this settings catalog.
export function normalizePropertyValueCatalog(value) {
    const rows = new Map();
    for (const entry of Array.isArray(value) ? value : []) {
        try {
            const key = validateEditablePropertyKey(entry?.key);
            const propertyType = normalizeMetadataPropertyType(entry.propertyType);
            const values = new Map();
            for (const raw of (Array.isArray(entry.values) ? entry.values : []).flat(Infinity)) {
                try {
                    if (raw === null || raw === undefined || typeof raw === "object" || isExclusivePropertySelectionValue(raw)) continue;
                    const parsed = parseMetadataPropertyInput(raw, propertyType);
                    const id = propertyValueKey(parsed);
                    if (!values.has(id)) values.set(id, parsed);
                } catch (_) { /* Invalid recovered options are not selectable. */ }
            }
            if (values.size) rows.set(key, { key, propertyType, values: [...values.values()] });
        } catch (_) { /* Reject reserved/managed keys at the catalog boundary. */ }
    }
    return [...rows.values()].sort((a, b) => a.key.localeCompare(b.key, "zh-Hans-CN", { numeric: true }));
}

export function validateEditablePropertyKey(value, excludedKeys = []) {
    const key = String(value || "").trim();
    if (!key || /[\x00-\x1f\x7f]/.test(key) || ["__proto__", "constructor", "prototype"].includes(key)) {
        throw new Error("请输入有效属性名");
    }
    if (GLS_MANAGED_TIME_KEYS.has(key)) throw new Error("此属性由 GLS 时间记录维护，不能作为普通属性修改");
    if (key.toLocaleLowerCase("zh-CN") === "tags") {
        throw new Error("标签已独立管理，请使用标签入口");
    }
    if (key === "position" || (excludedKeys || []).includes(key)) {
        throw new Error("请输入有效属性名");
    }
    return key;
}

export function normalizeEditableTagValue(value) {
    return String(value || "").replace(/^#+/, "").trim();
}

export function editableTagError(value) {
    const tag = normalizeEditableTagValue(value);
    if (!tag) return "";
    if (/\s/.test(tag)) return "标签不能包含空格";
    if (tag.includes("#")) return "标签中不能包含 #";
    if (tag.startsWith("/") || tag.endsWith("/") || tag.includes("//")) {
        return "标签层级路径无效";
    }
    return "";
}

export function normalizeIntegerSetting(value, fallback, { allowZero = false } = {}) {
    const parsed = Number.parseInt(String(value), 10);
    if (!Number.isFinite(parsed)) return fallback;
    const minimum = allowZero ? 0 : 1;
    return Math.max(minimum, parsed);
}

export function normalizeUniqueStringList(values) {
    const source = Array.isArray(values) ? values : [];
    const seen = new Set();
    const result = [];

    for (const value of source) {
        const key = String(value || "").trim();
        if (!key || seen.has(key)) continue;
        seen.add(key);
        result.push(key);
    }

    return result;
}

// Host Context Primitive：DOM Realm 永远跟随真实宿主节点，而不是插件加载时的主 window。
// 多窗口 / Pop-out / 原生 Tab 共用这一套 document/window/Element 判定；
// 业务层不得直接假定全局 document/window 与当前 Surface 属于同一个 Realm。
export function hostDocument(source = null) {
    if (source?.nodeType === 9) return source;
    if (source?.document?.nodeType === 9) return source.document;
    return source?.ownerDocument || globalThis.document;
}

export function hostWindow(source = null) {
    return hostDocument(source)?.defaultView || globalThis.window;
}

export function activeWorkspaceDocument(app) {
    const leaf = app?.workspace?.activeLeaf;
    const host = leaf?.view?.containerEl || leaf?.containerEl || null;
    return hostDocument(host);
}

export function isDomElement(value) {
    return Boolean(value && value.nodeType === 1);
}

export function isDomHTMLElement(value) {
    return Boolean(
        value
        && value.nodeType === 1
        && value.namespaceURI === "http://www.w3.org/1999/xhtml"
    );
}

export function isDomButton(value) {
    return isDomHTMLElement(value) && value.tagName === "BUTTON";
}

export function isDomInput(value) {
    return isDomHTMLElement(value) && value.tagName === "INPUT";
}

// Dida Master v1.1.0 · Control Interaction Primitive。
// interaction 是静态组件合同，不代表临时按压状态；CSS 只按正式语义消费。
// action: 执行动作；choice: 直接改变值/状态；chrome: 工具栏动作；
// text: 文本型轻动作；field: 元数据字段；tree-hit/tree-toggle: 外层 Tree Row 拥有反馈；
// quiet: 无临时反馈；input: 原生输入控件。
export function initializeSearchInteractionElement(element, interaction) {
    if (!isDomElement(element)) return element;
    element.dataset.lsInteraction = String(interaction || "quiet");
    if (element.tagName === "BUTTON" && !element.hasAttribute("type")) {
        element.setAttribute("type", "button");
    }
    return element;
}

export function createSearchButton(host, interaction, options = {}) {
    const button = host.createEl("button", {
        ...options,
        attr: { type: "button", ...options.attr }
    });
    return initializeSearchInteractionElement(button, interaction);
}

// Native form values share one construction contract; each visual component
// still owns its own geometry / focus surface. No focus listener or state is added here.
export function createSearchInput(host, options = {}) {
    return initializeSearchInteractionElement(
        host.createEl("input", { ...options, attr: { ...options.attr } }),
        "input"
    );
}

// Search Text Field Primitive：主搜索与 Picker 搜索共用唯一 DOM 结构。
// 外层 Field 是唯一 flex 项；真实 input 永远 width:100%，不直接参与兄弟动作区的 flex 尺寸计算。
export function createSearchTextField(host, {
    fieldClass = "",
    inputClass = "",
    ...inputOptions
} = {}) {
    const field = host.createDiv({
        cls: ["local-search-search-field", fieldClass].filter(Boolean).join(" ")
    });
    const input = createSearchInput(field, {
        ...inputOptions,
        cls: ["local-search-search-text-input", inputClass].filter(Boolean).join(" ")
    });
    return { field, input };
}

export function createSearchWindowAction(host, icon, label) {
    const button = createSearchButton(host, "chrome", {
        cls: "local-search-window-action",
        attr: { "aria-label": label }
    });
    setIcon(button, icon);
    return button;
}

// Mouse-only focus guard for controls that continue the same editing session.
// Cancelling touch pointerdown can suppress WebKit's subsequent click entirely;
// native touch/pen activation and text input must retain their default behavior.
export function bindInputFocusGuard(surface, inputOrResolver, {
    selector = "button",
    when = null,
    ignore = null
} = {}) {
    if (!isDomHTMLElement(surface)) return () => {};
    const onPointerDown = event => {
        if (event.pointerType !== "mouse" || event.button > 0) return;
        const input = typeof inputOrResolver === "function"
            ? inputOrResolver()
            : inputOrResolver;
        if (!input?.ownerDocument || input.ownerDocument.activeElement !== input) return;
        const target = isDomElement(event.target)
            ? event.target
            : event.target?.parentElement || null;
        if (
            !target?.closest(selector)
            || (when && !when(event, input, target))
            || (ignore && ignore(event, input, target))
        ) {
            return;
        }
        event.preventDefault();
    };
    surface.addEventListener("pointerdown", onPointerDown);
    return () => surface.removeEventListener("pointerdown", onPointerDown);
}

export function normalizeStringListMap(value) {
    const source = value && typeof value === "object" && !Array.isArray(value)
        ? value
        : {};
    const result = {};

    for (const [rawKey, rawList] of Object.entries(source)) {
        const key = String(rawKey || "").trim();
        if (!key) continue;
        const list = normalizeUniqueStringList(rawList);
        if (list.length) result[key] = list;
    }

    return result;
}

// 标签内部值统一去掉 Markdown # 前缀，但保留用户原始大小写。
// 大小写仅用于“同一个标签”的比较 / 去重，不得反向污染 UI 显示或 Frontmatter 写盘。
export function normalizeTagValue(value) {
    return String(value || "")
        .replace(/^#+/, "")
        .trim();
}

export function tagIdentityKey(value) {
    return normalizeTagValue(value)
        .toLocaleLowerCase("zh-CN");
}

export function normalizeUniqueTagList(values) {
    const source = Array.isArray(values) ? values : [];
    const seen = new Set();
    const result = [];

    for (const value of source) {
        const tag = normalizeTagValue(value);
        if (!tag) continue;
        const key = tagIdentityKey(tag);
        if (!key || seen.has(key)) continue;
        seen.add(key);
        result.push(tag);
    }

    return result;
}

export function tagPathMatches(candidate, selected) {
    const candidateKey = tagIdentityKey(candidate);
    const selectedKey = tagIdentityKey(selected);
    if (!candidateKey || !selectedKey) return false;
    return candidateKey === selectedKey
        || candidateKey.startsWith(selectedKey + "/");
}

// FilterState 标签条件的唯一规范化：
// - [没有标签] 与真实标签互斥；旧快照若同时存在，优先保留真实标签，避免形成不可能条件。
// - 标签筛选采用 AND；父 + 子同时存在时父条件已被子条件包含，因此只保留更具体的子标签。
export function normalizeFilterTagSelection(values) {
    const source = values instanceof Set
        ? [...values]
        : (Array.isArray(values) ? values : []);
    const unique = normalizeUniqueTagList(source);
    const hasNoTags = unique.includes(NO_TAGS_FILTER_VALUE);
    const realTags = unique.filter(tag => tag !== NO_TAGS_FILTER_VALUE);

    if (!realTags.length) {
        return hasNoTags ? [NO_TAGS_FILTER_VALUE] : [];
    }

    return realTags.filter(tag =>
        !realTags.some(descendant =>
            descendant !== tag
            && tagPathMatches(descendant, tag)
        )
    );
}

// 标签层级按文件去重计数，并同时统计“无标签”。
export function buildHierarchicalTagUsageCounts(candidates) {
    const counts = new Map();
    const normalizedPaths = new Map();
    let noTags = 0;
    for (const meta of candidates || []) {
        const tags = Array.isArray(meta?.tags) ? meta.tags : [];
        if (!tags.length) { noTags++; continue; }

        const seen = new Set();
        for (const rawTag of tags) {
            let keys = normalizedPaths.get(rawTag);
            if (!keys) {
                keys = [];
                let path = "";
                for (const part of normalizeTagValue(rawTag).split("/").filter(Boolean)) {
                    path = path ? `${path}/${part}` : part;
                    keys.push(tagIdentityKey(path));
                }
                normalizedPaths.set(rawTag, keys);
            }
            for (const key of keys) seen.add(key);
        }
        for (const key of seen) counts.set(key, (counts.get(key) || 0) + 1);
    }
    return { counts, noTags };
}

export function normalizeVaultFolderPath(value) {
    const raw = String(value || "")
        .trim()
        .replace(/\\/g, "/")
        .replace(/\/{2,}/g, "/")
        .replace(/^\/+|\/+$/g, "");

    if (!raw || raw === ".") return "";

    const parts = raw
        .split("/")
        .map(part => part.trim())
        .filter(Boolean);

    if (parts.some(part => part === "." || part === "..")) return "";
    return parts.join("/");
}

export function isSameOrDescendantVaultPath(path, parentPath) {
    const pathValue = String(path || "");
    const parent = normalizeVaultFolderPath(parentPath);
    if (!pathValue || !parent) return false;
    return pathValue === parent || pathValue.startsWith(parent + "/");
}

export function normalizeHexColor(value) {
    const raw = String(value || "").trim();
    if (!raw) return "";

    const shortMatch = raw.match(/^#([0-9a-f]{3})$/i);
    if (shortMatch) {
        return "#" + [...shortMatch[1]]
            .map(char => char + char)
            .join("")
            .toUpperCase();
    }

    const longMatch = raw.match(/^#([0-9a-f]{6})$/i);
    return longMatch
        ? `#${longMatch[1].toUpperCase()}`
        : "";
}

export function normalizeResultFolderColors(value) {
    const source =
        value && typeof value === "object" && !Array.isArray(value)
            ? value
            : {};
    const normalized = {};

    for (const [rawPath, rawConfig] of Object.entries(source)) {
        const originalPath = String(rawPath || "").trim();
        const path = originalPath === "/"
            ? "/"
            : normalizeVaultFolderPath(originalPath);

        if (!path && originalPath !== "/") continue;

        const config =
            rawConfig && typeof rawConfig === "object"
                ? rawConfig
                : {};
        const light = normalizeHexColor(config.light);
        const dark = normalizeHexColor(config.dark);

        if (!light && !dark) continue;
        normalized[path || "/"] = { light, dark };
    }

    return normalized;
}

export function resultFolderColorConfig(settings, folderPath) {
    const path = folderPath === "/"
        ? "/"
        : normalizeVaultFolderPath(folderPath);
    const colors = normalizeResultFolderColors(
        settings?.resultFolderColors
    );
    return colors[path || "/"] || null;
}

export function normalizeExcludedFolders(values) {
    const normalized = normalizeUniqueStringList(values)
        .map(normalizeVaultFolderPath)
        .filter(Boolean)
        .sort((a, b) =>
            a.localeCompare(b, "zh-Hans-CN", { numeric: true })
        );

    const result = [];
    for (const path of normalized) {
        if (result.some(parent =>
            isSameOrDescendantVaultPath(path, parent)
        )) {
            continue;
        }
        result.push(path);
    }
    return result;
}

export function isFolderExclusionInherited(path, selectedPaths) {
    const selected = selectedPaths instanceof Set
        ? selectedPaths
        : new Set(normalizeExcludedFolders(selectedPaths));
    let current = String(path || "");

    while (current.includes("/")) {
        current = current.slice(0, current.lastIndexOf("/"));
        if (selected.has(current)) return true;
    }
    return false;
}

export function toggleFolderExclusionSelection(selectedPaths, folderPath) {
    const selected = normalizeExcludedFolders([...selectedPaths]);
    const path = normalizeVaultFolderPath(folderPath);
    if (!path || isFolderExclusionInherited(path, selected)) return selected;
    return normalizeExcludedFolders(selected.includes(path)
        ? selected.filter(value => value !== path)
        : [...selected, path]);
}

// One folder-exclusion behavior; the caller supplies its authoritative setting.
// The controller owns no copied selection and never writes another caller's scope.
export function createFolderExclusionController({ read, write, isLive = () => true, onChange = () => {}, excludeLabel = "排除文件夹", restoreLabel = "恢复显示" }) {
    let pending = false;
    const paths = () => normalizeExcludedFolders(read());
    const state = path => {
        const current = new Set(paths());
        const explicit = !!path && path !== "/" && current.has(path);
        const inherited = !!path && path !== "/" && isFolderExclusionInherited(path, current);
        return { explicit, inherited, hidden: explicit || inherited };
    };
    const commit = async next => {
        if (pending || !isLive()) return false;
        pending = true;
        try { await write(normalizeExcludedFolders(next)); return true; }
        catch (error) { if (isLive()) new Notice(`排除设置保存失败：${error?.message || error}`); return false; }
        finally { pending = false; if (isLive()) onChange(); }
    };
    const toggle = path => !path || path === "/" || state(path).inherited
        ? Promise.resolve(false) : commit(toggleFolderExclusionSelection(paths(), path));
    return {
        paths, state, toggle,
        clear: () => commit([]), remove: path => commit(paths().filter(value => value !== path)),
        renderAction(row, path) {
            if (!path || path === "/") return;
            const value = state(path), name = path.split("/").pop() || path;
            const action = createPickerRowAction(row, {
                icon: value.hidden ? "eye-off" : "eye",
                label: value.inherited ? `${name} 随上级排除` : `${value.explicit ? restoreLabel : excludeLabel} ${name}`,
                onClick: () => { void toggle(path); }
            });
            action.disabled = value.inherited;
        }
    };
}

export const RESULT_VIEW_LABELS = {
    detailed: "详细",
    standard: "标准",
    compact: "精简"
};

// View Composer：结果卡“显示什么 / 按什么顺序显示”的唯一注册表。
// UI 与渲染层都引用同一份 id / flag，避免出现第二套顺序或显隐逻辑。
export const RESULT_CONTENT_DEFS = Object.freeze([
    Object.freeze({ id: "tags", label: "标签", flag: "showTags", kind: "block", icon: "tags" }),
    Object.freeze({ id: "properties", label: "属性", flag: "showProperties", kind: "block", icon: "list-tree" }),
    Object.freeze({ id: "folder", label: "文件夹", flag: "showFolder", kind: "meta", icon: "folder" }),
    Object.freeze({ id: "createdTime", label: "创建时间", flag: "showCreatedTime", kind: "meta", icon: "calendar-plus" }),
    Object.freeze({ id: "contentModifiedTime", label: "正文修改", flag: "showContentModifiedTime", kind: "meta", icon: "file-clock" }),
    Object.freeze({ id: "modifiedTime", label: "文件修改", flag: "showModifiedTime", kind: "meta", icon: "clock-3" })
]);

export function normalizeResultContentOrder(value, fallback = RESULT_CONTENT_IDS) {
    const source = normalizeUniqueStringList(Array.isArray(value) ? value : []);
    const allowed = new Set(RESULT_CONTENT_IDS);
    const next = source.filter(id => allowed.has(id));
    const seen = new Set(next);
    for (const id of Array.isArray(fallback) ? fallback : RESULT_CONTENT_IDS) {
        if (allowed.has(id) && !seen.has(id)) {
            seen.add(id);
            next.push(id);
        }
    }
    for (const id of RESULT_CONTENT_IDS) {
        if (!seen.has(id)) next.push(id);
    }
    return next;
}

// 筛选池固定为四类：共享设置只存顺序、点击模式、展示偏好与候选显隐。
// 候选本体、层级与排序全部复用正式 Facet Picker；新值实时来自 Metadata，不维护第二套树或排序。
// 属性永远只有一个 Pool；属性键与属性值只是该 Pool 内的两级显示偏好。
export const FILTER_POOL_KINDS = Object.freeze(["fileType", "tag", "folder", "property"]);

// Rail placement is presentation only: applied filters remain owned by FilterState.
// The only right-side presentation is a pin selected in the native Property Picker.
export const FILTER_TOOLBAR_ICON_PRESETS = Object.freeze([
    "folder-kanban", "briefcase-business", "user-round", "users-round",
    "circle-check", "circle-dot", "flag", "tags", "bookmark", "star",
    "calendar-days", "clock-3", "milestone", "target", "layers-3",
    "list-todo", "list-filter", "hash", "link", "package", "building-2",
    "map-pin", "wallet-cards", "badge-check", "chart-no-axes-column"
]);

// One recent history for every consumer of the shared icon library.
export function normalizeRecentIconIds(value) {
    return normalizeUniqueStringList(value).filter(id => /^[a-z0-9][a-z0-9-]{0,79}$/i.test(id)).slice(0, 24);
}

export function resolvePickerIcon(plugin, icon, fallback) {
    if (!icon || !plugin) return fallback;
    // Obsidian's registry includes externally registered addIcon IDs. Refresh
    // on library open, retain unavailable stored IDs, and render a safe default.
    if (!plugin._pickerIconIds) plugin._pickerIconIds = new Set(filterToolbarIconCatalog());
    return plugin._pickerIconIds.has(icon) ? icon : fallback;
}

export function rememberPickerIcon(plugin, icon) {
    if (!plugin?.settings || !icon) return;
    plugin.settings.recentIconIds = normalizeRecentIconIds([icon, ...normalizeRecentIconIds(plugin.settings.recentIconIds)]);
    plugin._throttleSaveActivity?.();
}

export function filterToolbarIconCatalog() {
    let ids = [];
    try {
        ids = typeof getIconIds === "function" ? getIconIds() : [];
    } catch (_) {}
    return normalizeUniqueStringList([
        ...FILTER_TOOLBAR_ICON_PRESETS,
        ...(Array.isArray(ids) ? ids : [])
    ]);
}

export const FILTER_POOL_FIXED_DEFS = Object.freeze([
    Object.freeze({ kind: "fileType", label: "文件类型", icon: "files", defaultShowAll: true }),
    Object.freeze({ kind: "tag", label: "标签", icon: "tags", defaultShowAll: false }),
    Object.freeze({ kind: "folder", label: "文件夹", icon: "folder", defaultShowAll: false }),
    Object.freeze({ kind: "property", label: "属性", icon: "list-tree", defaultShowAll: false })
]);

export function normalizeFilterPoolSelectionMode(value) {
    return value === "multi" ? "multi" : "single";
}

export function normalizePropertyPoolEntry(value = {}) {
    const source = value && typeof value === "object" ? value : {};
    return {
        showKey: source.showKey === true,
        pinnedRight: source.pinnedRight === true,
        shortcutIcon: String(source.shortcutIcon || PROPERTY_SHORTCUT_DEFAULT_ICON).trim()
            || PROPERTY_SHORTCUT_DEFAULT_ICON
    };
}

export function normalizePropertyPoolEntries(value) {
    const source = value && typeof value === "object" && !Array.isArray(value)
        ? value
        : {};
    const result = {};
    for (const [rawKey, rawConfig] of Object.entries(source)) {
        const key = String(rawKey || "").trim();
        if (!key) continue;
        result[key] = normalizePropertyPoolEntry(rawConfig);
    }
    return result;
}

export function propertyPoolEntryHasState(entry) {
    return Boolean(entry?.showKey || entry?.pinnedRight);
}

export function filterPoolId(kind) {
    return FILTER_POOL_KINDS.includes(kind) ? kind : "";
}

export function normalizeFilterPoolConfig(value) {
    const source = value && typeof value === "object" ? value : {};
    const kind = FILTER_POOL_KINDS.includes(source.kind) ? source.kind : "";
    const id = filterPoolId(kind);
    if (!id) return null;

    if (kind === "property") {
        return {
            id, kind, key: "", visible: source.visible !== false,
            autoIncludeKeys: source.autoIncludeKeys === true,
            hiddenKeyNames: normalizeUniqueStringList(source.hiddenKeyNames),
            propertyEntries: normalizePropertyPoolEntries(source.propertyEntries)
        };
    }

    const fixed = FILTER_POOL_FIXED_DEFS.find(def => def.kind === kind);
    return {
        id,
        kind,
        key: "",
        visible: source.visible !== false,
        selectionMode: normalizeFilterPoolSelectionMode(source.selectionMode),
        showAllValues: typeof source.showAllValues === "boolean"
            ? source.showAllValues
            : Boolean(fixed?.defaultShowAll),
        hiddenValueKeys: normalizeUniqueStringList(source.hiddenValueKeys),
        visibleValueKeys: normalizeUniqueStringList(source.visibleValueKeys)
    };
}

export function normalizeFilterPools(value) {
    const source = Array.isArray(value) ? value : [];
    const seen = new Set();
    const result = [];

    for (const raw of source) {
        const pool = normalizeFilterPoolConfig(raw);
        if (!pool) continue;

        if (seen.has(pool.id)) continue;
        seen.add(pool.id);
        result.push(pool);
    }

    // 四类筛选池固定存在；缺失项只补成关闭状态。
    // 这样“eye = 开/关”就是唯一生命周期，不再需要添加 / 删除。
    for (const def of FILTER_POOL_FIXED_DEFS) {
        const id = filterPoolId(def.kind);
        if (!id || seen.has(id)) continue;
        const pool = normalizeFilterPoolConfig({
            kind: def.kind,
            visible: false
        });
        if (!pool) continue;
        seen.add(id);
        result.push(pool);
    }

    return result;
}

export function normalizeResultViewId(value) {
    const id = String(value || "").toLowerCase();
    return RESULT_VIEW_IDS.includes(id) ? id : "standard";
}

export function normalizeResultViewConfig(value, fallback) {
    const source = value && typeof value === "object" ? value : {};
    const base = fallback && typeof fallback === "object"
        ? fallback
        : DEFAULT_RESULT_VIEWS.standard;

    return {
        snippetLines: Math.min(
            3,
            normalizeIntegerSetting(
                source.snippetLines,
                base.snippetLines,
                { allowZero: true }
            )
        ),
        showTags: typeof source.showTags === "boolean"
            ? source.showTags
            : base.showTags,
        showProperties: typeof source.showProperties === "boolean"
            ? source.showProperties
            : base.showProperties,
        showFolder: typeof source.showFolder === "boolean"
            ? source.showFolder
            : base.showFolder,

        // V5.0.28 前 showModifiedTime 表示唯一的“修改时间”。
        // 首次迁移时把用户原来的显示意图转移到“正文修改”，
        // 新增的“文件修改”默认关闭，避免升级后结果卡突然多出一份重复时间。
        showContentModifiedTime:
            typeof source.showContentModifiedTime === "boolean"
                ? source.showContentModifiedTime
                : typeof source.showModifiedTime === "boolean"
                    ? source.showModifiedTime
                    : base.showContentModifiedTime,
        showModifiedTime:
            typeof source.showContentModifiedTime === "boolean"
                ? (
                    typeof source.showModifiedTime === "boolean"
                        ? source.showModifiedTime
                        : base.showModifiedTime
                )
                : false,
        showCreatedTime: typeof source.showCreatedTime === "boolean"
            ? source.showCreatedTime
            : base.showCreatedTime,
        contentOrder: normalizeResultContentOrder(
            source.contentOrder,
            base.contentOrder || RESULT_CONTENT_IDS
        )
    };
}

export function normalizeResultViews(value) {
    const source = value && typeof value === "object" ? value : {};
    return Object.fromEntries(
        RESULT_VIEW_IDS.map(id => [
            id,
            normalizeResultViewConfig(
                source[id],
                DEFAULT_RESULT_VIEWS[id]
            )
        ])
    );
}

// Toolbar IDs are presentation preferences only. Version 2 keeps an explicit
// membership/order and a separate hidden list: remove, hide and add are distinct.
export const NAVIGATOR_TOOLBAR_CONTEXTS = Object.freeze({
    filters: { label: "筛选导航", order: ["collapse", "results", "view", "history", "create", "sort-navigation"], hidden: ["sort-navigation"] },
    results: { label: "搜索结果", order: ["search", "filters", "sort", "view", "batch", "create"], hidden: [] },
    create: { label: "创建文件", order: ["search", "filters", "create"], hidden: [] }
});

export function navigatorToolbarActionIdIsValid(id) {
    return typeof id === "string" && (Object.hasOwn(NAVIGATOR_TOOLBAR_ACTIONS, id)
        || (id.startsWith("pool:") && FILTER_POOL_KINDS.includes(id.slice(5)))
        || (id.startsWith("property:") && id.slice(9).trim() === id.slice(9) && id.length > 9));
}

export function navigatorToolbarActionAvailable(id, context) {
    // Search-only controls have no draft-creation equivalent. Retain an older
    // configuration, but do not offer a new command that cannot act on this page.
    return context !== "create" || !["time", "sort"].includes(id);
}

export function navigatorToolbarCatalog(plugin, { propertyKeys = [] } = {}) {
    const catalog = new Map(Object.entries(NAVIGATOR_TOOLBAR_ACTIONS));
    for (const def of FILTER_POOL_FIXED_DEFS) catalog.set(`pool:${def.kind}`, {
        label: `${def.label}筛选`, icon: def.icon, kind: "pool", poolKind: def.kind
    });
    const settings = plugin?.settings || {};
    const propertyPool = normalizeFilterPools(settings.filterPools).find(pool => pool.kind === "property");
    const entries = normalizePropertyPoolEntries(propertyPool?.propertyEntries);
    const excluded = new Set(settings.excludedKeys || []);
    // The existing property Picker owns keys/icons. A configured bottom shortcut
    // remains usable after its independent right-hand pin is removed.
    const storedKeys = Object.values(settings.navigatorToolbars || {}).flatMap(config =>
        Array.isArray(config?.order) ? config.order.filter(id => typeof id === "string" && id.startsWith("property:")).map(id => id.slice(9)) : []);
    const keys = sortByPreferredOrder([...new Set([
        ...Object.entries(entries).filter(([, entry]) => entry.pinnedRight).map(([key]) => key),
        ...propertyKeys,
        ...storedKeys
    ])].filter(key => key && !excluded.has(key)), settings.pickerPropertyOrder, key => key);
    for (const key of keys) catalog.set(`property:${key}`, {
        label: key, icon: entries[key]?.shortcutIcon || PROPERTY_SHORTCUT_DEFAULT_ICON,
        kind: "property", propertyKey: key
    });
    return catalog;
}

export function normalizeNavigatorToolbars(raw) {
    const result = {};
    for (const [context, defaults] of Object.entries(NAVIGATOR_TOOLBAR_CONTEXTS)) {
        const input = raw && typeof raw === "object" && !Array.isArray(raw)
            && raw[context] && typeof raw[context] === "object" && !Array.isArray(raw[context])
            ? raw[context] : {};
        const hasOrder = Array.isArray(input.order);
        const storedOrder = hasOrder ? input.order.map(id => id === "manage" ? "view" : id).filter(navigatorToolbarActionIdIsValid) : [];
        const order = [...new Set(input.version === 2 && hasOrder
            ? storedOrder : [...storedOrder, ...defaults.order])];
        const valid = new Set(order);
        const hidden = new Set((Array.isArray(input.hidden) ? input.hidden : defaults.hidden)
            .map(id => id === "manage" ? "view" : id).filter(id => valid.has(id)));
        // Two formerly separate entries may map to View settings. Keep the
        // merged entry visible if either configured launch action was visible.
        if (hasOrder && input.order.includes("manage") && input.order.includes("view")) {
            const originalHidden = new Set(Array.isArray(input.hidden) ? input.hidden : defaults.hidden);
            if (!originalHidden.has("manage") || !originalHidden.has("view")) hidden.delete("view");
        }
        // Newly introduced optional actions stay opt-in when older preferences
        // did not know them. Explicitly visible known actions remain visible.
        if (input.version !== 2) for (const id of defaults.hidden) if (!storedOrder.includes(id)) hidden.add(id);
        const storedIcons = input.icons && typeof input.icons === "object" && !Array.isArray(input.icons) ? input.icons : {};
        const icons = {};
        for (const id of order) {
            const icon = storedIcons[id] || (id === "view" ? storedIcons.manage : "");
            if (typeof icon === "string" && /^[a-z0-9][a-z0-9-]{0,79}$/i.test(icon)) icons[id] = icon;
        }
        result[context] = { version: 2, order, hidden: order.filter(id => hidden.has(id)), icons };
    }
    return result;
}

export function navigatorToolbarIcon(core, id, fallback, preferences = null) {
    const nav = core?.navigator;
    if (!nav || nav.layout !== "mobile") return fallback;
    const context = nav.page === "filters" ? "filters" : core.createFlow?.isCreateView?.() ? "create" : "results";
    const config = preferences || normalizeNavigatorToolbars(core.plugin.settings.navigatorToolbars)[context];
    return resolvePickerIcon(core.plugin, config.icons[id], fallback);
}

export const NAVIGATOR_VISIBLE_SECTION_DEFS = Object.freeze([
    { id: "folder", label: "文件夹", icon: "folder" },
    { id: "tags", label: "标签", icon: "tags" },
    { id: "properties", label: "属性", icon: "list-tree" },
    { id: "project", label: "所属项目快捷分组（桌面）", icon: "layers" },
    { id: "owner", label: "负责人快捷分组（桌面）", icon: "user" }
]);

export function normalizeNavigatorVisibleSections(value) {
    const allowed = new Set(NAVIGATOR_VISIBLE_SECTION_DEFS.map(def => def.id));
    return Array.isArray(value)
        ? [...new Set(value.filter(id => allowed.has(id)))]
        : [...allowed];
}

export function normalizeNavigatorTimeField(field) {
    return ["created", "modified", "fileModified"].includes(field) ? field : "created";
}

export function hasExcalidrawFrontmatter(frontmatter) {
    return !!frontmatter && typeof frontmatter === "object"
        && Object.prototype.hasOwnProperty.call(frontmatter, "excalidraw-plugin");
}

export function isExcalidrawMeta(file, cache) {
    if (!(file instanceof TFile) || file.extension.toLowerCase() !== "md") return false;
    // 保留已有 .excalidraw.md 的兼容入口，不把普通 *_绘图.md 单凭文件名误判为绘图。
    if (file.name.toLowerCase().endsWith(".excalidraw.md")) return true;
    return hasExcalidrawFrontmatter(cache?.frontmatter);
}

// 优化分词：过滤虚词、轻量文本分段，超长文本截断
export function simpleSegment(text, maxRead = 8000) {
    // invariant: only user-authored separators create query units.
    // Chinese text is never silently split into n-grams or dictionary tokens.
    return [...new Set(String(text || "").slice(0, maxRead).toLowerCase()
        .split(/[\s,，;；|]+/).map(s => s.trim()).filter(Boolean))];
}

export function decodeReadableEntities(text) {
    return String(text || "")
        .replace(/&nbsp;/gi, " ")
        .replace(/&amp;/gi, "&")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&quot;/gi, '"')
        .replace(/&#39;|&apos;/gi, "'")
        .replace(/&#(\d+);/g, (_, value) => {
            const codePoint = Number.parseInt(value, 10);
            return Number.isFinite(codePoint) && codePoint >= 0 && codePoint <= 0x10FFFF
                ? String.fromCodePoint(codePoint)
                : " ";
        })
        .replace(/&#x([0-9a-f]+);/gi, (_, value) => {
            const codePoint = Number.parseInt(value, 16);
            return Number.isFinite(codePoint) && codePoint >= 0 && codePoint <= 0x10FFFF
                ? String.fromCodePoint(codePoint)
                : " ";
        });
}

export function readableWikiTarget(target) {
    const raw = String(target || "").trim().replace(/\^[^#]+$/, "");
    const parts = raw.split("#");
    const file = (parts.shift() || "").split("/").pop() || "";
    return [file, parts.join(" ").trim()].filter(Boolean).join(" ");
}

export function normalizeReadableText(text) {
    return decodeReadableEntities(text)
        .replace(/[ \t]*\|[ \t]*/g, " ")
        .replace(/\r?\n+/g, " ")
        .replace(/[ \t\f\v]+/g, " ")
        .trim();
}

// Markdown / Obsidian 搜索与摘要净化入口。
// 搜索匹配、普通摘要与搜索摘要统一基于这一份可读纯文本，避免 offset 与展示口径漂移。
// “笔记字数”有独立语义：代码、引用、批注等用户实际写下的内容也应计入，
// 因此字数统计不再复用这里的降噪结果。
export function cleanMarkdownForSnippet(content) {
    let text = String(content || "").replace(/^\uFEFF/, "");

    // 文件级结构噪音：不属于用户实际阅读正文。
    text = text
        .replace(/^---[ \t]*\r?\n[\s\S]*?\r?\n---[ \t]*(?:\r?\n|$)/, "\n")
        .replace(/<!--[\s\S]*?-->/g, " ")
        .replace(/%%[\s\S]*?%%/g, " ")
        .replace(/^[ \t]*```+[^\n]*\r?\n[\s\S]*?(?:^[ \t]*```+[ \t]*(?:\r?\n|$)|(?![\s\S]))/gm, "\n")
        .replace(/^[ \t]*~~~+[^\n]*\r?\n[\s\S]*?(?:^[ \t]*~~~+[ \t]*(?:\r?\n|$)|(?![\s\S]))/gm, "\n")
        .replace(/\$\$[\s\S]*?\$\$/g, " ")
        .replace(/^[ \t]*\[[^\]]+\]:[ \t]*\S+.*$/gm, " ");

    // Obsidian 嵌入不把附件路径/目标名塞进摘要；普通双链保留用户可见的别名或可读目标。
    text = text
        .replace(/!\[\[[\s\S]*?\]\]/g, " ")
        .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")
        .replace(/\[\[([^\]|]+)\|([^\]]+)\]\]/g, (_, target, alias) => String(alias || target).trim())
        .replace(/\[\[([^\]]+)\]\]/g, (_, target) => readableWikiTarget(target))
        .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
        .replace(/<https?:\/\/[^>]+>/gi, " ")
        .replace(/<mailto:[^>]+>/gi, " ")
        .replace(/<[^>]+>/g, " ");

    // 行内代码与脚注/块标识等技术性标记。
    text = text
        .replace(/`+[^`\n]*`+/g, " ")
        .replace(/(?<!\$)\$[^$\n]+\$(?!\$)/g, " ")
        .replace(/\[\^([^\]]+)\]/g, " ")
        .replace(/[ \t]+\^[A-Za-z0-9_-]+(?=\s|$)/gm, " ");

    // 行首 Markdown / Obsidian 结构符号。Callout 只去掉 [!TYPE] 壳，保留用户写的标题。
    text = text
        .replace(/^[ \t]*>[ \t]*\[![^\]]+\][+-]?[ \t]*/gmi, "")
        .replace(/^[ \t]*>[ \t]?/gm, "");
    text = stripReadableLineSyntax(text);

    // 只去格式语法壳，不删除被格式化的真实文字。
    text = text
        .replace(/\*\*([^*\n]+)\*\*/g, "$1")
        .replace(/__([^_\n]+)__/g, "$1")
        .replace(/~~([^~\n]+)~~/g, "$1")
        .replace(/==([^=\n]+)==/g, "$1")
        .replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g, "$1")
        .replace(/(?<!\w)_([^_\n]+)_(?!\w)/g, "$1")
        .replace(/\\([#*_[\]()>`~|])/g, "$1");

    // 标签只去掉语法壳；裸 URL 在摘要里属于高噪音目标，普通 Markdown 链接的显示文字已在上面保留。
    text = text
        .replace(/(^|\s)#([^\s#]+)/g, "$1$2")
        .replace(/https?:\/\/[^\s)\]>]+/gi, " ");

    // 表格竖线、HTML 实体、换行与多余空白统一成自然语言间隔，绝不把相邻段落直接粘成一个词。
    return normalizeReadableText(text);
}

// 字数统计专用 Markdown / Obsidian 提取器。
// 与摘要降噪不同，这里保留“用户实际写下的内容”，只剥离结构壳：
// - 代码块 / 行内代码：保留代码正文，只去 fence / backtick；
// - 引用 / Callout：保留正文与自定义标题，只去 > / [!TYPE] 壳；
// - 标注：==高亮==、%%批注%%、HTML comment 内容都保留；
// - 数学块 / 行内公式：保留公式里的字母、数字；
// - 脚注定义：保留脚注正文；脚注引用标号本身不计；
// - Frontmatter 仍属于元数据，不计入正文；
// - 嵌入文件不递归展开，避免把其它文件内容重复计入当前笔记。
export function extractCountableTextFromMarkdown(content) {
    let text = String(content || "").replace(/^\uFEFF/, "");

    // Frontmatter：元数据，不属于正文阅读字数。
    text = text.replace(
        /^---[ \t]*\r?\n[\s\S]*?\r?\n---[ \t]*(?:\r?\n|$)/,
        "\n"
    );

    // 批注 / 注释：保留用户写下的内容，只去隐藏壳。
    text = text
        .replace(/<!--([\s\S]*?)-->/g, (_, body) => ` ${body || ""} `)
        .replace(/%%([\s\S]*?)%%/g, (_, body) => ` ${body || ""} `);

    // fenced code：只去开 / 闭 fence 行，代码正文完整保留。
    text = text
        .replace(/^[ \t]*(?:`{3,}|~{3,})[^\r\n]*$/gm, " ")
        .replace(/`+([^`\r\n]*?)`+/g, (_, body) => ` ${body || ""} `);

    // 数学公式：只去 $ / $$ 定界符，公式内容参与统计。
    text = text
        .replace(/\$\$([\s\S]*?)\$\$/g, (_, body) => ` ${body || ""} `)
        .replace(/(?<!\$)\$([^$\r\n]+)\$(?!\$)/g, (_, body) => ` ${body || ""} `);

    // 引用型链接定义不显示；脚注定义正文保留。
    text = text
        .replace(/^[ \t]*\[(?!\^)[^\]]+\]:[ \t]*\S+.*$/gm, " ")
        .replace(/^[ \t]*\[\^[^\]]+\]:[ \t]*/gm, "")
        .replace(/\[\^[^\]]+\]/g, " ");

    // Obsidian 嵌入不递归展开；普通双链保留用户可见别名 / 目标。
    text = text
        .replace(/!\[\[[\s\S]*?\]\]/g, " ")
        .replace(/!\[([^\]]*)\]\([^)]*\)/g, (_, alt) => ` ${alt || ""} `)
        .replace(/\[\[([^\]|]+)\|([^\]]+)\]\]/g, (_, target, alias) =>
            ` ${String(alias || target || "").trim()} `
        )
        .replace(/\[\[([^\]]+)\]\]/g, (_, target) => ` ${readableWikiTarget(target)} `)
        .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1");

    // URL / 邮箱在正文中按一个“串”计数，不拆成 https / domain / tld。
    text = text
        .replace(/<https?:\/\/[^>]+>/gi, " LSURLTOKEN ")
        .replace(/<mailto:[^>]+>/gi, " LSEMAILTOKEN ")
        .replace(/\bhttps?:\/\/[^\s)\]>]+/gi, " LSURLTOKEN ")
        .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, " LSEMAILTOKEN ");

    // HTML 标签只去标签本身，保留标签之间的文字。
    text = text.replace(/<[^>]+>/g, " ");

    // Callout / 引用：只去结构壳，正文完整保留。
    text = text
        .replace(/^[ \t]*>[ \t]*\[![^\]]+\][+-]?[ \t]*/gmi, "")
        .replace(/^[ \t]*>[ \t]?/gm, "");

    // 标题、列表、任务、编号、表格分隔线：去结构符号，保留实际文字。
    text = stripReadableLineSyntax(text);

    // 强调 / 高亮 / 删除线：只去语法壳，内部文字继续计数。
    text = text
        .replace(/\*\*([^*\r\n]+)\*\*/g, "$1")
        .replace(/__([^_\r\n]+)__/g, "$1")
        .replace(/~~([^~\r\n]+)~~/g, "$1")
        .replace(/==([^=\r\n]+)==/g, "$1")
        .replace(/(?<!\*)\*([^*\r\n]+)\*(?!\*)/g, "$1")
        .replace(/(?<!\w)_([^_\r\n]+)_(?!\w)/g, "$1")
        .replace(/\\([#*_[\]()>`~|])/g, "$1");

    // 标签仅去 #；块 ID 属于技术锚点，不计。
    text = text
        .replace(/(^|\s)#([^\s#]+)/g, "$1$2")
        .replace(/[ \t]+\^[A-Za-z0-9_-]+(?=\s|$)/gm, " ");

    return normalizeReadableText(text);
}

// 统一正文“字数”口径：
// - 每个汉字计 1；
// - 一串连续数字计 1（1,356 / 3.14 也各计 1）；
// - 一串连续英文 / 英数字标识计 1（ChatGPT / SKU123 / foo_bar 各计 1）；
// - 其它文字脚本按连续词段计 1；
// - 空白、标点、Markdown 结构符号不计。
export function readableTokenCountFromText(text) {
    const source = String(text || "");
    if (!source) return 0;

    const tokenRe =
        /[\p{Script=Han}]|\d+(?:[.,]\d+)*|[A-Za-z]+(?:[A-Za-z0-9_'’\-]*[A-Za-z0-9])?|[\p{L}\p{M}]+/gu;

    let count = 0;
    while (tokenRe.exec(source)) count++;
    return count;
}

// IO并发池
export class IoPool {
    constructor(limit) {
        const parsedLimit = Number.parseInt(String(limit), 10);
        this.limit = Number.isFinite(parsedLimit) && parsedLimit > 0
            ? parsedLimit
            : 1;
        this.running = 0;
        this.queue = [];
    }
    run(fn) {
        return new Promise((resolve, reject) => {
            const task = async () => {
                this.running++;
                try {
                    resolve(await fn());
                } catch (error) {
                    reject(error);
                } finally {
                    this.running--;
                    this.next();
                }
            };
            if (this.running < this.limit) void task();
            else this.queue.push(task);
        });
    }
    next() {
        if (this.queue.length && this.running < this.limit) {
            void this.queue.shift()();
        }
    }

    async forEach(items, fn, shouldContinue) {
        const batchSize = 300;
        for (let i = 0; i < items.length && shouldContinue(); i += batchSize) {
            await Promise.all(items.slice(i, i + batchSize).map(item => this.run(() => fn(item))));
            if (!shouldContinue()) return;
            if (i + batchSize < items.length) await new Promise(resolve => setTimeout(resolve, 0));
        }
    }
}

export class BodyIndex {
    constructor(maxLength = 8000) { this.documents = new Map(); this.maxLength = maxLength; }
    clear() { this.documents.clear(); }
    addFile(meta, content = "", readableText = null) {
        if (meta.extension !== "md") {
            this.documents.delete(meta.path);
            return;
        }
        const text = readableText === null
            ? cleanMarkdownForSnippet(content)
            : String(readableText || "");
        this.documents.set(
            meta.path,
            text.slice(0, this.maxLength).toLowerCase()
        );
    }
    removeFile(path) { this.documents.delete(path); }
    moveFile(oldPath, newPath) {
        if (!oldPath || !newPath || oldPath === newPath || !this.documents.has(oldPath)) return;
        const content = this.documents.get(oldPath);
        this.documents.delete(oldPath);
        this.documents.set(newPath, content);
    }
    get(path) { return this.documents.get(path) || ""; }
    serialize() { return { documents: Object.fromEntries(this.documents) }; }
    deserialize(data) { this.documents = new Map(Object.entries(data?.documents || {})); }
}

// ========== 批量修改笔记属性值：纯函数层 ==========

// ========== Search state / ranking ==========
export class QueryState {
    constructor(raw = "") { this.set(raw); }
    set(raw) {
        this.raw = String(raw || "");
        this.normalized = this.raw.trim().toLowerCase();
        this.intent = this.normalized.replace(/^#/, "");
        this.units = simpleSegment(this.intent);
        return this;
    }
    get active() { return this.units.length > 0; }
}

export function normalizeFileTypeFilterValue(value) {
    const raw = String(value || "").trim().toLowerCase();
    if (!raw || raw === "all") return "";
    if (["note", "canvas", "excalidraw", "attachment"].includes(raw)) return raw;
    return /^ext:[a-z0-9][a-z0-9._+-]*$/i.test(raw) ? raw : "";
}

export function normalizeFileTypeFilterSelection(values = []) {
    const source = values instanceof Set ? [...values] : (Array.isArray(values) ? values : [values]);
    const result = [];
    const seen = new Set();
    for (const raw of source) {
        const value = normalizeFileTypeFilterValue(raw);
        if (!value || seen.has(value)) continue;
        seen.add(value);
        result.push(value);
    }
    return result;
}

export function normalizeFilterMatchMode(value) {
    return value === "any" ? "any" : "all";
}

export const FILTER_TIME_FIELDS = Object.freeze({
    created: { key: "ctime", label: "创建时间" },
    modified: { key: "contentModifiedAt", label: "正文修改时间" },
    fileModified: { key: "fileModifiedAt", label: "文件修改时间" }
});

export function normalizeFilterDate(value) {
    const text = typeof value === "string" ? value.trim() : "";
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
    if (!match) return "";
    const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
    if (!year || month < 1 || month > 12 || day < 1 || day > 31) return "";
    // Date-only state never passes through Date.parse: UTC parsing would shift
    // the chosen calendar day on devices west of UTC.
    const check = new Date(0);
    check.setUTCFullYear(year, month - 1, day);
    return check.getUTCFullYear() === year
        && check.getUTCMonth() === month - 1
        && check.getUTCDate() === day ? text : "";
}

export function filterLocalDate(value) {
    const timestamp = parseGLSDate(value);
    if (!timestamp) return "";
    const date = new Date(timestamp);
    const year = date.getFullYear();
    if (year < 1 || year > 9999) return "";
    return `${String(year).padStart(4, "0")}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

export function normalizeFilterDateRange(value) {
    if (!value || typeof value !== "object" || !Object.prototype.hasOwnProperty.call(FILTER_TIME_FIELDS, value.field)) return null;
    const from = normalizeFilterDate(value.from);
    const to = normalizeFilterDate(value.to);
    if ((value.from && !from) || (value.to && !to) || (!from && !to) || (from && to && from > to)) return null;
    return { field: value.field, from, to };
}

export function filterDateRangeDisplay(value) {
    const range = normalizeFilterDateRange(value);
    if (!range) return "";
    const dates = range.from === range.to ? range.from
        : `${range.from || "不限"} 至 ${range.to || "不限"}`;
    return `${FILTER_TIME_FIELDS[range.field].label}：${dates}`;
}

export function recentFilterDateRange(field, days, now = new Date()) {
    const end = new Date(parseGLSDate(now));
    const start = new Date(end);
    // Calendar arithmetic includes today and remains correct across DST.
    start.setDate(start.getDate() - Math.max(0, Math.floor(days) - 1));
    return normalizeFilterDateRange({ field, from: filterLocalDate(start), to: filterLocalDate(end) });
}

export class FilterState {
    constructor() { this.clear(); }

    clear() {
        this.tags = new Set();
        this.folders = new Set();
        this.properties = new Map();
        this.fileTypes = new Set();
        this.dateRange = null;
        // 普通 Facet 保留 GLS 既有 AND 语义；筛选池多选可在同一 FilterState 内切到 OR。
        this.tagMatchMode = "all";
        this.propertyMatchMode = "all";
    }

    // 文件类型筛选池支持真正多选；旧 fileType 保留为单值兼容入口。
    get fileType() {
        return this.fileTypes.size === 1 ? [...this.fileTypes][0] : "all";
    }

    set fileType(value) {
        this.fileTypes.clear();
        const normalized = normalizeFileTypeFilterValue(value);
        if (normalized) this.fileTypes.add(normalized);
    }

    // 单目录兼容入口：只有恰好一个目录时才返回路径。
    // 多目录筛选属于 OR 查询范围，不能被“新建文件”等单目录功能误当成某一个目录。
    get folder() {
        return this.folders.size === 1
            ? [...this.folders][0]
            : "";
    }

    set folder(value) {
        this.folders.clear();
        const normalized = String(value || "").trim();
        if (normalized) this.folders.add(normalized);
    }

    get active() {
        return this.tags.size > 0
            || this.folders.size > 0
            || this.properties.size > 0
            || this.fileTypes.size > 0
            || Boolean(this.dateRange);
    }

    clone() {
        const f = new FilterState();
        f.tags = new Set(this.tags);
        f.folders = new Set(this.folders);
        f.fileTypes = new Set(this.fileTypes);
        f.dateRange = normalizeFilterDateRange(this.dateRange);
        f.tagMatchMode = normalizeFilterMatchMode(this.tagMatchMode);
        f.propertyMatchMode = normalizeFilterMatchMode(this.propertyMatchMode);
        f.properties = new Map(
            Array.from(
                this.properties,
                ([key, values]) => [key, new Set(values)]
            )
        );
        return f;
    }

    // FilterState 是唯一筛选状态模型；持久化也必须由它负责序列化 / 反序列化，
    // 避免 Modal、Sidebar、设置层各自维护一套字段口径。
    toSnapshot() {
        return FilterState.normalizeSnapshot({
            tags: [...this.tags],
            folders: [...this.folders],
            properties: [...this.properties.entries()]
                .map(([key, values]) => [key, [...values]]),
            fileTypes: [...this.fileTypes],
            fileType: this.fileType,
            dateRange: this.dateRange,
            tagMatchMode: normalizeFilterMatchMode(this.tagMatchMode),
            propertyMatchMode: normalizeFilterMatchMode(this.propertyMatchMode)
        });
    }

    static normalizeSnapshot(value) {
        const source = value && typeof value === "object" ? value : {};

        const tags = normalizeFilterTagSelection(source.tags);

        // 兼容旧版保存的单 folder 字段；新状态统一为 folders[]。
        const rawFolders = Array.isArray(source.folders)
            ? source.folders
            : source.folder
                ? [source.folder]
                : [];
        const folders = normalizeUniqueStringList(rawFolders)
            .map(raw => {
                const value = String(raw || "").trim();
                return value === "/"
                    ? "/"
                    : normalizeVaultFolderPath(value);
            })
            .filter(Boolean);

        const fileTypes = normalizeFileTypeFilterSelection(
            Array.isArray(source.fileTypes) ? source.fileTypes : [source.fileType || "all"]
        );
        const fileType = fileTypes.length === 1 ? fileTypes[0] : "all";

        const properties = [];
        const propertySource = Array.isArray(source.properties)
            ? source.properties
            : [];

        for (const entry of propertySource) {
            if (!Array.isArray(entry) || entry.length < 2) continue;

            const key = String(entry[0] || "").trim();
            if (!key) continue;

            const rawValues = Array.isArray(entry[1])
                ? entry[1]
                : [entry[1]];
            const seen = new Set();
            const values = [];

            for (const rawValue of rawValues) {
                if (rawValue === undefined || rawValue === null) continue;
                const value = String(rawValue).trim();
                if (!value) continue;

                // FilterState Snapshot 必须完整保存搜索语义。
                // PRESENT / MISSING / EMPTY 都属于正式筛选状态；
                // 只有进入 CreateDraft materialize 时才过滤不可写入 Frontmatter 的查询态。
                const semanticKey = propertyValueKey(value);
                if (seen.has(semanticKey)) continue;
                seen.add(semanticKey);
                values.push(value);
            }

            const normalizedSelection = normalizePropertySelection(values);
            if (normalizedSelection.size) {
                properties.push([key, [...normalizedSelection]]);
            }
        }

        return {
            tags,
            folders,
            properties,
            fileTypes,
            fileType,
            dateRange: normalizeFilterDateRange(source.dateRange),
            tagMatchMode: normalizeFilterMatchMode(source.tagMatchMode),
            propertyMatchMode: normalizeFilterMatchMode(source.propertyMatchMode)
        };
    }

    static fromSnapshot(value) {
        const snapshot = FilterState.normalizeSnapshot(value);
        const state = new FilterState();

        state.tags = new Set(snapshot.tags);
        state.folders = new Set(snapshot.folders);
        state.fileTypes = new Set(snapshot.fileTypes);
        state.dateRange = snapshot.dateRange;
        state.tagMatchMode = snapshot.tagMatchMode;
        state.propertyMatchMode = snapshot.propertyMatchMode;
        state.properties = new Map(
            snapshot.properties.map(
                ([key, values]) => [key, new Set(values)]
            )
        );

        return state;
    }
}

export function normalizeLegacyFilterPoolSnapshot(value, pools) {
    const source = value && typeof value === "object" ? value : {};
    const hasCurrentSemantics = Object.prototype.hasOwnProperty.call(source, "tagMatchMode")
        && Object.prototype.hasOwnProperty.call(source, "propertyMatchMode")
        && Array.isArray(source.fileTypes);
    if (hasCurrentSemantics) return FilterState.normalizeSnapshot(source);

    const state = FilterState.fromSnapshot(source);
    // 旧 Snapshot 没有来源语义时按 GLS 原正式 Facet 语义恢复；
    // 筛选池配置只决定点击方式，不允许仅因“配置为 Multi”就把已有条件从 AND 重解释为 OR。
    state.tagMatchMode = "all";
    state.propertyMatchMode = "all";
    for (const pool of normalizeFilterPools(pools)) {
        const mode = normalizeFilterPoolSelectionMode(pool.selectionMode);
        if (pool.kind === "tag") {
            if (mode === "single" && state.tags.size > 1) {
                const first = state.tags.values().next().value;
                state.tags.clear();
                if (first !== undefined) state.tags.add(first);
            }
        } else if (pool.kind === "property") {
            if (mode === "single") {
                let first = null;
                let count = 0;
                for (const [key, values] of state.properties) {
                    for (const item of values) {
                        if (!first) first = { key, value: item };
                        count++;
                    }
                }
                if (count > 1) {
                    state.properties.clear();
                    if (first) state.properties.set(first.key, new Set([first.value]));
                }
            }
        } else if (pool.kind === "folder" && mode === "single" && state.folders.size > 1) {
            const first = state.folders.values().next().value;
            state.folders.clear();
            if (first !== undefined) state.folders.add(first);
        } else if (pool.kind === "fileType" && mode === "single" && state.fileTypes.size > 1) {
            const first = state.fileTypes.values().next().value;
            state.fileTypes.clear();
            if (first !== undefined) state.fileTypes.add(first);
        }
    }
    return state.toSnapshot();
}

export function attachmentExtension(meta) {
    return String(meta?.extension || "").trim().toLowerCase();
}

export function normalizeExcludedAttachmentTypes(values) {
    return [...new Set((Array.isArray(values) ? values : [])
        .map(value => String(value || "").trim().toLowerCase())
        .filter(value => /^[a-z0-9][a-z0-9._+-]*$/.test(value)))].sort();
}

// 文件类型图标只有一个正式视觉源：结果卡、顶部类型按钮、创建元数据与创建默认设置共用。
// 按钮顺序由 RESULT_FILE_TYPE_ACTIONS 单独定义；视觉映射不再在各模块重复维护。
export const FILE_TYPE_ICONS = Object.freeze({
    note: "file-text",
    canvas: "layout-dashboard",
    excalidraw: "pencil-ruler",
    attachment: "paperclip"
});

export const RESULT_FILE_TYPE_ACTIONS = Object.freeze([
    Object.freeze({ value: "note", label: "笔记", icon: FILE_TYPE_ICONS.note }),
    Object.freeze({ value: "canvas", label: "Canvas", icon: FILE_TYPE_ICONS.canvas }),
    Object.freeze({ value: "excalidraw", label: "Excalidraw", icon: FILE_TYPE_ICONS.excalidraw }),
    Object.freeze({ value: "attachment", label: "其他文件", icon: FILE_TYPE_ICONS.attachment })
]);

export function resultFileTypeAction(kind) {
    return RESULT_FILE_TYPE_ACTIONS.find(def => def.value === kind)
        || RESULT_FILE_TYPE_ACTIONS[RESULT_FILE_TYPE_ACTIONS.length - 1];
}

export function fileTypeFilterDisplay(value) {
    const normalized = normalizeFileTypeFilterValue(value);
    if (!normalized) return "全部";
    if (normalized === "attachment") return "全部附件";
    if (normalized.startsWith("ext:")) return normalized.slice(4).toUpperCase();
    return resultFileTypeAction(normalized).label;
}

export function logicalFileType(meta) {
    const extension = attachmentExtension(meta);
    if (extension === "excalidraw") return "excalidraw";
    if (extension === "canvas") return "canvas";
    if (extension === "md") return "note";
    return "attachment";
}

export function resultFileTypeLabel(meta) {
    const kind = logicalFileType(meta);
    if (kind !== "attachment") return resultFileTypeAction(kind).label;
    const extension = attachmentExtension(meta);
    return extension ? extension.toUpperCase() : "文件";
}

export function resultFileTypeIcon(meta) {
    return resultFileTypeAction(logicalFileType(meta)).icon;
}

export function resultFileTypeDisplay(meta) {
    const label = resultFileTypeLabel(meta);
    const kind = logicalFileType(meta);
    const rawCount = kind === "note"
        ? meta?.textCount
        : kind === "canvas"
            ? meta?.canvasNodeCount
            : kind === "excalidraw"
                ? meta?.excalidrawElementCount
                : null;
    if (rawCount == null) return label;

    const count = Number(rawCount);
    const safeCount = Number.isFinite(count)
        ? Math.max(0, Math.trunc(count))
        : 0;
    return `${label}丨${safeCount}`;
}

export function canvasNodeCountFromContent(content) {
    try {
        const data = JSON.parse(String(content || ""));
        return Array.isArray(data?.nodes) ? data.nodes.length : 0;
    } catch (_) {
        return 0;
    }
}

export const LZ_BASE64_INDEX = new Map(
    [...LZ_BASE64_ALPHABET].map((char, index) => [char, index])
);

// Excalidraw 的 compressed-json 使用 LZString.compressToBase64。
// 这里只保留只读解压所需的最小解码器，避免把计数能力绑定到 Excalidraw 插件生命周期。
export function decompressLzBase64(input) {
    const source = String(input || "").replace(/\s+/g, "");
    if (!source) return null;

    const nextValue = index => {
        const value = LZ_BASE64_INDEX.get(source.charAt(index));
        return Number.isFinite(value) ? value : 0;
    };
    const data = { val: nextValue(0), position: 32, index: 1 };
    const dictionary = [];
    const result = [];
    let enlargeIn = 4;
    let dictSize = 4;
    let numBits = 3;

    for (let index = 0; index < 3; index += 1) {
        dictionary[index] = String(index);
    }

    const readBits = bitCount => {
        let bits = 0;
        let power = 1;
        const maxPower = Math.pow(2, bitCount);
        while (power !== maxPower) {
            const resb = data.val & data.position;
            data.position >>= 1;
            if (data.position === 0) {
                data.position = 32;
                data.val = nextValue(data.index++);
            }
            if (resb > 0) bits |= power;
            power <<= 1;
        }
        return bits;
    };

    let initial = readBits(2);
    let character = "";
    if (initial === 0) character = String.fromCharCode(readBits(8));
    else if (initial === 1) character = String.fromCharCode(readBits(16));
    else if (initial === 2) return "";
    else return null;

    dictionary[3] = character;
    let word = character;
    result.push(character);

    while (true) {
        if (data.index > source.length) return null;

        let code = readBits(numBits);
        if (code === 0) {
            dictionary[dictSize++] = String.fromCharCode(readBits(8));
            code = dictSize - 1;
            enlargeIn -= 1;
        } else if (code === 1) {
            dictionary[dictSize++] = String.fromCharCode(readBits(16));
            code = dictSize - 1;
            enlargeIn -= 1;
        } else if (code === 2) {
            return result.join("");
        }

        if (enlargeIn === 0) {
            enlargeIn = Math.pow(2, numBits);
            numBits += 1;
        }

        let entry = dictionary[code];
        if (entry === undefined) {
            if (code !== dictSize) return null;
            entry = word + word.charAt(0);
        }

        result.push(entry);
        dictionary[dictSize++] = word + entry.charAt(0);
        enlargeIn -= 1;
        word = entry;

        if (enlargeIn === 0) {
            enlargeIn = Math.pow(2, numBits);
            numBits += 1;
        }
    }
}

export function excalidrawSceneFromContent(content) {
    const source = String(content || "");
    const trimmed = source.trim();

    // 兼容 legacy .excalidraw 纯 JSON。
    if (trimmed.startsWith("{")) {
        try {
            const scene = JSON.parse(trimmed);
            if (Array.isArray(scene?.elements)) return scene;
        } catch (_) {
            // 继续尝试 Markdown Drawing block。
        }
    }

    const heading = source.match(/^#{1,2}\s+Drawing\s*$/im);
    const drawingSource = heading
        ? source.slice((heading.index || 0) + heading[0].length)
        : source;
    const block = drawingSource.match(
        /```(json|compressed-json)\s*\r?\n([\s\S]*?)```/i
    );
    if (!block) return null;

    let jsonText = block[2].trim();
    if (String(block[1]).toLowerCase() === "compressed-json") {
        jsonText = decompressLzBase64(jsonText);
    }
    if (!jsonText) return null;

    try {
        const scene = JSON.parse(jsonText);
        return Array.isArray(scene?.elements) ? scene : null;
    } catch (_) {
        return null;
    }
}

export function excalidrawElementCountFromContent(content) {
    const scene = excalidrawSceneFromContent(content);
    if (!scene) return null;
    return scene.elements.reduce(
        (count, element) => count + (element && element.isDeleted !== true ? 1 : 0),
        0
    );
}

export function resultFileTypeFilterValue(meta) {
    const kind = logicalFileType(meta);
    if (kind !== "attachment") return kind;

    const extension = attachmentExtension(meta);
    return extension ? `ext:${extension}` : "attachment";
}

// 结果卡 / 搜索索引 / 工作台共享的纯标题规则；旧版绘图继续兼容原物理路径。
export function drawingBasenameSuffix(file, logicalExtension) {
    if (logicalExtension !== "excalidraw" || file.extension.toLowerCase() !== "md") return "";
    if (file.basename.toLowerCase().endsWith(".excalidraw")) return ".excalidraw";
    if (file.basename.endsWith(EXCALIDRAW_DRAWING_SUFFIX)) return EXCALIDRAW_DRAWING_SUFFIX;
    return "";
}

export function displayBasename(file, logicalExtension) {
    const suffix = drawingBasenameSuffix(file, logicalExtension);
    return suffix && file.basename.length > suffix.length
        ? file.basename.slice(0, -suffix.length) : file.basename;
}

export function mergeTextRanges(ranges) {
    const normalized = ranges
        .filter(range => Array.isArray(range) && range.length === 2 && range[1] > range[0])
        .sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    const merged = [];
    for (const [start, end] of normalized) {
        const previous = merged[merged.length - 1];
        if (previous && start <= previous[1]) {
            previous[1] = Math.max(previous[1], end);
        } else {
            merged.push([start, end]);
        }
    }
    return merged;
}

// 搜索命中展示只有一套正式渲染路径：普通文本 + 命中文字颜色。
// 标题、正文摘要、标签全部复用此函数，禁止各自维护背景 / padding / 圆角等高亮实现。
export function fillSearchHitText(element, text, ranges) {
    if (!isDomElement(element)) return;
    const source = String(text || "");
    const validRanges = mergeTextRanges(ranges || [])
        .filter(([start, end]) => start >= 0 && end <= source.length);

    element.empty();
    if (!validRanges.length) {
        element.textContent = source;
        return;
    }

    let cursor = 0;
    for (const [start, end] of validRanges) {
        if (start > cursor) {
            element.append(element.ownerDocument.createTextNode(source.slice(cursor, start)));
        }
        element.createEl("mark", {
            text: source.slice(start, end),
            cls: "local-search-hit"
        });
        cursor = end;
    }
    if (cursor < source.length) {
        element.append(element.ownerDocument.createTextNode(source.slice(cursor)));
    }
}

// 标签搜索本身采用“查询单元包含”语义；展示层与同一 QueryState 保持一致。
// 这里只计算显示区间，不参与搜索判定，不新增第二套匹配状态。
export function tagQueryMatchRanges(text, query) {
    if (!query?.active) return [];
    const source = String(text || "");
    const lower = source.toLowerCase();
    const ranges = [];
    for (const unit of query.units || []) {
        if (!unit) continue;
        let from = 0;
        while (from <= lower.length - unit.length) {
            const start = lower.indexOf(unit, from);
            if (start < 0) break;
            ranges.push([start, start + unit.length]);
            from = start + Math.max(1, unit.length);
        }
    }
    return mergeTextRanges(ranges);
}

export function substringMatchRange(text, query) {
    if (!query) return null;
    const at = text.indexOf(query);
    return at < 0 ? null : [at, at + query.length];
}

export function unitMatchRanges(text, units) {
    const ranges = [];
    for (const unit of units) {
        const range = substringMatchRange(text, unit);
        if (!range) return null;
        ranges.push(range);
    }
    return mergeTextRanges(ranges);
}

// 多搜索单元命中时寻找覆盖全部单元的最短窗口，而不是机械使用每个单元的首次出现位置。
export function compactUnitMatchRanges(text, units) {
    const normalizedUnits = [...new Set((units || []).filter(Boolean))];
    if (!normalizedUnits.length) return null;
    if (normalizedUnits.length === 1) {
        const range = substringMatchRange(text, normalizedUnits[0]);
        return range ? [range] : null;
    }

    const occurrences = [];
    normalizedUnits.forEach((unit, unitIndex) => {
        let from = 0;
        while (from <= text.length - unit.length) {
            const start = text.indexOf(unit, from);
            if (start < 0) break;
            occurrences.push({ unitIndex, start, end: start + unit.length });
            from = start + Math.max(1, unit.length);
        }
    });
    if (!occurrences.length) return null;
    occurrences.sort((a, b) => a.start - b.start || a.end - b.end);

    const counts = new Array(normalizedUnits.length).fill(0);
    const maxEndDeque = [];
    let covered = 0;
    let left = 0;
    let best = null;

    for (let right = 0; right < occurrences.length; right++) {
        const current = occurrences[right];
        if (counts[current.unitIndex]++ === 0) covered++;
        while (maxEndDeque.length && occurrences[maxEndDeque[maxEndDeque.length - 1]].end <= current.end) {
            maxEndDeque.pop();
        }
        maxEndDeque.push(right);

        while (covered === normalizedUnits.length && left <= right) {
            const first = occurrences[left];
            const spanStart = first.start;
            const spanEnd = occurrences[maxEndDeque[0]].end;
            if (!best || (spanEnd - spanStart) < (best.end - best.start)) {
                best = { left, right, start: spanStart, end: spanEnd };
            }
            if (--counts[first.unitIndex] === 0) covered--;
            if (maxEndDeque[0] === left) maxEndDeque.shift();
            left++;
        }
    }
    if (!best) return null;

    const selected = [];
    const seen = new Set();
    for (let i = best.left; i <= best.right; i++) {
        const occurrence = occurrences[i];
        if (seen.has(occurrence.unitIndex)) continue;
        seen.add(occurrence.unitIndex);
        selected.push([occurrence.start, occurrence.end]);
    }
    return selected.length === normalizedUnits.length ? mergeTextRanges(selected) : null;
}

export function orderedMatchRanges(text, query) {
    if (!query) return [];
    const ranges = [];
    let at = 0;
    for (const ch of query) {
        const found = text.indexOf(ch, at);
        if (found < 0) return null;
        ranges.push([found, found + ch.length]);
        at = found + ch.length;
    }
    return mergeTextRanges(ranges);
}

// 正文的非连续顺序匹配比标题更严格：
// 1) 总跨度必须紧凑；2) 至少存在一个连续的多字符片段。
// 避免长正文里“无…效…代…码”这种逐字偶然出现被判成有效结果。
export function compactOrderedBodyMatchRanges(text, query) {
    const ranges = orderedMatchRanges(text, query);
    if (!ranges?.length) return null;

    const span = ranges[ranges.length - 1][1] - ranges[0][0];
    const queryLength = Array.from(query || "").length;
    const maxSpan = Math.max(12, queryLength * 4);
    if (span > maxSpan) return null;

    if (queryLength >= 3) {
        const hasMeaningfulFragment = ranges.some(([start, end]) => end - start >= 2);
        if (!hasMeaningfulFragment) return null;
    }

    return ranges;
}

// 正文搜索与搜索摘要共用唯一匹配模型。
// 优先级：完整短语 > 多单元最短共同窗口 > 紧凑片段式顺序匹配。
export function matchReadableText(text, query) {
    if (!text || !query?.active) return null;
    const phraseRange = substringMatchRange(text, query.intent);
    if (phraseRange) return { type: "phrase", ranges: [phraseRange] };

    if (query.units.length > 1) {
        const compactRanges = compactUnitMatchRanges(text, query.units);
        if (compactRanges) return { type: "units", ranges: compactRanges };
        return null;
    }

    const orderedRanges = compactOrderedBodyMatchRanges(text, query.intent);
    return orderedRanges ? { type: "ordered", ranges: orderedRanges } : null;
}

export function _findSnippetStartBoundary(text, start, matchStart) {
    // 只在“少量前文预算”内寻找离命中最近的自然边界。
    // 从后向前找，避免为了句界把摘要起点推回很远。
    const hardBoundary = /[。！？!?；;\n]/;
    for (let i = matchStart - 1; i >= start; i--) {
        if (hardBoundary.test(text[i])) return i + 1;
    }
    return start;
}

export function _findSnippetEndBoundary(text, end, radius = 24) {
    const hardBoundary = /[。！？!?；;\n]/;
    const max = Math.min(text.length, end + radius);
    for (let i = end; i < max; i++) {
        if (hardBoundary.test(text[i])) return i + 1;
    }
    return end;
}

export function buildSnippetWindow(text, matchRanges, maxLen = 200) {
    const cleanText = String(text || "");
    const limit = Math.max(40, Number.parseInt(String(maxLen), 10) || 200);
    const ranges = mergeTextRanges(matchRanges || [])
        .filter(([start, end]) => start >= 0 && end <= cleanText.length);

    if (!ranges.length) {
        const snippetText = cleanText.slice(0, limit);
        return {
            text: snippetText + (cleanText.length > limit ? "…" : ""),
            ranges: []
        };
    }

    const matchStart = ranges[0][0];
    const matchEnd = ranges[ranges.length - 1][1];
    const matchSpan = Math.max(1, matchEnd - matchStart);
    let start;
    let end;

    if (matchSpan < limit) {
        // 搜索摘要不是正文预览，而是“命中解释”：
        // 命中前只保留固定、很短的语境，不再按摘要长度百分比居中。
        // 这样 CSS 即使只显示三行，真正的命中也会稳定出现在可见前部。
        const beforeBudget = Math.min(24, Math.max(0, limit - matchSpan));
        start = Math.max(0, matchStart - beforeBudget);
        start = _findSnippetStartBoundary(cleanText, start, matchStart);

        end = Math.min(cleanText.length, start + limit);
        if (end < matchEnd) end = matchEnd;

        // 仅在不会明显拉长摘要时补到自然句界；所有额外空间都给命中后文。
        const naturalEnd = _findSnippetEndBoundary(cleanText, end, 24);
        if (naturalEnd > end && naturalEnd - start <= Math.floor(limit * 1.12)) {
            end = naturalEnd;
        }
    } else {
        // 极端长匹配跨度无法完整塞入一个摘要时，优先选择实际命中密度最高的窗口；
        // 每个候选窗口同样只给命中前保留少量语境。
        const beforeBudget = Math.min(24, Math.floor(limit * 0.15));
        let bestStart = Math.max(0, Math.min(matchStart - beforeBudget, cleanText.length - limit));
        let bestScore = -1;
        const candidates = new Set([bestStart]);
        for (const [rangeStart, rangeEnd] of ranges) {
            candidates.add(Math.max(0, Math.min(rangeStart - beforeBudget, cleanText.length - limit)));
            candidates.add(Math.max(0, Math.min(rangeEnd - Math.max(1, limit - beforeBudget), cleanText.length - limit)));
        }
        for (const candidate of candidates) {
            const candidateEnd = candidate + limit;
            let score = 0;
            for (const [rangeStart, rangeEnd] of ranges) {
                score += Math.max(0, Math.min(rangeEnd, candidateEnd) - Math.max(rangeStart, candidate));
            }
            if (score > bestScore) {
                bestScore = score;
                bestStart = candidate;
            }
        }
        start = bestStart;
        end = Math.min(cleanText.length, start + limit);
    }

    const prefix = start > 0 ? "…" : "";
    const suffix = end < cleanText.length ? "…" : "";
    const offset = prefix.length - start;
    const localRanges = [];
    for (const [rangeStart, rangeEnd] of ranges) {
        const clippedStart = Math.max(start, rangeStart);
        const clippedEnd = Math.min(end, rangeEnd);
        if (clippedEnd > clippedStart) {
            localRanges.push([clippedStart + offset, clippedEnd + offset]);
        }
    }

    return {
        text: prefix + cleanText.slice(start, end) + suffix,
        ranges: mergeTextRanges(localRanges)
    };
}

// 标签筛选的“没有标签”是筛选状态，不是真实标签。
// 语义：Frontmatter 标签 + 正文 inline 标签合并后，实际标签数量为 0。
export const NO_TAGS_FILTER_VALUE = "␟__LS_NO_TAGS_FILTER_VALUE__␟";

// 属性值唯一语义模型：筛选、分面计数、结果展示、结果点击全部只走这一套。
// “没有此属性”与“有属性但无值”使用不同内部哨兵，且都不会与用户真实文本发生碰撞。
export const MISSING_PROPERTY_VALUE = "␟__LS_MISSING_PROPERTY_VALUE__␟";

export function propertyValueDisplay(value) {
    if (value === MISSING_PROPERTY_VALUE) return "[没有此属性]";
    if (value === EMPTY_PROPERTY_VALUE) return "[有属性但无值]";
    if (value === PRESENT_PROPERTY_VALUE) return "含有此属性";
    return String(value);
}

// UI 摘要使用更自然的纯文本语义；内部哨兵仍保持原模型，避免把显示格式泄漏到业务逻辑。
export function propertyValuePlainDisplay(value) {
    if (value === MISSING_PROPERTY_VALUE) return "没有此属性";
    if (value === EMPTY_PROPERTY_VALUE) return "有属性但无值";
    if (value === PRESENT_PROPERTY_VALUE) return "含有此属性";
    return String(value);
}

// 特殊状态在属性 Picker 中使用更紧凑的短标签；
// 仅改变显示文本，筛选值仍复用统一哨兵模型。
export function propertySpecialInlineDisplay(value) {
    if (value === MISSING_PROPERTY_VALUE) return "没有此属性";
    if (value === EMPTY_PROPERTY_VALUE) return "有属性空值";
    return propertyValuePlainDisplay(value);
}

// 主筛选 Chip 对普通真实值保留原来的 [值] 视觉；特殊状态不再产生双层方括号。
export function propertyFilterChipValueDisplay(value) {
    if (
        value === MISSING_PROPERTY_VALUE
        || value === EMPTY_PROPERTY_VALUE
        || value === PRESENT_PROPERTY_VALUE
    ) return propertyValuePlainDisplay(value);
    return `[${propertyValuePlainDisplay(value)}]`;
}

export function propertyValueSortRank(value) {
    if (value === MISSING_PROPERTY_VALUE) return 0;
    if (value === EMPTY_PROPERTY_VALUE) return 1;
    return 2;
}

export function propertyValueKey(value) {
    if (
        value === MISSING_PROPERTY_VALUE
        || value === EMPTY_PROPERTY_VALUE
        || value === PRESENT_PROPERTY_VALUE
    ) return value;
    return String(value).trim().toLocaleLowerCase("zh-CN");
}

export function isSpecialPropertyValue(value) {
    return value === MISSING_PROPERTY_VALUE
        || value === EMPTY_PROPERTY_VALUE;
}

export function isExclusivePropertySelectionValue(value) {
    return value === PRESENT_PROPERTY_VALUE
        || isSpecialPropertyValue(value);
}

// 属性选择的唯一归一规则：
// - 真实值可同键多选（OR）；
// - “含有此属性 / 没有此属性 / 有属性空值”都是独占状态；
// - 旧状态若混入独占态与真实值，由独占态接管，避免运行期出现互相矛盾的筛选集合。
export function normalizePropertySelection(values = []) {
    const source = values instanceof Set
        ? [...values]
        : (Array.isArray(values) ? values : [values]);
    const normalValues = [];
    const seen = new Set();
    let exclusiveValue;

    for (const value of source) {
        if (value === undefined || value === null) continue;
        const id = propertyValueKey(value);
        if (!id || seen.has(id)) continue;
        seen.add(id);
        if (isExclusivePropertySelectionValue(value)) {
            if (exclusiveValue === undefined) exclusiveValue = value;
            continue;
        }
        normalValues.push(value);
    }

    return exclusiveValue !== undefined
        ? new Set([exclusiveValue])
        : new Set(normalValues);
}

// CreateDraft 只保留真正能够写入 Frontmatter 的属性值。
// 查询结构态（存在 / 缺失 / 空值）永远不进入新文件；真实值保持原有集合，
// 单值 / 多值约束由 Obsidian Property Type 在创建交互与最终落盘时统一决定。
export function materializableCreatePropertySelections(properties) {
    const source = properties instanceof Map ? properties : new Map();
    return new Map(
        [...source.entries()].flatMap(([key, values]) => {
            const normalized = normalizePropertySelection(values || []);
            const realValues = [...normalized].filter(value =>
                value !== PRESENT_PROPERTY_VALUE
                && !isSpecialPropertyValue(value)
            );
            return realValues.length
                ? [[key, new Set(realValues)]]
                : [];
        })
    );
}

export function normalizeCreateType(value, fallback = "md") {
    const type = String(value || "").trim().toLowerCase();
    return CREATE_TYPE_IDS.includes(type) ? type : fallback;
}

export function createTypeFromFileType(fileType, fallback = "md") {
    const value = String(fileType || "").trim().toLowerCase();
    if (value === "canvas") return "canvas";
    if (value === "excalidraw") return "excalidraw";
    if (value === "note") return "md";
    return normalizeCreateType(fallback);
}

export function fileTypeFromCreateType(type) {
    const value = normalizeCreateType(type);
    return value === "canvas"
        ? "canvas"
        : (value === "excalidraw" ? "excalidraw" : "note");
}

export function normalizeCreatePropertyTypes(value) {
    const entries = value instanceof Map ? [...value] : (Array.isArray(value) ? value : []);
    const result = new Map();
    for (const entry of entries) {
        if (!Array.isArray(entry) || entry.length < 2) continue;
        try {
            const key = validateEditablePropertyKey(entry[0]);
            result.set(key, normalizeMetadataPropertyType(entry[1]));
        } catch (_) { /* Ignore invalid recovered draft metadata. */ }
    }
    return result;
}

export function normalizeCreateMetadataMemory(value) {
    const source = value && typeof value === "object" ? value : {};
    const result = {};
    for (const type of CREATE_TYPE_IDS) {
        const raw = source[type] && typeof source[type] === "object"
            ? source[type]
            : {};
        const snapshot = FilterState.normalizeSnapshot({
            tags: raw.tags,
            properties: raw.properties,
            fileType: fileTypeFromCreateType(type)
        });
        const state = FilterState.fromSnapshot(snapshot);
        state.tags = new Set(
            normalizeFilterTagSelection(state.tags)
                .filter(tag => tag !== NO_TAGS_FILTER_VALUE)
        );
        state.properties = materializableCreatePropertySelections(
            state.properties
        );
        const clean = state.toSnapshot();
        const rawFolder = String(raw.folder || "").trim();
        const folder = rawFolder === "/"
            ? ""
            : normalizeVaultFolderPath(rawFolder);
        const templateSource = raw.template && typeof raw.template === "object"
            ? raw.template
            : {};
        const templatePath = String(templateSource.path || "").trim();
        result[type] = {
            folder,
            tags: clean.tags,
            properties: clean.properties,
            propertyTypes: [...normalizeCreatePropertyTypes(raw.propertyTypes)]
                .filter(([key]) => state.properties.has(key)),
            template: {
                enabled: !!templateSource.enabled && !!templatePath,
                path: templatePath
            }
        };
    }
    return result;
}

export function filterPoolLabel(pool) {
    if (!pool) return "筛选池";
    return FILTER_POOL_FIXED_DEFS.find(def => def.kind === pool.kind)?.label || "筛选池";
}

export function filterPoolIcon(pool) {
    return pool?.icon || FILTER_POOL_FIXED_DEFS.find(def => def.kind === pool?.kind)?.icon || "filter";
}

export function createTemplateFilesForType(app, type) {
    const allFiles = app?.vault?.getFiles?.() || [];
    if (type === "canvas") {
        return allFiles.filter(file => file.extension.toLowerCase() === "canvas");
    }
    if (type === "excalidraw") {
        return allFiles.filter(file =>
            isExcalidrawMeta(file, app.metadataCache.getFileCache(file))
        );
    }
    return allFiles.filter(file =>
        file.extension.toLowerCase() === "md"
        && !isExcalidrawMeta(file, app.metadataCache.getFileCache(file))
    );
}

export function orderTemplateFilesForPicker(files, favoritePaths) {
    const favorites = new Set(normalizeUniqueStringList(favoritePaths));
    return [...files].sort((a, b) => {
        const af = favorites.has(a.path);
        const bf = favorites.has(b.path);
        if (af !== bf) return af ? -1 : 1;
        return a.path.localeCompare(b.path, "zh-Hans-CN", { numeric: true });
    });
}

export function openTemplateFilePicker(core, {
    anchor,
    type,
    label,
    icon,
    title = `${label} 模板`,
    child = false,
    panelClasses = "",
    getSelection = () => ({ enabled: false, path: "" }),
    onSelect = null
} = {}) {
    if (!core?.dropdown || !isDomHTMLElement(anchor)) return null;
    const panel = child
        ? core.dropdown.openChild(anchor, title)
        : core.dropdown.open(anchor, title);
    if (!panel) return null;

    panel.addClass(
        "local-search-picker-dropdown",
        "local-search-facet-picker"
    );
    for (const cls of String(panelClasses || "").split(/\s+/).filter(Boolean)) {
        panel.addClass(cls);
    }

    configureSharedPickerHeader(panel, {
        headingText: title,
        icon
    });
    const { search, list } = createSharedPickerTreeShell(panel, {
        placeholder: "搜索模板文件…",
        showRoot: false
    });

    // Vault 扫描只在 Picker 打开时执行一次；搜索只过滤内存数组，收藏变化时才重排一次。
    const files = createTemplateFilesForType(core.app, type);
    let orderedFiles = [];
    const refreshOrder = () => {
        orderedFiles = orderTemplateFilesForPicker(
            files,
            core.plugin.settings.favoriteTemplatePaths
        );
    };
    refreshOrder();

    const choose = async selection => {
        core.dropdown.close(false);
        await onSelect?.({
            enabled: !!selection?.enabled,
            path: selection?.enabled ? String(selection?.path || "") : ""
        });
    };

    const render = () => {
        list.empty();
        const query = search.value.trim().toLocaleLowerCase("zh-CN");
        const selection = getSelection?.() || { enabled: false, path: "" };
        const currentPath = String(selection.path || "");
        const favorites = normalizeUniqueStringList(
            core.plugin.settings.favoriteTemplatePaths
        );
        const favoriteSet = new Set(favorites);

        if (!query || "不使用模板".includes(query)) {
            createSharedPickerTreeRow(list, {
                active: !selection.enabled,
                icon: "ban",
                name: "不使用模板",
                itemTitle: child
                    ? `新建 ${label} 时不使用模板`
                    : `本次新建 ${label} 不使用模板`,
                onClick: () => void choose({ enabled: false, path: "" }),
                restoreFocus: false
            });
        }

        const rows = orderedFiles.filter(file =>
            !query
            || file.name.toLocaleLowerCase("zh-CN").includes(query)
            || file.path.toLocaleLowerCase("zh-CN").includes(query)
        );

        for (const file of rows) {
            const favorite = favoriteSet.has(file.path);
            createSharedPickerTreeRow(list, {
                active: !!selection.enabled && currentPath === file.path,
                icon,
                name: file.basename || file.name,
                itemTitle: file.path,
                onClick: () => void choose({ enabled: true, path: file.path }),
                renderTrailing: row => {
                    const favoriteAction = createPickerRowAction(row, {
                        icon: "star",
                        label: favorite
                            ? `取消收藏模板 ${file.basename || file.name}`
                            : `收藏模板 ${file.basename || file.name}`,
                        onClick: () => {
                            const current = normalizeUniqueStringList(
                                core.plugin.settings.favoriteTemplatePaths
                            );
                            core.plugin.settings.favoriteTemplatePaths = favorite
                                ? current.filter(path => path !== file.path)
                                : normalizeUniqueStringList([...current, file.path]);
                            void core.plugin.saveSettings();
                            refreshOrder();
                            render();
                            core.dropdown.reposition();
                        }
                    });
                    favoriteAction.classList.add("is-template-favorite-action");
                    favoriteAction.classList.toggle("is-selected", favorite);
                    favoriteAction.setAttribute("aria-pressed", String(favorite));
                },
                restoreFocus: false
            });
        }

        if (!rows.length && query) {
            list.createDiv({
                cls: "local-search-empty-hint",
                text: "没有匹配的模板文件"
            });
        }
    };

    search.addEventListener("input", render);
    render();
    return panel;
}

export function filterPoolValueKey(pool, value) {
    if (!pool) return "";
    if (pool.kind === "property") return propertyValueKey(value);
    if (pool.kind === "tag") {
        return value === NO_TAGS_FILTER_VALUE
            ? NO_TAGS_FILTER_VALUE
            : tagIdentityKey(value);
    }
    if (pool.kind === "folder") {
        const raw = String(value || "").trim();
        return raw === "/" ? "/" : normalizeVaultFolderPath(raw);
    }
    return String(value || "").trim().toLowerCase();
}

export function filterPoolValueDisplay(pool, value) {
    if (!pool) return String(value || "");
    if (pool.kind === "property") return propertyValuePlainDisplay(value);
    if (pool.kind === "tag") {
        return value === NO_TAGS_FILTER_VALUE ? "没有标签" : String(value || "");
    }
    if (pool.kind === "folder") {
        return value === "/" ? "根目录" : String(value || "");
    }
    const def = RESULT_FILE_TYPE_ACTIONS.find(item => item.value === value);
    return def?.label || String(value || "");
}

export function filterPoolValueVisible(pool, key) {
    if (pool?.kind === "property") return false;
    const valueKey = String(key || "");
    if (!valueKey) return false;
    if (pool?.showAllValues) {
        return !(pool.hiddenValueKeys || []).includes(valueKey);
    }
    return (pool?.visibleValueKeys || []).includes(valueKey);
}

export function propertyPoolEntry(pool, key) {
    const propertyKey = String(key || "").trim();
    if (!propertyKey || pool?.kind !== "property") {
        return normalizePropertyPoolEntry();
    }
    return normalizePropertyPoolEntry(
        pool.propertyEntries?.[propertyKey]
    );
}

export function propertyPoolKeyVisible(pool, key) {
    if (pool?.autoIncludeKeys) return !(pool.hiddenKeyNames || []).includes(key);
    return propertyPoolEntry(pool, key).showKey;
}

export function moveOrderedKey(order, key, beforeKey = null) {
    const source = normalizeUniqueStringList(order);
    if (!key || !source.includes(key)) return source;
    const next = source.filter(item => item !== key);
    const beforeIndex = beforeKey ? next.indexOf(beforeKey) : -1;
    if (beforeIndex >= 0) next.splice(beforeIndex, 0, key);
    else next.push(key);
    return next;
}

// 只规范化“已存在属性”的原始值；缺失属性绝不从这里伪造成空值。
export function normalizePropertyValues(raw) {
    const out = [];
    const seen = new Set();
    const push = (value) => {
        if (Array.isArray(value)) {
            if (value.length === 0) push(null);
            else for (const item of value) push(item);
            return;
        }
        let normalized;
        if (value === null || value === undefined) normalized = EMPTY_PROPERTY_VALUE;
        else if (typeof value === "string") normalized = value.trim() || EMPTY_PROPERTY_VALUE;
        else if (typeof value === "number" || typeof value === "boolean") normalized = String(value);
        else return; // 不把对象/复杂 YAML 结构强转为 [object Object] 污染筛选值。
        const key = propertyValueKey(normalized);
        if (!seen.has(key)) {
            seen.add(key);
            out.push(normalized);
        }
    };
    push(raw);
    return out;
}

// 属性原始值到“筛选语义值”的唯一入口。
// 空字符串/null/空数组只有在整项没有任何真实值时才归入“有属性空值”；
// 一旦同一属性里存在任意真实值，空占位不再与真实值并存。
// 复杂对象仍保持不可筛选，不伪造成空值。
export function propertyValuesFromRaw(raw) {
    const normalized = normalizePropertyValues(raw);
    const realValues = normalized.filter(
        value => value !== EMPTY_PROPERTY_VALUE
    );
    if (realValues.length) return realValues;
    return normalized.includes(EMPTY_PROPERTY_VALUE)
        ? [EMPTY_PROPERTY_VALUE]
        : [];
}

// 列表写入统一展平历史嵌套数组；可选保留空数组语义。
export function flattenPropertyListStructure(rawValue, preserveEmptyArrays = false) {
    const out = [];
    const visit = value => {
        if (Array.isArray(value)) {
            if (!value.length) {
                if (preserveEmptyArrays) out.push(null);
                return;
            }
            for (const item of value) visit(item);
            return;
        }
        if (value !== undefined) out.push(value);
    };
    visit(rawValue);
    return out;
}

export function rawSampleForPropertyValue(rawValue, normalizedValue) {
    const wantedKey = propertyValueKey(normalizedValue);
    let found = false;
    let sample;

    const visit = value => {
        if (found) return;
        if (Array.isArray(value)) {
            if (value.length === 0 && normalizedValue === EMPTY_PROPERTY_VALUE) {
                found = true;
                sample = null;
                return;
            }
            for (const item of value) visit(item);
            return;
        }

        if (normalizePropertyValues(value).some(
            normalized => propertyValueKey(normalized) === wantedKey
        )) {
            found = true;
            sample = value;
        }
    };

    visit(rawValue);
    if (found) return sample;
    return normalizedValue === EMPTY_PROPERTY_VALUE ? null : undefined;
}

// Frontmatter 状态同时比较“键是否存在”和“值是什么”。
export function frontmatterPropertyStateEqual(
    beforePresent,
    beforeValue,
    afterPresent,
    afterValue
) {
    if (Boolean(beforePresent) !== Boolean(afterPresent)) return false;
    if (!beforePresent) return true;
    return JSON.stringify(beforeValue) === JSON.stringify(afterValue);
}

export function metaHasProperty(meta, key) {
    const properties = meta?.properties || {};
    return Object.prototype.hasOwnProperty.call(properties, key);
}

export function propertyValuesFromMeta(meta, key) {
    const properties = meta?.properties || {};
    if (!metaHasProperty(meta, key)) return [MISSING_PROPERTY_VALUE];
    return propertyValuesFromRaw(properties[key]);
}

export function propertySelectionMatches(meta, key, wantedValues) {
    const properties = meta?.properties || {};
    const hasProperty = Object.prototype.hasOwnProperty.call(properties, key);
    let actualKeys = null;

    for (const value of wantedValues || []) {
        if (value === PRESENT_PROPERTY_VALUE) {
            if (hasProperty) return true;
            continue;
        }
        if (!actualKeys) {
            actualKeys = new Set(
                propertyValuesFromMeta(meta, key).map(propertyValueKey)
            );
        }
        if (actualKeys.has(propertyValueKey(value))) return true;
    }
    return false;
}

export function buildPropertyUsageStats(
    candidates,
    key,
    selectedValues = [],
    knownValues = []
) {
    const canonical = new Map();
    if (key === "所属项目") for (const value of knownValues) {
        if (typeof value === "string" && !isSpecialPropertyValue(value)) canonical.set(value.toLocaleLowerCase(), value);
    }
    const display = value => key === "所属项目" && typeof value === "string" && !isSpecialPropertyValue(value)
        ? (canonical.get(value.toLocaleLowerCase()) || value) : value;
    const identities = new Map();
    const valueId = value => {
        if (!identities.has(value)) identities.set(value, propertyValueKey(display(value)));
        return identities.get(value);
    };
    const absent = Symbol("missing-property");
    const normalizedByRaw = new Map();
    const selectedByRaw = new Map();
    const counts = new Map();
    const valueMap = new Map();
    const selected = [...normalizePropertySelection(selectedValues)];
    const hasSelection = selected.length > 0;
    const presenceSelected = selected.some(
        value => value === PRESENT_PROPERTY_VALUE
    );
    const selectedSpecialValue = selected.find(isSpecialPropertyValue);
    const selectedSpecialId = selectedSpecialValue === undefined
        ? ""
        : valueId(selectedSpecialValue);
    const selectedOverlapCounts = new Map();
    let present = 0;
    let selectedMatchCount = 0;

    // 单次扫描同时产出：
    // 1) 属性/值原始使用量；
    // 2) 当前同键 OR 选择的命中数；
    // 3) 每个值与当前选择的重叠数。
    // Picker 因此可以直接算“再加入该值”的 OR 投影，不需要逐行重扫候选集。
    for (const meta of candidates || []) {
        const hasProperty = metaHasProperty(meta, key);
        if (hasProperty) present++;
        const raw = hasProperty ? meta.properties[key] : absent;
        if (!normalizedByRaw.has(raw)) normalizedByRaw.set(raw, propertyValuesFromMeta(meta, key));
        const values = normalizedByRaw.get(raw);
        const valueIds = new Set();
        for (const value of values) {
            const id = valueId(value);
            if (valueIds.has(id)) continue;
            valueIds.add(id);
            if (!valueMap.has(id)) valueMap.set(id, display(value));
            counts.set(id, (counts.get(id) || 0) + 1);
        }

        if (hasSelection && !selectedByRaw.has(raw)) selectedByRaw.set(raw, propertySelectionMatches(meta, key, selected));
        if (hasSelection && selectedByRaw.get(raw)) {
            selectedMatchCount++;
            for (const id of valueIds) {
                selectedOverlapCounts.set(
                    id,
                    (selectedOverlapCounts.get(id) || 0) + 1
                );
            }
        }
    }

    // Picker 可能展示“完整属性值宇宙”里的值，而当前候选域内 rawCount 恰好为 0。
    // 这些可见值仍必须进入同一 Projection Map：真实值模式计算同键 OR；
    // 互斥结构状态与真实值之间则直接复用 rawCount 作为 REPLACE Projection。
    // 不为切换交互另建统计链，也不逐行重复扫描候选集。
    for (const knownValue of knownValues || []) {
        if (knownValue === PRESENT_PROPERTY_VALUE) continue;
        const id = valueId(knownValue);
        if (!valueMap.has(id)) valueMap.set(id, display(knownValue));
    }
    for (const selectedValue of selected) {
        if (selectedValue === PRESENT_PROPERTY_VALUE) continue;
        const id = valueId(selectedValue);
        if (!valueMap.has(id)) valueMap.set(id, display(selectedValue));
    }

    const projectedCounts = new Map();
    for (const [id, value] of valueMap) {
        const rawCount = counts.get(id) || 0;
        let projected = rawCount;

        if (hasSelection && !presenceSelected) {
            if (selectedSpecialValue !== undefined) {
                // 结构状态与其它同键候选在数据上互斥，但交互允许直接切换。
                // 当前结构状态显示当前 Draft 命中数；其它结构状态/真实值显示
                // “用该候选替换当前键选择”后的结果数。候选域已经忽略当前键，
                // 所以 rawCount 正好就是 REPLACE Projection，无需第二次扫描。
                projected = id === selectedSpecialId
                    ? selectedMatchCount
                    : rawCount;
            } else if (isSpecialPropertyValue(value)) {
                // 当前是真实值 OR 模式；点击结构状态会原子替换整个键，
                // 因此这里同样显示 REPLACE Projection，而不是错误裁成 0。
                projected = rawCount;
            } else {
                // 同键真实值继续保持 OR Projection。
                projected = selectedMatchCount
                    + rawCount
                    - (selectedOverlapCounts.get(id) || 0);
            }
        }

        projectedCounts.set(id, projected);
    }

    const values = [...valueMap.values()].sort((a, b) =>
        propertyValueSortRank(a) - propertyValueSortRank(b)
        || propertyValueDisplay(a).localeCompare(propertyValueDisplay(b), "zh-Hans-CN", { numeric: true })
    );
    return {
        present,
        counts,
        values,
        selectedMatchCount,
        projectedCounts,
        projectedKeyCount: hasSelection ? selectedMatchCount : present
    };
}

export function createSharedPickerTreeRow(list, {
    depth = 0,
    rowClasses = "",
    active = false,
    hasChildren = false,
    expanded = false,
    toggleTitle = "",
    itemClasses = "",
    itemTitle = "",
    icon = "tag",
    name = "",
    count = null,
    countClasses = "",
    countPlacement = "row-end",
    onToggle = null,
    onIconClick = null,
    onClick = null,
    renderTrailing = null,
    staticItem = false,
    restoreFocus = true,
    sortKey = "",
    sortParent = "",
    sortPromoteParent = "",
    sortName = "",
    sortDisabled = false
} = {}) {
    const previousRow = list.lastElementChild;
    const row = list.createDiv({ cls: `local-search-move-tree-row ${rowClasses}`.trim() });
    row.dataset.treeDepth = String(depth);
    // Flat rows keep the sort owner intact; guide segments join across each ancestor level.
    for (const guide of previousRow?.querySelectorAll(":scope > .local-search-tree-guide") || []) {
        if (Number(guide.dataset.level) <= depth) guide.classList.remove("is-end");
    }
    for (let level = 1; level <= depth; level++) {
        const guide = row.createSpan({
            cls: `local-search-tree-guide is-end${Number(previousRow?.dataset.treeDepth || 0) < level ? " is-start" : ""}`,
            attr: { "aria-hidden": "true" }
        });
        guide.dataset.level = String(level);
        guide.style.setProperty("--ls-guide-level", String(level));
    }
    const footerOption = Boolean(list.closest(".local-search-picker-footer"));
    if (footerOption) row.addClass("is-footer-option");
    row.style.setProperty("--ls-move-depth", String(depth));
    if (sortKey) {
        row.dataset.sortKey = sortKey;
        row.dataset.sortDepth = String(depth);
        row.dataset.sortParent = sortParent || "";
        row.dataset.sortPromoteParent = sortPromoteParent || "";
        row.dataset.sortName = sortName || name || sortKey;
    }
    if (sortDisabled) row.addClass("is-no-sort");
    if (active) row.addClass("is-selected");
    row.dataset.pickerKey = itemTitle || name;
    const runAction = (action, selector) => {
        const hadFocus = row.contains(row.ownerDocument.activeElement);
        action();
        if (restoreFocus && hadFocus && !row.isConnected) {
            const replacement = [...list.children].find(el => el.dataset.pickerKey === row.dataset.pickerKey);
            replacement?.querySelector(selector)?.focus({ preventScroll: true });
        }
    };

    const toggle = createSearchButton(row, "tree-toggle", {
        cls: "local-search-move-tree-toggle local-search-row-hit-target",
        attr: { "data-ls-no-drag": "true" }
    });
    if (hasChildren) {
        setIcon(toggle, expanded ? "chevron-down" : "chevron-right");
        toggle.setAttribute("aria-expanded", String(expanded));
        toggle.setAttribute("aria-label", `${toggleTitle} ${name}`);
    } else {
        toggle.addClass("is-placeholder");
        toggle.tabIndex = -1;
        toggle.setAttribute("aria-hidden", "true");
    }

    const itemClassName =
        `local-search-move-tree-folder ${itemClasses}`.trim();
    const button = staticItem
        ? row.createDiv({
            cls: itemClassName,
            attr: {
                "aria-label": itemTitle || name,
                "aria-hidden": "true"
            }
        })
        : createSearchButton(row, "tree-hit", {
            cls: itemClassName,
            attr: {
                "aria-label": itemTitle || name,
                "aria-pressed": String(active)
            }
        });
    if (!staticItem && !onClick) button.disabled = true;
    if (!hasChildren) toggle.disabled = true;

    const iconEl = onIconClick
        ? createSearchButton(row, "tree-hit", { cls:"local-search-move-tree-folder-icon is-interactive", attr: {
            "aria-label": `多选 / 取消：${name}`, "aria-pressed": String(active), "data-ls-no-drag": "true"
        } })
        : button.createSpan({ cls:"local-search-move-tree-folder-icon"});
    setIcon(iconEl, icon);
    if (onIconClick) {
        row.insertBefore(iconEl, button);
        button.setAttribute("aria-label", `单选：${name}`);
        iconEl.addEventListener("click", e => {
            e.preventDefault();
            e.stopPropagation();
            runAction(onIconClick, ".is-interactive");
        });
    }
    button.createSpan({ text: name, cls:"local-search-move-tree-name"});
    const hasCount = count !== null && count !== undefined && count !== "";
    if (hasCount && countPlacement !== "row-end") {
        button.createSpan({
            text: String(count),
 cls: `local-search-move-current-badge ${countClasses}`.trim()
        });
    }

    if (onToggle && hasChildren) {
        toggle.addEventListener("click", e => {
            e.preventDefault();
            e.stopPropagation();
            runAction(onToggle, ".local-search-move-tree-toggle");
        });
    }
    if (onClick) {
        button.addEventListener("click", e => {
            e.preventDefault();
            e.stopPropagation();
            runAction(onClick, ".local-search-move-tree-folder");
        });
    }
    // 与母版共用行尾展开槽；图标 / 名称不因有没有子级而改变起点。
    row.appendChild(toggle);
    if (typeof renderTrailing === "function") renderTrailing(row);
    if (hasCount && countPlacement === "row-end") {
        if (footerOption) row.createSpan({ text: "·", cls: "local-search-picker-footer-dot", attr: { "aria-hidden": "true" } });
        row.createSpan({
            text: String(count),
            cls: `local-search-move-current-badge ${countClasses}`.trim()
        });
    }

    // Row 是 Tree / Picker 唯一 Surface 状态拥有者。
    // 直接子 button 只负责命中与 aria，不允许自己再绘制 Pressed / Selected 背景，
    // 避免父 Row 已选中时子 button:active 形成“中间截断”的第二层色块。
    for (const hitTarget of [button, iconEl].filter(el => el.tagName === "BUTTON")) {
        hitTarget.addClass("local-search-row-hit-target");
    }
    if (sortKey && !sortDisabled) {
        const grip = row.createSpan({ cls: "local-search-picker-sort-indicator", attr: { "aria-hidden": "true" } });
        setIcon(grip, "grip-vertical");
    }
    return { row, toggle, button, iconEl };
}

export function sortByPreferredOrder(items, preferredOrder, getKey = item => item?.path || "") {
    const order = new Map(
        normalizeUniqueStringList(preferredOrder)
            .map((key, index) => [key, index])
    );
    return [...items].sort((a, b) => {
        const aKey = getKey(a);
        const bKey = getKey(b);
        const ai = order.has(aKey) ? order.get(aKey) : Number.MAX_SAFE_INTEGER;
        const bi = order.has(bKey) ? order.get(bKey) : Number.MAX_SAFE_INTEGER;
        if (ai !== bi) return ai - bi;
        return String(aKey).localeCompare(String(bKey), "zh-Hans-CN", { numeric: true });
    });
}

export function updatePreferredSiblingOrder(existingOrder, siblingKeys, draggedKey, beforeKey = null) {
    const siblings = normalizeUniqueStringList(siblingKeys);
    if (!siblings.includes(draggedKey)) return normalizeUniqueStringList(existingOrder);

    const nextSiblings = siblings.filter(key => key !== draggedKey);
    const beforeIndex = beforeKey ? nextSiblings.indexOf(beforeKey) : -1;
    if (beforeIndex >= 0) nextSiblings.splice(beforeIndex, 0, draggedKey);
    else nextSiblings.push(draggedKey);

    const siblingSet = new Set(siblings);
    const untouched = normalizeUniqueStringList(existingOrder)
        .filter(key => !siblingSet.has(key));
    return [...untouched, ...nextSiblings];
}

export function remapPreferredPathOrder(order, oldPath, newPath) {
    if (!oldPath || oldPath === newPath) return normalizeUniqueStringList(order);
    return normalizeUniqueStringList(normalizeUniqueStringList(order).map(path => {
        if (path === oldPath) return newPath;
        if (path.startsWith(oldPath + "/")) {
            return newPath ? newPath + path.slice(oldPath.length) : "";
        }
        return path;
    }));
}

export function remapFilterPoolStoredKeys(pools, kind, remapKey) {
    if (typeof remapKey !== "function") return normalizeFilterPools(pools);
    return normalizeFilterPools(pools).map(pool => {
        if (pool.kind !== kind) return pool;
        return {
            ...pool,
            hiddenValueKeys: normalizeUniqueStringList(
                (pool.hiddenValueKeys || []).map(remapKey)
            ),
            visibleValueKeys: normalizeUniqueStringList(
                (pool.visibleValueKeys || []).map(remapKey)
            )
        };
    });
}

// ========== Pointer Sort：树形拖拽 / 普通排序共用唯一 Pointer Engine ==========
export class PointerSortCoordinator {
    constructor({
        list,
        scrollContainer = null,
        rowSelector = ".local-search-move-tree-row[data-sort-key]",
        hierarchical = false,
        getMeta = row => ({
            key: row?.dataset?.sortKey || "",
            depth: Number(row?.dataset?.sortDepth || 0),
            parentKey: row?.dataset?.sortParent || "",
            promoteParentKey: row?.dataset?.sortPromoteParent || "",
            name: row?.dataset?.sortName || row?.dataset?.sortKey || ""
        }),
        canStart = () => true,
        canNest = () => false,
        onCommit = null,
        onSettled = null
    } = {}) {
        this.list = list;
        this.scrollContainer = scrollContainer || list;
        this.rowSelector = rowSelector;
        this.hierarchical = hierarchical;
        this.getMeta = getMeta;
        this.canStart = canStart;
        this.canNest = canNest;
        this.onCommit = onCommit;
        this.onSettled = onSettled;
        this.enabled = false;
        this.session = null;
        this._feedback = null;
        this._raf = 0;
        this._lastPointer = null;
        this._suppressClickUntil = 0;
        this._committing = false;
        this._move = null;
        this._finish = null;
        this._cancel = null;

        this._blur = event => { if (event.target === this.session?.win) this.cancel(); };
        this._pointerDown = event => this._onPointerDown(event);
        this._clickCapture = event => {
            if (performance.now() >= this._suppressClickUntil) return;
            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation?.();
        };
        this.list?.addEventListener("pointerdown", this._pointerDown);
        this.list?.addEventListener("click", this._clickCapture, true);
    }

    setEnabled(enabled) {
        this.enabled = Boolean(enabled);
        this.list?.classList.toggle("is-sort-mode", this.enabled);
        if (!this.enabled) {
            this.cancel();
            // Leaving sort mode is an explicit new interaction. A drag's
            // compatibility-click guard must not swallow the next eye/delete
            // action after the user has already pressed the sort-mode button.
            this._suppressClickUntil = 0;
        }
    }

    _rows() {
        return [...(this.list?.querySelectorAll(this.rowSelector) || [])]
            .filter(row => row.isConnected && !row.classList.contains("is-no-sort")
                && row.getClientRects().length && row.getBoundingClientRect().height > 0);
    }

    _onPointerDown(event) {
        if (!this.enabled || this.session || this._committing || event.button !== 0) return;
        const target = event.target?.nodeType === 1 ? event.target : null;
        if (!target || target.closest("[data-ls-no-drag='true']")) return;
        const row = target.closest(this.rowSelector);
        if (!row || !this.list.contains(row) || !this.canStart(row, event)) return;

        const meta = this.getMeta(row);
        if (!meta?.key) return;

        event.preventDefault();
        event.stopPropagation();
        row.classList.add("is-dragging");
        this.list.classList.add("is-dragging");
        const win = this.list.ownerDocument.defaultView;
        win.document.body.classList.add("local-search-pointer-sorting");

        this.session = {
            win,
            pointerId: event.pointerId,
            row,
            meta,
            startX: event.clientX,
            startY: event.clientY,
            clientX: event.clientX,
            clientY: event.clientY,
            mode: "reorder",
            beforeKey: null,
            parentKey: meta.parentKey || "",
            targetRow: null
        };
        this._lastPointer = { x: event.clientX, y: event.clientY };

        this._move = moveEvent => this._onPointerMove(moveEvent);
        this._finish = finishEvent => this._finishSession(finishEvent, false);
        this._cancel = cancelEvent => this._finishSession(cancelEvent, true);
        win.addEventListener("pointermove", this._move, { passive: false, capture: true });
        win.addEventListener("pointerup", this._finish, true);
        win.addEventListener("pointercancel", this._cancel, true);
        win.addEventListener("blur", this._blur, true);
        this._updateDrop(event.clientX, event.clientY);
    }

    _onPointerMove(event) {
        const session = this.session;
        if (!session || event.pointerId !== session.pointerId) return;
        event.preventDefault();
        event.stopPropagation();
        session.clientX = event.clientX;
        session.clientY = event.clientY;
        this._lastPointer = { x: event.clientX, y: event.clientY };
        this._updateDrop(event.clientX, event.clientY);
        this._ensureAutoScroll();
    }

    _rowAtY(clientY, rows = this._rows()) {
        return rows.find(row => {
            const rect = row.getBoundingClientRect();
            return clientY >= rect.top && clientY <= rect.bottom;
        }) || null;
    }

    _sameLevelRows(meta) {
        return this._rows().filter(row => {
            if (row === this.session?.row) return false;
            const rowMeta = this.getMeta(row);
            return rowMeta.parentKey === (meta.parentKey || "")
                && Number(rowMeta.depth || 0) === Number(meta.depth || 0);
        });
    }

    _clearTargetVisual() {
        this.session?.targetRow?.classList.remove("is-sort-parent-target");
        if (this.session) this.session.targetRow = null;
        this.list?.classList.remove("is-sort-promote-root");
    }

    _showFeedback(clientY, label, y = null, target = null) {
        this._feedback ||= new SortFeedback(this.session.row);
        this._feedback.show({ bounds: this.list.getBoundingClientRect(),
            clip: this.scrollContainer.getBoundingClientRect(), y, pointerY: clientY, label, target });
    }

    _updateDrop(clientX, clientY) {
        const session = this.session;
        if (!session) return;
        this._clearTargetVisual();

        const dx = clientX - session.startX;
        const rows = this._rows();
        const hitRow = this._rowAtY(clientY, rows);
        const hitMeta = hitRow ? this.getMeta(hitRow) : null;

        if (
            this.hierarchical
            && dx <= -24
            && Number(session.meta.depth || 0) > 0
        ) {
            session.mode = "promote";
            session.parentKey = session.meta.promoteParentKey || "";
            session.beforeKey = null;
            this.list.classList.add("is-sort-promote-root");
            this._showFeedback(clientY, "← 提升一级", null, this.list.getBoundingClientRect());
            return;
        }

        if (
            this.hierarchical
            && dx >= 24
            && hitRow
            && hitRow !== session.row
            && this.canNest(session.meta, hitMeta, hitRow)
        ) {
            session.mode = "nest";
            session.parentKey = hitMeta.key;
            session.beforeKey = null;
            session.targetRow = hitRow;
            hitRow.classList.add("is-sort-parent-target");
            this._showFeedback(clientY, `移入 ${hitMeta.name || hitMeta.key}`, null, hitRow.getBoundingClientRect());
            return;
        }

        session.mode = "reorder";
        session.parentKey = session.meta.parentKey || "";
        const candidates = this._sameLevelRows(session.meta);
        let beforeRow = null;
        for (const row of candidates) {
            const rect = row.getBoundingClientRect();
            if (clientY < rect.top + rect.height / 2) {
                beforeRow = row;
                break;
            }
        }
        session.beforeKey = beforeRow ? this.getMeta(beforeRow).key : null;

        const listRect = this.list.getBoundingClientRect();
        let y = listRect.bottom;
        if (beforeRow) {
            y = beforeRow.getBoundingClientRect().top;
        } else if (candidates.length) {
            y = candidates[candidates.length - 1].getBoundingClientRect().bottom;
        }
        this._showFeedback(clientY, `移到第 ${beforeRow ? candidates.indexOf(beforeRow) + 1 : candidates.length + 1} 项`, y);
    }

    _ensureAutoScroll() {
        if (this._raf || !this.session) return;
        const win = this.session.win;
        const tick = () => {
            this._raf = 0;
            const scroller = this.scrollContainer || this.list;
            if (!this.session || !this.list?.isConnected || !scroller?.isConnected || !this._lastPointer) return;
            const rect = scroller.getBoundingClientRect();
            const y = this._lastPointer.y;
            const edge = 64;
            let velocity = 0;
            if (y < rect.top + edge) {
                velocity = -Math.min(16, Math.max(3, (rect.top + edge - y) / 4));
            } else if (y > rect.bottom - edge) {
                velocity = Math.min(16, Math.max(3, (y - (rect.bottom - edge)) / 4));
            }
            if (velocity) {
                const before = scroller.scrollTop;
                scroller.scrollTop += velocity;
                if (scroller.scrollTop !== before) {
                    this._updateDrop(this._lastPointer.x, this._lastPointer.y);
                    this._raf = win.requestAnimationFrame(tick);
                }
            }
        };
        this._raf = win.requestAnimationFrame(tick);
    }

    async _finishSession(event, cancelled) {
        const session = this.session;
        if (!session) return;
        if (event?.pointerId !== undefined && event.pointerId !== session.pointerId) return;

        event?.preventDefault?.();
        event?.stopPropagation?.();
        this._suppressClickUntil = performance.now() + 360;

        session.win.removeEventListener("pointermove", this._move, true);
        session.win.removeEventListener("pointerup", this._finish, true);
        session.win.removeEventListener("pointercancel", this._cancel, true);
        session.win.removeEventListener("blur", this._blur, true);
        this._move = null;
        this._finish = null;
        this._cancel = null;
        if (this._raf) session.win.cancelAnimationFrame(this._raf);
        this._raf = 0;

        session.row?.classList.remove("is-dragging");
        this.list?.classList.remove("is-dragging");
        session.win.document.body.classList.remove("local-search-pointer-sorting");
        this._clearTargetVisual();
        this._feedback?.destroy(); this._feedback = null;
        this.session = null;
        this._lastPointer = null;

        if (!cancelled && typeof this.onCommit === "function") {
            this._committing = true;
            this.list?.classList.add("is-sort-committing");
            try {
                await this.onCommit({
                    key: session.meta.key,
                    meta: session.meta,
                    mode: session.mode,
                    beforeKey: session.beforeKey,
                    parentKey: session.parentKey
                });
            } catch (error) {
                console.error("拖拽排序提交失败", error);
                new Notice(error?.message || "拖拽排序失败");
            } finally {
                this._committing = false;
                this.list?.classList.remove("is-sort-committing");
            }
        }
        this.onSettled?.({ cancelled });
    }

    cancel() {
        if (!this.session) {
            this._clearTargetVisual();
            this._feedback?.destroy(); this._feedback = null;
            if (this._raf) this.list?.ownerDocument.defaultView.cancelAnimationFrame(this._raf);
            this._raf = 0;
            return;
        }
        void this._finishSession(null, true);
    }

    destroy() {
        this.cancel();
        this.list?.removeEventListener("pointerdown", this._pointerDown);
        this.list?.removeEventListener("click", this._clickCapture, true);
        this.list?.classList.remove(
            "is-sort-mode",
            "is-dragging",
            "is-sort-promote-root",
            "is-sort-committing"
        );
        this.list = null;
        this.scrollContainer = null;
        this._move = null;
        this._finish = null;
        this._cancel = null;
        this.onCommit = null;
        this.onSettled = null;
    }
}

// ========== 共享文件夹 Picker：搜索弹窗与当前文件命令使用同一 DOM / 行模型 ==========
export function sharedFolderChildren(app, plugin, folder, {
    includeExcluded = false
} = {}) {
    const children = (folder?.children || [])
        .filter(child =>
            child instanceof TFolder
            && (includeExcluded || !plugin.isPathExcluded(child.path))
        );
    return sortByPreferredOrder(
        children,
        plugin?.settings?.pickerFolderOrder || [],
        child => child.path
    );
}

export function comparePickerTreePaths(a, b, order = new Map()) {
    const aPath = String(a || "");
    const bPath = String(b || "");
    if (aPath === bPath) return 0;
    if (aPath === "/") return -1;
    if (bPath === "/") return 1;
    const aParts = aPath.split("/").filter(Boolean);
    const bParts = bPath.split("/").filter(Boolean);
    const depth = Math.min(aParts.length, bParts.length);
    let aPrefix = "";
    let bPrefix = "";

    for (let index = 0; index < depth; index++) {
        aPrefix = aPrefix ? `${aPrefix}/${aParts[index]}` : aParts[index];
        bPrefix = bPrefix ? `${bPrefix}/${bParts[index]}` : bParts[index];
        if (aPrefix === bPrefix) continue;

        const ai = order.has(aPrefix)
            ? order.get(aPrefix)
            : Number.MAX_SAFE_INTEGER;
        const bi = order.has(bPrefix)
            ? order.get(bPrefix)
            : Number.MAX_SAFE_INTEGER;
        if (ai !== bi) return ai - bi;

        const siblingCompare = String(aParts[index]).localeCompare(
            String(bParts[index]),
            "zh-Hans-CN",
            { numeric: true }
        );
        if (siblingCompare) return siblingCompare;

        const pathCompare = aPrefix.localeCompare(
            bPrefix,
            "zh-Hans-CN",
            { numeric: true }
        );
        if (pathCompare) return pathCompare;
    }

    // 同一路径前缀下，父节点在其后代之前，保持 Picker 的深度优先顺序。
    if (aParts.length !== bParts.length) {
        return aParts.length - bParts.length;
    }
    return aPath.localeCompare(bPath, "zh-Hans-CN", { numeric: true });
}

export function orderFolderSelectionsForPicker(plugin, paths = []) {
    const selected = normalizeUniqueStringList([...(paths || [])]);
    if (!selected.length) return [];

    // 只对“已选路径”做层级比较，不再为几个 Chip 遍历整个 Vault 文件夹树。
    // 比较器直接复用 pickerFolderOrder 的 sibling 优先级 + 路径层级，
    // 因而与共享文件夹 Picker 的深度优先显示顺序保持一致。
    const order = new Map(
        normalizeUniqueStringList(plugin?.settings?.pickerFolderOrder)
            .map((key, index) => [key, index])
    );
    return selected.sort((a, b) => comparePickerTreePaths(a, b, order));
}

export function sharedFolderAncestors(path) {
    const paths = [];
    let current = path || "";
    while (current) {
        paths.push(current);
        const idx = current.lastIndexOf("/");
        current = idx >= 0 ? current.slice(0, idx) : "";
    }
    return paths;
}

export function createSharedFolderCountProvider(candidates) {
    const source = Array.isArray(candidates) ? candidates : [];
    const counts = new Map();
    let rootCount = 0;

    for (const meta of source) {
        const path = meta?.path || "";
        if (!path) continue;
        const slash = path.lastIndexOf("/");
        if (slash < 0) {
            rootCount++;
            continue;
        }
        let folder = path.slice(0, slash);
        while (folder) {
            counts.set(folder, (counts.get(folder) || 0) + 1);
            const parentSlash = folder.lastIndexOf("/");
            folder = parentSlash >= 0 ? folder.slice(0, parentSlash) : "";
        }
    }

    return path => {
        if (!path) return source.length;
        if (path === "/") return rootCount;
        return counts.get(path) || 0;
    };
}

export function createSharedPickerFooter(panel) {
    return panel.querySelector(":scope > .local-search-picker-footer")
        || panel.createDiv({ cls: "local-search-picker-footer" });
}

export function createSharedPickerTreeShell(panel, {
    placeholder,
    rootClasses = "",
    treeClasses = "",
    showRoot = true
}) {
    const searchWrap = panel.createDiv({ cls: "local-search-move-search-wrap" });
    const searchIcon = searchWrap.createSpan({ cls: "local-search-picker-search-icon", attr: { "aria-hidden": "true" } });
    setIcon(searchIcon, "search");
    const { input: search } = createSearchTextField(searchWrap, {
        fieldClass: "local-search-picker-search-field",
        inputClass: "local-search-picker-search",
        type: "text",
        placeholder,
        attr: { "aria-label": placeholder, autocomplete: "off", autocapitalize: "off", spellcheck: "false" }
    });
    search.dataset.searchPlaceholder = placeholder;
    const list = panel.createDiv({ cls: `local-search-move-tree ${treeClasses}`.trim() });
    const current = panel.querySelector(":scope > .local-search-picker-current-selection");
    if (current) panel.appendChild(current);
    const footer = createSharedPickerFooter(panel);
    panel.appendChild(footer);
    const rootHost = showRoot
        ? footer.createDiv({ cls: `local-search-move-root ${rootClasses}`.trim() })
        : null;

    // Native focus owns this search field. A panel-wide pointerdown guard used
    // to keep it focused even when a control opened another picker or changed
    // modes. On touch hosts that leaves a hidden field's DOM focus outliving
    // its native editing session. Local inline editors may retain their own
    // input guard; a navigation surface must not cancel native focus changes.
    registerPickerCleanup(panel, observePickerCountRail(panel, list, "--ls-picker-scrollbar-reserve"));

    return { search, rootHost, list };
}

export function setPickerSearchMode(panel, description = "") {
    const wrap = panel?.querySelector(":scope > .local-search-move-search-wrap");
    const input = wrap?.querySelector(".local-search-picker-search");
    if (!input) return;
    if (input.dataset.searchPlaceholder === undefined) input.dataset.searchPlaceholder = input.placeholder;
    // Mode text shares the native placeholder/description. A second overlay
    // line used to change input padding and line-height as soon as typing
    // started, moving the text/caret within the same fixed-height field.
    input.placeholder = description || input.dataset.searchPlaceholder;
    if (description) input.setAttribute("aria-description", description);
    else input.removeAttribute("aria-description");
}

export function captureScrollableAnchor(container, {
    selector = "[data-picker-key]",
    keyFrom = element => element?.dataset?.pickerKey || ""
} = {}) {
    if (!isDomHTMLElement(container)) return null;

    const bounds = container.getBoundingClientRect();
    const visible = [...container.querySelectorAll(selector)].find(element => {
        if (!isDomHTMLElement(element)) return false;
        const rect = element.getBoundingClientRect();
        return rect.bottom > bounds.top + 1
            && rect.top < bounds.bottom - 1;
    });

    return {
        key: visible ? String(keyFrom(visible) || "") : "",
        offset: visible
            ? visible.getBoundingClientRect().top - bounds.top
            : 0,
        scrollTop: container.scrollTop
    };
}

export function restoreScrollableAnchor(container, anchor, {
    selector = "[data-picker-key]",
    keyFrom = element => element?.dataset?.pickerKey || ""
} = {}) {
    if (!isDomHTMLElement(container) || !container.isConnected || !anchor) {
        return false;
    }

    let restored = false;
    if (anchor.key) {
        const target = [...container.querySelectorAll(selector)].find(
            element => String(keyFrom(element) || "") === anchor.key
        );
        if (isDomHTMLElement(target)) {
            const bounds = container.getBoundingClientRect();
            const rect = target.getBoundingClientRect();
            container.scrollTop += rect.top - bounds.top - anchor.offset;
            restored = true;
        }
    }

    if (!restored) {
        container.scrollTop = Math.max(0, Number(anchor.scrollTop) || 0);
    }

    const maxScroll = Math.max(
        0,
        container.scrollHeight - container.clientHeight
    );
    container.scrollTop = Math.min(
        Math.max(0, container.scrollTop),
        maxScroll
    );
    return restored;
}

export function revealScrollableKey(container, key, {
    selector = "[data-picker-key]",
    keyFrom = element => element?.dataset?.pickerKey || ""
} = {}) {
    if (!isDomHTMLElement(container) || !container.isConnected || !key
        || container.closest("[hidden], [inert], .pwb-modal-suspended")) {
        return false;
    }
    const target = [...container.querySelectorAll(selector)].find(
        element => String(keyFrom(element) || "") === String(key)
    );
    if (!isDomHTMLElement(target)) return false;

    const bounds = container.getBoundingClientRect();
    if (bounds.width <= 0 || bounds.height <= 0) return false;
    const rect = target.getBoundingClientRect();
    if (rect.top < bounds.top) {
        container.scrollTop += rect.top - bounds.top;
    } else if (rect.bottom > bounds.bottom) {
        container.scrollTop += rect.bottom - bounds.bottom;
    }
    const maxScroll = Math.max(
        0,
        container.scrollHeight - container.clientHeight
    );
    container.scrollTop = Math.min(
        Math.max(0, container.scrollTop),
        maxScroll
    );
    return true;
}

export function rerenderPickerListPreservingScroll(list, render) {
    if (!list || typeof render !== "function") return;
    const anchor = captureScrollableAnchor(list);
    render();
    restoreScrollableAnchor(list, anchor);
}

export function syncSharedPickerTreeRowSelection(row, selected) {
    if (!isDomHTMLElement(row)) return;
    const active = Boolean(selected);

    // Tree / Picker 的视觉状态只允许挂在 Row 上。
    // 子 button 只保留语义性的 aria-pressed，不再写入 is-selected，
    // 避免 Obsidian / 主题对 button.is-selected 注入额外背景并产生中间态。
    row.classList.toggle("is-selected", active);
    const button = row.querySelector(":scope > .local-search-move-tree-folder");
    button?.setAttribute("aria-pressed", String(active));
    const iconButton = row.querySelector(":scope > .local-search-move-tree-folder-icon.is-interactive");
    iconButton?.setAttribute("aria-pressed", String(active));
}

export function syncSharedPickerTreeRowAvailability(row, unavailable) {
    if (!isDomHTMLElement(row)) return;
    const disabled = Boolean(unavailable);
    row.classList.toggle("is-unavailable", disabled);
    row.setAttribute("aria-disabled", String(disabled));
    const button = row.querySelector(":scope > .local-search-move-tree-folder");
    if (isDomButton(button)) {
        button.disabled = disabled;
        button.tabIndex = disabled ? -1 : 0;
    }
}

