export function buildTagTreeModel(candidates = [], preferredOrder = []) {
    const canonicalOrder = normalizeUniqueStringList(preferredOrder.map(tagIdentityKey));
    const discovered = [...new Set(candidates.flatMap(meta => meta.tags || []))];
    const allTags = normalizeUniqueTagList(discovered).sort((a, b) =>
        a.localeCompare(b, "zh-Hans-CN", { numeric: true })
    );
    const nodeMap = new Map();

    // 节点身份大小写不敏感，但 path / name 始终保留第一次发现的真实标签写法。
    for (const tag of allTags) {
        const parts = String(tag).split("/").filter(Boolean);
        let parent = null;
        let displayPath = "";

        for (const part of parts) {
            const candidatePath = displayPath
                ? `${displayPath}/${part}`
                : part;
            const key = tagIdentityKey(candidatePath);
            let node = nodeMap.get(key);

            if (!node) {
                node = {
                    path: candidatePath,
                    name: part,
                    parentPath: parent?.path || "",
                    children: []
                };
                nodeMap.set(key, node);
                if (parent) parent.children.push(node);
            }

            parent = node;
            displayPath = node.path;
        }
    }

    for (const node of nodeMap.values()) {
        node.children = sortByPreferredOrder(
            node.children,
            canonicalOrder,
            child => tagIdentityKey(child.path)
        );
    }
    return sortByPreferredOrder(
        [...nodeMap.values()].filter(node => !node.parentPath),
        canonicalOrder,
        node => tagIdentityKey(node.path)
    );
}

export function flattenTagTreePaths(nodes = []) {
    const result = [];
    const visit = list => {
        for (const node of list || []) {
            if (!node?.path) continue;
            result.push(node.path);
            visit(node.children || []);
        }
    };
    visit(nodes);
    return result;
}

// 结果卡标签与标签 Picker 共用同一层级排序规则；只返回当前结果真实拥有的标签，
// 不把为了构建层级而产生的父节点标签注入结果卡。
export function orderTagsForPicker(tags = [], preferredOrder = []) {
    const source = normalizeUniqueTagList(tags);
    const actual = new Map(source.map(tag => [tagIdentityKey(tag), tag]));
    return flattenTagTreePaths(
        buildTagTreeModel([{ tags: source }], preferredOrder)
    )
        .map(path => actual.get(tagIdentityKey(path)))
        .filter(Boolean);
}

export function orderTagSelectionsForPicker(selectedTags = [], preferredOrder = []) {
    const selected = [...(selectedTags || [])];
    if (!selected.length) return [];

    const hasNoTags = selected.includes(NO_TAGS_FILTER_VALUE);
    const ordered = orderTagsForPicker(
        selected.filter(value => value !== NO_TAGS_FILTER_VALUE),
        preferredOrder
    );
    return hasNoTags
        ? [NO_TAGS_FILTER_VALUE, ...ordered]
        : ordered;
}

export function treeNodeMatches(node, query, getText = item => [item.path, item.name]) {
    if (!query) return true;
    if (getText(node).some(text => String(text || "").toLowerCase().includes(query))) {
        return true;
    }
    return (node.children || []).some(child =>
        treeNodeMatches(child, query, getText)
    );
}

export function collectPropertyKeys(candidates = [], excludedKeys = []) {
    const excluded = new Set(excludedKeys || []);
    excluded.add("position");

    const keys = new Set();
    for (const meta of candidates) {
        for (const key of Object.keys(meta.properties || {})) {
            if (
                !excluded.has(key)
                && String(key).toLowerCase() !== "tags"
            ) {
                keys.add(key);
            }
        }
    }

    return [...keys].sort((a, b) =>
        a.localeCompare(b, "zh-Hans-CN")
    );
}

export function orderPropertyValuesForPicker(values = [], preferredOrder = []) {
    const normal = sortByPreferredOrder(
        (values || []).filter(value => !isSpecialPropertyValue(value)),
        preferredOrder,
        propertyValueKey
    );
    const special = (values || [])
        .filter(isSpecialPropertyValue)
        .sort((a, b) =>
            propertyValueSortRank(a) - propertyValueSortRank(b)
            || propertyValueDisplay(a).localeCompare(
                propertyValueDisplay(b),
                "zh-Hans-CN",
                { numeric: true }
            )
        );
    return [...normal, ...special];
}

export function orderSelectedPropertyValues(values = [], preferredOrder = []) {
    const source = [...(values || [])];
    const presence = source.filter(value => value === PRESENT_PROPERTY_VALUE);
    return [
        ...presence,
        ...orderPropertyValuesForPicker(
            source.filter(value => value !== PRESENT_PROPERTY_VALUE),
            preferredOrder
        )
    ];
}

// 已选属性的唯一 Picker 顺序投影：所有“当前已选 / 当前条件 / 新建摘要 / 新建落盘”
// 都从同一 key/value order 派生，不再分别按 Map / Set 插入顺序解释。
export function orderPropertySelectionsForPicker(
    properties = new Map(),
    preferredKeyOrder = [],
    preferredValueOrder = {}
) {
    const source = properties instanceof Map ? properties : new Map();
    const orderedKeys = sortByPreferredOrder(
        [...source.keys()],
        preferredKeyOrder,
        key => key
    );
    return orderedKeys.map(key => [
        key,
        orderSelectedPropertyValues(
            source.get(key) || [],
            preferredValueOrder?.[key] || []
        )
    ]);
}

// Picker 排序的权威快照：维护动作开始前先把当前真实显示顺序物化。
// 重命名只替换原槽位，删除只移除原槽位；不能让新名称因“未命中偏好表”掉到列表底部。
export function materializeTagPickerOrder(candidates = [], preferredOrder = []) {
    return flattenTagTreePaths(
        buildTagTreeModel(candidates, preferredOrder)
    );
}

export function materializePropertyPickerOrders(
    candidates = [],
    excludedKeys = [],
    preferredKeyOrder = [],
    preferredValueOrder = {}
) {
    const keys = sortByPreferredOrder(
        collectPropertyKeys(candidates, excludedKeys),
        preferredKeyOrder,
        key => key
    );
    const values = {};
    for (const key of keys) {
        values[key] = orderPropertyValuesForPicker(
            buildPropertyUsageStats(candidates, key).values,
            preferredValueOrder?.[key] || []
        )
            .filter(value => !isSpecialPropertyValue(value))
            .map(propertyValueKey);
    }
    return { keys, values };
}

// 属性值写盘与内存索引共用同一纯转换，避免“文件已改、Picker 仍读旧缓存”的双状态。
export function removeRawPropertyValues(current, removeKeys) {
    const keys = removeKeys instanceof Set ? removeKeys : new Set(removeKeys || []);
    if (current === undefined || !keys.size) return current;
    if (Array.isArray(current)) {
        const matched = normalizePropertyValues(current).some(value =>
            keys.has(propertyValueKey(value))
        );
        if (!matched) return current;
        const next = flattenPropertyListStructure(current).filter(item =>
            !normalizePropertyValues(item).some(value =>
                keys.has(propertyValueKey(value))
            )
        );
        return next.length ? next : undefined;
    }
    return normalizePropertyValues(current).some(value =>
        keys.has(propertyValueKey(value))
    )
        ? undefined
        : current;
}

export function renameRawPropertyValue(
    current,
    oldValue,
    newValue,
    propertyType = "text"
) {
    const oldKey = propertyValueKey(oldValue);
    const listType = normalizeMetadataPropertyType(propertyType) === "multitext";
    const targetValues = normalizePropertyValues(newValue);
    if (targetValues.length !== 1) {
        throw new Error("目标属性值必须是单个有效值");
    }
    const targetNormalizedValue = targetValues[0];
    const sampledTargetValue = rawSampleForPropertyValue(
        newValue,
        targetNormalizedValue
    );
    const targetValue = sampledTargetValue !== undefined
        ? sampledTargetValue
        : (targetNormalizedValue === EMPTY_PROPERTY_VALUE
            ? null
            : targetNormalizedValue);

    const dedupeList = values => {
        const seen = new Set();
        const result = [];
        for (const value of flattenPropertyListStructure(values)) {
            const normalizedValues = normalizePropertyValues(value);
            if (!normalizedValues.length) {
                result.push(value);
                continue;
            }
            const id = propertyValueKey(normalizedValues[0]);
            if (seen.has(id)) continue;
            seen.add(id);
            result.push(value);
        }
        return result;
    };

    if (oldValue === MISSING_PROPERTY_VALUE) {
        return current === undefined
            ? (listType ? [targetValue] : targetValue)
            : current;
    }
    if (current === undefined) return current;
    if (Array.isArray(current)) {
        if (current.length === 0) {
            if (oldValue !== EMPTY_PROPERTY_VALUE) return current;
            return listType ? [targetValue] : targetValue;
        }
        const sourceItems = flattenPropertyListStructure(current, true);
        let matched = false;
        const next = sourceItems.map(item => {
            const hit = normalizePropertyValues(item).some(
                value => propertyValueKey(value) === oldKey
            );
            if (!hit) return item;
            matched = true;
            return targetValue;
        });
        return matched ? dedupeList(next) : current;
    }
    const matched = normalizePropertyValues(current).some(
        value => propertyValueKey(value) === oldKey
    );
    if (!matched) return current;
    return listType ? [targetValue] : targetValue;
}

export function appendPropertySpecialStateInlineGroup(host, {
    key,
    values = [],
    selectedValueKeys = new Set(),
    valueCount = () => 0,
    onToggle = () => {}
} = {}) {
    if (!host || !values.length) return null;

    const row = host.createDiv({
        cls: "local-search-property-special-state-inline",
        attr: {
            role: "group",
            "aria-label": `${key || "属性"}的特殊状态`
        }
    });

    const group = row.createDiv({
        cls: "local-search-property-special-state-group"
    });

    values.forEach(value => {
        const valueId = propertyValueKey(value);
        const selected = selectedValueKeys.has(valueId);
        const count = Math.max(0, Number(valueCount(value)) || 0);
        const unavailable = count <= 0 && !selected;
        const label = propertySpecialInlineDisplay(value);
        const button = createSearchButton(group, "choice", {
            cls: [
                "local-search-property-special-state-action",
                selected ? "is-selected" : "",
                unavailable ? "is-disabled" : ""
            ].filter(Boolean).join(" "),
            attr: {
                "aria-pressed": String(selected),
                "aria-disabled": String(unavailable),
                title: selected
                    ? `取消筛选：${key} · ${label}`
                    : unavailable
                        ? `当前条件下没有“${key} · ${label}”`
                        : `筛选：${key} · ${label}`
            }
        });
        button.disabled = unavailable;
        button.createSpan({
            cls: "local-search-property-special-state-label",
            text: label
        });
        button.createSpan({
            cls: "local-search-property-special-state-dot",
            text: "·",
            attr: { "aria-hidden": "true" }
        });
        button.createSpan({
            cls: "local-search-property-special-state-count",
            text: String(count)
        });

        if (!unavailable) {
            button.addEventListener("click", event => {
                event.preventDefault();
                event.stopPropagation();
                onToggle(value);
            });
        }
    });

    return row;
}

export class FilterEngine {
    static matchesDateRange(meta, value) {
        if (!value) return true;
        const range = normalizeFilterDateRange(value);
        if (!range) return false;
        // The index owns all three clocks. Never fall back to TFile.stat or
        // mtime, which can reflect NAS synchronization rather than user edits.
        const day = filterLocalDate(meta?.[FILTER_TIME_FIELDS[range.field].key]);
        return Boolean(day)
            && (!range.from || day >= range.from)
            && (!range.to || day <= range.to);
    }

    static matchesTags(meta, selectedTags, matchMode = "all") {
        const selected = selectedTags instanceof Set
            ? selectedTags
            : new Set(Array.isArray(selectedTags) ? selectedTags : []);
        if (!selected.size) return true;

        const tags = Array.isArray(meta?.tags) ? meta.tags : [];
        if (selected.has(NO_TAGS_FILTER_VALUE)) {
            // [没有标签] 是互斥条件；若外部旧状态仍混入真实标签，按无效状态处理。
            return selected.size === 1 && tags.length === 0;
        }

        const matches = wanted => tags.some(tag => tagPathMatches(tag, wanted));
        // 普通标签 Facet 继续使用 AND；筛选池“多选”与 Dida 一样使用同池 OR。
        return normalizeFilterMatchMode(matchMode) === "any"
            ? [...selected].some(matches)
            : [...selected].every(matches);
    }

    static matches(meta, filter) {
        if (!filter) return true;
        if (!FilterEngine.matchesDateRange(meta, filter.dateRange)) return false;
        const kind = logicalFileType(meta);
        const fileTypes = filter.fileTypes instanceof Set
            ? filter.fileTypes
            : new Set(normalizeFileTypeFilterSelection(filter.fileType));
        if (fileTypes.size) {
            const extension = kind === "attachment" ? attachmentExtension(meta) : "";
            let matched = false;
            for (const wanted of fileTypes) {
                if (wanted === "attachment") matched = kind === "attachment";
                else if (wanted.startsWith("ext:")) matched = kind === "attachment" && extension === wanted.slice(4);
                else matched = kind === wanted;
                if (matched) break;
            }
            if (!matched) return false;
        }
        if (filter.folders?.size) {
            let folderMatched = false;
            for (const folder of filter.folders) {
                if (
                    (folder === "/" && !meta.path.includes("/"))
                    || (folder !== "/" && meta.path.startsWith(folder + "/"))
                ) {
                    folderMatched = true;
                    break;
                }
            }
            if (!folderMatched) return false;
        }
        if (!FilterEngine.matchesTags(meta, filter.tags, filter.tagMatchMode)) return false;
        const propertyEntries = [...filter.properties];
        if (propertyEntries.length) {
            const propertyMatches = ([key, wanted]) => propertySelectionMatches(meta, key, wanted);
            const matched = normalizeFilterMatchMode(filter.propertyMatchMode) === "any"
                ? propertyEntries.some(propertyMatches)
                : propertyEntries.every(propertyMatches);
            if (!matched) return false;
        }
        return true;
    }
}

export class ResultRanker {
    static rank(meta, query) {
        if (!query.active) return { tier: 0, bodyOnly: false, titleMatchRanges: [] };
        const title = meta.nameLower || "";
        const tags = meta.tags || [];
        const phrase = query.intent;
        const everyTitle = query.units.every(u => title.includes(u));
        const everyTag = query.units.every(u =>
            tags.some(tag => {
                const key = tagIdentityKey(tag);
                return key === u || key.includes(u);
            })
        );
        const kind = logicalFileType(meta);
        const phraseRange = substringMatchRange(title, phrase);

        if (title === phrase) {
            return { tier: 1, bodyOnly: false, titleMatchRanges: [[0, title.length]] };
        }
        if (phraseRange) {
            return { tier: 2, bodyOnly: false, titleMatchRanges: [phraseRange] };
        }
        if (query.units.length > 1 && everyTitle) {
            return {
                tier: 3,
                bodyOnly: false,
                titleMatchRanges: unitMatchRanges(title, query.units) || []
            };
        }

        const orderedRanges = orderedMatchRanges(title, phrase);

        // Excalidraw / Canvas / 其他附件的关键词搜索只看标题；
        // tags / properties 仍保留给 FilterEngine 做正常元数据筛选。
        if (kind !== "note") {
            if (orderedRanges) {
                return { tier: 6, bodyOnly: false, titleMatchRanges: orderedRanges };
            }
            return null;
        }

        if (orderedRanges && everyTag) {
            return { tier: 4, bodyOnly: false, titleMatchRanges: orderedRanges };
        }
        if (everyTag) return { tier: 5, bodyOnly: false, titleMatchRanges: [] };
        if (orderedRanges) {
            return { tier: 6, bodyOnly: false, titleMatchRanges: orderedRanges };
        }
        return null;
    }
}

export function assertVaultPropertyMutationSucceeded(stats, action) {
    if (!stats.failed && !stats.conflict) return;
    const parts = [`${action}未全部完成`, `本次已修改 ${stats.changed} 个文件`];
    if (stats.failed) parts.push(`失败 ${stats.failed} 个文件`);
    if (stats.conflict) parts.push(`冲突 ${stats.conflict} 个文件，目标属性已存在`);
    if (stats.firstError) parts.push(`${stats.firstError.path}：${stats.firstError.message}`);
    if (stats.firstConflict) parts.push(`冲突文件：${stats.firstConflict}`);
    throw new Error(parts.join("；") + "。已完成的修改保留，未覆盖冲突内容。");
}

export class BatchMetadataService {
    constructor(app, plugin) { this.app = app; this.plugin = plugin; }

    // All file types share the same metadata mutation target resolver.
    metadataFiles(paths = this.app.vault.getFiles().map(file => file.path)) {
        return [...new Set(paths)]
            .map(path => this.app.vault.getAbstractFileByPath(path))
            .filter(file => file instanceof TFile && !this.plugin.isPathExcluded(file.path));
    }


    _normalizeTagList(values) {
        return normalizeUniqueTagList(values);
    }

    _frontmatterTagList(rawValue) {
        const source = Array.isArray(rawValue)
            ? rawValue
            : (
                rawValue === undefined
                || rawValue === null
                || rawValue === ""
                    ? []
                    : [rawValue]
            );
        return this._normalizeTagList(source);
    }

    summarize(paths) {
        const files = this.metadataFiles(paths);
        const out = new Map();
        const excluded = new Set(this.plugin.settings.excludedKeys || []);

        // tags 是 Obsidian 的特殊 Frontmatter 属性；标签增删与普通属性分开统计。
        // 这里只统计 Frontmatter tags；正文 inline #tag 不进入这条 processFrontMatter 编辑链。
        const tagSummary = {
            present: 0,
            values: new Map()
        };

        const addValue = (row, rawValue, normalizedValue = null) => {
            const values = normalizedValue === null
                ? propertyValuesFromRaw(rawValue)
                : [normalizedValue];
            for (const value of values) {
                const id = propertyValueKey(value);
                const existing = row.values.get(id);
                const rawSample = rawSampleForPropertyValue(rawValue, value);
                row.values.set(id, {
                    value,
                    rawSample: existing?.rawSample ?? rawSample,
                    count: (existing?.count || 0) + 1
                });
            }
        };

        for (const file of files) {
            // 与搜索和属性目录共用已提交的原始属性索引；不读延迟的宿主缓存或虚拟投影。
            const fm = this.plugin.fileMetaCache.get(file.path)?.properties || {};

            const frontmatterTags = this._frontmatterTagList(fm.tags);
            if (frontmatterTags.length) tagSummary.present++;
            for (const tag of frontmatterTags) {
                const tagKey = tagIdentityKey(tag);
                const existing = tagSummary.values.get(tagKey);
                tagSummary.values.set(tagKey, {
                    value: existing?.value || tag,
                    count: (existing?.count || 0) + 1
                });
            }

            for (const [key, rawValue] of Object.entries(fm)) {
                if (key === "position" || key === "tags" || excluded.has(key)) continue;
                if (!out.has(key)) out.set(key, { key, present: 0, values: new Map(), rawSample: rawValue });
                const row = out.get(key);
                row.present++;
                if (row.rawSample === undefined) row.rawSample = rawValue;
                addValue(row, rawValue);
            }
        }

        // 特殊状态是统一值模型的一部分：
        // [没有此属性]、[有属性但无值] 固定排在真实值之前，
        // 让批量增删时优先识别异常 / 待补全状态。
        for (const row of out.values()) {
            const missing = files.length - row.present;
            if (missing > 0) {
                row.values.set(propertyValueKey(MISSING_PROPERTY_VALUE), {
                    value: MISSING_PROPERTY_VALUE,
                    rawSample: undefined,
                    count: missing
                });
            }

            row.values = new Map(
                [...row.values.entries()].sort(([, a], [, b]) =>
                    (
                        propertyValueSortRank(a.value)
                        - propertyValueSortRank(b.value)
                    )
                    || propertyValueDisplay(a.value).localeCompare(
                        propertyValueDisplay(b.value),
                        "zh-Hans-CN",
                        { numeric: true }
                    )
                )
            );
        }

        return {
            files,
            tags: {
                present: tagSummary.present,
                values: [...tagSummary.values.values()].sort((a, b) =>
                    a.value.localeCompare(
                        b.value,
                        "zh-Hans-CN",
                        { numeric: true }
                    )
                )
            },
            rows: [...out.values()].sort((a, b) =>
                a.key.localeCompare(b.key, "zh-Hans-CN")
            )
        };
    }
    _mutateFiles(paths, operation) {
        if (!Array.isArray(paths) || paths.some(path => typeof path !== "string" || !path.trim())) {
            throw new Error("属性操作需要有效文件路径列表");
        }
        const unique = [...new Set(paths)];
        const files = this.metadataFiles(unique);
        return this.plugin.fileOperations.withTargets(files, async () => {
            const stats = await this._applyMutation(files, operation);
            stats.failed += unique.length - files.length;
            return stats;
        });
    }

    async _editFrontmatter(file, transform) {
        let outcome = "unchanged";
        if (file.extension.toLowerCase() !== "md") {
            outcome = await this.plugin._editNonMarkdownProperties(file, transform);
        } else {
            try {
                await this.plugin._editMarkdownFrontmatter(file, data => {
                    this.plugin.fileOperations.assertCurrent(file);
                    outcome = transform(data);
                    // Host 的原子回调抛出时不会写盘；真实 no-op / 冲突不重排 YAML、不改 mtime。
                    if (outcome !== "changed") throw NO_FRONTMATTER_WRITE;
                });
            } catch (error) {
                if (error !== NO_FRONTMATTER_WRITE) throw error;
            }
        }
        // 索引直接回读文件；所有属性写入共用这一出口，不再等待 MetadataCache.changed。
        if (outcome === "changed") this.plugin._queueFileIndex(file.path);
        return outcome;
    }

    async _applyMutation(files, operation) {
        const stats = { failed: 0, conflict: 0, changed: 0, unchanged: 0 };
        for (const file of files) {
            try {
                this.plugin.fileOperations.assertCurrent(file);
                const result = await operation(file);
                const status = typeof result === "string"
                    ? result : String(result?.status || "unchanged");
                const conflicts = typeof result === "object" && result
                    ? Math.max(0, Number(result.conflict) || 0)
                    : (status === "conflict" ? 1 : 0);
                stats.conflict += conflicts;
                if (conflicts && !stats.firstConflict) stats.firstConflict = file.path;
                if (status === "failed") stats.failed++;
                else if (status === "changed") stats.changed++;
                else if (status !== "conflict") stats.unchanged++;
            } catch (error) {
                stats.failed++;
                stats.firstError ||= { path: file.path, message: error?.message || String(error) };
            }
        }
        // 正式写入后的回读/发布只有这一出口；部分成功也必须发布实际结果。
        if (stats.changed) await this.plugin._flushIndexQueueNow();
        return stats;
    }

    transformValue(paths, key, transform) {
        key = validateEditablePropertyKey(key);
        return this._mutateFiles(paths, file =>
            this._editFrontmatter(file, data => {
                const beforePresent = Object.prototype.hasOwnProperty.call(data, key);
                const before = data[key];
                const after = transform(before);
                const afterPresent = after !== undefined;
                if (frontmatterPropertyStateEqual(beforePresent, before, afterPresent, after)) {
                    return "unchanged";
                }
                if (!afterPresent) delete data[key];
                else data[key] = after;
                return "changed";
            })
        );
    }

    applyMetadataDraft(paths, {
        addTags = [],
        removeTags = [],
        properties = []
    } = {}) {
        const wantedAddTags = this._normalizeTagList(addTags);
        const wantedRemoveTagKeys = new Set(
            this._normalizeTagList(removeTags).map(tagIdentityKey)
        );
        const propertyOps = (Array.isArray(properties) ? properties : [])
            .map(operation => {
                const key = validateEditablePropertyKey(operation?.key);
                return {
                    key,
                    propertyType: normalizeMetadataPropertyType(operation?.propertyType),
                    isNewKey: Boolean(operation?.isNewKey),
                    removeValues: Array.isArray(operation?.removeValues)
                        ? operation.removeValues
                        : [],
                    addValues: Array.isArray(operation?.addValues)
                        ? operation.addValues
                        : []
                };
            })
            .filter(Boolean);

        const createdPropertyKeys = new Set();
        const valueKeySet = values => new Set(
            (Array.isArray(values) ? values : [])
                .filter(value => value !== MISSING_PROPERTY_VALUE)
                .map(propertyValueKey)
        );
        const normalizeAddSamples = values => {
            const result = [];
            const seen = new Set();
            for (const raw of Array.isArray(values) ? values : []) {
                for (const normalized of normalizePropertyValues(raw)) {
                    if (
                        normalized === MISSING_PROPERTY_VALUE
                        || normalized === PRESENT_PROPERTY_VALUE
                        || normalized === EMPTY_PROPERTY_VALUE
                    ) continue;
                    const id = propertyValueKey(normalized);
                    if (seen.has(id)) continue;
                    const sample = rawSampleForPropertyValue(raw, normalized);
                    if (sample === undefined) continue;
                    seen.add(id);
                    result.push(sample);
                }
            }
            return result;
        };
        const addPropertyValues = (current, addSamples, propertyType) => {
            if (!addSamples.length) return current;
            const listType = propertyType === "multitext" || Array.isArray(current);
            if (current === undefined) {
                return listType ? [...addSamples] : addSamples[0];
            }
            if (!listType) return current;

            const next = flattenPropertyListStructure(current);
            const existing = new Set(
                next.flatMap(item => normalizePropertyValues(item))
                    .map(propertyValueKey)
            );
            let changed = false;
            for (const sample of addSamples) {
                const normalized = normalizePropertyValues(sample)[0];
                if (normalized === undefined) continue;
                const id = propertyValueKey(normalized);
                if (existing.has(id)) continue;
                existing.add(id);
                next.push(sample);
                changed = true;
            }
            return changed ? next : current;
        };
        const equalValue = (a, b) => JSON.stringify(a) === JSON.stringify(b);

        const inspect = frontmatter => {
            const draft = { ...frontmatter };
            const rawTags = draft.tags;
            const beforeTags = this._frontmatterTagList(rawTags);
            const afterTags = beforeTags.filter(tag => !wantedRemoveTagKeys.has(tagIdentityKey(tag)));
            const tagKeys = new Set(afterTags.map(tagIdentityKey));
            for (const tag of wantedAddTags) {
                if (!tagKeys.has(tagIdentityKey(tag))) { afterTags.push(tag); tagKeys.add(tagIdentityKey(tag)); }
            }
            if (JSON.stringify(beforeTags) !== JSON.stringify(afterTags)) {
                if (!afterTags.length) delete draft.tags;
                else draft.tags = Array.isArray(rawTags) || afterTags.length > 1 ? afterTags : afterTags[0];
            }
            for (const operation of propertyOps) {
                const next = addPropertyValues(
                    removeRawPropertyValues(draft[operation.key], valueKeySet(operation.removeValues)),
                    normalizeAddSamples(operation.addValues), operation.propertyType);
                if (next === undefined) delete draft[operation.key];
                else draft[operation.key] = next;
            }
            return [...new Set(["tags", ...propertyOps.map(operation => operation.key)])].flatMap(key => {
                const before = Object.prototype.hasOwnProperty.call(frontmatter, key);
                const present = Object.prototype.hasOwnProperty.call(draft, key);
                return before === present && equalValue(frontmatter[key], draft[key]) ? []
                    : [{ key, present, value: draft[key], created: !before && present
                        && propertyOps.some(operation => operation.key === key && operation.isNewKey) }];
            });
        };

        return this._mutateFiles(paths, async file => {
            let updates = [];
            const status = await this._editFrontmatter(file, data => {
                updates = inspect(data);
                if (!updates.length) return "unchanged";
                for (const update of updates) {
                    if (!update.present) delete data[update.key];
                    else data[update.key] = update.value;
                }
                return "changed";
            });
            if (status === "changed") for (const update of updates) {
                if (update.created) createdPropertyKeys.add(update.key);
            }
            return status;
        }
        ).then(stats => {
            stats.createdPropertyKeys = [...createdPropertyKeys];
            return stats;
        });
    }

    migrateValue(paths, key, normalizedOldValue, newValue, propertyType = "text") {
        return this.transformValue(paths, key, current =>
            renameRawPropertyValue(
                current,
                normalizedOldValue,
                newValue,
                propertyType
            )
        );
    }

    renameKey(paths, oldKey, newKey, completed = null) {
        oldKey = validateEditablePropertyKey(oldKey);
        newKey = validateEditablePropertyKey(newKey);
        return this._mutateFiles(paths, async file => {
            let renamedValue;
            const status = await this._editFrontmatter(file, data => {
                if (!Object.prototype.hasOwnProperty.call(data, oldKey) || oldKey === newKey) {
                    return "unchanged";
                }
                if (Object.prototype.hasOwnProperty.call(data, newKey)) return "conflict";
                renamedValue = JSON.stringify(data[oldKey]);
                data[newKey] = data[oldKey];
                delete data[oldKey];
                return "changed";
            });
            // 仅记录本次真正提交的文件和值；重试凭据归发起弹窗，不持久化为元数据。
            if (status === "changed") completed?.set(file, renamedValue);
            return status;
        });
    }
}

// ========== Picker 基础设施：纯 DOM 构建与聚焦，不持有 SearchCore 业务状态 ==========
export function createPickerHeaderIconAction(parent, {
    icon = "circle",
    label = "操作",
    classes = "",
    danger = false,
    pressed = null,
    interaction = "action",
    onClick = null
} = {}) {
    if (!parent) return null;

    const button = createSearchButton(parent, interaction, {
        cls: [
            "local-search-picker-title-icon-action",
            classes,
            danger ? "is-danger-action" : ""
        ].filter(Boolean).join(" "),
        attr: {
            type: "button",
            "aria-label": label,
            title: label
        }
    });
    if (pressed !== null && pressed !== undefined) {
        button.setAttribute("aria-pressed", String(Boolean(pressed)));
    }
    setIcon(button, icon);
    // Overflow and direct controls share this action; the callback is never copied
    // into another business owner or replayed through a synthetic DOM click.
    button._lsPickerAction = { icon, danger, invoke: event => onClick?.(button, event) };
    button.addEventListener("click", event => {
        event.preventDefault();
        event.stopPropagation();
        button._lsPickerAction.invoke(event);
    });
    return button;
}

export function configureSharedPickerHeader(panel, {
    headingText = "",
    countText = null,
    countAriaLabel = "",
    icon = "list-tree",
    allText = "",
    allTitle = "",
    onAll = null
} = {}) {
    const titleEl = panel.querySelector(".local-search-dropdown-title");
    if (!titleEl) {
        return {
            summary: null,
            heading: null,
            controls: null,
            actions: null,
            selectionActions: null,
            count: null,
            iconBtn: null
        };
    }

    titleEl.empty();
    titleEl.addClass("local-search-folder-dropdown-head");

    const summary = titleEl.createDiv({
        cls: "local-search-picker-title-summary"
    });

    let iconBtn = null;
    if (typeof onAll === "function") {
        iconBtn = createPickerHeaderIconAction(summary, {
            icon,
            label: allTitle || allText || headingText,
            onClick: () => onAll()
        });
    } else if (icon) {
        const iconEl = summary.createSpan({
            cls: "local-search-picker-title-icon",
            attr: { "aria-hidden": "true" }
        });
        setIcon(iconEl, icon);
    }

    const heading = summary.createSpan({
        text: headingText,
        cls: "local-search-folder-dropdown-heading"
    });

    // Header Controls 是标题右侧唯一正式组件：
    // maintenance actions -> selection mode -> count。
    // 组件只负责结构归一；视觉保持透明，不再制造额外 Surface / 外框。
    const controls = summary.createDiv({
        cls: "local-search-picker-title-controls"
    });
    const actions = controls.createDiv({
        cls: "local-search-picker-title-actions"
    });
    const selectionActions = controls.createDiv({
        cls: "local-search-picker-title-selection-actions"
    });

    const count = countText === null || countText === undefined
        ? null
        : controls.createSpan({
            text: String(countText),
            cls: "local-search-picker-title-count",
            attr: {
                "aria-label": countAriaLabel
                    || `当前文件数 ${countText}`
            }
        });

    return {
        summary,
        heading,
        controls,
        actions,
        selectionActions,
        count,
        iconBtn,
        backButton: null
    };
}

export function attachFacetPickerOverflow(core, panel, header) {
    if (!header?.actions || !header?.controls || !header.actions.children.length) return null;
    // The existing action controls keep ownership of their state. Only their
    // presentation moves into the common action list, after the multiselect.
    const source = header.actions;
    source.hidden = true;
    const host = header.controls.ownerDocument.createElement("div");
    host.className = "local-search-picker-title-overflow";
    header.controls.insertBefore(host, header.count || null);
    const button = createPickerHeaderIconAction(host, {
        icon: "ellipsis", label: "更多操作",
        classes: "local-search-picker-overflow-action",
        onClick: () => {
            if (!panel.isConnected || !core.dropdown.isActivePanel(panel)) return;
            const menu = core.dropdown.openChild(button, "更多操作");
            if (!menu) return;
            menu.addClass("local-search-picker-dropdown", "local-search-picker-action-menu");
            configureSharedPickerHeader(menu, { headingText: "更多操作", icon: "ellipsis" });
            const list = menu.createDiv({ cls: "local-search-folder-tree" });
            for (const actionButton of source.children) {
                const action = actionButton._lsPickerAction;
                if (!action || actionButton.disabled) continue;
                const row = createSharedPickerTreeRow(list, {
                    name: actionButton.getAttribute("aria-label") || actionButton.title || "操作",
                    icon: action.icon,
                    active: actionButton.getAttribute("aria-pressed") === "true",
                    onClick: () => {
                        core.dropdown.close(false);
                        if (!panel.isConnected || core._destroyed) return;
                        action.invoke();
                    }
                });
                if (action.danger) row.row.addClass("is-danger-action");
            }
        }
    });
    button.setAttribute("aria-haspopup", "dialog");
    return { button };
}

export function attachPickerHeaderModes(header, {
    modes = [],
    onChange = null
} = {}) {
    const actions = header?.actions;
    if (!actions) return null;

    const definitions = (Array.isArray(modes) ? modes : [])
        .map(mode => ({
            id: String(mode?.id || "").trim(),
            icon: String(mode?.icon || "circle"),
            title: String(mode?.title || "操作"),
            activeTitle: String(mode?.activeTitle || mode?.title || "退出操作"),
            description: String(mode?.description || `${mode?.title || "操作"}：点击条目进行设置`),
            danger: Boolean(mode?.danger)
        }))
        .filter(mode => mode.id);

    const buttons = new Map();
    let activeId = "";

    const sync = () => {
        for (const mode of definitions) {
            const button = buttons.get(mode.id);
            if (!button) continue;
            const active = activeId === mode.id;
            const label = active ? mode.activeTitle : mode.title;
            button.classList.toggle("is-selected", active);
            button.setAttribute("aria-pressed", String(active));
            button.setAttribute("aria-label", label);
            button.title = label;
        }
    };

    const setActive = id => {
        const wanted = definitions.some(mode => mode.id === id) ? id : "";
        if (wanted === activeId) return activeId;
        activeId = wanted;
        sync();
        onChange?.(activeId);
        const panel = actions.closest(".local-search-picker-dropdown");
        panel?.classList.toggle("is-persistent-toggle", Boolean(activeId));
        setPickerSearchMode(panel, definitions.find(mode => mode.id === activeId)?.description || "");
        return activeId;
    };

    for (const mode of definitions) {
        const button = createPickerHeaderIconAction(actions, {
            icon: mode.icon,
            label: mode.title,
            classes: `local-search-picker-title-mode-action${mode.icon === "pencil" ? " is-optical-edit" : ""}`,
            danger: mode.danger,
            pressed: false,
            interaction: "choice",
            onClick: () => {
                setActive(activeId === mode.id ? "" : mode.id);
            }
        });
        buttons.set(mode.id, button);
    }

    sync();
    return {
        buttons,
        get activeId() { return activeId; },
        isActive: id => activeId === id,
        setActive
    };
}

export function facetSelectionCount(state, kind) {
    if (!state) return 0;
    if (kind === "tag") return state.tags?.size || 0;
    if (kind === "folder") return state.folders?.size || 0;
    if (kind === "fileType") return state.fileTypes?.size || 0;
    if (kind === "property") {
        let count = 0;
        for (const values of state.properties?.values?.() || []) {
            count += values?.size || 0;
        }
        return count;
    }
    return 0;
}

export function commitFacetSelectionState(target, draft, kind) {
    if (!target || !draft) return false;
    if (kind === "tag") {
        target.tags = new Set(draft.tags || []);
        // 顶部正式 Facet 多选保持 GLS 自身既有 AND 语义；
        // 筛选池 Multi 的 OR 只由筛选池真实值操作声明，不能由设置项全局劫持。
        target.tagMatchMode = "all";
        return true;
    }
    if (kind === "folder") {
        target.folders = new Set(draft.folders || []);
        return true;
    }
    if (kind === "fileType") {
        target.fileTypes = new Set(draft.fileTypes || []);
        return true;
    }
    if (kind === "property") {
        target.properties = new Map(
            [...(draft.properties || new Map())].flatMap(([key, values]) => {
                const normalized = normalizePropertySelection(values || []);
                return normalized.size ? [[key, normalized]] : [];
            })
        );
        // 顶部属性 Facet 的跨键组合仍为 AND；同键多值继续由 Property Selection 自身 OR。
        target.propertyMatchMode = "all";
        return true;
    }
    return false;
}

export function createFacetPickerSelectionMode(panel, header, {
    core,
    kind,
    title = "多选",
    icon = "list-checks",
    onBeforeEnter = null,
    onStateChange = null,
    onCommit = null
} = {}) {
    const actions = header?.selectionActions;
    if (!panel || !actions || !core || !kind) return null;

    let active = false;
    let draft = null;

    const footer = createSharedPickerFooter(panel);
    const confirm = createSearchButton(footer, "action", {
        cls: "local-search-action-btn local-search-action-primary",
        attr: {
            "aria-label": "确认多选筛选"
        }
    });

    const commit = () => {
        if (!active || !draft) return false;
        if (!commitFacetSelectionState(core.filterState, draft, kind)) return false;
        core._onFilterChanged();
        if (core.dropdown.close() !== false) onCommit?.();
        return true;
    };

    const button = createPickerHeaderIconAction(actions, {
        icon,
        label: `进入${title}`,
        pressed: false,
        interaction: "choice",
        onClick: () => {
            setActive(!active);
        }
    });

    const sync = () => {
        const count = facetSelectionCount(draft, kind);
        const label = active ? `退出${title}` : `进入${title}`;
        button.classList.toggle("is-selected", active);
        button.setAttribute("aria-pressed", String(active));
        button.setAttribute("aria-label", label);
        button.title = label;
        panel.classList.toggle("is-persistent-toggle", active);
        setPickerSearchMode(panel, active ? "点击条目多选，确认后应用" : "");
        if (confirm) {
            confirm.hidden = !active;
            confirm.textContent = "确定";
            confirm.setAttribute("aria-label", `确认多选筛选，已选 ${count} 项`);
        }
    };

    const notify = () => onStateChange?.({ active, draft });

    function setActive(value) {
        const next = Boolean(value);
        if (next === active) return active;

        if (next) {
            onBeforeEnter?.();
            draft = core.filterState.clone();
            active = true;
        } else {
            active = false;
            draft = null;
        }

        sync();
        notify();
        return active;
    }

    const refresh = () => {
        if (!active || !draft) return;
        sync();
        notify();
    };

    confirm?.addEventListener("click", event => {
        event.preventDefault();
        event.stopPropagation();
        commit();
    });

    registerPickerCleanup(panel, () => {
        active = false;
        draft = null;
    });

    sync();
    return {
        button,
        footer,
        confirm,
        isActive: () => active,
        get draft() { return draft; },
        setActive,
        cancel: () => setActive(false),
        refresh,
        commit
    };
}

export function createSharedPickerSelectionStrip(panel, { onClear, canEdit = () => true } = {}) {
    // 母版：当前条件在列表后、底部分割线上；空集合不占位，Chip 原位更新。
    const root = panel.createDiv({ cls: "local-search-picker-current-selection", attr: { role: "group", "aria-label": "当前已选" } });
    const list = root.createDiv({ cls: "local-search-picker-current-list" });
    const clearButton = createSearchButton(root, "action", {
        cls: "local-search-action-btn local-search-picker-condition-clear", text: "清空",
        attr: { "aria-label": "清空当前已选" }
    });
    clearButton.addEventListener("click", event => {
        event.preventDefault();
        event.stopPropagation();
        if (!clearButton.disabled && panel.isConnected && canEdit()) onClear?.();
    });
    const chips = new Map();

    const createChip = key => {
        const chip = createSearchButton(list, "choice", {
            cls: "local-search-picker-current-chip"
        });
        chip.dataset.selectionKey = key;
        chip._lsText = chip.createSpan();
        const x = chip.createSpan({ cls: "local-search-picker-current-chip-x" });
        setIcon(x, "x");
        chip.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            if (chip.disabled || !panel.isConnected || !canEdit()) return;
            const entry = chip._lsSelectionEntry;
            if (!entry) return;
            entry.onRemove?.();
        });
        chips.set(key, chip);
        return chip;
    };

    const render = items => {
        const entries = Array.isArray(items) ? items.filter(Boolean) : [];
        const focused = root.contains(root.ownerDocument.activeElement) ? root.ownerDocument.activeElement : null;
        const focusedIndex = focused ? [...list.children].indexOf(focused) : -1;
        const keyboardFocus = focused?.matches(":focus-visible");
        const seen = new Set();
        const order = [];

        for (const entry of entries) {
            const text = String(entry.text || "");
            if (!text) continue;
            const key = String(entry.key ?? text);
            if (!key || seen.has(key)) continue;
            seen.add(key);
            order.push(key);

            const chip = chips.get(key) || createChip(key);
            chip._lsSelectionEntry = entry;
            chip.disabled = !canEdit();
            chip.title = entry.title || `移除 ${text}`;
            chip.setAttribute("aria-label", entry.title || `移除 ${text}`);
            if (chip._lsText?.textContent !== text) chip._lsText.textContent = text;
        }

        for (const [key, chip] of [...chips]) {
            if (seen.has(key)) continue;
            chip.remove();
            chips.delete(key);
        }

        const currentOrder = [...list.children]
            .map(chip => chip.dataset.selectionKey || "");
        if (JSON.stringify(currentOrder) !== JSON.stringify(order)) {
            const previousLeft = list.scrollLeft;
            for (const key of order) {
                const chip = chips.get(key);
                if (chip) list.appendChild(chip);
            }
            const maxLeft = Math.max(0, list.scrollWidth - list.clientWidth);
            list.scrollLeft = Math.min(previousLeft, maxLeft);
        }
        root.hidden = !order.length;
        clearButton.disabled = !order.length || !canEdit() || typeof onClear !== "function";
        if (keyboardFocus && (!focused.isConnected || root.hidden)) {
            (chips.get(order[Math.max(0, Math.min(focusedIndex, order.length - 1))])
                || panel.querySelector(".local-search-picker-search"))?.focus({ preventScroll: true });
        }
    };

    render([]);
    registerPickerCleanup(panel, () => chips.clear());
    return { root, list, clearButton, render };
}

export function createPickerRowAction(row, {
    icon = "pencil",
    label = "操作",
    danger = false,
    interaction = "action",
    onClick = null
} = {}) {
    const options = {
        cls: [
            "local-search-picker-row-action",
            danger ? "is-danger-action" : "",
            icon === "eye-off" ? "is-hidden-state" : ""
        ].filter(Boolean).join(" "),
        attr: {
            type: "button",
            "data-ls-no-drag": "true",
            "aria-label": label,
            title: label
        }
    };
    const button = createSearchButton(row, interaction, options);
    setIcon(button, icon);
    button.addEventListener("click", event => {
        event.preventDefault();
        event.stopPropagation();
        onClick?.(button, event);
    });
    return button;
}

export function openFilterToolbarIconPicker(core, {
    anchor,
    propertyKey = "",
    currentIcon = PROPERTY_SHORTCUT_DEFAULT_ICON,
    defaultIcon = PROPERTY_SHORTCUT_DEFAULT_ICON,
    preserveAnchor = false,
    heading = "",
    onSelect = null
} = {}) {
    const key = String(propertyKey || "").trim();
    if (!core || !anchor || !key) return null;
    const fromComposer = Boolean(anchor.closest?.(
        ".local-search-view-composer, .local-search-filter-pool-config-picker"
    ));
    const stableAnchor = preserveAnchor ? anchor : (fromComposer && core.resultControls?.resultViewBtn?.isConnected)
        ? core.resultControls.resultViewBtn
        : (core.propertyFilterBtn?.isConnected ? core.propertyFilterBtn : anchor);
    const panel = core.dropdown.openChild(stableAnchor, `图标 · ${key}`);
    if (!panel) return null;
    panel.addClass("local-search-folder-dropdown", "local-search-picker-dropdown", "local-search-facet-picker");
    panel.dataset.lsIconPicker = "true";
    const catalog = filterToolbarIconCatalog();
    const catalogSet = core.plugin._pickerIconIds = new Set(catalog);
    currentIcon = resolvePickerIcon(core.plugin, currentIcon, defaultIcon);
    const header = configureSharedPickerHeader(panel, {
        headingText: heading || `筛选图标 · ${key}`,
        icon: currentIcon || PROPERTY_SHORTCUT_DEFAULT_ICON
    });
    const { search, list } = createSharedPickerTreeShell(panel, {
        placeholder: "搜索图标名称…", showRoot: false
    });
    const presetSet = new Set(FILTER_TOOLBAR_ICON_PRESETS);
    const submission = core.dropdown.submissionFor(panel);
    const select = (icon, remember = true) => submission.submit(async () => {
        const accepted = await onSelect?.(icon);
        if (accepted === false) return false;
        if (remember) rememberPickerIcon(core.plugin, icon);
        return true;
    }, [...panel.querySelectorAll("button, input")], "图标保存失败，请重试");
    const reset = createPickerHeaderIconAction(header.actions, {
        icon: "rotate-ccw", label: "恢复默认图标", onClick: () => { void select(defaultIcon, false); }
    });
    reset.disabled = currentIcon === defaultIcon;
    const render = () => {
        list.empty();
        const query = search.value.trim().toLowerCase();
        const recent = normalizeRecentIconIds(core.plugin.settings.recentIconIds).filter(id => catalogSet.has(id));
        const groups = query
            ? [{ ids: catalog.filter(id => String(id).toLowerCase().includes(query)), label: "" }]
            : [{ ids: recent, label: "最近使用" }, {
                ids: normalizeUniqueStringList([currentIcon, defaultIcon, ...catalog.filter(id => presetSet.has(id))])
                    .filter(id => !recent.includes(id)), label: recent.length ? "常用图标" : ""
            }];
        let shown = 0;
        for (const group of groups) {
            const visible = group.ids.slice(0, Math.max(0, 96 - shown));
            if (group.label && visible.length) list.createDiv({ cls: "local-search-picker-section-label", text: group.label });
            for (const iconId of visible) {
                createSharedPickerTreeRow(list, {
                    depth: 0, active: iconId === currentIcon,
                    itemTitle: `使用图标 ${iconId}`, icon: iconId, name: iconId,
                    onClick: () => { void select(iconId); }
                });
            }
            shown += visible.length;
        }
        const count = groups.reduce((sum, group) => sum + group.ids.length, 0);
        if (!shown) list.createDiv({ cls: "local-search-empty-hint", text: "没有匹配的图标" });
        else if (count > shown) list.createDiv({ cls: "local-search-empty-hint", text: `继续输入以缩小范围 · ${count} 个匹配` });
    };
    activatePickerSearch(search, { onInput: render, initialRender: render });
    return panel;
}

export function trapDialogTab(root, event) {
    if (event.key !== "Tab" || event.isComposing || event.keyCode === 229 || event.defaultPrevented || !root?.isConnected) return false;
    const controls = [...root.querySelectorAll('button:not(:disabled), input:not(:disabled), textarea:not(:disabled), select:not(:disabled), a[href], [tabindex]')]
        .filter(node => node.tabIndex >= 0 && !node.closest('[hidden], [inert]') && node.getClientRects().length);
    const active = root.ownerDocument.activeElement;
    const first = controls[0], last = controls[controls.length - 1];
    if (!first || !root.contains(active) || (event.shiftKey ? active === first : active === last)) {
        event.preventDefault();
        event.stopPropagation();
        if (!first) root.tabIndex = -1;
        (event.shiftKey ? last : first)?.focus({ preventScroll: true });
        if (!first) root.focus({ preventScroll: true });
        return true;
    }
    return false;
}

// BEGIN SHARED DIALOG SUBMISSION — generated from shared/dialog-submission.js
// One submission owner per dialog or picker; host adapters own layout and dismissal.
// Read-only text fields preserve the current keyboard/caret while work is pending.
export function createDialogSubmission(root, isActive, close, reportError) {
    let busy = false;
    return {
        get busy() { return busy; },
        async submit(operation, controls, failureMessage, onError = reportError, { closeOnSuccess = true } = {}) {
            if (busy || !isActive()) return false;
            busy = true;
            root.setAttribute("aria-busy", "true");
            const doc = root.ownerDocument;
            const focused = root.contains(doc.activeElement) && doc.activeElement.matches?.(":focus-visible") ? doc.activeElement : null;
            const previous = controls.map(node => [node, node.disabled, node.readOnly]);
            for (const [node] of previous) {
                const text = node.tagName === "TEXTAREA" || (node.tagName === "INPUT"
                    && ["text", "search", "tel", "url", "email", "password", "date", "month", "week", "time", "datetime-local", "number"].includes(node.type));
                if (text) node.readOnly = true;
                else node.disabled = true;
            }
            try {
                const result = await operation();
                if (result === false) return false;
                busy = false;
                if (closeOnSuccess && isActive()) close();
                return true;
            } catch (error) {
                if (isActive()) onError?.(error, failureMessage);
                return false;
            } finally {
                busy = false;
                if (isActive()) {
                    root.removeAttribute("aria-busy");
                    for (const [node, disabled, readOnly] of previous) {
                        node.disabled = disabled;
                        if (readOnly !== undefined) node.readOnly = readOnly;
                    }
                    if (focused?.isConnected && doc.activeElement === doc.body) focused.focus({ preventScroll: true });
                }
            }
        }
    };
}

// END SHARED DIALOG SUBMISSION
export function resolveOverlayBounds(ownerEl, view, insetX = 0, insetY = insetX, useVisualViewport = true) {
    // 移动端 Popup 外框必须锁在一级主窗 / layout viewport 上。软键盘只改变可见区，
    // 不得把二级/三级 Surface 当成新的几何源反复重排。桌面仍可使用 visualViewport。
    const viewport = useVisualViewport ? view.visualViewport : null;
    const left = viewport?.offsetLeft || 0, top = viewport?.offsetTop || 0;
    const width = Math.max(1, viewport?.width || view.innerWidth || 1);
    const height = Math.max(1, viewport?.height || view.innerHeight || 1);
    const owner = ownerEl?.isConnected ? ownerEl.getBoundingClientRect() : null;
    const edgeX = Math.min(Math.max(0, insetX), Math.max(0, (width - 1) / 2));
    const edgeY = Math.min(Math.max(0, insetY), Math.max(0, (height - 1) / 2));
    let x1 = Math.max(left + edgeX, owner ? owner.left + edgeX : left + edgeX);
    let x2 = Math.min(left + width - edgeX, owner ? owner.right - edgeX : left + width - edgeX);
    let y1 = Math.max(top + edgeY, owner ? owner.top + edgeY : top + edgeY);
    let y2 = Math.min(top + height - edgeY, owner ? owner.bottom - edgeY : top + height - edgeY);
    if (x2 <= x1) { x1 = left + edgeX; x2 = left + width - edgeX; }
    if (y2 <= y1) { y1 = top + edgeY; y2 = top + height - edgeY; }
    return { left: x1, right: x2, top: y1, bottom: y2, width: x2 - x1, height: y2 - y1,
        owner: owner || { left, top, right: left + width, bottom: top + height, width, height } };
}

export function observePickerCountRail(panel, list, property) {
    const view = panel.ownerDocument.defaultView;
    let active = true;
    const sync = () => {
        if (active && panel.isConnected && list.isConnected)
            panel.style.setProperty(property, `${Math.max(0, list.offsetWidth - list.clientWidth)}px`);
    };
    const observer = new view.ResizeObserver(sync);
    observer.observe(list);
    let frame = view.requestAnimationFrame(() => { frame = null; sync(); });
    return () => {
        active = false;
        observer.disconnect();
        if (frame !== null) view.cancelAnimationFrame(frame);
        frame = null;
    };
}

export function createDialogSession(core, {
    backdropClass = "local-search-confirm-backdrop",
    ownerPanel = null,
    kind = "confirm",
    onFinish = null
} = {}) {
    if (core?._destroyed || !core?.containerEl?.isConnected) return null;
    const previous = core._confirmSession;
    if (previous) {
        previous.finish(false);
        if (!previous.settled) return null;
    }

    const doc = core.containerEl.ownerDocument;
    const focusOwner = ownerPanel?.isConnected ? ownerPanel : core.popupSurfaceHost();
    const host = focusOwner;
    const focusOrigin = ownerPanel?.isConnected ? ownerPanel : core.containerEl;
    const focused = doc.activeElement;
    // Mobile text inputs match :focus-visible after a finger tap as well.
    // Closing a child dialog must not resurrect that parent's native editing
    // session; it follows the same return-focus contract as child Pickers.
    const previousFocus = focusOrigin.contains(focused) && focused.matches?.(":focus-visible")
        && (!Platform.isMobile || !focused.matches?.('input, textarea, select, [contenteditable]:not([contenteditable="false"])'))
        ? focused : null;
    const fallbackFocus = focusOrigin.querySelector("button:not(:disabled)");
    const backdrop = host.createDiv({ cls: `${backdropClass} local-search-dialog-backdrop`.trim() });
    let dialog = null, submission = null, swipeCleanup = null, settled = false, resolveFinished;
    const finished = new Promise(resolve => { resolveFinished = resolve; });
    const active = () => !settled && !core._destroyed && dialog?.isConnected && core.containerEl.isConnected;

    // User dismissals wait for the transaction. Only host teardown may force
    // disposal; that ends the UI lease, not the already-started file operation.
    const finish = (value, { force = false, restoreFocus = true } = {}) => {
        if (settled || (submission?.busy && !force)) return false;
        const shouldRestore = restoreFocus && previousFocus && focusOwner.isConnected && !core._destroyed
            && (dialog?.contains(doc.activeElement) || doc.activeElement === doc.body);
        settled = true;
        swipeCleanup?.();
        swipeCleanup = null;
        focusOwner.removeEventListener("keydown", trapKeyboard, true);
        if (core._confirmSession === session) core._confirmSession = null;
        backdrop.remove();
        dialog?.remove();
        const confirmed = Boolean(value);
        try { onFinish?.(confirmed); }
        finally {
            resolveFinished(confirmed);
            if (!core._destroyed) core._scheduleResultIndexUpdate?.();
        }
        const target = previousFocus?.isConnected ? previousFocus : fallbackFocus;
        if (shouldRestore && !core._confirmSession && !core._destroyed && focusOwner.isConnected
            && target?.isConnected && !target.disabled && doc.activeElement === doc.body) {
            target.focus({ preventScroll: true });
        }
        return confirmed;
    };
    const trapKeyboard = event => {
        if (!active() || event.isComposing || event.keyCode === 229) return;
        if (event.key === "Escape") {
            event.preventDefault();
            event.stopImmediatePropagation();
            finish(false);
            return;
        }
        trapDialogTab(dialog, event);
    };
    focusOwner.addEventListener("keydown", trapKeyboard, true);
    const swallow = event => { event.stopPropagation(); event.stopImmediatePropagation(); };
    backdrop.addEventListener("pointerdown", swallow);
    backdrop.addEventListener("pointerup", swallow);
    backdrop.addEventListener("click", event => { event.preventDefault(); swallow(event); finish(false); });
    const session = {
        host, backdrop, ownerPanel, kind, finished, finish,
        get settled() { return settled; },
        get busy() { return Boolean(submission?.busy); },
        submit(operation, controls, errorText) { return submission?.submit(operation, controls, errorText) ?? false; },
        setDialog(value) {
            swipeCleanup?.();
            swipeCleanup = null;
            dialog = value;
            if (isDomElement(dialog)) {
                submission = createDialogSubmission(dialog, active, () => finish(true),
                    (error, fallback) => new Notice(error?.message || fallback));
                swipeCleanup = core.plugin?.swipeBack?.register(dialog, {
                    canGoBack: () => active() && !session.busy,
                    back: () => finish(false)
                }, [backdrop]) ?? null;
            }
            return dialog;
        }
    };
    core._confirmSession = session;
    return session;
}

// 文件重命名与删除保持同一个 Dialog 固定几何：不再监听软键盘、
// visualViewport 或动态覆盖中心坐标。iOS 仅由系统负责输入焦点与键盘。

export function openSearchRenameDialog(core, {
    ownerPanel = core.dropdown?.panel || null,
    kind = "rename",
    onFinish = null,
    title = "重命名",
    message = "",
    fieldLabel = "名称",
    initialValue = "",
    placeholder = "",
    confirmText = "确定",
    errorText = "保存失败",
    onSubmit = null
} = {}) {
    if (typeof onSubmit !== "function") return false;
    const session = createDialogSession(core, {
        backdropClass: "local-search-picker-dialog-backdrop",
        ownerPanel, kind,
        onFinish
    });
    if (!session) return null;

    const standaloneFileRename = kind === "rename-file" && !ownerPanel;
    const originalValue = String(initialValue || "");
    const surface = createSharedDialogSurface(session.host, {
        title, message, confirmText,
        closeable: standaloneFileRename,
        field: { label: fieldLabel, placeholder, value: originalValue },
        onFinish: confirmed => {
            if (!confirmed) session.finish(false);
            else void submit();
        }
    });
    const { dialog, input, cancelButton, confirmButton } = surface;
    dialog.addClass("local-search-picker-dialog", "local-search-rename-dialog");
    if (standaloneFileRename) dialog.addClass("local-search-file-rename-dialog", "local-search-file-operation-dialog");
    session.setDialog(dialog);

    const submit = () => {
        if (session.settled || session.busy) return;
        const next = String(input.value || "").trim();
        if (!next) {
            new Notice(`请输入${fieldLabel}`);
            input.focus({ preventScroll: true });
            return;
        }
        if (next === originalValue) { session.finish(false); return; }
        return session.submit(() => onSubmit(next), [input, cancelButton, confirmButton], errorText);
    };

    dialog.addEventListener("pointerdown", event => event.stopPropagation());
    dialog.addEventListener("click", event => event.stopPropagation());
    input.addEventListener("keydown", event => {
        event.stopPropagation();
        if (event.isComposing || event.keyCode === 229 || event.key !== "Enter") return;
        event.preventDefault();
        void submit();
    });

    input.focus({ preventScroll: true });
    if (Platform.isMobile) {
        // iOS: place the insertion caret after the editable base name, never select-all.
        if (input.ownerDocument.activeElement === input) {
            try { input.setSelectionRange(input.value.length, input.value.length); } catch (_) {}
        }
    } else input.select();
    return session;
}

export function openPickerDeleteDialog(core, {
    title = "删除",
    message = "",
    confirmText = "删除",
    onConfirm = null
} = {}) {
    if (typeof onConfirm !== "function") return false;
    const session = createDialogSession(core, {
        backdropClass: "local-search-picker-dialog-backdrop",
        ownerPanel: core.dropdown?.panel || null
    });
    if (!session) return false;

    const surface = createSharedDialogSurface(session.host, {
        title, message, confirmText, danger: true,
        onFinish: (confirmed, controls) => {
            if (!confirmed) { session.finish(false); return; }
            void session.submit(onConfirm, [controls.cancelButton, controls.confirmButton], "删除失败");
        }
    });
    surface.dialog.addClass("local-search-picker-dialog");
    session.setDialog(surface.dialog);
    surface.dialog.addEventListener("pointerdown", event => event.stopPropagation());
    surface.dialog.addEventListener("click", event => event.stopPropagation());
    surface.cancelButton.focus({ preventScroll: true });
    return true;
}

export function attachPickerSortModeToggle(header, {
    label = "拖拽",
    onChange = null
} = {}) {
    const actions = header?.actions;
    if (!actions) return null;

    let active = false;
    const button = createPickerHeaderIconAction(actions, {
        icon: "arrow-up-down",
        label: `进入${label}拖拽模式`,
        pressed: false,
        interaction: "choice",
        onClick: () => setActive(!active)
    });
    if (!button) return null;

    const sync = () => {
        const nextLabel = active
            ? `退出${label}拖拽模式`
            : `进入${label}拖拽模式`;
        button.classList.toggle("is-selected", active);
        button.setAttribute("aria-pressed", String(active));
        button.setAttribute("aria-label", nextLabel);
        button.title = nextLabel;
    };

    const setActive = value => {
        const next = Boolean(value);
        if (next === active) return active;
        active = next;
        sync();
        onChange?.(active);
        const panel = actions.closest(".local-search-picker-dropdown");
        panel?.classList.toggle("is-persistent-toggle", active);
        setPickerSearchMode(panel, active ? "拖动条目调整顺序" : "");
        return active;
    };

    sync();

    return {
        button,
        get active() { return active; },
        setActive,
        destroy() {
            setActive(false);
        }
    };
}

export function disposePickerCleanup(panel) {
    const cleanup = panel?._lsCleanup;
    if (panel) panel._lsCleanup = null;
    try { cleanup?.(); } catch (error) { console.warn("Picker cleanup failed", error); }
}

export function registerPickerCleanup(panel, cleanup) {
    if (!panel || typeof cleanup !== "function") return;
    const previous = panel._lsCleanup;
    panel._lsCleanup = () => {
        try { previous?.(); } catch (error) { console.warn("Picker cleanup failed", error); }
        try { cleanup(); } catch (error) { console.warn("Picker cleanup failed", error); }
    };
}

// BEGIN SHARED NAVIGATION — generated from shared/navigation.js
// Canonical navigation source. Bundled into each independent plugin by build_shared.py.
// One registry per document/input adapter; plugin instances own only their leases.
export function swipeBackCanNavigate(layer) {
    if (!layer || layer.disposed || layer.working || !layer.surface.isConnected
        || layer.surface.closest("[hidden], [inert], .pwb-modal-suspended")) return false;
    try { return layer.isEnabled() && layer.navigation.canGoBack?.() !== false; }
    catch (_) { return false; }
}

export function swipeBackResolve(layers, target) {
    if (target.closest("[hidden], [inert], .pwb-modal-suspended")) return null;
    let best = null, bestRoot = null;
    for (const layer of layers) {
        if (layer.disposed || !layer.surface.isConnected) continue;
        for (const root of layer.roots) {
            if (!root.isConnected || !root.contains(target)) continue;
            if (!bestRoot || bestRoot === root || bestRoot.contains(root)) {
                best = layer; bestRoot = root;
            }
        }
    }
    return best;
}

export function swipeBackNativeGestureOwner(doc, target) {
        if (target?.nodeType !== 1) return false;
        const win = doc.defaultView;
        if (doc.querySelector(".ui-sort-feedback")
            || target.closest(".is-sort-mode [data-sort-key], .is-sort-committing [data-sort-key]")
            || target.closest("[data-db-sort-key]")?._dbSortBound) return true;
        // Native horizontal scrolling owns the entire gesture, including either edge.
        for (let node = target; node; node = node.parentElement) {
            if (node.scrollWidth > node.clientWidth + 1) {
                const overflow = win.getComputedStyle(node).overflowX;
                if (overflow === "auto" || overflow === "scroll") return true;
            }
        }
        return Boolean(target.closest([
            "a, img, [draggable='true'], .cm-editor, .markdown-source-view",
            "[data-pwb-horizontal-gesture], [data-pwb-swipe-action]",
            ".pwb-layout-grip, .pwb-sort-active",
            ".local-search-drag-handle, .local-search-resize-handle",
            ".local-search-swipe-shell.has-swipe-actions",
            ".local-search-view-sort-list.is-sort-mode, .is-sort-committing",
            ".dida-bridge-drag-handle, .dida-bridge-resize-handle",
            ".dida-bridge-result-swipe-node.has-swipe-actions",
            ".dida-bridge-detail-checklist-row, .dida-bridge-tree-sort-active"
        ].join(", ")));
}

export function createSharedSwipeBackRealm(doc, key) {
    const win = doc.defaultView, layers = [], cleanups = [];
    let phase = 0, pointerId = null, entry = null, startX = 0, startY = 0;
    let suppressClickUntil = 0, releaseTimer = null, disposed = false;
    const element = value => value?.nodeType === 1;
    const clear = () => { phase = 0; pointerId = null; entry = null; };
    const consume = event => {
        if (event.cancelable) event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation?.();
    };
    const releaseIfIdle = () => {
        if (layers.length || disposed) return;
        if (releaseTimer !== null) win.clearTimeout(releaseTimer);
        releaseTimer = null;
        // Closing the final surface must still swallow this gesture's synthetic click.
        const remaining = suppressClickUntil - Date.now();
        if (remaining > 0) { releaseTimer = win.setTimeout(releaseIfIdle, remaining); return; }
        disposed = true;
        clear();
        for (const cleanup of cleanups) cleanup();
        if (doc[key] === realm) delete doc[key];
    };
    const canBack = swipeBackCanNavigate;
    const resolve = target => swipeBackResolve(layers, target);
    const priority = target => swipeBackNativeGestureOwner(doc, target);
    const listen = (type, listener, options) => {
        win.addEventListener(type, listener, options);
        cleanups.push(() => win.removeEventListener(type, listener, options));
    };
    listen("pointerdown", event => {
        if (event.isPrimary === false) { clear(); return; }
        suppressClickUntil = 0;
        clear();
        releaseIfIdle();
        if (disposed || event.button > 0 || event.ctrlKey || event.metaKey || event.altKey || event.shiftKey) return;
        const target = element(event.target) ? event.target : null;
        if (!target) return;
        const layer = resolve(target);
        // Disabled / blocked children never fall through to their parent.
        if (!canBack(layer) || target.isContentEditable || target.closest("input, textarea, select, option")
            || priority(target)) return;
        if (event.pointerType === "mouse" && !target.closest("button, [role='button']")
            && [...target.childNodes].some(node => node.nodeType === 3 && String(node.textContent || "").trim())
            && win.getComputedStyle(target).userSelect !== "none") return;
        phase = 1; pointerId = event.pointerId; entry = layer;
        startX = event.clientX; startY = event.clientY;
    }, true);
    listen("pointermove", event => {
        if (event.pointerId !== pointerId || phase === 0 || phase === 3) return;
        if (!canBack(entry) || (event.pointerType === "mouse" && !(event.buttons & 1))) { clear(); return; }
        if (phase === 1 && priority(event.target)) { phase = 3; return; }
        const dx = event.clientX - startX, dy = Math.abs(event.clientY - startY);
        if (phase === 1) {
            if (Math.abs(dx) < 10 && dy < 10) return;
            if (dx <= 0 || dx < dy * 1.35) { phase = 3; return; }
            phase = 2;
        }
        if (phase === 2) consume(event);
    }, { capture: true, passive: false });
    listen("pointerup", event => {
        if (event.pointerId !== pointerId || phase === 0) return;
        const layer = entry, dx = event.clientX - startX, dy = Math.abs(event.clientY - startY);
        const commit = phase === 2 && dx >= 48 && dx > dy * 1.35 && canBack(layer);
        if (phase === 2) { consume(event); suppressClickUntil = Date.now() + 320; }
        clear();
        if (commit) {
            layer.working = true;
            try {
                const result = layer.navigation.back();
                if (result?.then) Promise.resolve(result).then(
                    () => { layer.working = false; },
                    error => { layer.working = false; console.warn("Swipe-Back 返回失败", error); }
                );
                else layer.working = false;
            } catch (error) { layer.working = false; console.warn("Swipe-Back 返回失败", error); }
        }
        releaseIfIdle();
    }, true);
    listen("pointercancel", event => { if (event.pointerId === pointerId) clear(); }, true);
    listen("click", event => {
        if (Date.now() < suppressClickUntil) { suppressClickUntil = 0; consume(event); }
        releaseIfIdle();
    }, true);
    listen("blur", clear);
    const realm = {
        add(layer) {
            if (releaseTimer !== null) win.clearTimeout(releaseTimer);
            releaseTimer = null;
            layers.push(layer);
            return () => {
                if (layer.disposed) return;
                layer.disposed = true;
                const index = layers.indexOf(layer);
                if (index >= 0) layers.splice(index, 1);
                if (entry === layer) clear();
                releaseIfIdle();
            };
        }
    };
    return realm;
}

// Mac touchpad horizontal-wheel adapter v2: shared across GLS, Dida and Workbench.
// Pointer/Touch retain the existing independent v1 state machine. Navigation
// semantics belong to the original layer callbacks, not this input adapter.
// All plugins use one document symbol and one committed-gesture lock.
export function createSharedTrackpadBackRealm(doc, key) {
    const win = doc.defaultView, layers = [];
    let session = null, disposed = false, releaseTimer = null;
    const releaseIfIdle = () => {
        if (layers.length || disposed) return;
        if (releaseTimer !== null) win.clearTimeout(releaseTimer);
        releaseTimer = null;
        const remaining = session?.committed ? 480 - (Date.now() - session.lastAt) : 0;
        if (remaining > 0) { releaseTimer = win.setTimeout(releaseIfIdle, remaining); return; }
        disposed = true;
        session = null;
        win.removeEventListener("wheel", onWheel, true);
        if (doc[key] === realm) delete doc[key];
    };
    const canBack = swipeBackCanNavigate;
    const resolve = target => swipeBackResolve(layers, target);
    const nativeOwner = target => swipeBackNativeGestureOwner(doc, target);
    const foreignOwner = target => Boolean(target.closest([
        ".pwb-gls-embed, .pwb-dida-embed, .dida-bridge-embedded-host",
        ".local-search-swipe-shell, .local-search-modal, .local-search-embedded-host",
        ".dida-bridge-task-center, .dida-bridge-modal-shell",
        ".dida-bridge-dialog-container, .dida-bridge-child-dialog-surface"
    ].join(", ")));
    const consume = event => {
        if (event.cancelable) event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation?.();
    };
    // Electron's horizontal wheel sign changes when Natural Scrolling is off.
    const goesRight = event => event.webkitDirectionInvertedFromDevice === false
        ? event.deltaX > 0 : event.deltaX < 0;
    const onWheel = event => {
        const now = Date.now();
        // Once a gesture has navigated, it cannot navigate again when the
        // closing child's DOM disappears and inertia lands on its parent.
        // Do this before resolving the new target or checking its visibility.
        if (session?.committed) {
            if (now - session.lastAt <= 480) {
                if (event.deltaMode === 0 && Math.abs(event.deltaX) >= 2
                    && goesRight(event) && Math.abs(event.deltaX) >= Math.abs(event.deltaY) * 1.45) {
                    session.lastAt = now;
                    consume(event);
                }
                return;
            }
            session = null;
        }
        if (disposed || event.defaultPrevented || event.ctrlKey || event.metaKey || event.altKey
            || event.shiftKey || event.deltaMode !== 0 || !Number.isFinite(event.deltaX)
            || !Number.isFinite(event.deltaY)) { session = null; return; }
        const target = event.target?.nodeType === 1 ? event.target : event.target?.parentElement;
        if (!target || !target.isConnected) { session = null; return; }
        const layer = resolve(target);
        // Only Workbench yields for foreign UI with no native layer. Once GLS
        // or Dida has registered a deeper layer it MUST be allowed to navigate.
        if (!canBack(layer) || (layer.owner === "workbench" && foreignOwner(target))
            || target.isContentEditable || target.closest("input, textarea, select, option, [contenteditable]")
            || nativeOwner(target) || Boolean(win.getSelection?.()?.toString()?.trim())) {
            session = null; return;
        }
        const horizontal = Math.abs(event.deltaX), vertical = Math.abs(event.deltaY);
        if (horizontal < 2 || horizontal < vertical * 1.45 || !goesRight(event)) {
            session = null; return;
        }
        if (!session || session.layer !== layer || now - session.lastAt > 260) {
            session = { layer, distance: 0, count: 0, startedAt: now, lastAt: now, committed: false };
        }
        session.lastAt = now;
        session.distance += horizontal;
        session.count++;
        // Pixel-mode + 3 samples + horizontal dominance: don't steal a normal
        // mouse click, Shift+wheel, vertical scroll or imprecise diagonal scroll.
        if (session.count < 3 || session.distance < 78 || now - session.startedAt > 520) return;
        session.committed = true;
        consume(event);
        layer.working = true;
        try {
            const result = layer.navigation.back();
            if (result?.then) Promise.resolve(result).then(
                () => { layer.working = false; },
                error => { layer.working = false; console.warn("Mac 触控板右滑返回失败", error); }
            );
            else layer.working = false;
        } catch (error) { layer.working = false; console.warn("Mac 触控板右滑返回失败", error); }
    };
    win.addEventListener("wheel", onWheel, { capture: true, passive: false });
    const realm = {
        add(layer) {
            if (releaseTimer !== null) win.clearTimeout(releaseTimer);
            releaseTimer = null;
            layers.push(layer);
            return () => {
                const index = layers.indexOf(layer);
                if (index >= 0) layers.splice(index, 1);
                // A committed lock survives deregistration while other layers
                // remain. The inertial tail must not back out of the parent.
                if (session?.layer === layer && !session.committed) session = null;
                releaseIfIdle();
            };
        }
    };
    return realm;
}

export function getSharedTrackpadBackRealm(doc, isMobileApp) {
    const win = doc?.defaultView;
    if (!win || isMobileApp || !/Mac/i.test(String(win.navigator?.platform || "")
        + " " + String(win.navigator?.userAgent || ""))) return null;
    const key = Symbol.for("gls-dida.swipe-back.trackpad.v2");
    return doc[key] || (doc[key] = createSharedTrackpadBackRealm(doc, key));
}

export class SharedSwipeBackPrimitive {
    constructor(owner, isEnabled, isMobileApp) {
        this.owner = owner;
        this.isEnabled = typeof isEnabled === "function" ? isEnabled : () => true;
        this.isMobileApp = isMobileApp;
        this.releases = new Set();
        this.disposed = false;
    }
    register(surface, navigation, hitRoots = []) {
        const doc = surface?.ownerDocument;
        if (this.disposed || surface?.nodeType !== 1 || !doc?.defaultView || typeof navigation?.back !== "function") return () => {};
        const key = Symbol.for("gls-dida.swipe-back.v1");
        const realm = doc[key] || (doc[key] = createSharedSwipeBackRealm(doc, key));
        const roots = [surface, ...(Array.isArray(hitRoots) ? hitRoots : [hitRoots])]
            .filter(root => root?.nodeType === 1 && root.ownerDocument === doc);
        const layer = { surface, navigation, roots, owner: this.owner, isEnabled: this.isEnabled, disposed: false, working: false };
        const removePointer = realm.add(layer);
        const removeWheel = getSharedTrackpadBackRealm(doc, this.isMobileApp)?.add(layer);
        const release = () => { removeWheel?.(); removePointer(); this.releases.delete(release); };
        this.releases.add(release);
        return release;
    }
    dispose() {
        this.disposed = true;
        for (const release of [...this.releases]) release();
    }
}

// END SHARED NAVIGATION

export class LocalSearchSwipeBackPrimitive extends SharedSwipeBackPrimitive {
    constructor(isEnabled = () => true) { super("gls", isEnabled, Platform.isMobileApp); }
}

export function activatePickerSearch(search, {
    onInput = null,
    initialRender = null
} = {}) {
    if (!search) return;
    if (typeof onInput === "function") {
        search.addEventListener("input", onInput);
    }
    // Picker 打开只渲染，不夺取焦点；搜索由用户主动点击输入框后开始。
