}

export function renderSharedPickerRoot(rootHost, {
    rowClasses = "",
    itemClasses = "",
    title = "",
    icon = "list-tree",
    name = "",
    count = null,
    countClasses = "",
    active = false,
    interactive = true,
    onClick = null
} = {}) {
