        if (!owner || !anchor || this.busy) return null;

        owner._releaseSearchFocusForControl();
        if (this.close(false, { returnToParent: false }) === false) return null;
        this._frameLock = null;
        return this._mountPanel(anchor, title, { bindGlobalListeners: true, frameLock: null });
    }

    // 子 Picker 复用同一个 Dropdown Controller，但只暂存父 Surface。
    // 父结果视图不销毁、不重建；关闭子 Picker 后原位恢复。
    openChild(anchor, title) {
        const owner = this.owner;
        if (!owner || !anchor || this.busy) return null;
        if (!this.panel) return this.open(anchor, title);

        owner._releaseSearchFocusForControl();
        const childFrame = this._captureFrame(this.panel);
        const parentDocument = this.panel.ownerDocument;
        const active = parentDocument.activeElement;
        const returnFocusEl = this.panel.contains(active)
            && active?.matches?.(":focus-visible")
            // Text inputs match :focus-visible after a finger tap as well.
            // Refocusing one on a later child close cannot restore the iOS
            // keyboard's native edit session and must be left to a real tap.
            && (!Platform.isMobile || !this._isEditableTarget(active))
                ? active
                : null;
        const parent = {
            panel: this.panel,
            anchor: this.anchor,
            anchorWasCurrent: this.anchorWasCurrent,
            backHandler: this._backHandler,
            frameLock: this._frameLock,
            returnFocusEl
        };
        parent.panel.hidden = true;
        this._resizeObserver?.unobserve?.(parent.panel);
        this._panelStack.push(parent);

        this.panel = null;
        this.anchor = null;
        this.anchorWasCurrent = false;
        this._backHandler = null;
        this._frameLock = null;
        this.suppressClickUntil = 0;

        return this._mountPanel(
            anchor,
            title,
            { bindGlobalListeners: false, frameLock: childFrame,
                // Hiding the parent already released its DOM focus. Carry
                // keyboard intent across that transition instead of inferring
                // it afterwards from BODY or a hidden anchor.
                keyboardOpened: !Platform.isMobile || Boolean(returnFocusEl) }
        );
    }

    _handleOutside(event) {
        const owner = this.owner;
        const panel = this.panel;
        const anchor = this.anchor;
        if (!owner || !panel || !anchor) return;
        if (panel.contains(event.target) || anchor.contains(event.target)) return;

        if (!owner.containerEl.contains(event.target)) {
            // Another host owns this interaction. Never swallow its click or close its children.
            if (!event.target?.closest?.(".local-search-content, .dida-bridge-task-center")) this.close(false);
            return;
        }
        const target = event.target?.nodeType === 1 ? event.target : null;
        if (target?.closest(".local-search-dialog-backdrop, .local-search-dialog-surface")) {
            return;
        }

        if (this.busy) {
            event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation();
            return;
        }
        const interactive = target?.closest(
            'button, [role="button"], a[href], input, textarea, select'
        );
        const isOwnedInteractive = Boolean(
            interactive
            && owner.containerEl?.contains(interactive)
        );

        // Picker 切换只走 click capture：同一次 click 中先同步关闭旧 Surface，
        // 随后目标按钮自己的 click handler 立即打开新 Surface。浏览器在本次事件返回前不会绘制，
        // 因此不存在“pointerdown 先关闭、pointerup/click 再打开”的空白闪帧。
        if (isOwnedInteractive) {
            this.close(false, { returnToParent: false });
            return;
        }

        // 点击真正的非交互空白区域只负责关闭当前 Picker，避免事件穿透到底层结果卡。
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
        this.close(false);
    }

    _handleContextMenu(event) {
        if (!this.panel?.contains(event.target)) return;
        // Native text selection/caret menus belong to the editable control.
        // Suppressing them also suppresses WebKit's subsequent caret click.
        if (this._isEditableTarget(event.target)) return;
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();

        if (Platform.isMobile) {
            this.suppressClickUntil = performance.now() + 800;
            return;
        }
        this.close(false);
    }

    _handleClickGuard(event) {
        if (!this.busy && (!Platform.isMobile || performance.now() > this.suppressClickUntil)) return;
        if (!this.busy && this._isEditableTarget(event.target)) return;

        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
    }

    _isEditableTarget(target) {
        const element = target?.nodeType === 1 ? target : target?.parentElement;
        const editable = element?.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])');
        return Boolean(editable && this.panel?.contains(editable));
    }

    handleEscape(event) {
        const owner = this.owner;
        if (!owner || !this.panel || event.defaultPrevented) return false;
        const target = event.target?.nodeType === 1 ? event.target : this.panel.ownerDocument.activeElement;
        const insidePanel = this.panel.contains(target);
        const doc = this.panel.ownerDocument;
        const unfocusedEscape = event.key === "Escape" && (target === doc.body || target === doc.documentElement);
        if (unfocusedEscape) {
            if (topSearchPopupSurface(doc) !== this.panel) return false;
        } else if (!insidePanel && !owner.containerEl?.contains(target)) return false;
        const targetPicker = target?.closest?.(".local-search-dropdown");
        if (targetPicker && targetPicker !== this.panel) return false;
        const targetCore = target?.closest?.(".local-search-content");
        if (!insidePanel && targetCore && targetCore !== owner.containerEl) return false;
        if (target?.closest(".local-search-dialog-surface, .dida-bridge-task-center")) return false;
        if (this.panel._lsSubmission?.busy && !["Escape", "Tab"].includes(event.key)) {
            event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation();
            return true;
        }
        if (event.isComposing || event.keyCode === 229 || event.key !== "Escape") return false;

        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();

        this._navigateBack(this.panel);
        return true;
    }
}

// ========== Search Sort：排序字段 / 方向唯一状态源 ==========
export class SearchSortController {
    constructor(owner) {
        this.owner = owner;
        this.views = [];
        this.host = null;
        this.pickerBtn = null;
        this.fieldBtn = null;
        this.fieldLabel = null;
        this.directionBtn = null;
        this.directionIcon = null;
        this.cycleCursorField = null;
    }

    destroy() {
        this.views.length = 0;
        this.host = null;
        this.pickerBtn = null;
        this.fieldBtn = null;
        this.fieldLabel = null;
        this.directionBtn = null;
        this.directionIcon = null;
        this.cycleCursorField = null;
        this.owner = null;
    }

    allowedFields(view = null) {
        const core = this.owner;
        return sortFieldsForQuery(
            Boolean(core?.queryState?.active),
            core?.plugin?.settings
        );
    }

    ensureCycleCursor(fields = this.allowedFields()) {
        const core = this.owner;
        if (!core || !fields.length) {
            this.cycleCursorField = null;
            return null;
        }
        if (!fields.includes(this.cycleCursorField)) {
            this.cycleCursorField = fields.includes(core.sortField)
                ? core.sortField
                : fields[0];
        }
        return this.cycleCursorField;
    }

    normalize() {
        const core = this.owner;
        if (!core) return;
        const hasQuery = Boolean(core.queryState?.active);
        core.sortField = normalizeSortField(
            core.sortField,
            hasQuery,
            core.plugin?.settings
        );
        core.sortDirection = normalizeSortDirection(core.sortDirection);
    }

    fieldFor(view = null) {
        return this.owner?.sortField;
    }

    timeField() {
        const core = this.owner;
        const state = core?.createFlow?.searchResultFilterState?.() || core?.filterState;
        return normalizeNavigatorTimeField(state?.dateRange?.field || core?.plugin?.settings?.navigatorTimeField);
    }

    _isCreateVisible() {
        const core = this.owner;
        return Boolean(core?.createFlow?.isCreateView?.()
            && (core.createFlow.isCreateMode?.() || core.navigator?.page !== "filters"));
    }

    _prepareSearchAction() {
        const core = this.owner;
        if (!core || core._destroyed || this._isCreateVisible()) return false;
        // A zero-result draft can be held behind the filter tree. Restore the
        // search owner before mutating it; performSearch restores too late.
        if (core.createFlow?.isDerivedCreateView?.()) {
            if (core.navigator?.prepareSearch) return core.navigator.prepareSearch();
            core.createFlow.prepareSearchEvaluation();
        }
        return true;
    }

    applyField(field, view = null) {
        const core = this.owner;
        if (!this._prepareSearchAction()) return;
        const basis = ({ created: "created", contentModified: "modified", fileModified: "fileModified" })[field];
        if (basis) {
            const changed = core.plugin.settings.navigatorTimeField !== basis;
            core.plugin.settings.navigatorTimeField = basis;
            if (core.filterState.dateRange) core.filterState.dateRange = { ...core.filterState.dateRange, field: basis };
            if (changed) void core.plugin.saveSettings().then(saved => {
                if (saved === false) new Notice("时间依据未能保存，请重试");
            }).catch(error => new Notice(error?.message || "时间依据未能保存"));
            core.navigator?.refreshPreferences();
            if (changed) core.plugin._forEachActiveSearchCore?.(other => {
                if (other === core || other._destroyed) return;
                other.sorting?.sync();
                other.navigator?.refreshPreferences();
            });
        }
        core.sortField = field;
        this.sync();
        core.swipe?.closeAll?.({ immediate: true });
        core.performSearch(core.queryState.raw, true);
    }

    cycleField(view = null) {
        const core = this.owner;
        if (!this._prepareSearchAction()) return;
        this.normalize();
        const fields = this.allowedFields();
        const cursor = this.ensureCycleCursor(fields);
        if (!cursor) return;

        if (core.sortField !== cursor) {
            core.sortField = cursor;
        } else {
            const index = fields.indexOf(cursor);
            this.cycleCursorField = fields[(index + 1) % fields.length];
            core.sortField = this.cycleCursorField;
        }

        this.applyField(core.sortField, view);
    }

    openPicker(view = this.views[0]) {
        const core = this.owner;
        const anchor = view?.pickerBtn || this.pickerBtn;
        if (!anchor || !this._prepareSearchAction()) return;
        if (core.dropdown.closeIfSameAnchor(anchor)) {
            this.sync();
            return;
        }

        const navigator = core.navigator;
        const fromBottomCommand = navigator?.layout === "mobile"
            && navigator.mobileToolbar?.contains(anchor);
        const onCommit = view?.onCommit || (fromBottomCommand
            ? () => { if (!core._destroyed) navigator.showResults(false); }
            : null);
        this.normalize();
        const title = "排序与时间";
        const panel = core.dropdown.open(anchor, title);
        if (!panel) return;
        panel.dataset.lsDropdownSize = "compact-view";
        panel.addClass(
            "local-search-picker-dropdown",
            "local-search-sort-picker"
        );
        configureSharedPickerHeader(panel, {
            headingText: title,
            icon: "arrow-up-down"
        });

        const list = panel.createDiv({
            cls: "local-search-move-tree"
        });
        createSharedPickerTreeRow(list, {
                name: core.sortDirection === "desc" ? "降序 · 点击切换为升序" : "升序 · 点击切换为降序",
                icon: core.sortDirection === "desc" ? "arrow-down" : "arrow-up",
                onClick: () => {
                    if (core.dropdown.close(false) === false) return;
                    this.toggleDirection(view); onCommit?.();
                }
        });
        const fields = selectableSortFieldsForQuery(
            Boolean(core.queryState?.active),
            core.plugin?.settings
        );
        for (const id of fields) {
            const def = SORT_FIELD_DEFS[id];
            if (!def) continue;
            createSharedPickerTreeRow(list, {
                active: id === this.fieldFor(view),
                icon: def.icon || "arrow-up-down",
                name: def.label,
                itemTitle: `排序：${def.label}`,
                onClick: () => {
                    if (core.dropdown.close(false) === false) return;
                    this.applyField(id, view);
                    onCommit?.();
                },
                restoreFocus: false
            });
        }
        const range = normalizeFilterDateRange(core.filterState.dateRange);
        const basis = this.timeField();
        list.createDiv({
            cls: "local-search-list-section-label",
            text: `时间范围 · ${FILTER_TIME_FIELDS[basis].label}`
        });
        createSharedPickerTreeRow(list, {
            active: !range,
            icon: "calendar-off",
            name: "不限时间",
            onClick: () => this.applyTimeRange(0, onCommit),
            restoreFocus: false
        });
        for (const [label, days] of [["今天", 1], ["近3天", 3], ["近7天", 7], ["近30天", 30]]) {
            const preset = recentFilterDateRange(basis, days);
            createSharedPickerTreeRow(list, {
                active: Boolean(range && range.field === preset.field
                    && range.from === preset.from && range.to === preset.to),
                icon: "calendar-days",
                name: label,
                itemTitle: `${FILTER_TIME_FIELDS[basis].label} · ${label}`,
                onClick: () => this.applyTimeRange(days, onCommit),
                restoreFocus: false
            });
        }
        this.sync();
        return panel;
    }

    applyTimeRange(days, onCommit = null) {
        const core = this.owner;
        if (!this._prepareSearchAction()) return;
        const range = days ? recentFilterDateRange(this.timeField(), days) : null;
        if (core.dropdown.close(false) === false) return;
        core.filterState.dateRange = range;
        this.sync();
        core._onFilterChanged();
        onCommit?.();
    }

    toggleDirection(view = null) {
        const core = this.owner;
        if (!this._prepareSearchAction()) return;
        core.sortDirection = normalizeSortDirection(core.sortDirection) === "desc"
            ? "asc"
            : "desc";
        this.sync();
        core.swipe?.closeAll?.({ immediate: true });
        core.performSearch(core.queryState.raw, true);
    }

    build(parentEl, { context = "results" } = {}) {
        if (!parentEl) return null;
        const core = this.owner;
        const host = parentEl.createDiv({
            cls: "local-search-sort-control",
            attr: { role: "group", "aria-label": "结果排序" }
        });
        host.dataset.sortContext = context;
        const view = { host, context };
        this.views.push(view);

        view.fieldBtn = createSearchButton(host, "choice", {
            cls: "local-search-sort-field-btn"
        });
        view.fieldLabel = view.fieldBtn.createSpan({ cls: "local-search-sort-trigger-label" });
        view.fieldBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            core._releaseSearchFocusForControl();
            this.cycleField(view);
        });

        view.pickerBtn = createSearchButton(host, "action", {
            cls: "local-search-sort-picker-btn",
            attr: {
                "aria-label": "选择排序与时间范围",
                "aria-haspopup": "dialog",
                "aria-expanded": "false"
            }
        });
        view.pickerBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            this.openPicker(view);
        });

        view.directionBtn = createSearchButton(host, "choice", {
            cls: "local-search-sort-direction-btn"
        });
        view.directionIcon = view.directionBtn.createSpan({
            cls: "local-search-sort-direction-icon",
            attr: { "aria-hidden": "true" }
        });
        view.directionBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            core._releaseSearchFocusForControl();
            this.toggleDirection(view);
        });

        if (this.views.length === 1) Object.assign(this, view);

        this.sync();
        return host;
    }

    sync() {
        const core = this.owner;
        if (!core) return;
        this.normalize();
        const creating = this._isCreateVisible();
        for (const view of this.views) {
        const currentField = this.fieldFor(view);
        for (const button of [view.fieldBtn, view.pickerBtn, view.directionBtn]) {
            if (button && button.disabled !== creating) button.disabled = creating;
        }
        view.host?.setAttribute("aria-label", creating
            ? "搜索排序（创建期间保留，返回搜索后可调整）" : view.context === "time" ? "时间依据与排序" : "结果排序");
        const def = SORT_FIELD_DEFS[currentField] || SORT_FIELD_DEFS.opened;
        const direction = normalizeSortDirection(core.sortDirection);
        const fieldLabel = def.label;
        if (view.pickerBtn) {
            const open = Boolean(core.dropdown.isOpenFor(view.pickerBtn));
            view.pickerBtn.setAttribute("aria-expanded", String(open));
            view.pickerBtn.setAttribute("aria-label", `排序与时间；当前：${fieldLabel}${core.filterState.dateRange ? `；${filterDateRangeDisplay(core.filterState.dateRange)}` : ""}`);
            view.pickerBtn.classList.toggle("has-time-filter", Boolean(core.filterState.dateRange));
            const iconName = view.pickerBtn === this.pickerBtn
                ? navigatorToolbarIcon(core, "sort", def.icon || "arrow-up-down")
                : def.icon || "arrow-up-down";
            if (view.pickerBtn.dataset.lsIcon !== iconName) {
                view.pickerBtn.replaceChildren();
                setIcon(view.pickerBtn, iconName);
                view.pickerBtn.dataset.lsIcon = iconName;
            }
        }
        if (view.fieldBtn) {
            if (view.fieldLabel?.textContent !== fieldLabel) view.fieldLabel.textContent = fieldLabel;
            const fields = this.allowedFields(view);
            const cursor = view.context === "time" ? currentField : this.ensureCycleCursor(fields);
            let targetField = cursor;
            if (cursor && currentField === cursor) {
                const cursorIndex = fields.indexOf(cursor);
                targetField = fields[(cursorIndex + 1) % fields.length];
            }
            const targetLabel = SORT_FIELD_DEFS[targetField]?.label || "排序";
            const action = cursor && currentField !== cursor
                ? `点击返回快捷排序：${targetLabel}`
                : `点击切换为${targetLabel}`;
            const label = `排序：${fieldLabel}；${action}`;
            view.fieldBtn.setAttribute("aria-label", label);
        }
        if (view.directionBtn) {
            const isDesc = direction === "desc";
            const iconName = isDesc ? "arrow-down" : "arrow-up";
            if (view.directionIcon?.dataset.lsIcon !== iconName) {
                view.directionIcon?.replaceChildren();
                if (view.directionIcon) {
                    setIcon(view.directionIcon, iconName);
                    view.directionIcon.dataset.lsIcon = iconName;
                }
            }
            const human = currentField === "relevance"
                ? (isDesc ? "最佳匹配优先" : "低匹配优先")
                : currentField === "opened"
                    ? (isDesc ? "最近打开优先" : "最久打开优先")
                    : currentField === "created"
                        ? (isDesc ? "最新创建优先" : "最早创建优先")
                        : currentField === "contentModified"
                            ? (isDesc ? "最近正文修改优先" : "最早正文修改优先")
                            : currentField === "fileModified"
                                ? (isDesc ? "最近文件修改优先" : "最早文件修改优先")
                                : (isDesc ? "Z → A" : "A → Z");
            const next = isDesc ? "升序" : "降序";
            const label = `${fieldLabel}：${human}；点击切换为${next}`;
            view.directionBtn.setAttribute("aria-label", label);
            view.directionBtn.setAttribute("aria-pressed", String(!isDesc));
        }
        }
    }
}

export class SwipeActionCoordinator {
    constructor(owner) {
        this.owner = owner;
        this.allExpanded = false;
        this.expansionRevision = 0;
        this.enabled = true;
        this.activeCancel = null;
        this.openWrapper = null;
        this.openClose = null;
        this.gestureWrapper = null;
        this.closingWrapper = null;
        this.ownerDocument = hostDocument(owner.containerEl);
        this.pendingAction = null;
        this._dismissClickArmed = false;
        this._onDocumentPointerDown = event => {
            // 新的 pointer 序列开始时，上一轮若没有产生 click，则旧拦截自然失效。
            // 不使用 timeout / debounce，避免关闭动作引入额外时序状态。
            this._dismissClickArmed = false;
            if (this.pendingAction || !this.openWrapper || !this.openClose) return;
            const target = event?.target;
            if (target?.nodeType && this.openWrapper.contains(target)) return;
            if (!this._ownsTarget(target)) {
                this.openClose();
                return;
            }

            // A child picker/dialog or native field owns this new input
            // session. Closing a result shelf may not cancel its first tap;
            // otherwise the document capture guard swallows WebKit's focus
            // and compatibility click before the input receives either.
            if (target?.closest?.('input, textarea, select, [contenteditable]:not([contenteditable="false"]), .local-search-dropdown, .local-search-dialog-surface, .local-search-overlay-host')) {
                this.openClose();
                return;
            }

            // “更多操作”入口展开后，第一次点击外部区域只负责收起 Shelf。
            // pointerdown 先阻止底层控件获取焦点/按压态，随后同一序列的 click
            // 由当前宿主 capture 吞掉，避免关闭 Shelf 的同时又打开文件、筛选或另一张卡。
            if (!this.owner?.selection?.batchMode && this.openWrapper.classList.contains("is-swipe-trigger-open")) {
                event?.preventDefault?.();
                event?.stopPropagation?.();
                event?.stopImmediatePropagation?.();
                this._dismissClickArmed = true;
                this.openClose();
                return;
            }

            // 触控在此时还不能区分点击与纵向滚动，不提前收起并缩短滚动范围。
            // 真正点击外部时才由同一 click 入口关闭；滚动不产生 click。
        };
        this._onDocumentClick = event => {
            if (this.pendingAction) return;
            if (this._dismissClickArmed) {
                this._dismissClickArmed = false;
                if (!this._ownsTarget(event?.target)) return;
                event?.preventDefault?.();
                event?.stopPropagation?.();
                event?.stopImmediatePropagation?.();
                return;
            }
            const target = event?.target;
            if (this.openWrapper && target?.nodeType && !this.openWrapper.contains(target)) {
                this.openClose?.();
            }
        };
        this.ownerDocument.addEventListener(
            "pointerdown",
            this._onDocumentPointerDown,
            true
        );
        this.ownerDocument.addEventListener(
            "click",
            this._onDocumentClick,
            true
        );
    }

    _ownsTarget(target) {
        if (!target?.nodeType) return false;
        return Boolean(this.owner?.containerEl?.contains(target)
            || this.owner?.dropdown?.panel?.contains(target));
    }

    mountedBindings() {
        return [...(this.owner?.containerEl?.querySelectorAll(".local-search-swipe-shell") || [])]
            .map(wrapper => wrapper._lsResultBinding).filter(Boolean);
    }

    setAllExpanded(expanded) {
        const next = Boolean(expanded);
        if (next === this.allExpanded) return false;
        const viewport = this.owner?.resultRenderer;
        const anchor = viewport?._geometryAnchor?.();
        this.cancel();
        viewport?.cancelSwipeReveal?.();
        this.allExpanded = next;
        this.expansionRevision++;
        for (const binding of this.mountedBindings()) {
            if (next) binding.syncAllExpanded();
            else binding.close(true);
        }
        viewport?.refreshActionShelfLayout?.(anchor);
        return true;
    }

    closeOpen(except = null) {
        if (this.allExpanded) return;
        if (this.openWrapper && this.openWrapper !== except) {
            this.openClose?.();
        }
    }

    cancel() {
        this.activeCancel?.();
        this.activeCancel = null;
        this.openClose?.(true);
        this.openWrapper = null;
        this.openClose = null;
        this.gestureWrapper = null;
        this.closingWrapper = null;
    }

    closeAll({ immediate = false } = {}) {
        this.activeCancel?.();
        this.activeCancel = null;
        this.openClose?.(immediate);
        this.openWrapper = null;
        this.openClose = null;
        this.gestureWrapper = null;
        if (immediate) this.closingWrapper = null;
    }

    resetForRender() {
        this.cancel();
        this.closingWrapper = null;
        this.owner?.resultRenderer?.cancelSwipeReveal();
    }

    setEnabled(enabled) {
        this.enabled = Boolean(enabled);
        if (!this.enabled) this.cancel();
    }

    destroy() {
        this.pendingAction = null;
        this.allExpanded = false;
        for (const binding of this.mountedBindings()) binding.close(true);
        this.resetForRender();
        this.gestureWrapper = null;
        this.ownerDocument?.removeEventListener(
            "pointerdown",
            this._onDocumentPointerDown,
            true
        );
        this.ownerDocument?.removeEventListener(
            "click",
            this._onDocumentClick,
            true
        );
        this._dismissClickArmed = false;
        this.ownerDocument = null;
        this._onDocumentPointerDown = null;
        this._onDocumentClick = null;
        this.owner = null;
    }

    bind(wrapper, row, options = {}) {
        if (!wrapper || !row) return null;
        const actions = (Array.isArray(options.actions) ? options.actions : [])
            .filter(Boolean);
        if (!actions.length) return null;

        wrapper.classList.add("has-swipe-actions");
        const desktopTrigger = options.desktopTrigger
            && typeof options.desktopTrigger.addEventListener === "function"
                ? options.desktopTrigger
                : null;

        const consume = event => {
            event?.preventDefault?.();
            event?.stopPropagation?.();
            event?.stopImmediatePropagation?.();
        };

        // Action Shelf 只在第一次真实需要时创建。
        // 首屏结果卡不再预建 5 个动作按钮 / 图标 / 标签；桌面 More 与触控 Swipe
        // 仍共用同一套 Shelf、同一状态机，只把 DOM 成本从“打开搜索”移到“第一次操作该卡片”。
        let panel = null;
        let activeDirection = null;
        let close = () => {};
        const ensurePanel = () => {
            if (panel?.isConnected) return panel;

            panel = wrapper.ownerDocument.createElement("div");
            panel.className = "local-search-swipe-actions is-edge-right";
            panel.setAttribute("aria-hidden", "true");
            panel.style.setProperty("--ls-swipe-action-count", String(actions.length));
            for (const item of actions) {
                const button = createSearchButton(panel, "choice", {
                    cls: `local-search-swipe-action${item.tone ? ` is-${item.tone}` : ""}${item.className ? ` ${item.className}` : ""}`,
                    attr: {
                        tabindex: "-1",
                        title: item.label || "操作",
                        "aria-label": item.ariaLabel || item.label || "操作"
                    }
                });
                const icon = button.createSpan({
                    cls: "local-search-swipe-action-icon",
                    attr: { "aria-hidden": "true" }
                });
                if (item.icon) setIcon(icon, item.icon);
                button.createSpan({
                    cls: "local-search-swipe-action-label",
                    text: item.shortLabel || item.label || "操作"
                });
                button.addEventListener("click", event => {
                    consume(event);
                    if (this.pendingAction) return;
                    const token = { wrapper };
                    this.pendingAction = token;
                    button.setAttribute("aria-busy", "true");
                    const finish = () => {
                        button.removeAttribute("aria-busy");
                        if (this.pendingAction !== token) return;
                        this.pendingAction = null;
                        if (wrapper.isConnected) close();
                    };
                    try {
                        const pending = options.onAction?.(item.key, button, activeDirection);
                        if (pending?.then) Promise.resolve(pending).catch(error => {
                            new Notice(error?.message || "操作失败");
                        }).finally(finish);
                        else finish();
                    } catch (error) {
                        finish();
                        new Notice(error?.message || "操作失败");
                    }
                });
            }
            wrapper.appendChild(panel);
            return panel;
        };

        let widthCache = null;
        let renderedOffset = 0;
        const widthFor = () => {
            if (Number.isFinite(widthCache)) return widthCache;
            return widthCache = Math.max(0, ensurePanel().getBoundingClientRect().width || 0);
        };
        const hasActions = () => widthFor() > 0;
        const setDirectionClass = direction => {
            wrapper.classList.toggle("is-swipe-left", direction === "left");
            wrapper.classList.toggle("is-swipe-right", direction === "right");
        };
        const setPanelEdge = direction => {
            const shelf = ensurePanel();
            const revealFromRight = direction !== "right";
            shelf.classList.toggle("is-edge-right", revealFromRight);
            shelf.classList.toggle("is-edge-left", !revealFromRight);
        };
        const setPanelProgress = (progress, direction) => {
            wrapper.style.setProperty("--ls-swipe-progress", progress.toFixed(4));
            if (!panel) return;
            const shift = (direction === "right" ? -100 : 100) * (1 - progress);
            panel.style.setProperty("transform", progress === 1 ? "none" : `translate3d(${shift}%, 0, 0)`, "important");
        };
        const setOffset = (value, direction = null) => {
            const motionDirection = direction === "desktop" ? "left" : direction;
            const width = motionDirection ? widthFor() : 0;
            const numeric = Number(value) || 0;
            const next = Math.round(motionDirection === "left" ? Math.max(-width, Math.min(0, numeric))
                : motionDirection === "right" ? Math.min(width, Math.max(0, numeric)) : 0);
            if (next === renderedOffset && direction) return next;
            renderedOffset = next;
            setPanelProgress(width > 0 ? Math.min(1, Math.abs(next) / width) : 0, motionDirection);
            return next;
        };
        const setPanelTabState = active => {
            if (!panel && !active) return;
            const shelf = ensurePanel();
            shelf.setAttribute("aria-hidden", active ? "false" : "true");
            for (const button of shelf.querySelectorAll("button")) {
                button.setAttribute("tabindex", active ? "0" : "-1");
            }
        };
        const syncDesktopTrigger = expanded => {
            if (!desktopTrigger) return;
            desktopTrigger.setAttribute(
                "aria-expanded",
                expanded ? "true" : "false"
            );
        };

        close = (immediate = false) => {
            // 批量展开由工具栏独占控制；动作、外部点击和反向手势不改变全局展示状态。
            if (this.allExpanded) {
                if (wrapper.classList.contains("is-swiping")) open("left");
                return;
            }
            if (!this.allExpanded && wrapper.matches(".is-swiping, .is-swipe-open")) {
                this.closingWrapper = immediate ? null : wrapper;
            }
            if (immediate && this.closingWrapper === wrapper) this.closingWrapper = null;
            if (immediate) this.owner?.resultRenderer?.cancelSwipeReveal(wrapper);
            const currentDirection = wrapper.classList.contains("is-swipe-left")
                ? "left"
                : wrapper.classList.contains("is-swipe-right")
                    ? "right"
                    : activeDirection;
            if (immediate) wrapper.classList.add("is-swipe-no-transition");
            wrapper.classList.remove("is-swipe-open", "is-swiping", "is-swipe-trigger-open");
            syncDesktopTrigger(false);
            setPanelTabState(false);
            renderedOffset = 0;
            setPanelProgress(0, currentDirection);
            activeDirection = null;
            if (this.closingWrapper === wrapper) {
                const style = wrapper.ownerDocument.defaultView.getComputedStyle(wrapper);
                const baseline = parseFloat(style.getPropertyValue("--ls-virtual-trailing-space")) || 0;
                if (parseFloat(style.paddingBottom) <= baseline + 0.1) {
                    this.closingWrapper = null;
                    this.owner?.resultRenderer?.cancelSwipeReveal(wrapper);
                }
            }
            this.owner?._scheduleResultIndexUpdate?.();
            if (this.openWrapper === wrapper) {
                this.openWrapper = null;
                this.openClose = null;
            }
            if (immediate) {
                wrapper.classList.remove("is-swipe-left", "is-swipe-right");
            }
        };
        const open = (direction, reveal = true) => {
            if (this.allExpanded) direction = "left";
            wrapper.classList.remove("is-swipe-no-transition");
            widthCache = null;
            if (!direction) { close(); return; }
            ensurePanel();
            this.closeOpen(wrapper);
            if (!this.allExpanded && reveal && !wrapper.matches(".is-swiping, .is-swipe-open")) {
                this.owner?.resultRenderer?.beginSwipeReveal(wrapper);
            }
            if (this.closingWrapper === wrapper) this.closingWrapper = null;
            wrapper.classList.remove("is-swipe-trigger-open");
            wrapper.classList.add("is-swipe-open");
            wrapper.classList.remove("is-swiping");
            setDirectionClass(direction);
            setPanelEdge(direction);
            activeDirection = direction;
            syncDesktopTrigger(false);
            setPanelTabState(true);
            renderedOffset = null;
            setPanelProgress(1, direction);
            if (!this.allExpanded) {
                this.openWrapper = wrapper;
                this.openClose = close;
            }
        };
        const openFromTrigger = () => {
            if (this.allExpanded) return;
            widthCache = null;
            ensurePanel();
            this.closeOpen(wrapper);
            if (!this.allExpanded && !wrapper.matches(".is-swiping, .is-swipe-open")) {
                this.owner?.resultRenderer?.beginSwipeReveal(wrapper);
            }
            if (this.closingWrapper === wrapper) this.closingWrapper = null;
            wrapper.classList.remove("is-swipe-left", "is-swipe-right", "is-swiping");
            wrapper.classList.add("is-swipe-open", "is-swipe-trigger-open");
            setPanelEdge("left");
            activeDirection = "desktop";
            renderedOffset = null;
            setPanelProgress(1, "left");
            syncDesktopTrigger(true);
            setPanelTabState(true);
            if (!this.allExpanded) {
                this.openWrapper = wrapper;
                this.openClose = close;
            }
        };

        row.addEventListener("click", event => {
            if (event.target?.closest?.(".local-search-card-more")) return;
            if (
                Date.now() < (wrapper._lsSwipeSuppressClickUntil || 0)
                || (wrapper.classList.contains("is-swipe-open") && !this.allExpanded && !this.owner?.selection?.batchMode)
            ) {
                consume(event);
                close();
            }
        }, true);

        if (desktopTrigger) {
            // Dida Master：Hover / Focus 只负责让“…”入口可见；真正展开由 click / Enter / Space 决定。
            // 展开后由 ownerDocument capture 统一处理外部点击关闭，不用 pointerleave / timeout 补救链。
            desktopTrigger.addEventListener("click", event => {
                consume(event);
                if (!this.enabled || options.canStart?.(event) === false) return;
                const isCurrentPanelOpen =
                    wrapper.classList.contains("is-swipe-open")
                    && wrapper.classList.contains("is-swipe-trigger-open");
                isCurrentPanelOpen ? close() : openFromTrigger();
            });
        }

        // Touch 与 Pointer 分流：触摸设备只走 Touch Events；触控笔使用 Pointer Events。
        // 鼠标只通过右上角“更多操作”悬浮 / Focus 进入同一 Action Shelf。
        // 触控左右 Swipe 都进入同一 Shelf；方向只控制 Shelf 从左/右哪一侧滑入。
        let activeTouch = null;

        const beginGesture = ({ startX, startY, inputType, pointerId = null }) => {
            widthCache = null;
            this.activeCancel?.();
            this.gestureWrapper = wrapper;

            const startedDirection = wrapper.classList.contains("is-swipe-open")
                ? (wrapper.classList.contains("is-swipe-left")
                    ? "left"
                    : wrapper.classList.contains("is-swipe-right")
                        ? "right"
                        : wrapper.classList.contains("is-swipe-trigger-open") ? "left" : null)
                : null;
            let startOffset = 0;
            let offset = 0;
            let direction = null;
            let gestureMode = "pending";
            let finished = false;
            let captured = false;
            const win = hostWindow(row);

            const lockSwipe = next => {
                if (gestureMode !== "pending" || !next || !hasActions()) return false;
                startOffset = startedDirection === "left" ? -widthFor() : startedDirection === "right" ? widthFor() : 0;
                offset = startOffset;
                wrapper.classList.remove("is-swipe-no-transition", "is-swipe-trigger-open");
                syncDesktopTrigger(false);
                // 只有横滑成立才切换展开卡；触摸另一张卡向上/下滚动不关闭当前 Shelf。
                this.closeOpen(wrapper);
                direction = next;
                activeDirection = direction;
                gestureMode = "swipe";
                this.owner?.resultRenderer?.beginSwipeReveal(wrapper);
                if (this.closingWrapper === wrapper) this.closingWrapper = null;
                wrapper.classList.add("is-swiping");
                wrapper.classList.remove("is-swipe-open");
                setDirectionClass(direction);
                setPanelEdge(direction);
                setPanelTabState(true);
                if (inputType === "pointer" && pointerId != null) {
                    try {
                        row.setPointerCapture?.(pointerId);
                        captured = true;
                    } catch (_) {}
                }
                return true;
            };

            // 唯一方向判定：PENDING → SWIPE 或 PENDING → SCROLL。
            // PENDING 阶段不移动卡片；横向必须越过 4px 死区且明显强于纵向才锁 Swipe。
            // 一旦进入 SWIPE，固定 Action Shelf 才开始露出，并在本次手势结束前持续 preventDefault。
            const applyMove = (clientX, clientY, cancelableEvent = null) => {
                if (finished) return;
                const dx = clientX - startX;
                const dy = clientY - startY;

                if (gestureMode === "pending") {
                    const absX = Math.abs(dx);
                    const absY = Math.abs(dy);
                    const horizontalIntent =
                        absX >= RESULT_SWIPE_INTENT_SLOP_PX
                        && absX > absY * RESULT_SWIPE_HORIZONTAL_BIAS;

                    if (horizontalIntent) {
                        const nextDirection = startedDirection
                            || (dx < 0 ? "left" : dx > 0 ? "right" : null);
                        if (!lockSwipe(nextDirection)) {
                            releaseToScroll();
                            return;
                        }
                    } else if (absY >= RESULT_SWIPE_INTENT_SLOP_PX) {
                        releaseToScroll();
                        return;
                    } else {
                        return;
                    }
                }

                if (gestureMode !== "swipe" || !direction) return;
                if (cancelableEvent?.cancelable) cancelableEvent.preventDefault();
                offset = setOffset(startOffset + dx, direction);
            };

            const cleanupPointer = () => {
                if (inputType !== "pointer") return;
                win.removeEventListener("pointermove", pointerMove, true);
                win.removeEventListener("pointerup", pointerEnd, true);
                win.removeEventListener("pointercancel", pointerCancel, true);
                if (captured) {
                    try { row.releasePointerCapture?.(pointerId); } catch (_) {}
                }
            };

            const cleanup = () => {
                cleanupPointer();
                if (inputType === "touch" && activeTouch?.gesture === gesture) {
                    activeTouch = null;
                }
                if (this.activeCancel === abort) this.activeCancel = null;
                if (this.gestureWrapper === wrapper) this.gestureWrapper = null;
                this.owner?._scheduleResultIndexUpdate?.();
            };

            // open/close 原子切换展开态；不能先清 is-swiping 再在 open 的测宽中触发布局。
            const settle = cancelled => {
                if (finished) return;
                finished = true;
                cleanup();

                if (cancelled) {
                    if (direction) startedDirection ? open(startedDirection) : close();
                    return;
                }

                if (direction) wrapper._lsSwipeSuppressClickUntil = Date.now() + 360;
                if (!direction) return;

                const width = widthFor();
                const threshold = Math.min(
                    width * RESULT_SWIPE_SETTLE_RATIO,
                    RESULT_SWIPE_SETTLE_MAX_PX
                );
                const revealed = direction === "left" ? -offset : offset;
                if (startedDirection === direction) {
                    const reverseDistance = direction === "left"
                        ? Math.max(0, offset - startOffset)
                        : Math.max(0, startOffset - offset);
                    reverseDistance >= threshold ? close() : open(direction);
                } else {
                    revealed >= threshold ? open(direction) : close();
                }
            };

            const releaseToScroll = () => {
                if (finished) return;
                gestureMode = "scroll";
                this.owner?.resultRenderer?.yieldSwipeReveal();
                finished = true;
                cleanup();
            };

            const abort = () => {
                if (finished) return;
                finished = true;
                cleanup();
                if (direction) startedDirection ? open(startedDirection) : close(true);
            };

            const pointerMove = moveEvent => {
                if (moveEvent.pointerId !== pointerId || finished) return;
                applyMove(moveEvent.clientX, moveEvent.clientY, moveEvent);
            };
            const pointerEnd = endEvent => {
                if (endEvent.pointerId === pointerId) settle(false);
            };
            const pointerCancel = cancelEvent => {
                if (!cancelEvent || cancelEvent.pointerId === pointerId) settle(true);
            };

            const gesture = { applyMove, settle, abort, releaseToScroll };
            this.activeCancel = abort;

            if (inputType === "pointer") {
                win.addEventListener("pointermove", pointerMove, { capture: true, passive: false });
                win.addEventListener("pointerup", pointerEnd, true);
                win.addEventListener("pointercancel", pointerCancel, true);
            }

            return gesture;
        };

        row.addEventListener("pointerdown", event => {
            if (
                event.pointerType === "touch"
                || event.pointerType === "mouse"
                || !this.enabled
                || event.button > 0
                || options.canStart?.(event) === false
            ) return;

            beginGesture({
                startX: event.clientX,
                startY: event.clientY,
                inputType: "pointer",
                pointerId: event.pointerId
            });
        });

        // iOS non-passive touchmove 必须在手势开始前就注册在命中链上。
        row.addEventListener("touchstart", event => {
            if (
                !this.enabled
                || event.touches?.length !== 1
                || options.canStart?.(event) === false
            ) return;

            const touch = event.changedTouches?.[0] || event.touches?.[0];
            if (!touch) return;

            const gesture = beginGesture({
                startX: touch.clientX,
                startY: touch.clientY,
                inputType: "touch"
            });
            activeTouch = {
                identifier: touch.identifier,
                gesture
            };
        }, { passive: true });

        row.addEventListener("touchmove", event => {
            const state = activeTouch;
            if (!state) return;
            if (event.touches?.length !== 1) {
                state.gesture.settle(true);
                return;
            }
            const touch = event.touches[0];
            if (!touch || touch.identifier !== state.identifier) return;
            state.gesture.applyMove(touch.clientX, touch.clientY, event);
        }, { passive: false });

        row.addEventListener("touchend", event => {
            const state = activeTouch;
            if (!state) return;
            const ended = Array.from(event.changedTouches || [])
                .some(item => item.identifier === state.identifier);
            if (ended) state.gesture.settle(false);
        }, { passive: true });

        row.addEventListener("touchcancel", event => {
            const state = activeTouch;
            if (!state) return;
            const cancelled = Array.from(event.changedTouches || [])
                .some(item => item.identifier === state.identifier);
            if (cancelled || !event.changedTouches?.length) state.gesture.settle(true);
        }, { passive: true });

        let expansionRevision = -1;
        const binding = {
            get panel() { return panel; }, close, open, openFromTrigger,
            syncAllExpanded: () => {
                if (!this.allExpanded || !wrapper.isConnected || expansionRevision === this.expansionRevision) return;
                expansionRevision = this.expansionRevision;
                open("left", false);
                wrapper.classList.add("is-swipe-no-transition");
            }
        };
        wrapper._lsResultBinding = binding;
        return binding;
    }
}

// ========== SearchSelectionController：选择状态 / 查看已选 / 批量互斥锁唯一实现 ==========
export class SearchSelectionController {
    constructor(owner) {
        this.owner = owner;
        this.selectedPaths = new Set();
        this.anchorPath = null;
        this.shiftBasePaths = null;
        this.mutationState = "idle";
        this.batchMode = Boolean(owner?.externalSelectionStartInBatchMode);
        for (const key of SEARCH_SELECTION_UI_REF_KEYS) this[key] = null;
    }

    get busy() {
        return this.mutationState !== "idle";
    }

    resetShiftRange() {
        this.shiftBasePaths = null;
    }

    _iconButton(parent, icon, label, className = "", interaction = "chrome", role = "selection") {
        const baseClass = role === "entry"
            ? "local-search-batch-mode-toggle"
            : "local-search-selection-icon-action";
        const button = createSearchButton(parent, interaction, {
            cls: [baseClass, className].filter(Boolean).join(" "),
            attr: { title: label, "aria-label": label }
        });
        setIcon(button, icon);
        button.dataset.lsIcon = icon;
        return button;
    }

    _statItem(parent, label, value = 0) {
        const item = parent.createSpan({ cls: "local-search-stats-item" });
        const indicator = item.createSpan({ cls: "local-search-stats-indicator" });
        indicator.createSpan({ text: label, cls: "local-search-stats-label" });
        indicator.createSpan({
            text: "·",
            cls: "local-search-stats-dot",
            attr: { "aria-hidden": "true" }
        });
        return indicator.createSpan({
            text: String(value),
            cls: "local-search-stats-value"
        });
    }

    buildToolbar() {
        const core = this.owner;
        if (!core?.containerEl) return null;

        this.toolbar = core.containerEl.createDiv({
            cls: "local-search-results-header"
        });

        this.normalPanel = this.toolbar.createDiv({
            cls: "local-search-status-summary"
        });
        const normalStats = this.normalPanel.createDiv({
            cls: "local-search-status-items",
            attr: { role: "status", "aria-live": "polite", "aria-atomic": "true" }
        });
        this.normalCurrentEl = this._statItem(normalStats, "结果", 0);
        normalStats.createSpan({ cls: "local-search-stats-separator", attr: { "aria-hidden": "true" } });
        this.normalTotalEl = this._statItem(normalStats, "全部", 0);
        const normalActions = this.normalPanel.createDiv({ cls: "local-search-status-action-rail", attr: { "aria-label": "结果筛选与批量入口" } });
        core.facets?.buildTypeActions?.(normalActions);
        this.batchEntryBtn = this._iconButton(
            normalActions,
            "list-checks",
            "进入批量操作",
            "",
            "choice",
            "entry"
        );
        this.batchEntryBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            if (this.batchMode) this.exitBatchMode(); else this.enterBatchMode();
        });

        this.batchPanel = this.toolbar.createDiv({
            cls: "local-search-status-summary local-search-batch-summary"
        });
        const selectedStatus = this.batchPanel.createDiv({
            cls: "local-search-batch-selected",
            attr: { role: "status", "aria-live": "polite", "aria-atomic": "true" }
        });
        this.batchSelectedEl = this._statItem(selectedStatus, "已选", 0);
        selectedStatus.createSpan({
            cls: "local-search-stats-separator",
            attr: { "aria-hidden": "true" }
        });
        this.batchResultEl = this._statItem(selectedStatus, "结果", 0);

        // 单层 Batch Action Rail：未固定动作可滚动，固定动作留在右侧；
        // 两组都是第三行直接子项，视觉间距只由 --ls-action-rail-gap 唯一负责。
        const actions = this.batchPanel.createDiv({ cls: "local-search-batch-actions", attr: { "aria-label": "批量操作" } });
        const controls = this.batchPanel.createDiv({ cls: "local-search-status-action-rail", attr: { "aria-label": "批量选择" } });
        if (core.externalSelectionHandler) {
            this.externalSubmitBtn = this._iconButton(
                actions,
                "check",
                core.externalSelectionActionLabel,
                "",
                "action"
            );
            this.externalSubmitBtn.addEventListener("click", () => void this.submitExternalSelection());
        }

        this.tagMetadataBtn = this._iconButton(actions, "tags", "标签");
        this.propertyMetadataBtn = this._iconButton(actions, "list-filter", "属性");
        this.moveFilesBtn = this._iconButton(actions, "folder-input", "移动到");
        this.deleteFilesBtn = this._iconButton(actions, "trash-2", "删除文件", "is-danger-action");
        this.batchSelectToggleBtn = this._iconButton(controls, "list-checks", "全选当前结果", "", "choice");
        this.batchSelectToggleBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            this.toggleSelectAll();
        });
        this.expandActionsBtn = this._iconButton(controls, "panel-bottom-open", "展开全部左滑按钮", "", "choice");
        this.expandActionsBtn.addEventListener("click", event => {
            event.preventDefault(); event.stopPropagation();
            if (!this.batchMode || this.expandActionsBtn.disabled) return;
            core.swipe?.setAllExpanded(!core.swipe.allExpanded);
            this.syncControls();
        });
        this.exitBatchBtn = this._iconButton(controls, "x", "退出批量操作", "is-exit", "choice");

        this.tagMetadataBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            if (this.tagMetadataBtn.disabled) return;
            core.batchMetadata.open(this.tagMetadataBtn, { initialAction: "tag" });
        });
        this.propertyMetadataBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            if (this.propertyMetadataBtn.disabled) return;
            core.batchMetadata.open(this.propertyMetadataBtn, { initialAction: "property" });
        });
        this.moveFilesBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            if (this.moveFilesBtn.disabled) return;
            const files = core._filesFromPaths(this.selectedPaths);
            if (files.length) core.showMovePickerForFiles(files, this.moveFilesBtn);
        });
        this.deleteFilesBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            if (this.deleteFilesBtn.disabled) return;
            const files = core._filesFromPaths(this.selectedPaths);
            void core.deleteFiles(files).catch(error => {
                if (!core._destroyed) {
                    console.error("批量删除流程失败", error);
                    new Notice("批量删除失败");
                }
            });
        });
        this.exitBatchBtn.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            this.exitBatchMode();
        });

        if (core.externalPickHandler) {
            this.toolbar.hidden = true;
            this.toolbar.setAttribute("aria-hidden", "true");
        }

        // Shell 阶段只建立稳定几何，不扫描结果集 / Vault。
        // 第一轮正式结果完成后 renderPage() 会进入 syncControls()，一次性写入真实统计与可用状态。
        core.containerEl.classList.toggle("is-batch-mode", this.batchMode);
        this.normalPanel?.toggleAttribute("hidden", this.batchMode);
        this.batchPanel?.toggleAttribute("hidden", !this.batchMode);
        for (const button of [
            this.batchEntryBtn,
            this.batchSelectToggleBtn,
            this.expandActionsBtn,
            this.externalSubmitBtn,
            this.tagMetadataBtn,
            this.propertyMetadataBtn,
            this.moveFilesBtn,
            this.deleteFilesBtn,
            this.exitBatchBtn
        ]) {
            if (button) button.disabled = true;
        }
        return this.toolbar;
    }

    updateStats() {
        const core = this.owner;
        if (!core) return;
        const selectedCount = this.selectedPaths.size;
        const currentCount = core.resultRenderer?.visibleResultCount?.() ?? core.fullResults.filter(result => result?.file).length;
        const totalCount = core._visibleVaultFileCount();
        if (this.normalCurrentEl) this.normalCurrentEl.textContent = String(currentCount);
        if (this.normalTotalEl) this.normalTotalEl.textContent = String(totalCount);
        if (this.batchSelectedEl) this.batchSelectedEl.textContent = String(selectedCount);
        if (this.batchResultEl) this.batchResultEl.textContent = String(currentCount);
        this.normalPanel?.querySelector(".local-search-status-items")?.setAttribute(
            "aria-label",
            `当前结果 ${currentCount}，全部文件 ${totalCount}`
        );
        this.batchPanel?.querySelector(".local-search-batch-selected")?.setAttribute(
            "aria-label",
            `已选 ${selectedCount} 个文件，当前结果 ${currentCount}`
        );
    }

    getSelectableResults() {
        const core = this.owner;
        return core.resultRenderer.getVisibleResultIndices()
            .map(index => core.fullResults[index])
            .filter(result => result?.file);
    }

    enterBatchMode() {
        const core = this.owner;
        if (!core || this.batchMode) return false;
        core.dropdown.close(false);
        core.swipe?.closeAll?.({ immediate: true });
        this.batchMode = true;
        this.syncUI();
        return true;
    }

    exitBatchMode() {
        const core = this.owner;
        if (!core) return false;
        this.batchMode = false;
        this.selectedPaths.clear();
        this.anchorPath = null;
        this.resetShiftRange();
        this.syncUI();
        return true;
    }

    externalSelectedFiles() {
        const core = this.owner;
        if (!core?.externalSelectionHandler || !this.selectedPaths.size) return [];
        const files = [];
        for (const path of this.selectedPaths) {
            const file = core.app.vault.getAbstractFileByPath(path);
            if (file instanceof TFile) files.push(file);
        }
        return files;
    }

    async submitExternalSelection() {
        const core = this.owner;
        if (!core?.externalSelectionHandler || core._destroyed) return false;
        const files = this.externalSelectedFiles();
        if (!files.length) {
            new Notice("请先选择文件");
            return false;
        }
        if (!this.beginMutation("external-submit")) return false;
        let shouldClose = false;
        try {
            const result = await core.externalSelectionHandler(files);
            shouldClose = result !== false && core.closeOnExternalSelectionSubmit;
            return result !== false;
        } catch (error) {
            console.error("外部多选提交失败", error);
            new Notice(error?.message || `${core.externalSelectionActionLabel}失败`);
            return false;
        } finally {
            this.endMutation("external-submit");
            if (shouldClose && !core._destroyed) core.close();
        }
    }

    beginMutation(kind) {
        const core = this.owner;
        if (!core || core._destroyed) return false;
        if (this.busy) {
            new Notice("已有操作正在执行");
            return false;
        }
        this.mutationState = String(kind || "working");
        return true;
    }

    endMutation(kind) {
        if (kind && this.mutationState !== kind) return;
        this.mutationState = "idle";
        this.owner?._scheduleResultIndexUpdate?.();
    }

    clearState() {
        this.selectedPaths.clear();
        this.anchorPath = null;
        this.resetShiftRange();
    }

    clear() {
        this.selectedPaths.clear();
        this.anchorPath = null;
        this.resetShiftRange();
        this.syncUI();
    }

    selectAll() {
        if (!this.batchMode) return;
        this.selectedPaths = new Set(this.getSelectableResults().map(result => result.path));
        this.anchorPath = null;
        this.resetShiftRange();
        this.syncUI();
    }

    toggleSelectAll() {
        if (!this.batchMode) return;
        const selectable = this.getSelectableResults();
        const allSelected = selectable.length > 0
            && selectable.every(result => this.selectedPaths.has(result.path));
        if (allSelected) {
            this.selectedPaths.clear();
            this.anchorPath = null;
            this.resetShiftRange();
            this.syncUI();
        } else {
            this.selectAll();
        }
    }

    togglePath(path) {
        const core = this.owner;
        if (!core || !path || !this.batchMode) return;
        if (this.selectedPaths.has(path)) this.selectedPaths.delete(path);
        else this.selectedPaths.add(path);
        this.anchorPath = path;
        this.resetShiftRange();
        this.syncControls();
        this.syncRenderedItem(path);
    }

    selectRangeTo(index) {
        const core = this.owner;
        if (!core || !this.batchMode) return;

        const target = core.fullResults[index];
        if (!target?.path) return;

        const paths = this.getSelectableResults().map(result => result.path);
        const end = paths.indexOf(target.path);
        if (end < 0) return;

        const anchor = paths.indexOf(this.anchorPath);

        // 没有有效 Anchor 时，第一次 Shift 点击只建立 Anchor / 单选目标。
        if (anchor < 0) {
            this.selectedPaths.add(target.path);
            this.anchorPath = target.path;
            this.resetShiftRange();
            this.syncUI();
            return;
        }

        // 第一次 Shift 冻结“范围操作开始前”的选择集。
        // Anchor 在这份快照中的状态就是本次 Shift 会话的目标状态：
        // 普通点击后 Anchor 为选中 => Shift 批量选中；
        // 普通点击后 Anchor 为取消 => Shift 批量取消。
        if (!(this.shiftBasePaths instanceof Set)) {
            this.shiftBasePaths = new Set(this.selectedPaths);
        }

        const shouldSelect = this.shiftBasePaths.has(this.anchorPath);
        const nextSelected = new Set(this.shiftBasePaths);
        for (let i = Math.min(anchor, end); i <= Math.max(anchor, end); i++) {
            const path = paths[i];
            if (shouldSelect) nextSelected.add(path);
            else nextSelected.delete(path);
        }

        this.selectedPaths = nextSelected;
        // Anchor 只由普通点击重新建立；Shift 本身不漂移 Anchor。
        this.syncUI();
    }

    retainPaths(validPaths) {
        const valid = validPaths instanceof Set ? validPaths : new Set(validPaths || []);
        this.selectedPaths = new Set([...this.selectedPaths].filter(path => valid.has(path)));
        if (this.anchorPath && !valid.has(this.anchorPath)) this.anchorPath = null;
        this.resetShiftRange();
    }

    removePaths(paths) {
        const removing = paths instanceof Set ? paths : new Set(paths || []);
        for (const path of removing) this.selectedPaths.delete(path);
        if (this.anchorPath && !this.selectedPaths.has(this.anchorPath)) this.anchorPath = null;
        this.resetShiftRange();
    }

    remapPathState(oldPath, newPath, { descendants = false } = {}) {
        const core = this.owner;
        if (!core || !oldPath || !newPath) return;
        const replace = path => core.plugin._replacePathPrefix(path, oldPath, newPath, { descendants });
        this.selectedPaths = new Set([...this.selectedPaths].map(replace));
        if (this.anchorPath) this.anchorPath = replace(this.anchorPath);
        this.resetShiftRange();
    }

    removePathPrefix(path) {
        if (!path) return;
        const prefix = path + "/";
        this.selectedPaths = new Set(
            [...this.selectedPaths].filter(item => item !== path && !item.startsWith(prefix))
        );
        if (this.anchorPath && (this.anchorPath === path || this.anchorPath.startsWith(prefix))) {
            this.anchorPath = null;
        }
        this.resetShiftRange();
    }

    syncControls() {
        const core = this.owner;
        if (!core) return;
        const count = this.selectedPaths.size;
        const selectableCount = core.resultRenderer.visibleResultCount();
        const editableCount = count > 0 ? core.batchMetadata.editablePaths().size : 0;
        // 高频控件同步只比较数量；完整结果数组仅在真正“全选 / 范围选择”时构造。
        const allSelected = selectableCount > 0 && count === selectableCount;

        core.containerEl.classList.toggle("is-batch-mode", this.batchMode);
        const active = this.toolbar?.ownerDocument?.activeElement || null;
        const changingPanel = Boolean(this.normalPanel && this.batchPanel)
            && this.normalPanel.hidden !== this.batchMode;
        const restoreToolbarFocus = changingPanel && Boolean(active && this.toolbar?.contains(active));
        if (changingPanel) {
            this.normalPanel.hidden = this.batchMode;
            this.batchPanel.hidden = !this.batchMode;
        }
        this.updateStats();

        // disabled 只表达业务本身是否可用；Mutation Gate 不参与视觉或普通交互状态。
        if (this.batchEntryBtn) {
            this.batchEntryBtn.disabled = !this.batchMode && selectableCount === 0;
            this.batchEntryBtn.classList.toggle("is-selected", this.batchMode);
            this.batchEntryBtn.setAttribute("aria-pressed", String(this.batchMode));
            this.batchEntryBtn.setAttribute("aria-label", this.batchMode ? "退出批量操作" : "进入批量操作");
        }
        if (this.batchSelectToggleBtn) {
            this.batchSelectToggleBtn.disabled = selectableCount === 0;
            const label = allSelected ? "清空当前选择" : `全选当前结果，共 ${selectableCount} 个文件`;
            this.batchSelectToggleBtn.setAttribute("aria-label", label);
            this.batchSelectToggleBtn.setAttribute("title", label);
            const nextIcon = allSelected ? "eraser" : "list-checks";
            if (this.batchSelectToggleBtn.dataset.lsIcon !== nextIcon) {
                this.batchSelectToggleBtn.empty();
                setIcon(this.batchSelectToggleBtn, nextIcon);
                this.batchSelectToggleBtn.dataset.lsIcon = nextIcon;
            }
        }
        if (this.externalSubmitBtn) this.externalSubmitBtn.disabled = count === 0;
        if (this.tagMetadataBtn) this.tagMetadataBtn.disabled = editableCount === 0;
        if (this.propertyMetadataBtn) this.propertyMetadataBtn.disabled = editableCount === 0;
        if (this.moveFilesBtn) this.moveFilesBtn.disabled = count === 0;
        if (this.deleteFilesBtn) this.deleteFilesBtn.disabled = count === 0;
        if (this.exitBatchBtn) this.exitBatchBtn.disabled = false;
        if (this.expandActionsBtn) {
            const expanded = Boolean(core.swipe?.allExpanded);
            const label = expanded ? "收起全部左滑按钮" : "展开全部左滑按钮";
            this.expandActionsBtn.disabled = selectableCount === 0 || Boolean(core.externalPickHandler);
            this.expandActionsBtn.setAttribute("aria-pressed", String(expanded));
            this.expandActionsBtn.setAttribute("aria-label", label);
            this.expandActionsBtn.setAttribute("title", label);
        }

        if (restoreToolbarFocus) {
            const target = this.batchMode
                ? (this.batchSelectToggleBtn?.disabled ? this.exitBatchBtn : this.batchSelectToggleBtn)
                : this.batchEntryBtn;
            target?.focus?.({ preventScroll: true });
        }

        core.swipe?.setEnabled?.(!core.externalPickHandler);
    }

    syncElement(el, path) {
        if (!el || !path) return;
        const selecting = this.batchMode;
        const selected = selecting && this.selectedPaths.has(path);
        el.classList.toggle("is-selected", selected);
        // Dida Result Row：普通态与批量态都进入原生 Tab 顺序；业务语义只切 role / aria-checked。
        el.tabIndex = 0;
        el.removeAttribute("aria-selected");
        if (selecting) {
            el.setAttribute("role", "checkbox");
            el.setAttribute("aria-checked", String(selected));
        } else {
            el.setAttribute("role", "group");
            el.removeAttribute("aria-checked");
        }
        if (el._lsSelecting !== selecting) {
            el._lsSelecting = selecting;
            for (const control of el.querySelectorAll("button, .local-search-result-metadata-flow")) {
                if (selecting && !control.matches(".local-search-batch-title-open, .local-search-card-more")) control.tabIndex = -1;
                else control.removeAttribute("tabindex");
            }
        }
    }

    syncRenderedItem(path) {
        const core = this.owner;
        const el = core?.resultsContainer?.querySelector(
            `.local-search-item[data-path="${CSS.escape(path)}"]`
        );
        if (el) this.syncElement(el, path);
    }

    syncUI() {
        const core = this.owner;
        if (!core) return;
        this.syncControls();
        core._notifyStateChange();
        for (const el of core.resultsContainer?.querySelectorAll(".local-search-item[data-path]") || []) {
            this.syncElement(el, el.dataset.path || "");
        }
    }

    destroy() {
        this.selectedPaths.clear();
        this.anchorPath = null;
        this.resetShiftRange();
        this.mutationState = "idle";
        this.batchMode = false;
        for (const key of SEARCH_SELECTION_UI_REF_KEYS) this[key] = null;
        this.owner = null;
    }
}

// Normal search hosts share only the query model. Each host still owns its viewport,
// selection, draft and navigation presentation; external pickers remain isolated.
export class SharedSearchStateCoordinator {
    constructor(plugin) {
        this.plugin = plugin;
        this.state = null;
        this.revision = 0;
        this.members = new Map();
    }

    _normalize(source) {
        const settings = this.plugin.settings;
        const query = normalizeModalSearchQuery(source?.query);
        return {
            query,
            filterSnapshot: FilterState.normalizeSnapshot(source?.filterSnapshot),
            sortField: normalizeSortField(source?.sortField, Boolean(query.trim()), settings),
            sortDirection: normalizeSortDirection(source?.sortDirection),
            browseSortField: normalizeSortField(source?.browseSortField, false, settings),
            bodyExpanded: source?.bodyExpanded === true
        };
    }

    _capture(core) {
        const creating = core.createFlow?.isCreateView?.();
        const filter = creating && core.createFlow.searchFilterState instanceof FilterState
            ? core.createFlow.searchFilterState : core.filterState;
        return this._normalize({
            query: core.queryState.raw,
            filterSnapshot: filter.toSnapshot(),
            sortField: core.sortField,
            sortDirection: core.sortDirection,
            browseSortField: core._browseSortField,
            bodyExpanded: core.bodyExpanded
        });
    }

    _same(left, right) { return JSON.stringify(left) === JSON.stringify(right); }

    // Vault maintenance changes identities even while every search host is closed.
    // Transform the committed model and each member's comparison baseline together;
    // pending local queries and independent CreateDrafts remain with their owners.
    transformFilters(transform) {
        if (typeof transform !== "function" || !this.plugin) return false;
        const convert = snapshot => {
            const state = FilterState.fromSnapshot(snapshot);
            transform(state);
            return state.toSnapshot();
        };
        for (const member of this.members.values()) {
            member.observed.filterSnapshot = convert(member.observed.filterSnapshot);
        }
        const saved = this.plugin.settings.sharedSearchState;
        const source = this.state || (saved?.version === 1 ? saved.state : null);
        if (!source) return false;
        const next = this._normalize(source);
        next.filterSnapshot = convert(next.filterSnapshot);
        if (this._same(next.filterSnapshot, this._normalize(source).filterSnapshot)) return false;
        this.state = next;
        this.revision = Math.max(this.revision, Number(saved?.revision) || 0) + 1;
        this._remember();
        for (const core of this.members.keys()) this.schedule(core);
        return true;
    }

    attach(core) {
        if (!core.sharedSearchState || core._destroyed || this.members.has(core)) return;
        const saved = this.plugin.settings.sharedSearchState;
        if (!this.state && saved?.version === 1 && saved.state && typeof saved.state === "object") {
            this.state = this._normalize(saved.state);
            this.revision = Math.max(1, Number(saved.revision) || 1);
        }
        const observed = this._capture(core);
        this.members.set(core, { observed, applied: 0, queued: false, applying: false });
        if (!this.state) {
            this.state = observed;
            this.revision = 1;
            this._remember();
        }
        this.consume(core);
    }

    _remember() {
        this.plugin.settings.sharedSearchState = {
            version: 1, revision: this.revision,
            state: JSON.parse(JSON.stringify(this.state))
        };
        this.plugin._throttleSaveActivity();
    }

    // A stale Picker may commit one dimension while another host changed the query.
    // Merge only fields actually changed by this host, never republish its stale snapshot.
    publish(core, { closing = false } = {}) {
        const member = this.members.get(core);
        if (!member || member.applying || core._restoringSharedSearchState || core._destroyed
            || core._inputComposing || core.createFlow?.isCreateMode?.()) return false;
        const current = this._capture(core);
        if (closing && core.searchInput && !core.createFlow?.isCreateMode?.()) {
            const live = normalizeModalSearchQuery(core.searchInput.value);
            if (live !== current.query) {
                const wasActive = Boolean(current.query.trim());
                const active = Boolean(live.trim());
                if (active !== wasActive) {
                    if (active) { current.browseSortField = current.sortField; current.sortField = "relevance"; }
                    else current.sortField = current.browseSortField;
                }
                current.query = live;
                current.bodyExpanded = false;
            }
        }
        const previous = member.observed;
        const next = JSON.parse(JSON.stringify(this.state));
        for (const key of ["query", "sortField", "sortDirection", "browseSortField", "bodyExpanded"]) {
            if (!this._same(current[key], previous[key])) next[key] = current[key];
        }
        for (const key of ["tags", "folders", "properties", "fileTypes", "dateRange", "tagMatchMode", "propertyMatchMode"]) {
            if (!this._same(current.filterSnapshot[key], previous.filterSnapshot[key])) {
                next.filterSnapshot[key] = current.filterSnapshot[key];
            }
        }
        member.observed = current;
        const normalized = this._normalize(next);
        if (this._same(normalized, this.state)) {
            if (!closing) this.schedule(core);
            return false;
        }
        this.state = normalized;
        this.revision++;
        this._remember();
        for (const target of this.members.keys()) if (!closing || target !== core) this.schedule(target);
        return true;
    }

    _blocked(core) {
        return core._inputComposing || core.searchTimer || core._restoringSharedSearchState
            || core.dropdown?.isOpen || core._confirmSession || core.selection?.busy
            || core.createFlow?.isCreateMode?.() || core.createFlow?._createInFlight
            || core.swipe?.activeCancel || core.swipe?.openWrapper || core.swipe?.closingWrapper
            || core.resultRenderer?.isNativeScrolling?.()
            || (core.searchInput && !core.createFlow?.isCreateMode?.()
                && normalizeModalSearchQuery(core.searchInput.value) !== core.queryState.raw);
    }

    schedule(core) {
        const member = this.members.get(core);
        if (!member || member.queued || member.applying || member.applied === this.revision) return;
        member.queued = true;
        queueMicrotask(() => {
            member.queued = false;
            if (this.members.get(core) === member) this.consume(core);
        });
    }

    consume(core) {
        const member = this.members.get(core);
        if (!member || member.applying || core._destroyed || member.applied === this.revision
            || this._blocked(core)) return false;
        const target = this.state;
        member.applying = true;
        try {
            const before = this._capture(core);
            if (!this._same(before, target)) {
                // Restore the search-side FilterState before updating a zero-hit create preview.
                core.createFlow?.prepareSearchEvaluation?.();
                core.queryState.set(target.query);
                core.filterState = FilterState.fromSnapshot(target.filterSnapshot);
                core.sortField = target.sortField;
                core.sortDirection = target.sortDirection;
                core._browseSortField = target.browseSortField;
                core.bodyExpanded = target.bodyExpanded;
                if (core.searchInput) core.searchInput.value = target.query;
                core.sorting?.sync();
                core.facets?.syncFilterButtons();
                if (core._resultGeneration) {
                    core._refreshCurrentResultsAfterMutation({ preserveSelection: true, refreshPools: true });
                }
                core._syncSearchHeaderControls?.();
                core._notifyStateChange();
            }
            member.applied = this.revision;
            member.observed = this._capture(core);
            return true;
        } finally { member.applying = false; }
    }

    restored(core) {
        const member = this.members.get(core);
        if (!member) return;
        member.observed = this._capture(core);
        member.applied = 0;
        this.consume(core);
    }

    detach(core) {
        this.publish(core, { closing: true });
        this.members.delete(core);
    }

    destroy() { this.members.clear(); this.plugin = null; }
}

// Navigator owns presentation only. Queries, facets, cards and writes stay in SearchCore.
// Navigator presentation metadata. File/tag/property order still belongs to
// the existing picker*Order settings and setPickerSiblingOrder write owner.
export const NAVIGATOR_CUSTOMIZATION_KINDS = new Set(["group", "folder", "tag", "property-key", "property-value", "time", "separator"]);

export function navigatorItemId(kind, key = "", value = "") {
    kind = kind === "property" ? "property-key" : kind === "value" ? "property-value" : String(kind || "");
    if (!NAVIGATOR_CUSTOMIZATION_KINDS.has(kind)) return "";
    key = String(key ?? "");
    if (kind === "folder") key = key === "/" ? "/" : normalizeVaultFolderPath(key);
    if (kind === "tag") key = tagIdentityKey(key);
    const valueId = kind === "property-value" ? propertyValueKey(value) : String(value ?? "");
    return JSON.stringify([kind, key, valueId]);
}

export function parseNavigatorItemId(id) {
    if (typeof id !== "string" || id.length > 4096) return null;
    try {
        const parts = JSON.parse(id);
        return Array.isArray(parts) && parts.length === 3 && NAVIGATOR_CUSTOMIZATION_KINDS.has(parts[0])
            && parts.every(part => typeof part === "string") ? { kind: parts[0], key: parts[1], valueId: parts[2] } : null;
    } catch (_) { return null; }
}

export function normalizeNavigatorCustomization(raw) {
    const object = value => value && typeof value === "object" && !Array.isArray(value) ? value : {};
    const source = object(raw);
    const colors = value => ({ light: normalizeHexColor(value?.light), dark: normalizeHexColor(value?.dark) });
    const result = { version: 1, appearance: {}, groupOrder: [], separators: {} };
    for (const [id, value] of Object.entries(object(source.appearance)).slice(0, 3000)) {
        const parsed = parseNavigatorItemId(id);
        if (!parsed || parsed.kind === "separator") continue;
        const entry = object(value);
        const icon = /^[a-z0-9][a-z0-9-]{0,79}$/i.test(entry.icon || "") ? entry.icon : "";
        // Folder foreground is the existing resultFolderColors authority.
        const color = colors(parsed.kind === "folder" ? null : entry.color);
        const background = colors(entry.background);
        if (icon || color.light || color.dark || background.light || background.dark)
            result.appearance[id] = { icon, color, background };
    }
    result.groupOrder = [...new Set(Array.isArray(source.groupOrder) ? source.groupOrder : [])]
        .filter(id => parseNavigatorItemId(id)?.kind === "group").slice(0, 30);
    for (const [id, value] of Object.entries(object(source.separators)).slice(0, 300)) {
        if (parseNavigatorItemId(id)?.kind !== "separator") continue;
        const entry = object(value);
        const parentId = String(entry.parentId || "");
        if (parentId !== "groups" && !parseNavigatorItemId(parentId)) continue;
        const beforeId = entry.beforeId == null ? null : String(entry.beforeId);
        if (beforeId !== null && (!parseNavigatorItemId(beforeId) || parseNavigatorItemId(beforeId).kind === "separator")) continue;
        result.separators[id] = {
            parentId, beforeId,
            rank: Math.max(0, Math.min(10000, Number(entry.rank) || 0)),
            style: ["solid", "dashed", "dotted"].includes(entry.style) ? entry.style : "solid",
            color: colors(entry.color),
            space: [8, 12, 20].includes(Number(entry.space)) ? Number(entry.space) : 12
        };
    }
    return result;
}

// Invoked by the existing successful folder/tag/property rename/delete owners,
// before their normal settings save. No filesystem operation lives here.
export function remapNavigatorCustomization(settings, { kind, from, to = null, key = "" } = {}) {
    kind = kind === "property" ? "property-key" : kind === "value" ? "property-value" : kind;
    if (!["folder", "tag", "property-key", "property-value"].includes(kind)) return false;
    const state = normalizeNavigatorCustomization(settings.navigatorCustomization);
    const source = kind === "tag" ? tagIdentityKey(from) : kind === "folder" ? normalizeVaultFolderPath(from)
        : kind === "property-value" ? propertyValueKey(from) : String(from ?? "");
    const target = to == null ? null : kind === "tag" ? tagIdentityKey(to) : kind === "folder" ? normalizeVaultFolderPath(to)
        : kind === "property-value" ? propertyValueKey(to) : String(to);
    if (!source || target === source) return false;
    let changed = false;
    const remap = id => {
        const parsed = parseNavigatorItemId(id);
        if (!parsed) return id;
        let nextKey = parsed.key, nextValue = parsed.valueId;
        const tree = kind === "folder" || kind === "tag";
        if (tree && parsed.kind === kind && (parsed.key === source || parsed.key.startsWith(`${source}/`))) {
            changed = true;
            if (target === null) return null;
            nextKey = target + parsed.key.slice(source.length);
        } else if (kind === "property-key" && ["property-key", "property-value"].includes(parsed.kind) && parsed.key === source) {
            changed = true;
            if (target === null) return null;
            nextKey = target;
        } else if (kind === "property-value" && parsed.kind === kind && parsed.key === String(key) && parsed.valueId === source) {
            changed = true;
            if (target === null) return null;
            nextValue = target;
        }
        return JSON.stringify([parsed.kind, nextKey, nextValue]);
    };
    const appearance = {};
    // An explicit destination style wins over a renamed source on a merge.
    for (const [id, style] of Object.entries(state.appearance)) if (remap(id) === id) appearance[id] = style;
    for (const [id, style] of Object.entries(state.appearance)) {
        const nextId = remap(id);
        if (nextId && !Object.prototype.hasOwnProperty.call(appearance, nextId)) appearance[nextId] = style;
    }
    state.appearance = appearance;
    for (const [id, separator] of Object.entries(state.separators)) {
        const parentId = separator.parentId === "groups" ? "groups" : remap(separator.parentId);
        const beforeId = separator.beforeId == null ? null : remap(separator.beforeId);
        if (!parentId || (separator.beforeId != null && !beforeId)) { delete state.separators[id]; changed = true; }
        else { separator.parentId = parentId; separator.beforeId = beforeId; }
    }
    if (kind === "property-key") {
        const oldId = `property:${source}`;
        const newId = target === null ? null : `property:${target}`;
        const toolbars = normalizeNavigatorToolbars(settings.navigatorToolbars);
        let toolbarChanged = false;
        for (const config of Object.values(toolbars)) {
            if (!config.order.includes(oldId)) continue;
            const destinationExists = newId !== null && config.order.includes(newId);
            const move = id => id !== oldId ? id : destinationExists ? null : newId;
            config.order = [...new Set(config.order.map(move).filter(Boolean))];
            // When keys merge, preserve the destination shortcut's existing
            // position/visibility rather than inheriting the removed source.
            config.hidden = [...new Set(config.hidden.map(move).filter(id => id && config.order.includes(id)))];
            if (newId && !destinationExists && config.icons[oldId]) config.icons[newId] = config.icons[oldId];
            delete config.icons[oldId];
            toolbarChanged = true;
        }
        if (toolbarChanged) { settings.navigatorToolbars = toolbars; changed = true; }
    }
    if (changed) settings.navigatorCustomization = state;
    return changed;
}

export class NavigatorCustomization {
    constructor(core, { scroll, onChanged = null } = {}) {
        this.core = core;
        this.scroll = scroll;
        this.onChanged = onChanged;
        this.sortMode = false;
        this.maintenanceMode = null;
        this.rows = new Map();
        this.lists = new Map();
        this._writes = Promise.resolve();
        this._destroyed = false;
        this._contextMenu = event => {
            const row = event.target?.closest?.("[data-nav-id]");
            const descriptor = this.rows.get(row);
            if (!descriptor || !this.scroll.contains(row)) return;
            event.preventDefault(); event.stopPropagation();
            this.openMenu(event, descriptor, row);
        };
        this.scroll.addEventListener("contextmenu", this._contextMenu);
        this._actionAnchorClick = event => {
            const panel = this._actionPanel;
            if (!panel?.isConnected || !this.core?.dropdown?.isActivePanel(panel)) return;
            const row = event.target?.closest?.("[data-nav-id]");
            if (!row || row.dataset.navId !== panel.dataset.navItemId) return;
            // A native contextmenu can be followed by a click on its source
            // row. While the shared action Picker owns that row, the click
            // must not also select a scope or reopen the separator controls.
            event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation();
        };
        this.scroll.addEventListener("click", this._actionAnchorClick, true);
        this._maintenanceClick = event => {
            const item = event.target?.closest?.(".local-search-move-tree-folder");
            const row = item?.closest?.("[data-nav-id]");
            const descriptor = this.rows.get(row);
            if (!descriptor || !this.scroll.contains(row) || (!this.sortMode && !this.maintenanceMode)) return;
            event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation();
            if (this._maintenanceDefinition(descriptor)) this._runMaintenance(descriptor, item);
            else {
                // A tool changes the row's purpose. Unsupported rows may still
                // disclose children, but never unexpectedly open results.
                const toggle = row.querySelector(":scope > .local-search-move-tree-toggle");
                if (toggle && !toggle.disabled) toggle.click();
            }
        };
        this.scroll.addEventListener("click", this._maintenanceClick, true);
        this.coordinator = new PointerSortCoordinator({
            list: scroll, scrollContainer: scroll,
            rowSelector: "[data-nav-id][data-sort-key]",
            hierarchical: false,
            canStart: (row, event) => Boolean(event.target?.closest?.(".local-search-nav-sort-grip")
                && this.rows.get(row)?.sortable !== false),
            onCommit: operation => this.commitSort({ ...operation, visibleBoundary: true }),
            onSettled: () => {
                if (!this._destroyed && !this.core?._destroyed) this.core?.navigator?.sync();
            }
        });
    }

    get state() {
        const raw = this.core?.plugin?.settings?.navigatorCustomization;
        if (this._stateSource !== raw || !this._normalizedState) {
            this._stateSource = raw;
            this._normalizedState = normalizeNavigatorCustomization(raw);
        }
        return this._normalizedState;
    }

    _folderColors() {
        const raw = this.core?.plugin?.settings?.resultFolderColors;
        if (this._folderColorSource !== raw || !this._normalizedFolderColors) {
            this._folderColorSource = raw;
            this._normalizedFolderColors = normalizeResultFolderColors(raw);
        }
        return this._normalizedFolderColors;
    }

    descriptor(value, parentId = value?.parentId || "") {
        const kind = value.kind === "property" ? "property-key" : value.kind === "value" ? "property-value" : value.kind;
        const id = value.id || navigatorItemId(kind, value.key, value.value);
        const orderKey = value.orderKey ?? (kind === "property-value" ? propertyValueKey(value.value) : String(value.key ?? ""));
        return { ...value, id, kind, parentId, orderKey,
            sortable: kind === "time" ? false : value.sortable,
            label: String(value.label ?? value.name ?? value.key ?? "") };
    }

    beginRender() {
        // Unchanged cached sections keep their live descriptors. Prune detached
        // rows rather than discarding registrations for sections not rebuilt.
        for (const row of this.rows.keys()) if (!row.isConnected) this.rows.delete(row);
    }

    order(parentId, values) {
        const source = values.map(value => this.descriptor(value, parentId)).filter(value => value.id);
        let ordered = source;
        const settings = this.core.plugin.settings;
        const kind = source.find(value => value.sortable !== false)?.kind;
        const order = kind === "group" ? this.state.groupOrder
            : kind === "folder" ? settings.pickerFolderOrder
            : kind === "tag" ? settings.pickerTagOrder
            : kind === "property-key" ? settings.pickerPropertyOrder
            : kind === "property-value" ? settings.pickerPropertyValueOrder?.[source.find(value => value.kind === kind)?.key]
            : [];
        // Fixed virtual entries retain their original slots; they do not get
        // dragged into the order of real folders/tags/property values.
        const candidates = source.filter(value => value.sortable !== false);
        const groupRanks = new Map((order || []).map((id, index) => [id, index]));
        const tagRanks = new Map((order || []).map((id, index) => [tagIdentityKey(id), index]));
        const sortable = kind === "group"
            ? [...candidates].sort((a, b) => (groupRanks.get(a.id) ?? Infinity) - (groupRanks.get(b.id) ?? Infinity))
            : kind === "tag" ? [...candidates].sort((a, b) => {
                const rank = (tagRanks.get(tagIdentityKey(a.orderKey)) ?? Infinity) - (tagRanks.get(tagIdentityKey(b.orderKey)) ?? Infinity);
                return Number.isNaN(rank) || rank === 0
                    ? a.orderKey.localeCompare(b.orderKey, "zh-Hans-CN", { numeric: true }) : rank;
            })
            : sortByPreferredOrder(candidates, order || [], value => value.orderKey);
        let index = 0;
        ordered = source.map(value => value.sortable === false ? value : sortable[index++]);
        const separators = Object.entries(this.state.separators)
            .filter(([, config]) => config.parentId === parentId)
            .sort((a, b) => a[1].rank - b[1].rank || a[0].localeCompare(b[0]));
        const result = [];
        const addBefore = id => {
            for (const [separatorId, config] of separators) {
                if (config.beforeId === id) result.push({ id: separatorId, kind: "separator", parentId,
                    label: "分割线", icon: "minus", ...config });
            }
        };
        for (const value of ordered) { addBefore(value.id); result.push(value); }
        if (ordered.length) addBefore(null);
        this.lists.set(parentId, result);
        return result;
    }

    _inheritance(descriptor) {
        const ids = [descriptor.id];
        const { kind, key } = descriptor;
        if (kind === "property-value") ids.push(navigatorItemId("property-key", key));
        if (kind === "folder" || kind === "tag") {
            const parts = String(key).split("/").filter(Boolean);
            while (parts.length > 1) { parts.pop(); ids.push(navigatorItemId(kind, parts.join("/"))); }
        }
        const group = kind === "folder" ? "folder" : kind === "tag" ? "tags"
            : kind.startsWith("property-") ? "properties" : kind === "time" ? "time" : "";
        if (descriptor.groupId && parseNavigatorItemId(descriptor.groupId)?.kind === "group") ids.push(descriptor.groupId);
        else if (group) ids.push(navigatorItemId("group", group));
        return ids;
    }

    resolvedAppearance(descriptor) {
        const state = this.state;
        const own = state.appearance[descriptor.id] || {};
        const result = { icon: own.icon || descriptor.icon || "", color: { light: "", dark: "" }, background: { light: "", dark: "" } };
        for (const id of this._inheritance(descriptor)) {
            const parsed = parseNavigatorItemId(id);
            const style = state.appearance[id] || {};
            const foreground = parsed?.kind === "folder"
                ? this._folderColors()[parsed.key] || {} : style.color || {};
            for (const theme of ["light", "dark"]) {
                if (!result.color[theme] && foreground[theme]) result.color[theme] = foreground[theme];
                if (!result.background[theme] && style.background?.[theme]) result.background[theme] = style.background[theme];
            }
        }
        return result;
    }

    decorate(row, value) {
        const descriptor = this.descriptor(value);
        if (!row || !descriptor.id) return row;
        this.rows.set(row, descriptor);
        row.dataset.navId = descriptor.id;
        row.dataset.sortKey = descriptor.id;
        row.dataset.sortParent = descriptor.parentId;
        row.dataset.sortDepth = String(descriptor.depth ?? row.dataset.treeDepth ?? 0);
        row.dataset.sortName = descriptor.label || "分割线";
        row.classList.toggle("is-no-sort", descriptor.sortable === false);
        if (descriptor.kind !== "separator") {
            const appearance = this.resolvedAppearance(descriptor);
            const icon = row.querySelector(".local-search-move-tree-folder-icon");
            if (icon && appearance.icon && icon.dataset.navIcon !== appearance.icon) {
                setIcon(icon, appearance.icon); icon.dataset.navIcon = appearance.icon;
            }
            for (const field of ["color", "background"]) for (const theme of ["light", "dark"]) {
                const color = appearance[field][theme];
                row.classList.toggle(`has-nav-${field}-${theme}`, Boolean(color));
                if (color) row.style.setProperty(`--ls-nav-item-${field}-${theme}`, color);
                else row.style.removeProperty(`--ls-nav-item-${field}-${theme}`);
            }
        }
        let grip = row.querySelector(":scope > .local-search-nav-sort-grip");
        if (!grip && descriptor.sortable !== false) {
            grip = createSearchButton(row, "chrome", { cls: "local-search-nav-sort-grip",
                attr: { "aria-label": `拖动排序 ${descriptor.label || "分割线"}`, title: "拖动排序；键盘 Alt + 上下箭头移动" } });
            setIcon(grip, "grip-vertical");
            grip.addEventListener("click", event => { event.preventDefault(); event.stopPropagation(); });
            grip.addEventListener("keydown", event => {
                if (!this.sortMode || !event.altKey || !["ArrowUp", "ArrowDown"].includes(event.key)) return;
                const current = this.rows.get(row);
                const siblings = this.lists.get(current?.parentId) || [];
                const sourceIndex = siblings.findIndex(item => item.id === current?.id);
                const destination = sourceIndex + (event.key === "ArrowUp" ? -1 : 1);
                if (sourceIndex < 0 || destination < 0 || destination >= siblings.length) return;
                event.preventDefault(); event.stopPropagation();
                const beforeKey = event.key === "ArrowUp" ? siblings[destination].id : siblings[destination + 1]?.id || null;
                void this.commitSort({ key: current.id, meta: { parentKey: current.parentId }, mode: "reorder", beforeKey, parentKey: current.parentId })
                    .catch(error => new Notice(error?.message || "排序保存失败"));
            });
        }
        if (grip) { grip.hidden = !this.sortMode; grip.tabIndex = this.sortMode ? 0 : -1; }
        this._decorateMaintenance(row, descriptor);
        return row;
    }

    _maintenanceDefinition(descriptor) {
        const mode = this.maintenanceMode;
        if (!mode || descriptor.kind !== mode.kind) return null;
        if (!this.core?.facets?.canSidebarMaintenance?.(descriptor.kind, mode.id, this._maintenanceTarget(descriptor))) return null;
        return this.core?.facets?.sidebarMaintenanceModes?.(mode.kind)?.find(item => item.id === mode.id) || null;
    }

    _maintenanceTarget(descriptor) {
        const key = String(descriptor.key || "");
        const parts = key.split("/").filter(Boolean);
        return { ...descriptor, path: key, name: parts.at(-1) || key, parentPath: parts.slice(0, -1).join("/") };
    }

    _runMaintenance(descriptor, anchor) {
        const mode = this._maintenanceDefinition(descriptor);
        if (!mode || this._destroyed || this.core?._destroyed || this.core?._confirmSession) return;
        const target = this._maintenanceTarget(descriptor);
        if (this.core.facets.sidebarMaintenancePresentation?.(descriptor.kind, mode.id, target)?.disabled) return;
        // Keep dialog/input creation on the trusted row gesture. Defer only
        // asynchronous error reporting, never the native focus handoff.
        try {
            Promise.resolve(this.core.facets.runSidebarMaintenance(descriptor.kind, mode.id, target, anchor, {
                onChange: detail => this.core?.navigator?._refreshAfterMaintenance(descriptor.kind, detail)
            })).catch(error => { if (!this._destroyed) new Notice(error?.message || "操作失败，请重试"); });
        } catch (error) { if (!this._destroyed) new Notice(error?.message || "操作失败，请重试"); }
    }

    _decorateMaintenance(row, descriptor) {
        const definition = this._maintenanceDefinition(descriptor);
        let action = row.querySelector(":scope > .local-search-nav-maintenance-action");
        const signature = definition ? `${descriptor.kind}:${definition.id}` : "";
        if (action && action.dataset.navMaintenance !== signature) { action.remove(); action = null; }
        if (!definition) return;
        const presentation = this.core.facets.sidebarMaintenancePresentation?.(descriptor.kind, definition.id, this._maintenanceTarget(descriptor))
            || { icon: definition.icon, label: `${definition.title} · ${descriptor.label}`, danger: definition.danger };
        if (!action) {
            action = createPickerRowAction(row, { ...presentation,
                onClick: button => this._runMaintenance(this.rows.get(row) || descriptor, button) });
            action.addClass("local-search-nav-maintenance-action");
            action.dataset.navMaintenance = signature;
        }
        setIcon(action, presentation.icon);
        action.setAttribute("aria-label", presentation.label);
        action.title = presentation.label;
        action.disabled = Boolean(presentation.disabled);
        if (typeof presentation.pressed === "boolean") action.setAttribute("aria-pressed", String(presentation.pressed));
        else action.removeAttribute("aria-pressed");
    }

    setMaintenanceMode(kind = "", id = "") {
        const prior = this.maintenanceMode;
        const valid = this.core?.facets?.sidebarMaintenanceModes?.(kind)?.some(item => item.id === id);
        this.maintenanceMode = valid ? { kind, id } : null;
        if (this.maintenanceMode) this.setSortMode(false);
        for (const [row, descriptor] of this.rows) if (row.isConnected) this._decorateMaintenance(row, descriptor);
        this.onChanged?.({ modeOnly: true, projection: prior?.id === "exclude" || id === "exclude" });
    }

    renderSeparator(parent, descriptor, depth = 0) {
        const tree = createSharedPickerTreeRow(parent, { depth,
            rowClasses: "local-search-nav-row local-search-nav-separator", name: "", icon: "minus",
            onClick: () => this.openMenu(null, this.rows.get(tree.row) || descriptor, tree.row) });
        tree.button.replaceChildren();
        tree.button.setAttribute("aria-label", "管理分割线");
        tree.button.createSpan({ cls: "local-search-nav-separator-label", text: "分割线", attr: { "aria-hidden": "true" } });
        tree.button.createSpan({ cls: "local-search-nav-separator-line", attr: { "aria-hidden": "true" } });
        tree.row.setAttribute("role", "group");
        tree.row.setAttribute("aria-label", "自定义分割线");
        tree.row.style.setProperty("--ls-nav-separator-space", `${descriptor.space || 12}px`);
        tree.row.style.setProperty("--ls-nav-separator-style", descriptor.style || "solid");
        for (const theme of ["light", "dark"]) {
            const value = normalizeHexColor(descriptor.color?.[theme]);
            tree.row.classList.toggle(`has-nav-separator-color-${theme}`, Boolean(value));
            if (value) tree.row.style.setProperty(`--ls-nav-separator-color-${theme}`, value);
        }
        this.decorate(tree.row, { ...descriptor, depth });
        const remove = createPickerRowAction(tree.row, { icon: "trash-2", label: "删除分割线", danger: true,
            onClick: button => this._run(async () => {
                if (button.disabled) return;
                button.disabled = true;
                try { await this.removeSeparator(descriptor.id); }
                finally { if (button.isConnected) button.disabled = false; }
            }) });
        remove.addClass("local-search-nav-separator-remove");
        remove.hidden = !this.sortMode;
        remove.tabIndex = this.sortMode ? 0 : -1;
        return tree;
    }

    finishRender() {
        for (const row of this.rows.keys()) if (!row.isConnected) this.rows.delete(row);
        this.coordinator.setEnabled(this.sortMode);
    }

    setSortMode(value) {
        const priorMaintenance = this.maintenanceMode;
        this.sortMode = Boolean(value);
        if (this.sortMode && this.maintenanceMode) {
            this.maintenanceMode = null;
            for (const [row, descriptor] of this.rows) if (row.isConnected) this._decorateMaintenance(row, descriptor);
        }
        this.coordinator.setEnabled(this.sortMode);
        for (const row of this.rows.keys()) {
            const grip = row.querySelector(":scope > .local-search-nav-sort-grip");
            if (grip) { grip.hidden = !this.sortMode; grip.tabIndex = this.sortMode ? 0 : -1; }
            const remove = row.querySelector(":scope > .local-search-nav-separator-remove");
            if (remove) { remove.hidden = !this.sortMode; remove.tabIndex = this.sortMode ? 0 : -1; }
        }
        this.onChanged?.({ modeOnly: true, projection: this.sortMode && priorMaintenance?.id === "exclude" });
    }

    _notify() {
        if (this._destroyed) return;
        this.onChanged?.();
        // Refresh live presentation consumers without advancing result indexes.
        this.core.plugin._forEachActiveSearchCore?.(other => {
            if (other === this.core || !other.navigator) return;
            other.navigator.renderRevision = -1;
            for (const ref of other.navigator.sections?.values?.() || []) ref.signature = "";
            other.navigator._projectionCache?.clear();
            other.navigator.sync();
        });
    }

    _write(change) {
        const run = async () => {
            if (this._destroyed || this.core?._destroyed) return false;
            const plugin = this.core.plugin;
            const keys = ["navigatorCustomization", "resultFolderColors", "pickerFolderOrder", "pickerTagOrder", "pickerPropertyOrder", "pickerPropertyValueOrder"];
            const prior = Object.fromEntries(keys.map(key => [key, plugin.settings[key]]));
            const next = normalizeNavigatorCustomization(this.state);
            let written = null;
            try {
                await change(next, plugin);
                plugin.settings.navigatorCustomization = normalizeNavigatorCustomization(next);
                written = Object.fromEntries(keys.map(key => [key, JSON.stringify(plugin.settings[key])]));
                if (await plugin.saveSettings() === false) throw new Error("设置未能写入，请重试");
            } catch (error) {
                // saveSettings normalizes/replaces object identities. Compare the
                // actual values so a rejected write still restores the UI.
                for (const key of keys) if (!written || JSON.stringify(plugin.settings[key]) === written[key]) plugin.settings[key] = prior[key];
                plugin._refreshPickerOrderConsumers?.("property-key");
                plugin._refreshActiveResultCards?.();
                this._notify(); throw error;
            }
            this._notify(); return true;
        };
        const queue = this.core?.plugin?._navigatorCustomizationWrites || this._writes;
        const promise = queue.then(run, run);
        this._writes = promise.catch(() => {});
        if (this.core?.plugin) this.core.plugin._navigatorCustomizationWrites = this._writes;
        return promise;
    }

    setAppearance(id, patch) {
        const parsed = parseNavigatorItemId(id);
        if (!parsed || parsed.kind === "separator") return Promise.resolve(false);
        return this._write((state, plugin) => {
            const entry = { ...(state.appearance[id] || {}) };
            for (const field of ["icon", "color", "background"]) {
                if (!(field in patch)) continue;
                if (field === "color" && parsed.kind === "folder") {
                    const colors = normalizeResultFolderColors(plugin.settings.resultFolderColors);
                    if (patch.color?.light || patch.color?.dark) colors[parsed.key] = patch.color;
                    else delete colors[parsed.key];
                    plugin.settings.resultFolderColors = normalizeResultFolderColors(colors);
                    plugin._refreshActiveResultCards?.();
                } else entry[field] = patch[field];
            }
            state.appearance[id] = entry;
        });
    }

    addSeparator(value, placement = "after") {
        const descriptor = this.descriptor(value);
        const siblings = this.lists.get(descriptor.parentId) || [];
        const index = siblings.findIndex(item => item.id === descriptor.id);
        const next = placement === "before" ? descriptor.id
            : siblings.slice(index + 1).find(item => item.kind !== "separator")?.id || null;
        return this._write(state => {
            if (Object.keys(state.separators).length >= 300) throw new Error("分割线最多 300 条，请先移除不需要的分割线");
            const token = this.scroll.ownerDocument.defaultView.crypto?.randomUUID?.()
                || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
            const id = navigatorItemId("separator", token);
            const rank = Math.max(0, ...Object.values(state.separators).map(item => item.rank)) + 1;
            state.separators[id] = { parentId: descriptor.parentId, beforeId: next, rank,
                style: "solid", color: { light: "", dark: "" }, space: 12 };
        });
    }

    updateSeparator(id, patch) {
        return this._write(state => {
            if (state.separators[id]) state.separators[id] = { ...state.separators[id], ...patch };
        });
    }

    removeSeparator(id) { return this._write(state => { delete state.separators[id]; }); }

    async commitSort({ key, meta = {}, mode = "reorder", beforeKey = null, parentKey = meta.parentKey || "", visibleBoundary = false }) {
        if (mode !== "reorder" || this._destroyed) return false;
        const current = this.lists.get(parentKey) || [];
        const source = current.find(item => item.id === key);
        if (!source || source.sortable === false || (beforeKey && !current.some(item => item.id === beforeKey))) return false;
        if (visibleBoundary && !beforeKey) {
            const visible = this.coordinator._rows().filter(row => row.dataset.sortParent === parentKey && row.dataset.sortKey !== key);
            const last = visible[visible.length - 1]?.dataset.sortKey;
            const lastIndex = current.findIndex(item => item.id === last);
            // An abbreviated tree is still a projection of all siblings. A
            // drop below its last displayed row means just below that row,
            // never an invisible jump behind hundreds of unmounted siblings.
            if (lastIndex >= 0) beforeKey = current.slice(lastIndex + 1).find(item => item.id !== key)?.id || null;
        }
        const reordered = current.filter(item => item.id !== key);
        const targetIndex = beforeKey ? reordered.findIndex(item => item.id === beforeKey) : reordered.length;
        reordered.splice(Math.max(0, targetIndex), 0, source);
        if (JSON.stringify(current.map(item => item.id)) === JSON.stringify(reordered.map(item => item.id))) return false;
        return this._write(async (state, plugin) => {
            const real = reordered.filter(item => item.kind !== "separator" && item.sortable !== false);
            if (source.kind === "group") {
                const changed = real.map(item => item.id);
                state.groupOrder = [...changed, ...state.groupOrder.filter(id => !changed.includes(id))];
            } else if (["folder", "tag", "property-key", "property-value"].includes(source.kind)) {
                const sourceIndex = real.findIndex(item => item.id === source.id);
                const before = real[sourceIndex + 1]?.orderKey || null;
                await plugin.setPickerSiblingOrder(source.kind, real.map(item => item.orderKey), source.orderKey, before,
                    source.kind === "property-value" ? source.key : "", { persist: false });
            }
            for (let index = 0; index < reordered.length; index++) {
                const descriptor = reordered[index];
                if (descriptor.kind !== "separator" || !state.separators[descriptor.id]) continue;
                state.separators[descriptor.id].beforeId = reordered.slice(index + 1).find(item => item.kind !== "separator")?.id || null;
                state.separators[descriptor.id].rank = index;
            }
        });
    }

    _run(action) {
        Promise.resolve().then(action).catch(error => { if (!this._destroyed) new Notice(error?.message || "导航设置保存失败"); });
    }

    openMenu(event, value, row) {
        const core = this.core;
        if (this._destroyed || !core || core._destroyed || this.coordinator.session || core._confirmSession) return null;
        const descriptor = this.descriptor(value);
        const anchor = row?.querySelector(".local-search-move-tree-folder") || row;
        if (!anchor?.isConnected) return null;
        event?.preventDefault?.();
        event?.stopPropagation?.();
        const panel = core.dropdown.open(anchor, descriptor.kind === "separator" ? "分割线设置" : `${descriptor.label || "导航"} · 设置`);
        if (!panel) return null;
        panel.addClass("local-search-picker-dropdown", "local-search-nav-actions-picker");
        panel.dataset.navItemId = descriptor.id;
        this._actionPanel = panel;
        registerPickerCleanup(panel, () => { if (this._actionPanel === panel) this._actionPanel = null; });
        const header = configureSharedPickerHeader(panel, {
            headingText: descriptor.kind === "separator" ? "分割线设置" : descriptor.label || "导航设置",
            icon: descriptor.kind === "separator" ? "separator-horizontal" : this.resolvedAppearance(descriptor).icon || "sliders-horizontal"
        });
        createPickerHeaderIconAction(header.actions, { icon: "x", label: "关闭导航设置",
            onClick: () => core.dropdown.close(false) });
        const list = panel.createDiv({ cls: "local-search-move-tree" });
        const add = (id, title, icon, action, { active = false, danger = false } = {}) => {
            const item = createSharedPickerTreeRow(list, { name: title, icon, active,
                rowClasses: danger ? "is-danger-action" : "", onClick: () => {
                    if (!core.dropdown.isActivePanel(panel)) return;
                    // All actions leave through the shared dismissal owner.
                    // Close before a write replaces its original navigation row
                    // or a subsequent shared Picker/Dialog takes ownership.
                    if (core.dropdown.close(false, { returnToParent: false }) === false) return;
                    this._run(action);
                } });
            item.button.dataset.navAction = id;
            return item;
        };
        if (descriptor.kind === "separator") {
            const current = this.state.separators[descriptor.id];
            if (!current) { core.dropdown.close(false); return null; }
            for (const [style, title] of [["solid", "实线"], ["dashed", "虚线"], ["dotted", "点线"]])
                add(`separator-style-${style}`, title, "minus", () => this.updateSeparator(descriptor.id, { style }), { active: current.style === style });
            for (const [space, title] of [[8, "紧凑间距"], [12, "标准间距"], [20, "宽松间距"]])
                add(`separator-space-${space}`, title, "space", () => this.updateSeparator(descriptor.id, { space }), { active: current.space === space });
            add("separator-color", "更改分割线颜色", "palette", () => this.openColorEditor(descriptor, "separator"));
            add("separator-remove", "删除分割线", "trash-2", () => this.removeSeparator(descriptor.id), { danger: true });
        } else {
            add("icon", "更改图标", "image", () => {
                const current = this.resolvedAppearance(descriptor);
                openFilterToolbarIconPicker(core, { anchor, propertyKey: descriptor.label || "导航",
                    currentIcon: current.icon, defaultIcon: descriptor.icon || "list", preserveAnchor: true,
                    heading: `图标 · ${descriptor.label || "导航"}`,
                    onSelect: icon => this.setAppearance(descriptor.id, { icon: icon === descriptor.icon ? "" : icon }) });
            });
            add("color", "更改颜色", "palette", () => this.openColorEditor(descriptor, "color"));
            add("background", "更改背景", "paint-bucket", () => this.openColorEditor(descriptor, "background"));
            add("appearance-reset", "恢复默认外观", "rotate-ccw", () => this.setAppearance(descriptor.id, { icon: "", color: {}, background: {} }));
            add("separator-before", "在上方添加分割线", "separator-horizontal", () => this.addSeparator(descriptor, "before"));
            add("separator-after", "在下方添加分割线", "separator-horizontal", () => this.addSeparator(descriptor, "after"));
        }
        add("sort-navigation", this.sortMode ? "完成导航排序" : "调整导航顺序", this.sortMode ? "check" : "list-start",
            () => this.setSortMode(!this.sortMode));
        registerPickerCleanup(panel, observePickerCountRail(panel, list, "--ls-picker-scrollbar-reserve"));
        return panel;
    }

    openColorEditor(descriptor, field) {
        const core = this.core;
        if (!core || core._destroyed) return;
        const title = `${field === "background" ? "背景" : field === "separator" ? "分割线颜色" : "颜色"} · ${descriptor.label || "导航"}`;
        const session = createDialogSession(core, { backdropClass: "local-search-picker-dialog-backdrop", kind: "navigator-appearance" });
        if (!session) return;
        const panel = session.setDialog(session.host.createDiv({
            cls: "local-search-confirm-dialog local-search-picker-dialog local-search-picker-dropdown local-search-folder-color-editor-picker local-search-dialog-surface",
            attr: { role: "dialog", "aria-modal": "true", "aria-label": title }
        }));
        panel.createDiv({ cls: "local-search-dropdown-title" });
        panel.addEventListener("pointerdown", event => event.stopPropagation());
        panel.addEventListener("click", event => event.stopPropagation());
        const header = configureSharedPickerHeader(panel, { headingText: title, icon: field === "background" ? "paint-bucket" : "palette" });
        const own = () => field === "separator" ? this.state.separators[descriptor.id]?.color || {}
            : field === "color" && descriptor.kind === "folder" ? resultFolderColorConfig(core.plugin.settings, descriptor.key) || {}
            : this.state.appearance[descriptor.id]?.[field] || {};
        const update = colors => field === "separator" ? this.updateSeparator(descriptor.id, { color: colors })
            : this.setAppearance(descriptor.id, { [field]: colors });
        const reset = createPickerHeaderIconAction(header?.actions, { icon: "rotate-ccw", label: "恢复默认",
            onClick: () => this._run(async () => { await update({}); if (!session.settled) render(); }) });
        const close = createPickerHeaderIconAction(header?.actions, { icon: "x", label: "关闭调色", onClick: () => session.finish(false) });
        const body = panel.createDiv({ cls: "local-search-folder-color-editor" });
        const render = () => {
            body.replaceChildren();
            const current = own();
            if (reset) reset.disabled = !current.light && !current.dark;
            for (const [theme, label] of [["light", "浅色模式"], ["dark", "深色模式"]]) {
                const inherited = field === "separator" ? "" : this.resolvedAppearance(descriptor)[field]?.[theme];
                const fallback = field === "background" ? theme === "light" ? "#E7EFED" : "#30413D"
                    : theme === "light" ? "#42796E" : "#9BBFB4";
                const shown = current[theme] || inherited || fallback;
                const row = body.createDiv({ cls: "local-search-folder-color-editor-row" });
                const copy = row.createDiv({ cls: "local-search-folder-color-editor-copy" });
                copy.createDiv({ cls: "local-search-folder-color-editor-label", text: label });
                const value = copy.createDiv({ cls: "local-search-folder-color-editor-value", text: current[theme] || "跟随默认" });
                const control = row.createEl("label", { cls: "local-search-folder-color-editor-control" });
                control.style.setProperty("--ls-folder-color-swatch", shown);
                control.createSpan({ cls: "local-search-folder-color-editor-swatch", attr: { "aria-hidden": "true" } });
                const input = createSearchInput(control, { type: "color", cls: "local-search-folder-color-editor-input",
                    attr: { "aria-label": `${title} · ${label}`, value: shown } });
                input.value = shown;
                const preview = () => {
                    const color = normalizeHexColor(input.value);
                    if (color) { value.textContent = color; control.style.setProperty("--ls-folder-color-swatch", color); }
                    return color;
                };
                input.addEventListener("input", preview);
                // Preserve the exact native iOS color input while it owns focus.
                input.addEventListener("change", () => {
                    const color = preview();
                    if (!color) return;
                    this._run(async () => { await update({ ...own(), [theme]: color }); if (!session.settled && reset) reset.disabled = false; });
                });
            }
        };
        render(); close?.focus({ preventScroll: true });
    }

    destroy() {
        this._destroyed = true;
        this.coordinator.destroy();
        this.scroll.removeEventListener("contextmenu", this._contextMenu);
        this.scroll.removeEventListener("click", this._actionAnchorClick, true);
        this.scroll.removeEventListener("click", this._maintenanceClick, true);
        this._actionPanel = null;
        this.rows.clear(); this.lists.clear();
        this.core = null;
    }
}

export class SearchNavigatorController {
    constructor(core, workspace, facets, main) {
        this.core = core;
        this.root = core.containerEl;
        this.workspace = workspace;
        this.facets = facets;
        this.main = main;
        this.page = "filters";
        this.layout = "stack";
        this.expanded = new Set();
        this.collapsed = new Set(Platform.isMobile ? ["folder"] : ["properties", "owner"]);
        this.sections = new Map();
        this.cleanups = [];
        this.renderRevision = -1;
        this.searchVisible = false;
        this._projectionCache = new Map();
        this.root.addClass("local-search-navigator");
        this.root.setAttribute("data-ignore-swipe", "true");
        this.header = this.root.querySelector(".local-search-header");
        facets.prepend(this.header);
        const heading = this.header.querySelector(".local-search-heading");
        this.headingTitle = heading.querySelector(".local-search-heading-title");
        this.headingTitle.textContent = "GLS Navigator";
        this.backButton = createSearchWindowAction(heading, "arrow-left", "返回筛选");
        this.backButton.addClass("local-search-nav-back");
        heading.prepend(this.backButton);
        this.backButton.addEventListener("click", () => this.back());
        core.searchInput.placeholder = "搜索文件、内容、标签、属性…";
        core.searchInput.setAttribute("aria-label", "搜索文件、内容、标签、属性");
        this.scroll = facets.createDiv({ cls: "local-search-nav-scroll", attr: { "aria-label": "筛选导航" } });
        this.customization = new NavigatorCustomization(core, { scroll: this.scroll, onChanged: event => {
            if (event?.modeOnly && !event.projection) this._syncMobileTools();
            else this.refreshPreferences();
        } });
        this.footer = facets.createDiv({ cls: "local-search-nav-footer" });
        this.resultsButton = createSearchWindowAction(this.footer, "eye", "查看结果");
        this.resultsButton.addClass("local-search-nav-show-results");
        this.resultsButton.addEventListener("click", () => { if (this.prepareSearch()) this.showResults(); });
        this.resultHeading = main.createDiv({ cls: "local-search-nav-result-heading" });
        main.prepend(this.resultHeading);
        this.resultTitle = this.resultHeading.createDiv({ cls: "local-search-nav-result-title", text: "全部文件" });
        this.resultHeading.append(this.root.querySelector(".local-search-filter-sort-slot"));
        this._buildMobileToolbar();
        this._listen(core.searchInput, "keydown", event => {
            if (event.key !== "Enter" || event.isComposing || event.keyCode === 229 || core.createFlow?.isCreateMode()) return;
            if (this.page !== "filters") return;
            event.preventDefault();
            event.stopImmediatePropagation();
            core.performSearch(core.searchInput.value);
            this.showResults(false);
        }, true);
        this._listen(this.root, "keydown", event => {
            if (event.key !== "Escape" || core.dropdown.isOpen || core._confirmSession || event.isComposing) return;
            if (this.page === "filters" && (this.customization.sortMode || this.customization.maintenanceMode)) {
                event.preventDefault(); event.stopImmediatePropagation(); this.clearSidebarMode(); return;
            }
            if (this.layout === "mobile" && this.page === "results") {
                event.preventDefault(); event.stopImmediatePropagation(); this.back();
            }
        }, true);
        this._listen(this.scroll, "scroll", () => core.onStateChange?.(), { passive: true });
        const win = this.root.ownerDocument.defaultView;
        this.observer = new win.ResizeObserver(() => this.resize());
        this.observer.observe(this.root);
        this.resize();
        this.sync();
    }

    _listen(node, type, fn, options) {
        node.addEventListener(type, fn, options);
        this.cleanups.push(() => node.removeEventListener(type, fn, options));
    }

    _buildMobileToolbar() {
        const core = this.core;
        this.mobileToolbar = this.root.createDiv({ cls: "local-search-nav-mobile-toolbar", attr: { role: "toolbar", "aria-label": "导航操作" } });
        this.tools = new Map();
        this.movedTools = [];
        const slot = (id, button) => {
            const host = this.mobileToolbar.createDiv({ cls: "local-search-nav-tool-slot" });
            host.dataset.navAction = id;
            button.addClass("local-search-nav-tool");
            this.tools.set(id, { host, button });
            return host;
        };
        const action = (id, icon, label, run) => {
            const button = createSearchWindowAction(this.mobileToolbar, icon, label);
            slot(id, button).append(button);
            button.addEventListener("click", event => {
                if (id !== "search") core._releaseSearchFocusForControl();
                run(button, event);
            });
        };
        this._addToolbarAction = action;
        const move = (id, button) => {
            const marker = this.root.ownerDocument.createComment(`navigator-${id}`);
            button.before(marker);
            this.movedTools.push({ button, marker, host: slot(id, button) });
        };
        action("search", "search", "搜索文件", () => {
            core._releaseSearchFocusForControl();
            if (this.page === "filters") {
                if (!this.prepareSearch()) return;
                this.searchVisible = true;
                this.showResults(false);
            } else {
                this.searchVisible = !this.searchVisible;
                this.syncPage();
                core.onStateChange?.();
            }
        });
        action("collapse", "chevrons-down-up", "折叠全部导航", () => {
            if (!this.prepareSearch()) return;
            this.setPage("filters");
            const ids = this._definitions().map(([id]) => id);
            const allCollapsed = ids.every(id => this.collapsed.has(id));
            for (const id of ids) allCollapsed ? this.collapsed.delete(id) : this.collapsed.add(id);
            if (!allCollapsed) this.expanded.clear();
            this.renderRevision = -1; this.sync(); core._notifyStateChange();
        });
        move("results", this.resultsButton);
        action("filters", "list-filter", "返回筛选导航", () => {
            if (!this.prepareSearch()) return;
            if (core.selection.batchMode) core.selection.exitBatchMode();
            this.setPage("filters");
        });
        action("sort-navigation", "list-tree", "侧栏工具", button => {
            if (!this.prepareSearch()) return;
            this.setPage("filters"); this.openSidebarTools(button);
        });
        move("sort", core.sorting.pickerBtn);
        action("view", "sliders-horizontal", "视图设置", button => {
            if (!core.dropdown.closeIfSameAnchor(button)) core.resultControls.openViewDropdown(button);
        });
        move("history", core.resultControls.historyBtn);
        move("batch", core.selection.batchEntryBtn);
        this._listen(core.selection.batchEntryBtn, "click", event => {
            if (this.layout !== "mobile") return;
            if (core.createFlow?.isCreateView?.() && !this.prepareSearch()) {
                event.preventDefault(); event.stopImmediatePropagation();
                return;
            }
            if (this.page === "filters") this.showResults(false);
        }, true);
        move("create", core.resultControls.createNoteBtn);
        this._listen(core.searchInput, "input", () => this._syncMobileTools());
        this._listen(core.searchInput, "focus", () => {
            this.searchVisible = true; this._syncMobileTools();
        });
    }

    _placeMobileTools(mobile) {
        for (const { button, marker, host } of this.movedTools) {
            if (mobile && button.parentElement !== host) host.append(button);
            else if (!mobile && button.parentNode !== marker.parentNode) marker.after(button);
        }
        this.mobileToolbar.hidden = !mobile;
    }

    _syncMobileTools() {
        if (!this.tools) return;
        const core = this.core;
        const create = this.page === "results" && Boolean(core.createFlow?.isCreateView?.());
        const filters = this.page === "filters";
        const state = filters ? core.createFlow?.searchResultFilterState?.() || core.filterState : core.filterState;
        const context = create ? "create" : filters ? "filters" : "results";
        const preferences = normalizeNavigatorToolbars(core.plugin.settings.navigatorToolbars)[context];
        const catalog = navigatorToolbarCatalog(core.plugin);
        const configured = new Set(Object.values(normalizeNavigatorToolbars(core.plugin.settings.navigatorToolbars)).flatMap(value => value.order));
        for (const [id, tool] of this.tools) if ((id.startsWith("pool:") || id.startsWith("property:") || id === "filter-pools") && !configured.has(id)) {
            if (!this._releaseToolbarAnchor(tool)) continue;
            tool.host.remove(); this.tools.delete(id);
        }
        for (const id of preferences.order) {
            const definition = catalog.get(id);
            if (!definition || this.tools.has(id)) continue;
            this._addToolbarAction(id, definition.icon, definition.label, button => this._runAdditionalToolbarAction(id, button));
        }
        const hidden = new Set(preferences.hidden);
        const visible = new Set(preferences.order.filter(id => !hidden.has(id) && catalog.has(id) && this.tools.has(id)));
        if (!core.allowCreate) visible.delete("create");
        const order = [...preferences.order, ...this.tools.keys()].filter((id, index, all) => all.indexOf(id) === index);
        const orderKey = JSON.stringify(order);
        if (orderKey !== this._toolbarOrderKey) {
            this._toolbarOrderKey = orderKey;
            let cursor = this.mobileToolbar.firstElementChild;
            for (const id of order) {
                const host = this.tools.get(id)?.host;
                if (!host) continue;
                if (host !== cursor) this.mobileToolbar.insertBefore(host, cursor);
                cursor = host.nextElementSibling;
            }
        }
        for (const [id, tool] of this.tools) {
            if (!visible.has(id) && !this._releaseToolbarAnchor(tool)) visible.add(id);
            tool.host.hidden = !visible.has(id);
        }
        for (const id of visible) {
            const definition = catalog.get(id), tool = this.tools.get(id);
            if (definition?.kind === "property" || definition?.kind === "pool") {
                const icon = navigatorToolbarIcon(core, id, definition.icon, preferences);
                if (tool.button.dataset.lsIcon !== icon) {
                    setIcon(tool.button, icon); tool.button.dataset.lsIcon = icon;
                }
                tool.button.setAttribute("aria-label", definition.label);
                const applied = definition.kind === "property" ? Boolean(state.properties.get(definition.propertyKey)?.size)
                    : definition.poolKind === "folder" ? state.folders.size > 0
                    : definition.poolKind === "tag" ? state.tags.size > 0
                    : definition.poolKind === "property" ? state.properties.size > 0
                    : state.fileTypes.size > 0;
                tool.button.setAttribute("aria-pressed", String(applied));
                tool.button.setAttribute("aria-expanded", String(core.dropdown.isOpenFor(tool.button)));
            }
        }
        this.mobileToolbar.hidden = this.layout !== "mobile" || visible.size === 0;
        const timeTool = this.tools.get("time")?.button;
        if (timeTool) timeTool.disabled = !navigatorToolbarActionAvailable("time", context);
        const sidebarTool = this.tools.get("sort-navigation")?.button;
        const maintenance = this.customization?.maintenanceMode;
        const maintenanceDefinition = maintenance && core.facets.sidebarMaintenanceModes?.(maintenance.kind)?.find(item => item.id === maintenance.id);
        const modeLabel = this.customization?.sortMode ? "拖拽排序" : maintenanceDefinition?.title || "";
        sidebarTool?.setAttribute("aria-pressed", String(Boolean(modeLabel)));
        sidebarTool?.setAttribute("aria-label", modeLabel ? `侧栏工具 · ${modeLabel}` : "侧栏工具");
        sidebarTool?.setAttribute("title", modeLabel ? `侧栏工具 · ${modeLabel}` : "侧栏工具");
        const ids = this._definitions().map(([id]) => id);
        const allCollapsed = ids.every(id => this.collapsed.has(id));
        this.tools.get("collapse").button.setAttribute("aria-label", allCollapsed ? "展开全部导航" : "折叠全部导航");
        this.tools.get("search").button.setAttribute("aria-pressed", String(!filters && (this.searchVisible || create)));
        // Search belongs to results/create. A retained query must never re-open
        // the filter page's header or summon the keyboard during navigation.
        this.root.classList.toggle("is-nav-search-visible", !filters && (this.searchVisible || create));
        this.root.classList.toggle("has-nav-query", Boolean(core.searchInput?.value));
        const title = create ? "创建文件" : this._scopeTitle();
        this.headingTitle.textContent = this.layout === "mobile" ? `${title}${create ? "" : ` · ${core.fullResults.length}`}` : "GLS Navigator";
        this.headingTitle.title = title;
        // Only the presentation icon is overridden. Labels, disabled/pressed
        // state and behavior still belong to each original command controller.
        for (const [id, tool] of this.tools) {
            const fallback = id === "sort"
                ? (SORT_FIELD_DEFS[core.sorting.fieldFor(core.sorting)]?.icon || "arrow-up-down")
                : catalog.get(id)?.icon;
            if (!fallback) continue;
            const icon = navigatorToolbarIcon(core, id, fallback, preferences);
            if (tool.button.dataset.lsIcon !== icon) {
                tool.button.replaceChildren(); setIcon(tool.button, icon); tool.button.dataset.lsIcon = icon;
            }
        }
        this.mobileToolbar.setAttribute("aria-label", filters ? "导航操作" : create ? "创建操作" : "结果操作");
    }

    _releaseToolbarAnchor(tool) {
        const dropdown = this.core.dropdown;
        // Desktop uses the original result-control location. A hidden mobile
        // slot does not own that native anchor or its active Picker.
        if (!tool.host.contains(tool.button)) return true;
        if (!dropdown.isOpenFor(tool.button)) return true;
        const settingsPanel = [dropdown.panel, ...(dropdown._panelStack || []).map(frame => frame.panel)]
            .find(panel => panel?.classList?.contains("local-search-view-composer"));
        if (!settingsPanel && dropdown.close(false, { returnToParent: false }) !== false) return true;
        // A saving Picker owns its anchor until it settles. Use that existing
        // lifecycle to apply the pending toolbar removal instead of detaching it.
        const panel = settingsPanel || dropdown.panel;
        if (panel && this._pendingToolbarSyncPanel !== panel) {
            this._pendingToolbarSyncPanel = panel;
            registerPickerCleanup(panel, () => queueMicrotask(() => {
                if (this._pendingToolbarSyncPanel === panel) this._pendingToolbarSyncPanel = null;
                if (this.core && !this.core._destroyed) this._syncMobileTools();
            }));
        }
        return false;
    }

    _runAdditionalToolbarAction(id, anchor) {
        const core = this.core;
        if (!core || core._destroyed || core.dropdown.closeIfSameAnchor(anchor)) return;
        if (this.page === "filters" && !this.prepareSearch()) return;
        const definition = navigatorToolbarCatalog(core.plugin).get(id);
        // Navigation is the intent of a confirmed bottom command, not a side
        // effect of closing or changing a Picker. Cancel and maintenance stay
        // on their origin page; creation keeps its existing metadata workflow.
        const onCommit = () => {
            if (this.core && !core._destroyed && !core.createFlow?.isCreateMode?.()) this.showResults(false);
        };
        if (id === "time") core.sorting.openPicker({ pickerBtn: anchor, context: "time", onCommit });
        else if (id === "filter-pools") core.resultControls.openViewDropdown(anchor, { section: "filterPools" });
        else if (definition?.kind === "property") core.facets.openPropertyPicker(definition.propertyKey, anchor, { mode: "quick-value", onCommit });
        else if (definition?.poolKind === "folder") core.facets.showFolderDropdown({ anchor, onCommit });
        else if (definition?.poolKind === "tag") core.facets.openTagPicker({ anchor, onCommit });
        else if (definition?.poolKind === "property") core.facets.openPropertyPicker("", anchor, { onCommit });
        else if (definition?.poolKind === "fileType") core.resultControls._openFileTypeChoicePicker(anchor, { onCommit });
    }

    _scopeTitle() {
        const core = this.core;
        const state = core.createFlow?.searchResultFilterState?.() || core.filterState;
        const scopes = [];
        if (state.folders.size) scopes.push(`文件夹 / ${[...state.folders].map(x => x === "/" ? "根目录" : x).join("、")}`);
        if (state.tags.size) scopes.push(`标签 / ${[...state.tags].map(x => x === NO_TAGS_FILTER_VALUE ? "无标签" : x).join("、")}`);
        for (const [key, values] of state.properties) scopes.push(`${key} / ${[...values].map(propertyValueDisplay).join("、")}`);
        if (state.dateRange) scopes.push("时间筛选");
        if (state.fileTypes.size) scopes.push([...state.fileTypes].map(value => RESULT_FILE_TYPE_ACTIONS.find(def => def.value === value)?.label || value).join("、"));
        if (!scopes.length) return core.queryState.raw.trim() ? "搜索结果" : "全部文件";
        return scopes.length === 1 ? scopes[0] : `${scopes[0]} +${scopes.length - 1}`;
    }

    openSidebarTools(anchor) {
        const core = this.core;
        if (core.dropdown.closeIfSameAnchor(anchor)) return;
        const panel = core.dropdown.open(anchor, "侧栏工具");
        if (!panel) return;
        panel.addClass("local-search-picker-dropdown", "local-search-nav-tools-picker");
        configureSharedPickerHeader(panel, { headingText: "侧栏工具", icon: "list-tree" });
        const list = panel.createDiv({ cls: "local-search-move-tree" });
        const choose = action => {
            if (core.dropdown.close(false, { returnToParent: false }) !== false) action();
        };
        const add = ({ id, title, icon, active = false, danger = false, onClick }) => {
            const row = createSharedPickerTreeRow(list, { name: title, icon, active,
                rowClasses: danger ? "is-danger-action" : "", onClick: () => choose(onClick) });
            row.button.dataset.sidebarTool = id;
        };
        if (this.customization.sortMode || this.customization.maintenanceMode) add({ id: "finish", title: "退出当前操作", icon: "check",
            onClick: () => this.clearSidebarMode() });
        add({ id: "sort", title: "拖拽排序", icon: "grip-vertical", active: this.customization.sortMode,
            onClick: () => this.setSortMode(!this.customization.sortMode) });
        const scopes = [["folder", "文件夹", "folder"], ["tag", "标签", "tags"], ["property-key", "属性", "list"], ["property-value", "属性值", "equal"]];
        for (const [kind, label, section] of scopes) {
            if (!this._definitions().some(([id]) => id === (kind.startsWith("property") ? "properties" : section))) continue;
            const modes = core.facets.sidebarMaintenanceModes?.(kind) || [];
            if (!modes.length) continue;
            list.createDiv({ cls: "local-search-list-section-label", text: label });
            for (const mode of modes) add({ id: `${kind}:${mode.id}`, title: mode.title, icon: mode.icon, danger: mode.danger,
                active: this.customization.maintenanceMode?.kind === kind && this.customization.maintenanceMode?.id === mode.id,
                onClick: () => {
                    const active = this.customization.maintenanceMode?.kind === kind && this.customization.maintenanceMode?.id === mode.id;
                    this.customization.setMaintenanceMode(active ? "" : kind, active ? "" : mode.id);
                    if (!active) this.collapsed.delete(kind.startsWith("property") ? "properties" : section);
                    this.renderRevision = -1; this.sync(); core._notifyStateChange();
                } });
        }
        registerPickerCleanup(panel, observePickerCountRail(panel, list, "--ls-picker-scrollbar-reserve"));
        return panel;
    }

    clearSidebarMode() {
        this.customization.setMaintenanceMode();
        this.setSortMode(false);
    }

    _definitions() {
        const definitions = [["folder", "文件夹", "folder"], ["tags", "标签", "tags"], ["properties", "属性", "list"]];
        if (this.layout !== "mobile") definitions.push(["project", "所属项目", "layers"], ["owner", "负责人", "user"]);
        const visible = this.core.plugin.settings.navigatorVisibleSections;
        return Array.isArray(visible) ? definitions.filter(([id]) => visible.includes(id)) : definitions;
    }

    capture() {
        return { navigationVersion: 2, page: this.page, searchVisible: this.searchVisible,
            expanded: [...this.expanded], collapsed: [...this.collapsed],
            scrollTop: this.facets.hidden ? this._filterScrollTop || 0 : this.scroll.scrollTop };
    }

    hiddenResultAnchor() {
        return this.main.hidden
            ? normalizeModalViewportAnchor(this.resultAnchor || this.core._initialViewportAnchor || { scrollTop: 0 })
            : null;
    }

    restore(state, resultAnchor = null) {
        if (!state || typeof state !== "object") return;
        this._restoringPage = true;
        this.resultAnchor = normalizeModalViewportAnchor(resultAnchor);
        // The old detail page is now an ordinary file-open action, never a blank pane.
        this.page = state.page === "results" || state.page === "detail" ? "results" : "filters";
        this.searchVisible = state.navigationVersion === 2 ? Boolean(state.searchVisible) : this.page === "results";
        this.expanded = new Set(normalizeUniqueStringList(state.expanded).slice(0, 500));
        if (state.navigationVersion === 2 || !Platform.isMobile) this.collapsed = new Set(normalizeUniqueStringList(state.collapsed));
        this._restoreScrollTop = Math.max(0, Number(state.scrollTop) || 0);
        this._filterScrollTop = this._restoreScrollTop;
        this.resize();
        this.renderRevision = -1;
        this.sync();
        this._restoringPage = false;
    }

    resize() {
        if (!this.core || this.core._destroyed) return;
        const width = this.root.getBoundingClientRect().width;
        if (!width) return;
        this.width = width;
        const next = Platform.isMobile ? "mobile" : width >= 650 ? "split" : "stack";
        const changed = next !== this.layout;
        this.layout = next;
        this.root.dataset.navLayout = next;
        // One live input is moved, never cloned or replaced. An active IME stays attached.
        const parent = next === "mobile" ? this.root : this.facets;
        if (this.header.parentElement !== parent) parent.prepend(this.header);
        this._placeMobileTools(next === "mobile");
        this.syncPage();
        if (changed) { this.renderRevision = -1; this.sync(); }
        this.core.dropdown?._queueReposition();
    }

    refreshPreferences() {
        if (!this.core || this.core._destroyed) return;
        this._projectionCache.clear();
        this._cacheRevision = -1;
        this.renderRevision = -1;
        for (const ref of this.sections.values()) ref.signature = null;
        this._syncMobileTools();
        this.sync();
    }

    _refreshAfterMaintenance(kind, detail = {}) {
        const prefix = kind === "folder" ? "folder:" : kind === "tag" ? "tag:" : kind === "property-key" ? "properties:" : "";
        const from = detail.oldPath ?? detail.oldKey ?? (detail.deleted ? detail.path ?? detail.key : null);
        const to = detail.newPath ?? detail.newKey;
        if (prefix && from) {
            const source = `${prefix}${from}`;
            this.expanded = new Set([...this.expanded].flatMap(key => {
                const related = key === source || (kind !== "property-key" && key.startsWith(source + "/"));
                if (!related) return [key];
                return to ? [`${prefix}${to}${key.slice(source.length)}`] : detail.deleted ? [] : [key];
            }));
        }
        this.refreshPreferences();
    }

    setSortMode(enabled) {
        this.core._releaseSearchFocusForControl();
        this.customization?.setSortMode(Boolean(enabled));
        this._syncMobileTools();
        this.core.onStateChange?.();
    }

    syncPage() {
        const hideResults = this.layout === "mobile" && this.page !== "results";
        const wasHidden = this.main.hidden;
        const hideFacets = this.layout === "mobile" && this.page !== "filters";
        const facetsWereHidden = this.facets.hidden;
        if (!this._restoringPage) {
            if (!facetsWereHidden && hideFacets) this._filterScrollTop = this.scroll.scrollTop;
        }
        // display:none reports scrollTop=0. Save the semantic result anchor while
        // the result pane is still measurable, independently of the shared query.
        if (!wasHidden && hideResults && !this._restoringPage && this.core._resultGeneration) {
            this.resultAnchor = this.core.resultRenderer.captureViewportAnchor();
        }
        this.root.dataset.navPage = this.page;
        this.backButton.hidden = this.layout !== "mobile" || this.page === "filters";
        this.backButton.setAttribute("aria-label", "返回导航");
        this.footer.hidden = true;
        // hidden removes inactive pages from accessibility and keyboard navigation as well as layout.
        this.facets.hidden = hideFacets;
        this.main.hidden = hideResults;
        const conditions = this.core.propertyFilterRow;
        const conditionParent = this.layout === "mobile" ? this.root : this.main;
        if (conditions && conditions.parentElement !== conditionParent) {
            conditionParent.insertBefore(conditions, this.layout === "mobile" ? this.mobileToolbar : null);
        }
        if (facetsWereHidden && !hideFacets) this.scroll.scrollTop = this._filterScrollTop || 0;
        // An empty result set has no row anchor, but still needs one render on
        // reveal so its query can enter the composer in the now-visible pane.
        if (wasHidden && !hideResults && !this._restoringPage && this.core._resultGeneration) {
            const anchor = this.resultAnchor;
            this.resultAnchor = null;
            this.core.resultRenderer.renderInitialPage(anchor);
        }
        this._syncMobileTools();
    }

    setPage(page, notify = true) {
        if (page === "filters" && this.core.selection?.batchMode) this.core.selection.exitBatchMode();
        this.page = page;
        this.syncPage();
        if (page === "filters") this.sync();
        // Native sidebar / SwipeBack already owns transitions. Never animate a
        // second translucent, transformed layer around a live virtual scroller.
        if (notify) this.core._notifyStateChange();
    }

    showResults(commitInput = true) {
        if (commitInput && !this.core.createFlow?.isCreateMode() && this.core.searchInput.value !== this.core.queryState.raw) {
            this.core.performSearch(this.core.searchInput.value);
        }
        const query = this.core.queryState.raw.trim();
        if (query) this.core.plugin.recordSearchHistory(query);
        this.core._releaseSearchFocusForControl();
        if (this.page !== "results") this.searchVisible = true;
        this.setPage("results");
    }

    back() {
        if (this.core.dropdown.isOpen) { this.core.dropdown._navigateBack(this.core.dropdown.panel); return true; }
        if (this.core._confirmSession) { this.core._confirmSession.finish(false); return true; }
        if (this.layout === "mobile" && this.page === "results") {
            if (this.core.selection.batchMode) { this.core.selection.exitBatchMode(); return true; }
            const wasCreateMode = this.core.createFlow.isCreateMode();
            if (this.core.createFlow.isCreateView() && !this.prepareSearch()) return true;
            if (wasCreateMode) return true;
            this.core._releaseSearchFocusForControl();
            this.searchVisible = false;
            this.setPage("filters");
            this.resultsButton.focus({ preventScroll: true });
            return true;
        }
        return false;
    }

    prepareSearch() {
        const flow = this.core.createFlow;
        if (flow._createInFlight) {
            new Notice("正在创建文件，请稍候");
            return false;
        }
        if (flow.createDraft?.pendingCreation) {
            new Notice("文件已创建，属性尚未完成。可补写属性，或选择“保留文件并返回”");
            return false;
        }
        if (flow.isCreateMode()) return flow.toggleInputMode({ focusInput: false }) !== false;
        flow.prepareSearchEvaluation();
        return true;
    }

    select(kind, value, key = "") {
        if (!this.prepareSearch()) return;
        const state = this.core.filterState;
        if (kind === "tag") state.tagMatchMode = "all";
        if (kind === "property") state.propertyMatchMode = "all";
        // A navigation row enters its scope, including when it is already selected.
        // Removing a condition remains the shared condition chip / Picker's action.
        this.core._applyFacetSelection(kind, value, { key, mode: "replace" });
        this.core._onFilterChanged();
        if (this.layout === "mobile") this.showResults(false);
    }

    openSection(kind, anchor) {
        if (!this.prepareSearch()) return;
        if (kind === "time") {
            return this.core.sorting.openPicker({ pickerBtn: anchor, context: "time" });
        }
        const before = JSON.stringify(this.core.filterState.toSnapshot());
        const core = this.core;
        if (kind === "folder") core.facets.showFolderDropdown({ anchor });
        else if (kind === "tags") core.facets.openTagPicker({ anchor });
        else if (kind === "properties") core.facets.openPropertyPicker("", anchor);
        else if (kind === "project") core.facets.openPropertyPicker("所属项目", anchor, { mode: "quick-value" });
        else if (kind === "owner") core.facets.openPropertyPicker("项目负责人", anchor, { mode: "quick-value" });
        this._trackPicker(before);
    }

    _openProperty(key, anchor) {
        if (!this.prepareSearch()) return;
        const before = JSON.stringify(this.core.filterState.toSnapshot());
        this.core.facets.openPropertyPicker(key, anchor, { mode: "quick-value" });
        this._trackPicker(before);
    }

    _trackPicker(before) {
        const core = this.core;
        const panel = core.dropdown.panel;
        if (!panel) return;
        this.pickerFlow = { panel, before, page: this.page };
    }

    didClosePicker() {
        const flow = this.pickerFlow;
        if (!flow || flow.panel.isConnected) return;
        this.pickerFlow = null;
        // Management is a child of the originating page. A filter mutation is
        // not a navigation command: Back never implies "show results".
    }

    _section(id, title, icon) {
        let ref = this.sections.get(id);
        if (!ref) {
            const section = this.scroll.createDiv({ cls: "local-search-nav-section" });
            section.dataset.navSection = id;
            const expand = () => {
                if (this.collapsed.has(id)) this.collapsed.delete(id); else this.collapsed.add(id);
                this.renderRevision = -1; this.sync(); this.core._notifyStateChange();
            };
            const tree = createSharedPickerTreeRow(section, { name: title, icon,
                rowClasses: "local-search-nav-section-heading local-search-nav-group-row",
                itemClasses: "local-search-nav-section-toggle", hasChildren: true,
                onClick: expand, onToggle: expand });
            const heading = tree.row;
            const summary = heading.createSpan({ cls: "local-search-nav-count" });
            const manage = createSearchWindowAction(heading, "ellipsis", `选择和管理${title}`);
            manage.addClass("local-search-nav-manage");
            manage.addEventListener("click", () => this.openSection(id, manage));
            const content = section.createDiv({ cls: "local-search-nav-section-content" });
            ref = { section, heading, toggle: tree.button, summary, content, manage, chevron: tree.toggle };
            this.sections.set(id, ref);
        }
        ref.content.hidden = this.collapsed.has(id);
        ref.manage.hidden = this.layout === "mobile";
        ref.toggle.setAttribute("aria-expanded", String(!ref.content.hidden));
        setIcon(ref.chevron, ref.content.hidden ? "chevron-right" : "chevron-down");
        ref.chevron.setAttribute("aria-expanded", String(!ref.content.hidden));
        ref.chevron.setAttribute("aria-label", `${ref.content.hidden ? "展开" : "折叠"} ${title}`);
        return ref;
    }

    _row(ref, options) {
        const depth = (options.depth || 0) + (this.layout === "mobile" ? 1 : 0);
        const id = options.navDescriptor ? this.customization.descriptor(options.navDescriptor).id
            : options.rowKey || `more:${options.itemTitle || options.name}`;
        ref.rows ||= new Map();
        let tree = ref.rows.get(id);
        if (tree && Number(tree.row.dataset.treeDepth) !== depth) {
            if (ref.rowCursor === tree.row) ref.rowCursor = tree.row.nextElementSibling;
            tree.row.remove(); ref.rows.delete(id); tree = null;
        }
        if (!tree) {
            tree = createSharedPickerTreeRow(ref.content, { ...options, depth,
                // Install stable hit-target callbacks once. Later projections
                // update their data instead of replacing the focused DOM row.
                hasChildren: true,
                rowClasses: `local-search-nav-row ${options.rowClasses || ""}`,
                onClick: () => tree._navOptions?.onClick?.(),
                onToggle: () => tree._navOptions?.onToggle?.() });
            ref.rows.set(id, tree);
        }
        tree._navOptions = options;
        tree.row.dataset.navRowKey = id;
        tree.row.dataset.pickerKey = options.itemTitle || options.name || "";
        tree.row.classList.toggle("is-selected", Boolean(options.active));
        tree.button.setAttribute("aria-pressed", String(Boolean(options.active)));
        tree.button.setAttribute("aria-label", options.itemTitle || options.name || "");
        tree.button.disabled = !options.onClick;
        const name = tree.button.querySelector(".local-search-move-tree-name");
        if (name && name.textContent !== String(options.name || "")) name.textContent = options.name || "";
        const hasChildren = Boolean(options.hasChildren);
        tree.toggle.classList.toggle("is-placeholder", !hasChildren);
        tree.toggle.disabled = !hasChildren;
        tree.toggle.tabIndex = hasChildren ? 0 : -1;
        if (hasChildren) {
            tree.toggle.removeAttribute("aria-hidden");
            tree.toggle.setAttribute("aria-expanded", String(Boolean(options.expanded)));
            tree.toggle.setAttribute("aria-label", `${options.expanded ? "折叠" : "展开"} ${options.name || ""}`);
            const toggleIcon = options.expanded ? "chevron-down" : "chevron-right";
            if (tree.toggle.dataset.navIcon !== toggleIcon) { setIcon(tree.toggle, toggleIcon); tree.toggle.dataset.navIcon = toggleIcon; }
        } else {
            tree.toggle.setAttribute("aria-hidden", "true");
            tree.toggle.removeAttribute("aria-expanded");
        }
        let badge = tree.row.querySelector(":scope > .local-search-move-current-badge");
        const hasCount = options.count !== null && options.count !== undefined && options.count !== "";
        if (!badge && hasCount) badge = tree.row.createSpan({ cls: "local-search-move-current-badge" });
        if (badge) { badge.hidden = !hasCount; if (hasCount && badge.textContent !== String(options.count)) badge.textContent = String(options.count); }
        if (options.icon && tree.iconEl.dataset.navIcon !== options.icon && !options.navDescriptor) {
            setIcon(tree.iconEl, options.icon); tree.iconEl.dataset.navIcon = options.icon;
        }
        if (options.navDescriptor) this.customization.decorate(tree.row, { ...options.navDescriptor,
            depth });
        this._placeProjectionRow(ref, id, tree.row);
        return tree;
    }

    _placeProjectionRow(ref, id, row) {
        ref.usedRows?.add(id);
        if (row !== ref.rowCursor) ref.content.insertBefore(row, ref.rowCursor || null);
        ref.rowCursor = row.nextElementSibling;
    }

    _separator(ref, descriptor, depth = 0) {
        ref.rows ||= new Map();
        const signature = JSON.stringify([descriptor, depth, this.layout]);
        let tree = ref.rows.get(descriptor.id);
        if (!tree || tree.separatorSignature !== signature) {
            if (ref.rowCursor === tree?.row) ref.rowCursor = tree.row.nextElementSibling;
            tree?.row.remove();
            tree = this.customization.renderSeparator(ref.content, descriptor, depth + (this.layout === "mobile" ? 1 : 0));
            tree.separatorSignature = signature;
            ref.rows.set(descriptor.id, tree);
        }
        this._placeProjectionRow(ref, descriptor.id, tree.row);
        return tree;
    }

    _finishProjectionRows(ref) {
        for (const [id, tree] of ref.rows || []) if (!ref.usedRows.has(id)) { tree.row.remove(); ref.rows.delete(id); }
        ref.usedRows = null;
        ref.rowCursor = null;
    }

    _more(ref, kind, text = "显示全部…") {
        const row = this._row(ref, { rowKey: `more:${kind}`, name: text, icon: "ellipsis", itemClasses: "local-search-nav-more",
            onClick: () => this.openSection(kind, row.button) });
    }

    _cached(key, build) {
        if (!this._projectionCache.has(key)) this._projectionCache.set(key, build());
        return this._projectionCache.get(key);
    }

    _propertyKeys(universe) {
        const showExcluded = this.customization.maintenanceMode?.kind === "property-key" && this.customization.maintenanceMode.id === "exclude";
        const excluded = showExcluded ? [] : this.core.plugin.settings.excludedKeys;
        return this._cached("property-keys", () => this.core.plugin.propertyCatalogKeys(collectPropertyKeys(universe, excluded), excluded));
    }

    _propertyStats(key, universe, state) {
        return this._cached(`property:${key}`, () => {
            const selected = state.properties.get(key);
            const known = buildPropertyUsageStats(universe, key, selected, this.core.plugin.propertyCatalogValues(key)).values;
            return buildPropertyUsageStats(this.core._facetCandidates("property", key, universe), key, selected, known);
        });
    }

    _tree(ref, roots, keyPrefix, row, kind, fixed = null) {
        let count = 0, truncated = false;
        const visit = (nodes, depth, parentId) => {
            const descriptors = nodes.map(node => ({ kind: keyPrefix, key: node.path, label: node.name,
                icon: keyPrefix === "folder" ? "folder" : "tag", node }));
            if (depth === 0 && fixed) descriptors.unshift(fixed);
            for (const descriptor of this.customization.order(parentId, descriptors)) {
                if (descriptor.kind === "separator") { this._separator(ref, descriptor, depth); continue; }
                if (descriptor.fixedOptions) { this._row(ref, { ...descriptor.fixedOptions, navDescriptor: descriptor }); continue; }
                if (count >= 70) { truncated = true; return; }
                count++;
                const node = descriptor.node;
                const key = `${keyPrefix}:${node.path}`;
                const expanded = this.expanded.has(key);
                const children = node.children || [];
                this._row(ref, { depth, navDescriptor: descriptor, hasChildren: children.length > 0, expanded,
                    toggleTitle: expanded ? "折叠" : "展开", ...row(node),
                    onToggle: () => { if (expanded) this.expanded.delete(key); else this.expanded.add(key);
                        this.renderRevision = -1; this.sync(); this.core._notifyStateChange(); } });
                if (expanded && children.length) visit(children, depth + 1, descriptor.id);
            }
        };
        visit(roots, 0, navigatorItemId("group", kind));
        if (truncated) this._more(ref, kind);
    }

    sync() {
        const core = this.core;
        if (!core || core._destroyed) return;
        if (core.createFlow?.isCreateMode?.() && this.page !== "results") this.setPage("results", false);
        const n = core.fullResults.length;
        this.resultsButton.setAttribute("aria-label", `查看结果 · ${n}`);
        this.resultsButton.setAttribute("title", `查看结果 · ${n}`);
        this.resultTitle.textContent = this._scopeTitle();
        this.resultTitle.title = this.resultTitle.textContent;
        this._syncMobileTools();
        // A hidden tree has no work to paint. Rebuild only on returning to it.
        if (this.layout === "mobile" && this.page !== "filters") return;
        if (this.renderRevision === core._resultGeneration) return;
        // Result cards commit first. Navigation projection is one cancellable
        // follow-up task and always consumes the latest query/generation.
        if (this._projectionTimer != null) return;
        this._projectionTimer = this.root.ownerDocument.defaultView.setTimeout(() => {
            this._projectionTimer = null;
            if (this.core === core && !core._destroyed) this._renderProjection();
        }, 0);
    }

    _renderProjection() {
        const core = this.core;
        if (!core || core._destroyed || this.renderRevision === core._resultGeneration) return;
        if (this.layout === "mobile" && this.page !== "filters") return;
        if (this.customization.coordinator.session || this.customization.coordinator._committing) return;
        this.customization.beginRender();
        const doc = this.root.ownerDocument;
        const focused = doc.activeElement;
        const focusedRow = focused?.closest?.("[data-nav-id]");
        let focusReturn = null;
        if (focusedRow && this.scroll.contains(focusedRow)) {
            const section = [...this.sections].find(([, ref]) => ref.section.contains(focusedRow));
            focusReturn = { section: section?.[0], key: focusedRow.dataset.pickerKey, navId: focusedRow.dataset.navId,
                selector: focused.closest(".local-search-nav-sort-grip") ? ".local-search-nav-sort-grip"
                    : focused.closest(".local-search-move-tree-toggle") ? ".local-search-move-tree-toggle"
                    : focused.closest(".is-interactive") ? ".is-interactive" : ".local-search-move-tree-folder" };
        }
        const state = core.createFlow?.searchResultFilterState?.() || core.filterState;
        this.renderRevision = core._resultGeneration;
        // Batch one projection per open section; no file reads and no per-row vault scans.
        const scroll = this._restoreScrollTop ?? (this.facets.hidden ? this._filterScrollTop || 0 : this.scroll.scrollTop);
        const anchorOptions = { selector: "[data-nav-id]", keyFrom: row => row.dataset.navId };
        const scrollAnchor = this._restoreScrollTop == null ? captureScrollableAnchor(this.scroll, anchorOptions) : null;
        const scrollBounds = this.scroll.getBoundingClientRect();
        const oldAnchors = scrollAnchor ? [...this.scroll.querySelectorAll("[data-nav-id]")].flatMap(row => {
            const rect = row.getBoundingClientRect();
            return rect.height ? [{ key: row.dataset.navId, offset: rect.top - scrollBounds.top, scrollTop: scroll }] : [];
        }) : [];
        if (this._cacheRevision !== core._resultGeneration) {
            this._cacheRevision = core._resultGeneration;
            this._projectionCache.clear();
        }
        const universe = this._cached("universe", () => core._facetUniverse());
        const definitions = this._definitions();
        for (const [id, ref] of this.sections) ref.section.hidden = !definitions.some(def => def[0] === id);
        this._groupSeparators ||= new Map();
        const activeGroupSeparators = new Set();
        const groups = this.customization.order("groups", definitions.map(([key, label, icon]) => ({ kind: "group", key, label, icon, depth: 0 })));
        let nextGroupNode = this.scroll.firstElementChild;
        const placeGroup = node => {
            if (node !== nextGroupNode) this.scroll.insertBefore(node, nextGroupNode);
            nextGroupNode = node.nextElementSibling;
        };
        for (const group of groups) {
            if (group.kind === "separator") {
                activeGroupSeparators.add(group.id);
                const signature = JSON.stringify(group);
                let entry = this._groupSeparators.get(group.id);
                if (!entry || entry.signature !== signature) {
                    if (entry?.row === nextGroupNode) nextGroupNode = entry.row.nextElementSibling;
                    entry?.row.remove();
                    entry = { ...this.customization.renderSeparator(this.scroll, group), signature };
                    this._groupSeparators.set(group.id, entry);
                }
                placeGroup(entry.row); continue;
            }
            const { key: id, label: title, icon } = group;
            const ref = this._section(id, title, icon);
            placeGroup(ref.section);
            this.customization.decorate(ref.heading, group);
            // Expanding one branch does not rebuild unrelated sections or scan the vault.
            const prefix = id === "tags" ? "tag:" : `${id}:`;
            const signature = JSON.stringify([core._resultGeneration, this.layout, [...this.expanded].filter(key => key.startsWith(prefix))]);
            let count = 0, selected = false;
            if (id === "folder") {
                count = this._cached("folder-candidates", () => core._facetCandidates("folder", "", universe)).length;
                selected = state.folders.size > 0;
            } else if (id === "tags") {
                count = this._cached("tag-candidates", () => core._facetCandidates("tags", "", universe)).length;
                selected = state.tags.size > 0;
            } else if (id === "properties") {
                const candidates = this._cached("property-candidates", () => core._facetCandidates("properties", "", universe));
                const keys = this._propertyKeys(universe);
                count = this._cached("property-present-count", () => candidates.filter(meta => keys.some(key => metaHasProperty(meta, key))).length);
                selected = state.properties.size > 0;
            } else {
                const key = id === "project" ? "所属项目" : "项目负责人";
                count = this._propertyStats(key, universe, state).present;
                selected = Boolean(state.properties.get(key)?.size);
            }
            ref.summary.textContent = String(count);
            ref.summary.hidden = false;
            ref.summary.setAttribute("aria-label", `${count} 个文件`);
            ref.heading.classList.toggle("is-selected", selected);
            if (ref.content.hidden || ref.signature === signature) continue;
            ref.signature = signature;
            ref.usedRows = new Set();
            ref.rowCursor = ref.content.firstElementChild;
            if (id === "folder") {
                const counts = this._cached("folder-counts", () => createSharedFolderCountProvider(this._cached("folder-candidates", () => core._facetCandidates("folder", "", universe))));
                const makeNodes = folder => sharedFolderChildren(core.app, core.plugin, folder).map(child => ({
                    path: child.path, name: child.name, get children() { return makeNodes(child); }
                }));
                this._tree(ref, makeNodes(core.app.vault.getRoot()), "folder", node => ({
                    name: node.name, itemTitle: node.path, icon: "folder", count: counts(node.path),
                    active: state.folders.has(node.path), onClick: () => this.select("folder", node.path)
                }), id, { kind: "folder", key: "/", label: "根目录", icon: "folder-root", sortable: false,
                    fixedOptions: { name: "根目录", icon: "folder-root", count: counts("/"), active: state.folders.has("/"), onClick: () => this.select("folder", "/") } });
            } else if (id === "tags") {
                const candidates = this._cached("tag-candidates", () => core._facetCandidates("tags", "", universe));
                const counts = this._cached("tag-counts", () => buildHierarchicalTagUsageCounts(candidates));
                this._tree(ref, this._cached("tag-tree", () => buildTagTreeModel(universe, core.plugin.settings.pickerTagOrder)), "tag", node => ({
                    name: node.name, itemTitle: node.path, icon: "tag", count: counts.counts.get(tagIdentityKey(node.path)) || 0,
                    active: [...state.tags].some(tag => tagIdentityKey(tag) === tagIdentityKey(node.path)), onClick: () => this.select("tag", node.path)
                }), id, { kind: "tag", key: NO_TAGS_FILTER_VALUE, label: "无标签", icon: "tag", sortable: false,
                    fixedOptions: { name: "无标签", icon: "tag", count: counts.noTags, active: state.tags.has(NO_TAGS_FILTER_VALUE), onClick: () => this.select("tag", NO_TAGS_FILTER_VALUE) } });
            } else if (id === "properties") {
                const keys = this._propertyKeys(universe);
                const properties = this.customization.order(group.id, keys.map(key => ({ kind: "property-key", key, label: key, icon: "list" })));
                let displayedKeys = 0;
                for (const descriptor of properties) {
                    if (descriptor.kind === "separator") { this._separator(ref, descriptor); continue; }
                    if (++displayedKeys > 40) break;
                    const key = descriptor.key;
                    const stats = this._propertyStats(key, universe, state);
                    if (this.layout !== "mobile") {
                        const row = this._row(ref, { name: key, icon: "list", navDescriptor: descriptor, count: stats.present, active: state.properties.has(key), onClick: () => this._openProperty(key, row.button) });
                        continue;
                    }
                    const expansion = `properties:${key}`;
                    const expanded = this.expanded.has(expansion);
                    const toggle = () => {
                        expanded ? this.expanded.delete(expansion) : this.expanded.add(expansion);
                        this.renderRevision = -1; this.sync(); core._notifyStateChange();
                    };
                    const keyRow = this._row(ref, { name: key, itemTitle: key, icon: "list", navDescriptor: descriptor, rowClasses: "local-search-nav-property-key",
                        hasChildren: true, expanded, count: stats.present, toggleTitle: expanded ? "折叠" : "展开",
                        active: state.properties.has(key), onClick: toggle, onToggle: toggle });
                    keyRow.row.dataset.propertyKey = key;
                    if (!expanded) continue;
                    const values = stats.values.filter(value => !isSpecialPropertyValue(value) && value !== PRESENT_PROPERTY_VALUE);
                    let displayedValues = 0;
                    for (const valueDescriptor of this.customization.order(descriptor.id, values.map(value => ({ kind: "property-value", key, value, label: propertyValueDisplay(value), icon: "equal" })))) {
                        if (valueDescriptor.kind === "separator") { this._separator(ref, valueDescriptor, 1); continue; }
                        if (++displayedValues > 60) break;
                        const value = valueDescriptor.value;
                        this._row(ref, { depth: 1, navDescriptor: valueDescriptor, name: propertyValueDisplay(value), icon: "equal",
                        count: stats.counts.get(propertyValueKey(value)) || 0,
                        active: [...(state.properties.get(key) || [])].some(v => propertyValueKey(v) === propertyValueKey(value)),
                        onClick: () => this.select("property", value, key) });
                    }
                    if (values.length > 60) {
                        const more = this._row(ref, { depth: 1, rowKey: `more-property:${key}`, name: `显示全部 ${values.length} 个值`, icon: "ellipsis",
                            onClick: () => this._openProperty(key, more.button) });
                    }
                }
                if (keys.length > 40) this._more(ref, id);
            } else if (id === "project" || id === "owner") {
                const key = id === "project" ? "所属项目" : "项目负责人";
                const stats = this._propertyStats(key, universe, state);
                const values = stats.values.filter(v => !isSpecialPropertyValue(v) && v !== PRESENT_PROPERTY_VALUE);
                let displayedValues = 0;
                for (const descriptor of this.customization.order(group.id, values.map(value => ({ kind: "property-value", key, value, label: propertyValueDisplay(value), icon, groupId: group.id })))) {
                    if (descriptor.kind === "separator") { this._separator(ref, descriptor); continue; }
                    if (++displayedValues > 60) break;
                    const value = descriptor.value;
                    this._row(ref, { navDescriptor: descriptor, name: propertyValueDisplay(value), icon,
                    count: stats.counts.get(propertyValueKey(value)) || 0,
                    active: [...(state.properties.get(key) || [])].some(v => propertyValueKey(v) === propertyValueKey(value)),
                    onClick: () => this.select("property", value, key) });
                }
                if (values.length > 60) this._more(ref, id, `显示全部 ${values.length} 个值`);

            }
            this._finishProjectionRows(ref);
        }
        for (const [id, entry] of this._groupSeparators) if (!activeGroupSeparators.has(id)) { entry.row.remove(); this._groupSeparators.delete(id); }
        this.customization.finishRender();
        if (scrollAnchor) {
            const remaining = new Set([...this.scroll.querySelectorAll("[data-nav-id]")].filter(row => row.getClientRects().length).map(row => row.dataset.navId));
            const nearest = remaining.has(scrollAnchor.key) ? scrollAnchor
                : oldAnchors.filter(anchor => remaining.has(anchor.key)).sort((a, b) => Math.abs(a.offset - scrollAnchor.offset) - Math.abs(b.offset - scrollAnchor.offset))[0];
            restoreScrollableAnchor(this.scroll, nearest || scrollAnchor, anchorOptions);
        } else this.scroll.scrollTop = scroll;
        this._filterScrollTop = this.scroll.scrollTop;
        this._restoreScrollTop = null;
        this.syncPage();
        // Deferred projection replaces rows after the shared Tree Primitive's
        // synchronous action has returned. Restore only a removed owned focus;
        // an input/Picker that has since taken focus must remain untouched.
        if (focusReturn && doc.activeElement !== focused && !this.facets.hidden
            && (doc.activeElement === doc.body || doc.activeElement === doc.documentElement)) {
            const ref = this.sections.get(focusReturn.section);
            const row = [...(ref?.section || this.scroll).querySelectorAll("[data-nav-id]")].find(node => node.dataset.navId === focusReturn.navId);
            const target = row?.querySelector(focusReturn.selector);
            if (target?.getClientRects().length && !target.disabled) target.focus({ preventScroll: true });
        }
    }

    destroy() {
        if (this._projectionTimer != null) this.root.ownerDocument.defaultView.clearTimeout(this._projectionTimer);
        this._projectionTimer = null;
        this.observer?.disconnect();
        this.customization?.destroy();
        for (const cleanup of this.cleanups.splice(0)) cleanup();
        this.root.removeClass("local-search-navigator", "is-nav-search-visible", "has-nav-query");
        for (const key of ["navLayout", "navPage"]) delete this.root.dataset[key];
        this.root.removeAttribute("data-ignore-swipe");
        this.core = null;
    }
}

// Shared mobile frame: CSS owns geometry; this controller owns only a measured
// pre-keyboard frame and extra scroll room only when an input is occluded.
// Hosts own disposal. The provider also releases frames borrowed through its API
// on unload. Embedded cores inherit their host and never bind twice.
export const MOBILE_FRAME_OWNER = Symbol.for("integrated-ui.mobile-frame");

export class MobileFrameController {
    constructor(root, options = {}, onDispose = null) {
        root[MOBILE_FRAME_OWNER]?.destroy();
        this.root = root;
        this.onDispose = onDispose;
        this.win = root.ownerDocument.defaultView;
        this.options = options;
        this.cleanups = [];
        this.frame = 0;
        this.disposed = false;
        this.nativeHeight = 0;
        this.nativeOpen = false;
        this.frameHeight = 0;
        this.restingBottom = this.visualBottom();
        this.restingHeight = this.win.innerHeight;
        this.scrollport = null;
        root[MOBILE_FRAME_OWNER] = this;
        root.classList.add("ui-mobile-frame");
        const listen = (node, type, handler, capture = false) => {
            if (!node) return;
            node.addEventListener(type, handler, capture);
            this.cleanups.push(() => node.removeEventListener(type, handler, capture));
        };
        listen(root, "focusin", event => {
            if (!this.ownsFocus(event.target)) return;
            this.lock(); this.refresh();
        }, true);
        listen(root, "focusout", () => this.refresh(), true);
        listen(root, "input", event => {
            if (this.root.classList.contains("is-ui-keyboard-open") && this.ownsFocus(event.target)) this.refresh();
        }, true);
        const show = event => {
            if (!this.ownsFocus(root.ownerDocument.activeElement)) return;
            this.lock(); this.nativeOpen = true;
            const height = Number(event.keyboardHeight ?? event.detail?.keyboardHeight);
            if (Number.isFinite(height) && height > 0) this.nativeHeight = height;
            this.refresh();
        };
        for (const type of ["keyboardWillShow", "keyboardDidShow"]) listen(this.win, type, show);
        // Keep the frame and inset until the keyboard has actually finished hiding.
        listen(this.win, "keyboardDidHide", () => {
            this.nativeOpen = false; this.nativeHeight = 0; this.refresh();
        });
        for (const type of ["resize", "scroll"]) listen(this.win.visualViewport, type, () => this.refresh());
        listen(this.win, "resize", () => this.refresh());
        listen(this.win, "orientationchange", () => {
            this.unlock(); this.restingBottom = this.visualBottom();
            this.restingHeight = this.win.innerHeight;
            options.onOrientation?.(); this.refresh();
        });
        this.refresh();
    }
    ownsFocus(target) {
        return this.root.contains(target) && target.closest?.(".ui-mobile-frame") === this.root && this.isTextEntry(target);
    }
    isTextEntry(target) {
        return !!target?.matches?.('input:not([type="checkbox"]):not([type="radio"]):not([type="button"]):not([type="range"]), textarea, select, [contenteditable="true"], [contenteditable=""]');
    }
    visualBottom() {
        const viewport = this.win.visualViewport;
        return viewport ? viewport.offsetTop + viewport.height : this.win.innerHeight;
    }
    get locked() { return this.frameHeight > 0; }
    lock() {
        if (this.disposed || this.locked || !this.root.isConnected) return;
        const rect = this.root.getBoundingClientRect();
        if (rect.height <= 0) return;
        this.frameHeight = rect.height;
        // Native leaves already resize with their host. Keep the editing
        // session/inset bookkeeping, but never freeze a second height over it.
        // Viewport popups still retain their measured frame while editing.
        if (this.options.preserveFrame === false) return;
        this.root.style.setProperty("--ui-mobile-frame-height", `${rect.height}px`);
        this.root.classList.add("is-ui-frame-locked");
    }
    clearScrollport() {
        if (!this.scrollport) return;
        this.scrollport.classList.remove("ui-mobile-keyboard-scrollport");
        for (const name of ["--ui-mobile-scroll-height", "--ui-mobile-scroll-padding", "--ui-mobile-scroll-reserve"]) this.scrollport.style.removeProperty(name);
        this.scrollport = null;
    }
    unlock() {
        this.clearScrollport();
        this.frameHeight = 0;
        this.root.classList.remove("is-ui-frame-locked", "is-ui-keyboard-open");
        this.root.style.removeProperty("--ui-mobile-frame-height");
        this.root.style.removeProperty("--ui-mobile-keyboard-inset");
    }
    refresh() {
        if (this.disposed || this.frame) return;
        this.frame = this.win.requestAnimationFrame(() => {
            this.frame = 0;
            if (this.disposed || !this.root.isConnected) return;
            const active = this.root.ownerDocument.activeElement;
            const editing = this.ownsFocus(active);
            const bottom = this.visualBottom();
            // Obsidian iOS publishes the keyboard inset as a CSS variable; Capacitor
            // hosts may also include it in the native event. Neither moves the frame.
            const nativeHeight = this.nativeOpen ? Math.max(this.nativeHeight,
                Number.parseFloat(this.win.getComputedStyle(this.root.ownerDocument.documentElement).getPropertyValue("--keyboard-height")) || 0) : 0;
            const visibleBottom = nativeHeight > 0 ? Math.min(bottom, this.restingHeight - nativeHeight) : bottom;
            const inset = Math.max(0, this.root.getBoundingClientRect().bottom - visibleBottom);
            const keyboardOpen = this.nativeOpen || (this.locked && bottom < this.restingBottom - 1);
            this.root.classList.toggle("is-ui-keyboard-open", keyboardOpen);
            const nextInset = `${keyboardOpen ? inset : 0}px`;
            if (this.root.style.getPropertyValue("--ui-mobile-keyboard-inset") !== nextInset)
                this.root.style.setProperty("--ui-mobile-keyboard-inset", nextInset);
            if (!keyboardOpen) this.clearScrollport();
            if (this.locked && !editing && !keyboardOpen) {
                this.unlock(); this.options.onSettled?.();
            }
            if (!this.locked && !keyboardOpen) {
                this.restingBottom = bottom; this.restingHeight = this.win.innerHeight;
            }
            if (!editing) return;
            if (!this.locked) this.lock();
            let scroller = active.parentElement;
            while (scroller && scroller !== this.root) {
                if (/(auto|scroll)/.test(this.win.getComputedStyle(scroller).overflowY)) break;
                scroller = scroller.parentElement;
            }
            // A header input must never resize an unrelated results list. Only
            // the ancestor containing the active input can consume keyboard room.
            if (!scroller || scroller === this.root) return;
            const scrollRect = scroller.getBoundingClientRect();
            const controlRect = active.getBoundingClientRect();
            const gap = Number.parseFloat(this.win.getComputedStyle(this.root).getPropertyValue("--ui-mobile-focus-gap")) || 0;
            if (this.scrollport && this.scrollport !== scroller) this.clearScrollport();
            if (keyboardOpen && (this.scrollport === scroller || controlRect.bottom > visibleBottom - gap)) {
                if (!this.scrollport) {
                    this.scrollport = scroller;
                    scroller.style.setProperty("--ui-mobile-scroll-height", `${scrollRect.height}px`);
                    scroller.style.setProperty("--ui-mobile-scroll-padding", this.win.getComputedStyle(scroller).paddingBottom);
                    scroller.classList.add("ui-mobile-keyboard-scrollport");
                }
                // Add reachable space below the last field; preserve the scrollport,
                // footer and outer frame. No keyboard-height cap or upward reflow.
                scroller.style.setProperty("--ui-mobile-scroll-reserve", `${Math.max(0, scrollRect.bottom - visibleBottom + gap)}px`);
            }
            if (this.options.revealFocusedControl?.(active) === true) return;
            const control = active.getBoundingClientRect(), rect = scroller.getBoundingClientRect();
            const top = Math.max(rect.top, this.win.visualViewport?.offsetTop || 0) + gap;
            const end = Math.min(rect.bottom, visibleBottom) - gap;
            if (end <= top) return;
            const delta = control.height > end - top
                ? (control.top >= end ? control.top - top : control.bottom <= top ? control.bottom - end : 0)
                : control.bottom > end ? control.bottom - end : control.top < top ? control.top - top : 0;
            if (delta) scroller.scrollTop += delta;
        });
    }
    destroy() {
        if (this.disposed) return;
        this.disposed = true;
        if (this.frame) this.win.cancelAnimationFrame(this.frame);
        this.frame = 0;
        for (const cleanup of this.cleanups.splice(0)) cleanup();
        this.unlock(); this.root.classList.remove("ui-mobile-frame");
        if (this.root[MOBILE_FRAME_OWNER] === this) delete this.root[MOBILE_FRAME_OWNER];
        this.onDispose?.(); this.onDispose = null;
    }
}

export function mountMobileFrame(root, options = {}, onDispose = null) {
    return Platform.isMobile && root?.ownerDocument?.defaultView ? new MobileFrameController(root, options, onDispose) : null;
}

// Workspace 能力层：原生 Leaf 几何、软键盘与手势边界；无全局触摸拦截。
export class SearchWorkspaceCapabilities {
    constructor(core) {
        this.core = core;
        this.root = core.containerEl;
        this.win = this.root.ownerDocument.defaultView;
        this.cleanups = [];
        if (!Platform.isMobile) return;
        const listen = (node, type, handler, options) => {
            node.addEventListener(type, handler, options);
            this.cleanups.push(() => node.removeEventListener(type, handler, options));
        };
        this.mobileFrame = mountMobileFrame(this.root, {
            preserveFrame: false,
            onSettled: () => core.dropdown?._queueReposition(),
            onOrientation: () => core.dropdown?.invalidateFrame()
        });
        const internal = target => target?.closest?.(".local-search-swipe-shell.has-swipe-actions, .local-search-dropdown, .local-search-dialog-surface, .local-search-filter-pool-rail");
        const contain = event => {
            if (internal(event.target)) event.stopPropagation();
            // Never preventDefault here: the existing Swipe / Tree primitive owns intent;
            // native vertical scrolling and editable controls retain their default behavior.
        };
        for (const type of ["touchstart", "touchmove", "touchend", "touchcancel", "pointerdown", "pointermove", "pointerup", "pointercancel"]) {
            listen(this.root, type, contain, { passive: true });
        }
        this.mobileFrame?.refresh();
    }
    resize() { this.mobileFrame?.refresh(); }
    destroy() {
        for (const cleanup of this.cleanups.splice(0)) cleanup();
        this.mobileFrame?.destroy();
        this.mobileFrame = null;
        this.core = null;
    }
}

// Native ItemView hosts one SearchCore. Both existing sidebar and new tab use this implementation.
export class SearchView extends ItemView {
    constructor(leaf, plugin, viewType = VIEW_TYPE) {
        super(leaf);
        this.plugin = plugin;
        this.viewType = viewType;
        this._state = {};
        this._closed = false;
        this.core = null;
        this._ready = null;
        this.capabilities = null;
        this._activeLeafRef = null;
        this._swipeBackCleanup = null;
        this._sessionKey = `workspace:${viewType}:${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
    }

    getViewType() { return this.viewType; }
    getDisplayText() { return this.viewType === VIEW_TYPE ? "GLS Navigator" : "本地搜索"; }
    getIcon() { return "search"; }

    _collapseMobileSidebar() {
        if (!Platform.isMobile || this.viewType !== VIEW_TYPE) return false;
        const workspace = this.app.workspace;
        const roots = [workspace.leftSplit, workspace.rightSplit].filter(Boolean);
        let node = this.leaf;
        while (node) {
            if (roots.includes(node)) { node.collapse?.(); return true; }
            node = node.parent;
        }
        const root = this.leaf?.getRoot?.();
        if (roots.includes(root)) { root.collapse?.(); return true; }
        return false;
    }

    getState() {
        return { sessionKey: this._sessionKey, session: this.core?.captureSession() || this._state.session || null };
    }

    async setState(state, result) {
        this._state = state && typeof state === "object" ? state : {};
        if (typeof this._state.sessionKey === "string" && this._state.sessionKey.startsWith(`workspace:${this.viewType}:`)) {
            const claimed = [...this.plugin.activeSearchCores].some(core => core !== this.core && core.sessionKey === this._state.sessionKey);
            if (!claimed) this._sessionKey = this._state.sessionKey;
        }
        if (this.core && !this.core._destroyed) {
            this.core.sessionKey = this._sessionKey;
            const session = this.plugin.recoverSearchSession(this._sessionKey, this._state.session);
            if (session) {
                this.core.restoreSession(session);
                if (this.core._resultGeneration) this.core._initializeResultState();
            }
        }
        await super.setState(state, result);
    }

    async onOpen() {
        if (this._closed || this.plugin._unloaded) return;
        const core = new SearchCore(this.app, this.plugin, this.contentEl, {
            hostKind: this.viewType === TAB_VIEW_TYPE ? "tab" : "sidebar",
            persistModalSession: false,
            sessionKey: this._sessionKey,
            onStateChange: () => this.app.workspace.requestSaveLayout?.(),
            onFileOpened: (_file, options) => {
                if (!options.newTab && !options.forceKeepOpen) this._collapseMobileSidebar();
            },
            onCloseRequest: () => { // Escape only leaves input; native tab chrome owns closing.
                core._releaseSearchFocusForControl();
                this.contentEl.focus({ preventScroll: true });
                return false;
            }
        });
        this.core = core;
        this._ready = (async () => {
            const fail = error => {
                if (this._closed || this.plugin._unloaded) return false;
                if (error) console.error("搜索工作区初始化失败", error);
                new Notice("本地搜索初始化失败，请重新打开");
                this.leaf?.detach();
                return false;
            };
            try {
                if (!await core.mountShell()) return fail();
                if (this._closed || this.plugin._unloaded) return false;
                core.sessionKey = this._sessionKey;
                core.restoreSession(this.plugin.recoverSearchSession(this._sessionKey, this._state.session));

                // Dida Bridge 3.0.53：Native Tab 自身就是一级导航宿主。
                // 必须把 Tab Surface 注册到同一个 SwipeBack Primitive，back 直接交给 WorkspaceLeaf.detach()；
                // data-ignore-swipe 只隔离 Obsidian 工作区原生侧栏手势，不拦截本插件内部 Result/Picker 手势。
                if (this.viewType === TAB_VIEW_TYPE || this.viewType === VIEW_TYPE) {
                    this.contentEl.setAttribute("data-ignore-swipe", "true");
                    this._swipeBackCleanup?.();
                    this._swipeBackCleanup = this.plugin.swipeBack.register(this.contentEl, {
                        canGoBack: () => !this._closed && this.contentEl?.isConnected && Boolean(this.leaf),
                        back: () => { if (!core.navigator?.back(false) && !this._collapseMobileSidebar()) this.leaf?.detach(); }
                    });
                }

                this.capabilities = new SearchWorkspaceCapabilities(core);
                this._activeLeafRef = this.app.workspace.on("active-leaf-change", leaf => {
                    if (this._closed || core._destroyed) return;
                    if (leaf !== this.leaf) core.suspendInteractions();
                    else { this.capabilities?.resize(); core.dropdown._queueReposition(); }
                });
                return await core.startResults() || fail();
            } catch (error) {
                return fail(error);
            }
        })();
        await this._ready;
    }

    onResize() {
        this.capabilities?.resize();
        this.core?.navigator?.resize();
        if (!this.contentEl.classList.contains("is-ui-frame-locked")) {
            this.core?.dropdown?._queueReposition();
        }
    }

    focusSearchInput() {
        // The tab command never raises a mobile keyboard, even if modal autofocus is enabled.
        if (Platform.isMobile && (this.viewType === TAB_VIEW_TYPE || this.viewType === VIEW_TYPE || !this.plugin.settings.focusSearchOnMobileOpen)) return false;
        const input = this.core?.searchInput;
        if (!input?.isConnected) return false;
        input.focus({ preventScroll: true });
        try { input.setSelectionRange(input.value.length, input.value.length); } catch (_) {}
        return true;
    }

    onClose() {
        if (this._closed) return;
        this._closed = true;
        this._state = this.getState();
        this.plugin._closedSearchViewStates.set(this.viewType, this._state);
        this._swipeBackCleanup?.();
        this._swipeBackCleanup = null;
        this.contentEl.removeAttribute("data-ignore-swipe");
        this.capabilities?.destroy();
        this.capabilities = null;
        if (this._activeLeafRef) this.app.workspace.offref(this._activeLeafRef);
        this._activeLeafRef = null;
        this.core?.destroy();
        this.core = null;
        this.contentEl.empty();
        this.contentEl.removeClass("local-search-content", "local-search-workspace-host");
    }
}

// Modal 内容由插件自己拥有：沿 contentEl → modalEl 的祖先链删除 Obsidian
// 自动插入的 Header / 其它同级 Chrome，避免宿主外壳继续参与窗口几何。
export function stripObsidianModalChrome(modalEl, contentEl) {
    if (!modalEl || !contentEl) return;

    let branch = contentEl;
    while (branch && branch !== modalEl) {
        const parent = branch.parentElement;
        if (!parent) break;

        for (const sibling of [...parent.children]) {
            if (sibling !== branch) sibling.remove();
        }
        branch = parent;
    }
}

// 搜索窗口
// ========== SearchWindowSession：搜索业务唯一会话；Host 仅由打开入口一次性确定 ==========
export class SearchWindowSession {
    constructor(app, plugin, options = {}) {
        this.app = app;
        this.plugin = plugin;
        this.options = options && typeof options === "object" ? options : {};
        this.floating = this.options.floating === true;
        this.host = null;
        this.modalEl = null;
        this.contentEl = null;
        this.core = null;
        this._geometrySaveTimer = null;
        this._desktopBounds = null;
        this._dragCleanup = null;
        this._resizeCleanup = null;
        this._activeDragCleanup = null;
        this._activeResizeCleanup = null;
        this._windowResizeCleanup = null;

        // 一级主窗口只保留一个正式关闭生命周期；所有关闭入口最终都进入 close()。
        this._searchSessionCloseHandled = false;
        this._closing = false;
        this._mobileBackdropCleanup = null;
        this._swipeBackCleanup = null;
        this._startupTimer = null;
        this._autofocusFrame = 0;
        this._mobileFrame = null;
        this._contextMenuCloseHandler = null;

    }


    _attachHost(host, modalEl, contentEl) {
        this.host = host;
        this.modalEl = modalEl;
        this.contentEl = contentEl;
    }

    _hostDocument() {
        return this.modalEl?.ownerDocument
            || this.contentEl?.ownerDocument
            || activeWorkspaceDocument(this.app);
    }

    _hostWindow() {
        return hostWindow(this._hostDocument());
    }

    _handleEscapeEvent(event) {
        if (!event) return false;
        // Modal Scope 已经按 Escape 路由；modeless document listener 则传入真实 KeyboardEvent。
        // 兼容 Scope 回调未暴露 event.key 的宿主版本，同时拒绝任何明确的非 Escape 键。
        if (event.key && event.key !== "Escape") return false;
        if (event.isComposing || event.keyCode === 229) return false;

        event.preventDefault?.();
        event.stopPropagation?.();
        event.stopImmediatePropagation?.();

        const core = this.core;
        if (core?._confirmSession) core._confirmSession.finish(false);
        else if (core?.dropdown?.isOpen) core.dropdown.handleEscape(event);
        else this.close();
        return true;
    }

    open() {
        if (this._closing) return false;
        if (this.host?.isOpen?.()) return true;

        const host = this.floating
            ? new SearchFloatingHost(this)
            : new SearchModalHost(this.app, this);
        this.host = host;
        host.open();
        return true;
    }

    _focusSearchInput(core, expectedFocus) {
        if (this._closing || this.core !== core || core?._destroyed) return;
        if (core.dropdown?.isOpen || core._confirmSession) return;
        if (this.options.externalSession && this.options.focusInputOnOpen !== true) return;
        if (Platform.isMobile && !this.options.focusInputOnOpen && !this.plugin.settings.focusSearchOnMobileOpen) return;
        const input = core?.searchInput;
        if (!input?.isConnected) return;
        const doc = input.ownerDocument;
        const active = doc.activeElement;
        if (active === input || (active !== expectedFocus && active !== doc.body)) return;

        input.focus({ preventScroll: true });
        const end = input.value.length;
        try {
            input.setSelectionRange(end, end);
        } catch (_) {}
    }

    _desktopViewport() {
        const win = hostWindow(this.modalEl);
        const vv = win.visualViewport;
        return {
            width: Math.max(1, Math.round(vv?.width || win.innerWidth)),
            height: Math.max(1, Math.round(vv?.height || win.innerHeight))
        };
    }

    _desktopMetrics() {
        const style = this._hostWindow().getComputedStyle(this.modalEl);
        const value = name => Math.max(0, Number.parseFloat(style.getPropertyValue(name)) || 0);
        return {
            edge: value("--ls-desktop-window-edge"),
            minWidth: value("--ls-desktop-window-min-width"),
            minHeight: value("--ls-desktop-window-min-height"),
            width: value("--ls-desktop-window-default-width"),
            height: value("--ls-desktop-window-default-height")
        };
    }

    _clampDesktopBounds(bounds, metrics = this._desktopMetrics(), keepOrigin = false) {
        const { width: vw, height: vh } = this._desktopViewport();
        const edge = Math.min(metrics.edge, Math.max(0, (Math.min(vw, vh) - 1) / 2));
        const left = Math.min(Math.max(Number(bounds?.x) || 0, edge), vw - edge - 1);
        const top = Math.min(Math.max(Number(bounds?.y) || 0, edge), vh - edge - 1);
        const maxW = Math.max(1, vw - (keepOrigin ? left : edge) - edge);
        const maxH = Math.max(1, vh - (keepOrigin ? top : edge) - edge);
        const requestedWidth = Number(bounds?.width);
        const requestedHeight = Number(bounds?.height);
        const width = Math.min(Math.max(Number.isFinite(requestedWidth) ? requestedWidth : metrics.width || maxW, Math.min(metrics.minWidth, maxW)), maxW);
        const height = Math.min(Math.max(Number.isFinite(requestedHeight) ? requestedHeight : metrics.height || maxH, Math.min(metrics.minHeight, maxH)), maxH);
        const x = keepOrigin ? left : Number.isFinite(Number(bounds?.x))
            ? Math.min(Math.max(Number(bounds.x), edge), vw - width - edge) : (vw - width) / 2;
        const y = keepOrigin ? top : Number.isFinite(Number(bounds?.y))
            ? Math.min(Math.max(Number(bounds.y), edge), vh - height - edge) : (vh - height) / 2;
        return { x: Math.round(x), y: Math.round(y), width: Math.round(width), height: Math.round(height) };
    }

    _applyDesktopBounds(bounds, metrics = null, keepOrigin = false) {
        if (!this.modalEl || Platform.isMobile) return null;
        const next = this._clampDesktopBounds(bounds, metrics || this._desktopMetrics(), keepOrigin);
        const previous = this._desktopBounds;
        this._desktopBounds = next;
        // 固定外框样式由 CSS 接管；运行时只写四个真实几何量，拖动/缩放共用同一出口。
        for (const [key, property] of [["x", "left"], ["y", "top"], ["width", "width"], ["height", "height"]]) {
            if (!previous || previous[key] !== next[key]) this.modalEl.style[property] = `${next[key]}px`;
        }
        return next;
    }

    _queueGeometrySave(bounds, { immediate = false } = {}) {
        if (
            Platform.isMobile
            || !bounds
            || this.plugin._unloaded
        ) return;

        const exact = this._clampDesktopBounds(bounds);
        this._desktopBounds = exact;

        // Update in-memory state immediately. Reopening before disk I/O finishes
        // still gets the newest position/size.
        this.plugin.settings.modalBoundsV3 = { ...exact };

        const enqueue = () => {
            if (this.plugin._unloaded) return;

            // modalBoundsV3 已在内存中更新；只使用插件的 settings write chain。
            void this.plugin.saveSettings();
        };

        if (this._geometrySaveTimer) {
            this._hostWindow().clearTimeout(this._geometrySaveTimer);
            this._geometrySaveTimer = null;
        }

        if (immediate) enqueue();
        else this._geometrySaveTimer = this._hostWindow().setTimeout(() => {
            this._geometrySaveTimer = null;
            enqueue();
        }, 120);
    }

    _prepareDesktopWindowGeometry() {
        if (Platform.isMobile || !this.modalEl) return;
        this.modalEl.addClass("local-search-modal-resizable");
        // 首帧前只写最终窗口几何；拖拽 / Resize 监听等交互等 Shell 建立后再绑定。
        this._applyDesktopBounds(this.plugin.settings.modalBoundsV3);
    }

    _setupDesktopWindowGeometry() {
        if (Platform.isMobile || !this.modalEl) return;
        if (!this._desktopBounds) this._prepareDesktopWindowGeometry();

        // 首帧几何已在挂载前写入；静态外框由 CSS 固定，不再下一帧抢写一次。
        const win = this.modalEl.ownerDocument.defaultView;

        // ----- Drag: header empty area only; size never changes. -----
        const dragHandle = this.contentEl.querySelector(".local-search-header");
        if (dragHandle) {
            dragHandle.addClass("local-search-drag-handle");

            const onPointerDown = (e) => {
                if (e.button !== 0) return;
                if (e.target.closest("input, textarea, button, a, select, [contenteditable='true']")) return;

                e.preventDefault();
                this._activeResizeCleanup?.();
                this._activeDragCleanup?.();
                const metrics = this._desktopMetrics();

                const start = { ...(this._desktopBounds || this._applyDesktopBounds(this.plugin.settings.modalBoundsV3)) };
                const startX = e.clientX;
                const startY = e.clientY;

                const onMove = (ev) => {
                    if (ev.pointerId !== e.pointerId) return;
                    ev.preventDefault();
                    this._applyDesktopBounds({
                        x: start.x + ev.clientX - startX,
                        y: start.y + ev.clientY - startY,
                        width: start.width,
                        height: start.height
                    }, metrics);
                };

                const cleanupActiveDrag = () => {
                    win.removeEventListener("pointermove", onMove, true);
                    win.removeEventListener("pointerup", finish, true);
                    win.removeEventListener("pointercancel", finish, true);
                    if (this._activeDragCleanup === cleanupActiveDrag) {
                        this._activeDragCleanup = null;
                    }
                };

                const finish = event => {
                    if (event && event.pointerId !== e.pointerId) return;
                    cleanupActiveDrag();
                    if (this._desktopBounds) {
                        this._queueGeometrySave(
                            this._desktopBounds,
                            { immediate: true }
                        );
                    }
                };

                this._activeDragCleanup = cleanupActiveDrag;
                win.addEventListener("pointermove", onMove, true);
                win.addEventListener("pointerup", finish, true);
                win.addEventListener("pointercancel", finish, true);
            };

            dragHandle.addEventListener("pointerdown", onPointerDown);
            this._dragCleanup = () => {
                dragHandle.removeEventListener("pointerdown", onPointerDown);
                this._activeDragCleanup?.();
                this._activeDragCleanup = null;
            };
        }

        // ----- Resize: handle MUST be inside modal-content. -----
        // A direct modal child is intentionally hidden elsewhere by CSS.
        const resizeHandle = this.contentEl.createDiv({
 cls:"local-search-resize-handle",
            attr: {
                role: "separator",
                "aria-label": "调整搜索窗口大小"
            }
        });

        const onResizeDown = (e) => {
            if (e.button !== 0) return;
            e.preventDefault();
            e.stopPropagation();
            this._activeDragCleanup?.();
            this._activeResizeCleanup?.();
            const metrics = this._desktopMetrics();

            const start = { ...(this._desktopBounds || this._applyDesktopBounds(this.plugin.settings.modalBoundsV3)) };
            const startX = e.clientX;
            const startY = e.clientY;

            const onMove = (ev) => {
                if (ev.pointerId !== e.pointerId) return;
                ev.preventDefault();
                // 同一 clamp 只改变右下角；不再复制 min/max/边缘合同。
                this._applyDesktopBounds({
                    x: start.x,
                    y: start.y,
                    width: start.width + ev.clientX - startX,
                    height: start.height + ev.clientY - startY
                }, metrics, true);
            };

            const cleanupActiveResize = () => {
                win.removeEventListener("pointermove", onMove, true);
                win.removeEventListener("pointerup", finish, true);
                win.removeEventListener("pointercancel", finish, true);
                if (this._activeResizeCleanup === cleanupActiveResize) {
                    this._activeResizeCleanup = null;
                }
            };

            const finish = event => {
                if (event && event.pointerId !== e.pointerId) return;
                cleanupActiveResize();
                if (this._desktopBounds) {
                    this._queueGeometrySave(
                        this._desktopBounds,
                        { immediate: true }
                    );
                }
            };

            this._activeResizeCleanup = cleanupActiveResize;
            win.addEventListener("pointermove", onMove, true);
            win.addEventListener("pointerup", finish, true);
            win.addEventListener("pointercancel", finish, true);
        };

        resizeHandle.addEventListener("pointerdown", onResizeDown);
        this._resizeCleanup = () => {
            resizeHandle.removeEventListener("pointerdown", onResizeDown);
            this._activeResizeCleanup?.();
            this._activeResizeCleanup = null;
        };

        // Viewport change: clamp the existing state, don't re-measure the DOM.
        const onWindowResize = () => {
            if (!this.modalEl?.isConnected || !this._desktopBounds) return;
            const next = this._applyDesktopBounds(this._desktopBounds);
            if (next) this._queueGeometrySave(next);
        };
        win.addEventListener("resize", onWindowResize);
        this._windowResizeCleanup = () => win.removeEventListener("resize", onWindowResize);
    }

    _setupMobileBackdropGuard() {
        if (!Platform.isMobile) return;
        this._teardownMobileBackdropGuard();

        const container = this.modalEl?.closest(".modal-container");
        if (!container) return;
        const eventRoot = hostDocument(container);
        const backdropEvents = typeof hostWindow(container).PointerEvent === "function"
            ? ["pointerdown", "click"]
            : ["touchstart", "mousedown", "click"];

        const blockBackdropDismiss = event => {
            const target = event.target;
            if (!isDomElement(target) || !container.contains(target)) return;
            const onBackdrop = target === container || Boolean(target.closest(".modal-bg"));
            if (!onBackdrop || this.modalEl.contains(target)) return;

            const clientY = Number(event.clientY);
            const modalBottom = this.modalEl.getBoundingClientRect().bottom;
            // 与 Dida Bridge 一致：一级窗下方命令坞是真正穿透区，其余背景不允许误关。
            if (Number.isFinite(clientY) && clientY > modalBottom) return;

            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation();
        };

        const closeAfterCommandDockClick = event => {
            if (this._closing || !this.modalEl?.isConnected) return;
            const target = isDomElement(event.target) ? event.target : null;
            if (target && (this.modalEl.contains(target) || this.core?._popupHost?.contains(target))) return;

            const clientY = Number(event.clientY);
            if (!Number.isFinite(clientY)) return;
            const modalBottom = this.modalEl.getBoundingClientRect().bottom;
            if (clientY <= modalBottom) return;

            queueMicrotask(() => {
                if (this.modalEl?.isConnected && !this._closing) this.close();
            });
        };

        for (const type of backdropEvents)
            eventRoot.addEventListener(type, blockBackdropDismiss, true);
        eventRoot.addEventListener("click", closeAfterCommandDockClick, true);

        this._mobileBackdropCleanup = () => {
            for (const type of backdropEvents)
                eventRoot.removeEventListener(type, blockBackdropDismiss, true);
            eventRoot.removeEventListener("click", closeAfterCommandDockClick, true);
        };
    }

    _teardownMobileBackdropGuard() {
        this._mobileBackdropCleanup?.();
        this._mobileBackdropCleanup = null;
    }

    _setupMobileViewportGeometry() {
        this._teardownMobileViewportGeometry();
        this._mobileFrame = mountMobileFrame(this.modalEl, {
            onOrientation: () => this.core?.dropdown?.invalidateFrame()
        });
    }

    _teardownMobileViewportGeometry() {
        this._mobileFrame?.destroy(); this._mobileFrame = null;
        if (this._autofocusFrame) this._hostWindow().cancelAnimationFrame(this._autofocusFrame);
        this._autofocusFrame = 0;
    }

    _installWindowInteractions(core) {
        if (!core || core._destroyed || !this.modalEl?.isConnected) return;

        if (!Platform.isMobile) {
            this._setupDesktopWindowGeometry();
        }

        if (Platform.isMobile) {
            this._setupMobileViewportGeometry();

            // 移动端自动聚焦只允许由这一处入口触发，并严格受设置开关控制。
            if (this.options.focusInputOnOpen === true || !this.options.externalSession && this.plugin.settings.focusSearchOnMobileOpen) {
                const expectedFocus = this.contentEl.ownerDocument.activeElement;
                const win = this._hostWindow();
                this._autofocusFrame = win.requestAnimationFrame(() => {
                    this._autofocusFrame = win.requestAnimationFrame(() => {
                        this._autofocusFrame = 0;
                        this._focusSearchInput(core, expectedFocus);
                    });
                });
            }
        }

        // Dida Master 3.0.53：一级窗口与桌面鼠标/移动触控共用同一 Swipe-Back Primitive。
        // Picker / Child Dialog / Overlay 作为后注册的更高导航层优先接管；结果卡 Swipe、横向滚动、排序与编辑区自动让位。
        this._swipeBackCleanup?.();
        this._swipeBackCleanup = this.plugin.swipeBack.register(this.modalEl, {
            canGoBack: () => !this._closing && this.modalEl?.isConnected,
            back: () => this.close()
        });

        this._contextMenuCloseHandler = e => {
            const target = isDomElement(e.target) ? e.target : null;
            if (!target) return;
            if (
                target.closest(".local-search-item")
                || target.closest("input, textarea, button, a, select, [contenteditable='true']")
            ) {
                return;
            }
            e.preventDefault();
            e.stopPropagation();
            this.close();
        };
        this.modalEl.addEventListener("contextmenu", this._contextMenuCloseHandler);
    }

    async _mountSearchCore(externalSession) {
        if (this._closing || !this.modalEl?.isConnected) return false;

        const core = new SearchCore(this.app, this.plugin, this.contentEl, {
            hostKind: "window",
            sharedSearchState: !externalSession,
            sessionKey: externalSession ? "" : "window",
            initialFilterSnapshot: externalSession
                ? this.options.initialFilterSnapshot
                : this.plugin.settings.modalFilterSnapshot,
            initialQuery: externalSession
                ? this.options.initialQuery
                : this.plugin.settings.modalSearchQuery,
            initialSortField: externalSession
                ? this.options.initialSortField
                : this.plugin.settings.modalSortField,
            initialSortDirection: externalSession
                ? this.options.initialSortDirection
                : this.plugin.settings.modalSortDirection,
            initialViewportAnchor: externalSession
                ? null
                : this.plugin.settings.modalViewportAnchor,
            persistModalSession: !externalSession,
            allowedPaths: externalSession ? this.options.allowedPaths : null,
            ignoreResultExclusions: externalSession
                ? this.options.ignoreResultExclusions
                : false,
            onPickFile: externalSession ? this.options.onPickFile : null,
            onOpenFile: externalSession ? this.options.onOpenFile : null,
            closeOnPick: externalSession ? this.options.closeOnPick : true,
            externalSelectionAction: externalSession
                ? this.options.externalSelectionAction
                : null,
            allowCreate: externalSession ? this.options.allowCreate : true,
            createFolder: externalSession ? this.options.createFolder : "",
            createProperties: externalSession ? this.options.createProperties : [],
            createType: externalSession ? this.options.createType : "",
            initialCreate: externalSession && this.options.initialCreate === true,
            onCreated: externalSession ? this.options.onCreated : null,
            headingTitle: externalSession ? this.options.headingTitle : "本地搜索",
            headingCaption: externalSession ? this.options.headingCaption : "你的知识，触手可及",
            // 打开入口在创建 Session 时一次性确定关闭语义：
            // 默认 Modal 打开文件后退出；专用浮窗命令保持常驻。
            closeAfterFileOpen: !this.floating,
            onCloseRequest: closeOptions => this.close(closeOptions)
        });
        this.core = core;

        const initialized = await core.mountShell();
        if (
            !initialized
            || this.core !== core
            || core._destroyed
            || !this.modalEl?.isConnected
        ) {
            if (this.core === core && this.modalEl?.isConnected) this.close();
            return false;
        }

        if (!externalSession) core.restoreSession(this.plugin.settings.createSessionRecovery?.window?.session);
        this._installWindowInteractions(core);

        // Shell 已稳定；结果扫描 / 排序 / 首批虚拟卡片继续进入下一启动任务。
        const expectedFocus = this.contentEl.ownerDocument.activeElement;
        this._startupTimer = this._hostWindow().setTimeout(() => {
            this._startupTimer = null;
            if (this.core !== core || core._destroyed || !this.modalEl?.isConnected) return;
            void core.startResults().then(started => {
                if (this.core !== core || core._destroyed || !this.modalEl?.isConnected) return;
                if (!started) {
                    this.close();
                    return;
                }
                if (!Platform.isMobile) this._focusSearchInput(core, expectedFocus);
            });
        }, 0);
        return true;
    }

    onOpen() {
        // 命令首帧只负责宿主 Modal 外框与固定几何。
        // SearchCore 构造、Shell DOM、状态同步、结果计算全部退出“命令 → 外框出现”同步热路径。
        this.contentEl.empty();
        this.contentEl.addClass("local-search-content");
        this.modalEl.addClass("local-search-modal");
        this.modalEl.closest(".modal-container")?.addClass("local-search-modal-container");
        stripObsidianModalChrome(this.modalEl, this.contentEl);
        this._setupMobileBackdropGuard();

        const externalSession = this.options.externalSession === true;
        if (!Platform.isMobile) this._prepareDesktopWindowGeometry();

        this._startupTimer = this._hostWindow().setTimeout(() => {
            this._startupTimer = null;
            if (this._closing || !this.modalEl?.isConnected) return;
            void this._mountSearchCore(externalSession);
        }, 0);
    }

    _finalizeSearchSessionClose() {
        if (this._searchSessionCloseHandled) return;
        this._searchSessionCloseHandled = true;

        if (this.options.externalSession === true) return;

        const core = this.core;
        if (!core || core._destroyed) return;

        core._persistCurrentModalView();
    }

    /**
     * 一级主窗口唯一关闭入口。
     * X / ESC / 右滑 / 空白右键 / 外部窗口交接全部进入这里；
     * 移动端与 Dida Bridge 一致：同步隐藏并摘除当前 modal-container，避免跨插件切窗叠层残留。
     */
    close(options = {}) {
        if (this._closing) return false;
        if (
            (this.core?.selection?.busy || this.core?._confirmSession?.busy)
            && !this.plugin?._unloaded
        ) {
            new Notice("操作正在执行，请稍候");
            return false;
        }

        const closeOptions = options && typeof options === "object"
            ? options
            : {};
        const core = this.core;
        let persistAfterClose = false;

        if (this.options.externalSession !== true && core && !core._destroyed) {
            // 打开结果可直接把“打开前”的正式锚点交进来；普通 X / ESC 则现场捕获一次。
            // 关闭全过程只规范化 / 比较一次 Session。
            const session = closeOptions.sessionSnapshot
                || core._captureCurrentModalSession();
            persistAfterClose = core._persistModalSessionSnapshot(session, {
                persist: false
            });
            this._searchSessionCloseHandled = true;
        }

        // Geometry 每次变化时已经同步写入 settings 内存；若 120ms 防抖尚未落盘，
        // 关闭时只取消 timer，并并入同一次 settings 写入。
        if (this._geometrySaveTimer) {
            this._hostWindow().clearTimeout(this._geometrySaveTimer);
            this._geometrySaveTimer = null;
            persistAfterClose = true;
        }

        const container = this.modalEl?.closest(".modal-container");
        this._closing = true;
        if (Platform.isMobile && container) container.style.display = "none";
        try {
            this.host?._closeDirect?.();
        } finally {
            if (Platform.isMobile) container?.remove?.();
        }

        if (persistAfterClose && !this.plugin?._unloaded) {
            // UI / Host 已结束，立即冻结快照并交给唯一写链；不再用可被紧随的 unload 丢弃的 timer。
            // 写盘仍是异步，不等待磁盘，不在下一会话改动后才采集这次关闭状态。
            void this.plugin.saveSettings();
        }
        return true;
    }

    onClose() {
        this._closing = true;
        // 防御性兜底：宿主若绕过 close() 直接进入生命周期，仍走同一保存与清理路径。
        this._finalizeSearchSessionClose();
        this._teardownMobileBackdropGuard();
        this._swipeBackCleanup?.();
        this._swipeBackCleanup = null;

        if (this._contextMenuCloseHandler) {
            this.modalEl.removeEventListener(
                "contextmenu",
                this._contextMenuCloseHandler
            );
            this._contextMenuCloseHandler = null;
        }

        if (this._geometrySaveTimer) {
            this._hostWindow().clearTimeout(this._geometrySaveTimer);
            this._geometrySaveTimer = null;
        }
        this._dragCleanup?.();
        this._dragCleanup = null;
        this._resizeCleanup?.();
        this._resizeCleanup = null;

        this._windowResizeCleanup?.();
        this._windowResizeCleanup = null;
        if (this._startupTimer !== null) {
            this._hostWindow().clearTimeout(this._startupTimer);
            this._startupTimer = null;
        }
        const core = this.core;
        this.core = null;
        core?.destroy();

        this._teardownMobileViewportGeometry();
        const modalContainer = this.modalEl?.closest(".modal-container");
        modalContainer?.classList.remove("local-search-modal-container");
        this.host = null;
        // 只清理当前实例引用，避免旧实例的 onClose 影响已打开的新实例。
        if (this.plugin.searchSession === this) this.plugin.searchSession = null;

        const onExternalClose = this.options.onExternalClose;
        this.options.onExternalClose = null;

        // 关闭后清掉外部会话携带的大对象/回调引用。
        this.options.onPickFile = null;
        this.options.onOpenFile = null;
        this.options.externalSelectionAction = null;
        this.options.allowedPaths = null;

        if (typeof onExternalClose === "function") {
            try {
                const result = onExternalClose();
                if (result && typeof result.then === "function") {
                    result.catch(error => {
                        console.warn("外部搜索关闭回调失败", error);
                    });
                }
            } catch (error) {
                console.warn("外部搜索关闭回调失败", error);
            }
        }
    }
}

// 默认搜索入口：Obsidian Modal Host；搜索业务全部由 SearchWindowSession 持有。
export class SearchModalHost extends Modal {
    constructor(app, session) {
        super(app);
        this.session = session;
        this.scope = new Scope(this.scope);
        this.scope.register([], "Escape", event => {
            this.session?._handleEscapeEvent(event);
            return false;
        });
    }

    isOpen() {
        return Boolean(this.modalEl?.isConnected);
    }

    onOpen() {
        this.session?._attachHost(this, this.modalEl, this.contentEl);
        this.session?.onOpen();
    }

    close() {
        return this.session?.close() ?? false;
    }

    _closeDirect() {
        super.close();
    }

    onClose() {
        this.session?.onClose();
    }
}

// 专用浮窗命令入口：真正 modeless Host，不进入 Obsidian Modal Scope。
// 除 Escape 外不注册任何全局键盘快捷键，因此浮窗存在时 Obsidian 全局快捷键照常工作。
export class SearchFloatingHost {
    constructor(session) {
        this.session = session;
        this.panel = null;
        this.contentEl = null;
        this._escapeHandler = null;
    }

    isOpen() {
        return Boolean(this.panel?.isConnected);
    }

    _createPanel() {
        const doc = this.session?._hostDocument?.() || activeWorkspaceDocument(this.session?.app);
        const panel = doc.body.createDiv({
            cls: "local-search-modal local-search-modeless-window",
            attr: {
                role: "dialog",
                "aria-modal": "false",
                "aria-label": "本地搜索"
            }
        });
        this.panel = panel;
        this._escapeHandler = event => {
            if (event.key !== "Escape") return;
            this.session?._handleEscapeEvent(event);
        };
        panel.addEventListener("keydown", this._escapeHandler, true);
        return panel;
    }

    open() {
        if (this.isOpen()) return true;
        const panel = this._createPanel();
        const contentEl = panel.createDiv({ cls: "local-search-content" });
        this.contentEl = contentEl;
        this.session?._attachHost(this, panel, contentEl);
        this.session?.onOpen();
        return true;
    }

    close() {
        return this.session?.close() ?? false;
    }

    _closeDirect() {
        const panel = this.panel;
        if (this._escapeHandler) {
            panel?.removeEventListener("keydown", this._escapeHandler, true);
            this._escapeHandler = null;
        }

        // Modeless Host 没有 Obsidian Modal 动画 / Scope 需要等待。
        // 先从文档树摘除窗口，再做 SearchCore / Observer / Picker 清理；
        // 避免“清理完成后窗口才消失”的反向视觉顺序。
        panel?.remove();
        this.panel = null;
        this.contentEl = null;
        this.session?.onClose();
    }
}

// 设置面板

/**
 * 顶层 Overlay 的唯一生命周期宿主。
 * 只负责：挂载 / 背景点击 / ESC / 关闭按钮 / 销毁。
 * 业务层只负责向 overlayEl 中渲染自己的 Surface。
 */
export class LocalSearchOverlayHost {
    constructor({ className = "", onClose = null, canClose = null, closeOnContextmenu = false, ownerDocument = null, ownerElement = null, swipeBack = null } = {}) {
        this.className = className;
        this.onClose = onClose;
        this.canClose = canClose;
        this.closeOnContextmenu = closeOnContextmenu;
        this.ownerDocument = ownerDocument;
        this.ownerElement = ownerElement;
        this.swipeBack = swipeBack;
        this.overlayEl = null;
        this._closed = true;
        this._keydownHandler = null;
        this._swipeCleanup = null;
    }

    open() {
        if (this.overlayEl?.isConnected) return this.overlayEl;
        this._closed = false;

        const doc = hostDocument(this.ownerDocument);
        this.ownerDocument = doc;
        // Match SearchCore's native Modal portal boundary. Mounting outside the
        // owning modal loses its focus scope; mounting in the transformed inner
        // .modal would create a different fixed-position coordinate system.
        const owner = this.ownerElement?.isConnected && this.ownerElement.ownerDocument === doc
            ? this.ownerElement : null;
        const mount = owner?.closest(".modal-container") || doc.body;
        const overlay = mount.createDiv({
            cls: `local-search-overlay-host${this.className ? ` ${this.className}` : ""}`,
            attr: { role: "presentation" }
        });
        markSearchPopupActive(overlay);
        overlay.addEventListener("click", event => {
            if (event.target === overlay) this.close();
        });
        if (this.closeOnContextmenu) {
            overlay.addEventListener("contextmenu", event => {
                if (event.target !== overlay) return;
                event.preventDefault();
                this.close();
            });
        }
        this._swipeCleanup = this.swipeBack?.register(overlay, {
            canGoBack: () => !this._closed && overlay.isConnected,
            back: () => this.close()
        }) ?? null;

        this._keydownHandler = event => {
            if (event.key !== "Escape" || event.isComposing || event.keyCode === 229) return;
            const target = event.target?.nodeType === 1 ? event.target : doc.activeElement;
            if (!overlay.contains(target)) {
                if ((target !== doc.body && target !== doc.documentElement)
                    || topSearchPopupSurface(doc) !== overlay) return;
            }
            // A nested Dropdown/Dialog retains its own back/transaction owner.
            if (target.closest?.(".local-search-dialog-surface")) return;
            event.preventDefault();
            event.stopImmediatePropagation();
            const picker = target.closest?.(".local-search-dropdown");
            if (typeof picker?._lsNavigateBack === "function") picker._lsNavigateBack();
            else this.close();
        };
        doc.addEventListener("keydown", this._keydownHandler, true);

        this.overlayEl = overlay;
        return overlay;
    }

    createCloseButton(surface, { title = "关闭", positioned = false } = {}) {
        if (Platform.isMobile && !surface[MOBILE_FRAME_OWNER]) {
            const frame = mountMobileFrame(surface);
            if (frame) registerPickerCleanup(surface, () => frame.destroy());
        }
        const controls = surface.querySelector(":scope > .local-search-dropdown-title .local-search-picker-title-controls");
        const button = createSearchButton(controls || surface, "action", {
            cls: `local-search-overlay-close${positioned && !controls ? " is-positioned" : ""}`,
            attr: { "aria-label": title }
        });
        setIcon(button, "x");
        button.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            this.close();
        });
        if (!surface.contains(surface.ownerDocument.activeElement)
            && (!Platform.isMobile || this.ownerElement?.matches?.(":focus-visible"))) {
            surface.tabIndex = -1;
            surface.focus({ preventScroll: true });
        }
        return button;
    }

    close({ force = false } = {}) {
        if (this._closed && !this.overlayEl) return;
        if (!force && this.canClose?.() === false) return false;
        const doc = this.ownerDocument;
        const restoreFocus = this.ownerElement?.isConnected
            && (this.overlayEl?.contains(doc?.activeElement) || doc?.activeElement === doc?.body);
        this._closed = true;
        if (this._keydownHandler) {
            this.ownerDocument?.removeEventListener("keydown", this._keydownHandler, true);
            this._keydownHandler = null;
        }
        this._swipeCleanup?.();
        this._swipeCleanup = null;
        this.overlayEl?.remove();
        this.overlayEl = null;
        this.onClose?.();
        if (restoreFocus && this.ownerElement?.isConnected && doc?.activeElement === doc?.body
            && !this.ownerElement.closest("[hidden], [inert]")) {
            this.ownerElement.focus({ preventScroll: true });
        }
    }
}

/**
 * 设置页共享选择器 Overlay。
 * 不再使用独立 Obsidian Modal；文件夹与模板文件都复用搜索弹窗现有
 * local-search-dropdown / Picker Tree 结构与实体 Surface 样式。
 */
// BEGIN SHARED SETTINGS — generated from shared/settings.js
// Native Setting keeps its components and callbacks. Plugin rows own their DOM
// classes so host settings snippets cannot become a second layout owner.
export function createPluginSettingClass(NativeSetting) {
    return class PluginSettingRow extends NativeSetting {
        constructor(parent) {
            super(parent);
            for (const [key, nativeClass, ownClass] of [
                ["settingEl", "setting-item", "ui-setting-row"],
                ["infoEl", "setting-item-info", "ui-setting-info"],
                ["nameEl", "setting-item-name", "ui-setting-name"],
                ["descEl", "setting-item-description", "ui-setting-description"],
                ["controlEl", "setting-item-control", "ui-setting-control"]
            ]) {
                this[key].classList.replace(nativeClass, ownClass);
            }
        }
        addToggle(callback) {
            return super.addToggle(control => {
                control.toggleEl.classList.replace("checkbox-container", "ui-setting-toggle");
                callback(control);
            });
        }
        addText(callback) {
            return super.addText(control => {
                control.inputEl.classList.add("ui-setting-input");
                callback(control);
            });
        }
        addTextArea(callback) {
            return super.addTextArea(control => {
                control.inputEl.classList.add("ui-setting-input");
                callback(control);
            });
        }
        addButton(callback) {
            return super.addButton(control => {
                control.buttonEl.classList.add("ui-setting-action");
                callback(control);
                if (control.buttonEl.classList.contains("mod-cta")) {
                    control.buttonEl.classList.replace("mod-cta", "ui-setting-primary");
                }
            });
        }
        addPicker(callback) {
            this.settingEl.classList.add("ui-setting-block");
            return super.addButton(control => {
                control.buttonEl.classList.add("ui-setting-picker");
                callback(control);
            });
        }
        addExtraButton(callback) {
            return super.addExtraButton(control => {
                control.extraSettingsEl.classList.add("ui-setting-icon");
                callback(control);
            });
        }
    };
}

export class LocalSearchSettingTab extends PluginSettingTab {
    constructor(app, plugin) {
        super(app, plugin);
        this.plugin = plugin;
        this._activeModuleId = "search";
        this._moduleCleanups = [];
    }

    _disposeModule() {
        for (const cleanup of this._moduleCleanups.splice(0)) {
            try { cleanup(); } catch (error) { console.warn("设置模块清理失败", error); }
        }
    }

    _renderNavigatorSettings(card) {
        new SearchSettingRow(card)
            .setName("视图设置")
            .setDesc("侧栏显示内容和各页面底栏按钮统一在视图设置中管理。长按导航条目可调整图标、颜色、背景和分隔线。")
            .addButton(control => control
                .setButtonText("打开视图设置")
                .onClick(async () => {
                    control.setDisabled(true);
                    try {
                        if (!await this.plugin.activateView()) return;
                        const leaf = this.app.workspace.getLeavesOfType(VIEW_TYPE)
                            .find(item => item.view?.plugin === this.plugin && !item.view?._closed);
                        const core = leaf?.view?.core;
                        if (!core || core._destroyed) return;
                        this.app.setting?.close?.();
                        const anchor = core.navigator?.tools?.get("view")?.button;
                        core.resultControls.openViewDropdown(
                            anchor?.isConnected && !anchor.closest("[hidden]") ? anchor : core.resultControls.resultViewBtn,
                            { section: "toolbars" }
                        );
                    } finally { control.setDisabled(false); }
                }));
    }

    display() {
        const { containerEl } = this;
        this._disposeModule();
        containerEl.empty();
        containerEl.addClass("local-search-settings-page");

        const modules = [
            {
                id: "search",
                label: "搜索交互",
                title: "搜索交互",
                desc: "管理搜索交互与再次打开时的结果缓存。",
                render: card => {
                    new SearchSettingRow(card)
                        .setName("常驻搜索结果缓存")
                        .setDesc("保留最近搜索结果与筛选候选，加快再次打开。最多 3 组、合计 20,000 条；占用部分内存，文件变化自动失效。关闭开关立即释放，退出 Obsidian 后不保留。")
                        .addToggle(toggle => toggle
                            .setValue(this.plugin.settings.keepSearchResultsInMemory !== false)
                            .onChange(async value => {
                                this.plugin.settings.keepSearchResultsInMemory = value;
                                if (!value) this.plugin._clearResidentSearchResults();
                                await this.plugin.saveSettings();
                            }));
                    new SearchSettingRow(card)
                        .setName("Tab 快速聚焦搜索框")
                        .setDesc("开启后，在搜索结果界面且当前焦点不在输入框内时，按 Tab 会聚焦搜索框并全选当前搜索词；Shift+Tab 保持原生行为。")
                        .addToggle(toggle => toggle
                            .setValue(this.plugin.settings.enableTabFocusSearch)
                            .onChange(async value => {
                                this.plugin.settings.enableTabFocusSearch = value;
                                await this.plugin.saveSettings();
                            }));
                }
            },
            {
                id: "navigation",
                label: "导航与工具栏",
                title: "导航与工具栏",
                desc: "管理侧栏导航与移动端各页面的底部操作。修改立即生效，不清空搜索和创建内容。",
                render: card => this._renderNavigatorSettings(card)
            },
            {
                id: "mobile",
                label: "移动端",
                title: "移动端",
                desc: "管理移动端打开搜索时的焦点与键盘行为。",
                render: card => {
                    new SearchSettingRow(card)
                        .setName("移动端打开时聚焦搜索框")
                        .setDesc("开启后，移动端每次打开本地搜索都会自动聚焦搜索框并弹出键盘；关闭时保持当前不抢焦点的行为。")
                        .addToggle(toggle => toggle
                            .setValue(this.plugin.settings.focusSearchOnMobileOpen)
                            .onChange(async value => {
                                this.plugin.settings.focusSearchOnMobileOpen = value;
                                await this.plugin.saveSettings();
                            }));
                }
            },
            {
                id: "time",
                label: "时间与历史",
                title: "时间与历史",
                desc: "GLS 时间记录随仓库经 NAS 同步；历史目录必须位于 Obsidian 仓库内。",
                render: card => {
                    new SearchSettingRow(card)
                        .setName("元数据目录")
                        .setDesc("仓库相对路径，默认 GLS-元数据。修改后先复制并验证旧时间记录，再切换位置；旧目录不会自动删除。")
                        .addText(control => {
                            control.setPlaceholder(GLS_METADATA_DEFAULT_DIRECTORY);
                            control.setValue(this.plugin.settings.metadataDirectory);
                            const input = control.inputEl;
                            if (!input) return;
                            let pending = false;
                            const commit = async () => {
                                if (pending || input.value === this.plugin.settings.metadataDirectory) return;
                                pending = true;
                                input.disabled = true;
                                try {
                                    const changed = await this.plugin.changeMetadataDirectory(input.value);
                                    if (changed) new Notice("GLS 元数据目录已更新；旧文件保留，可核对后自行清理");
                                    else input.value = this.plugin.settings.metadataDirectory;
                                } catch (error) {
                                    new Notice(`元数据目录未修改：${error.message || "路径不可用"}`);
                                    input.value = this.plugin.settings.metadataDirectory;
                                } finally {
                                    pending = false;
                                    input.disabled = false;
                                }
                            };
                            input.addEventListener("change", () => void commit());
                            input.addEventListener("keydown", event => {
                                if (event.key !== "Enter" || event.isComposing || event.keyCode === 229) return;
                                event.preventDefault();
                                input.blur();
                            });
                        });
                    new SearchSettingRow(card)
                        .setName("文件时间记录")
                        .setDesc("创建时间固定；正文与普通属性分别记录修改时间。Markdown 保存在 YAML，其他文件保存在元数据目录。最近打开独立记录。");
                }
            },
            {
                id: "files",
                label: "文件操作",
                title: "文件操作",
                desc: "管理删除等高风险文件操作的确认行为。",
                render: card => {
                    new SearchSettingRow(card)
                        .setName("删除文件前确认")
                        .setDesc("开启时删除文件会先显示确认弹窗；在删除弹窗勾选“不再询问”会关闭此项，可随时在这里重新开启。")
                        .addToggle(toggle => toggle
                            .setValue(this.plugin.settings.confirmBeforeDelete !== false)
                            .onChange(async value => {
                                this.plugin.settings.confirmBeforeDelete = value;
                                await this.plugin.saveSettings();
                            }));
                }
            }
        ];
        const moduleById = new Map(modules.map(module => [module.id, module]));
        if (!moduleById.has(this._activeModuleId)) this._activeModuleId = modules[0].id;

        const tabs = containerEl.createDiv({
            cls: "local-search-settings-tabs",
            attr: { role: "tablist", "aria-label": "设置模块" }
        });
        const panel = containerEl.createDiv({
            cls: "local-search-settings-module",
            attr: { role: "tabpanel", id: "local-search-settings-module-panel" }
        });
        const tabButtons = new Map();

        const focusTab = moduleId => {
            const button = tabButtons.get(moduleId);
            if (!button) return;
            button.focus({ preventScroll: true });
            const outer = tabs.getBoundingClientRect();
            const inner = button.getBoundingClientRect();
            if (inner.left < outer.left) tabs.scrollLeft += inner.left - outer.left;
            else if (inner.right > outer.right) tabs.scrollLeft += inner.right - outer.right;
        };

        const renderModule = (id, focus = false) => {
            const module = moduleById.get(id) || modules[0];
            if (panel.dataset.lsModuleId === module.id && panel.childElementCount) {
                if (focus) focusTab(module.id);
                return;
            }
            this._activeModuleId = module.id;
            for (const [moduleId, button] of tabButtons) {
                const selected = moduleId === module.id;
                button.classList.toggle("is-selected", selected);
                button.setAttribute("aria-selected", String(selected));
                button.setAttribute("tabindex", selected ? "0" : "-1");
            }
            this._disposeModule();
            panel.empty();
            panel.dataset.lsModuleId = module.id;
            panel.setAttribute("aria-labelledby", `local-search-settings-tab-${module.id}`);
            const head = panel.createDiv({ cls: "local-search-settings-module-head" });
            head.createDiv({ text: module.title, cls: "local-search-settings-section-title" });
            if (module.desc) head.createDiv({ text: module.desc, cls: "local-search-settings-section-desc" });
            const card = panel.createDiv({ cls: "local-search-settings-card" });
            const group = card.createDiv({ cls: "local-search-settings-group" });
            module.render(group);
            if (focus) focusTab(module.id);
        };

        for (const module of modules) {
            const button = createSearchButton(tabs, "choice", {
                text: module.label,
                cls: "local-search-settings-tab",
                attr: {
                    role: "tab",
                    id: `local-search-settings-tab-${module.id}`,
                    "aria-controls": "local-search-settings-module-panel",
                    "aria-selected": "false",
                    tabindex: "-1"
                }
            });
            button.addEventListener("click", () => renderModule(module.id));
            tabButtons.set(module.id, button);
        }

        tabs.addEventListener("keydown", event => {
            if (event.isComposing || event.altKey || event.ctrlKey || event.metaKey) return;
            if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
            const current = Math.max(0, modules.findIndex(module => module.id === this._activeModuleId));
            let next = current;
            if (event.key === "Home") next = 0;
            else if (event.key === "End") next = modules.length - 1;
            else if (event.key === "ArrowLeft") next = (current - 1 + modules.length) % modules.length;
            else if (event.key === "ArrowRight") next = (current + 1) % modules.length;
            const module = modules[next];
            if (!module) return;
            event.preventDefault();
            renderModule(module.id, true);
        });

        renderModule(this._activeModuleId);
        this.plugin._hoverHintObserver?.observeRoot(containerEl);
    }

    hide() {
        this._disposeModule();
        this.plugin._hoverHintObserver?.forgetRoot(this.containerEl);
        super.hide();
    }

}

// ========== 文件操作服务：搜索结果与独立 Command 共用同一底层实现 ==========
export class FileOperationService {
    constructor(app, plugin) {
        this.app = app;
        this.plugin = plugin;
        this._targetLeases = new Set();
        // Runtime object identity only; recovery metadata remains in CreateDraft.
        this._pendingCreationFiles = new Map();
    }

    assertCurrent(file) {
        if (this.plugin._unloaded) throw new Error("插件已停用，未继续写入");
        if (!(file instanceof TFile || file instanceof TFolder)
            || this.app.vault.getAbstractFileByPath(file.path) !== file) {
            throw new Error("目标文件已删除或被替换，请重新选择");
        }
    }

    async withTargets(files, operation, destinations = []) {
        if (this.plugin._unloaded) throw new Error("插件已停用，未继续写入");
        const targets = [...new Set(files || [])];
        for (const file of targets) this.assertCurrent(file);
        const paths = [...new Set([...targets.map(file => file.path), ...destinations])];
        for (const lease of this._targetLeases) {
            if (paths.some(path => lease.some(active =>
                isSameOrDescendantVaultPath(path, active)
                || isSameOrDescendantVaultPath(active, path)
            ))) throw new Error("目标文件或目录正在处理，请稍后重试");
        }
        // 占用范围包括重命名的两端及目录子树；其它文件仍可同时操作。
        // 仅活跃调用持有，成功、异常均释放；不排队重放旧用户意图。
        this._targetLeases.add(paths);
        try {
            return await operation();
        } finally {
            this._targetLeases.delete(paths);
        }
    }

    createFolder(rawPath, { allowExisting = false } = {}) {
        const path = normalizeVaultFolderPath(rawPath);
        if (!path || /[<>:"|?*\x00-\x1f]/.test(path)) {
            throw new Error("请输入有效的文件夹名称，不能包含 .、.. 或特殊路径字符");
        }
        return this.withTargets([], async () => {
            const existing = this.app.vault.getAbstractFileByPath(path);
            if (existing) {
                if (allowExisting && existing instanceof TFolder) return existing;
                throw new Error(`目标路径已存在：${path}`);
            }
            let current = "";
            let folder;
            for (const part of path.split("/")) {
                current = current ? `${current}/${part}` : part;
                const item = this.app.vault.getAbstractFileByPath(current);
                if (item && !(item instanceof TFolder)) {
                    throw new Error(`目标路径不是文件夹：${current}`);
                }
                folder = item || await this.app.vault.createFolder(current);
            }
            return folder;
        }, [path]);
    }

    createFile(path, content, metadata = null) {
        return this.withTargets([], async () => {
            if (metadata) metadata = { ...metadata,
                properties: (metadata.properties || []).map(([key, value]) => [validateEditablePropertyKey(key), value]),
                tags: normalizeUniqueTagList(metadata.tags || []) };

            if (this.app.vault.getAbstractFileByPath(path)) {
                throw new Error(`目标路径已存在：${path}`);
            }
            const file = await this.app.vault.create(path, content);
            const createdAt = Date.now();
            try {
                this.plugin._noteOwnedCreation(file, createdAt);
                await this._writeCreatedMetadata(file, content, metadata, createdAt);
            } catch (cause) {
                this._pendingCreationFiles.set(file.path, file);
                let currentContent = content;
                try { currentContent = await this.app.vault.read(file); } catch (_) {}
                const error = new Error(`文件已创建，但属性尚未完成：${cause?.message || cause}`);
                error.pendingCreation = {
                    path: file.path,
                    createdAt,
                    ctime: Number(file.stat?.ctime) || 0,
                    contentFingerprint: fastContentFingerprint(currentContent),
                    propertyFingerprint: file.extension.toLowerCase() === "md" ? null
                        : fastContentFingerprint(stableTimeProperties(this.plugin._nonMarkdownProperties(file.path))),
                    metadata: JSON.parse(JSON.stringify(metadata || { tags: [], properties: [] }))
                };
                error.createdFile = file;
                throw error;
            }
            return file;
        }, [path]);
    }

    async _writeCreatedMetadata(file, content, metadata, createdAt, propertyFingerprint = null) {
        this.assertCurrent(file);
        if (file.extension.toLowerCase() === "md") {
            await this.app.fileManager.processFrontMatter(file, fm => {
                    this.assertCurrent(file);
                    // 明确新建才生成新创建时间；模板的内部时间不属于这个新文件。
                    fm.gls_created_at = new Date(createdAt).toISOString();
                    fm.gls_created_source = "gls-created";
                    fm.gls_body_modified_at = new Date(createdAt).toISOString();
                    fm.gls_body_fingerprint = markdownBodyFingerprint(content);
                    if (metadata?.tags?.length) {
                        const existing = Array.isArray(fm.tags) ? fm.tags : fm.tags ? [fm.tags] : [];
                        fm.tags = [...new Set([
                            ...existing.map(tag => String(tag).replace(/^#/, "")),
                            ...metadata.tags
                        ])];
                    }
                    for (const [key, value] of metadata?.properties || []) {
                        if (value === undefined) delete fm[key];
                        else fm[key] = value;
                    }
                    fm.gls_file_modified_at = new Date(createdAt).toISOString();
                    fm.gls_file_fingerprint = fastContentFingerprint(
                        fm.gls_body_fingerprint + "\n" + stableTimeProperties(indexedFileProperties(fm)));
            });
        } else if (metadata && (metadata.tags?.length || metadata.properties?.length)) {
            await this.plugin._editNonMarkdownProperties(file, data => {
                    this.assertCurrent(file);
                    if (propertyFingerprint !== null
                        && fastContentFingerprint(stableTimeProperties(data)) !== propertyFingerprint) {
                        throw new Error("已创建文件的属性已发生变化，请打开文件检查，或保留文件并返回");
                    }
                    if (metadata.tags?.length) data.tags = [...new Set([...(Array.isArray(data.tags) ? data.tags : []), ...metadata.tags])];
                    for (const [key, value] of metadata.properties || []) {
                        if (value === undefined) delete data[key];
                        else data[key] = value;
                    }
                    return "changed";
            });
        }
    }

    resumeCreationMetadata(pending) {
        const file = this.app.vault.getAbstractFileByPath(pending?.path || "");
        if (!(file instanceof TFile)) throw new Error("已创建文件已不存在，请保留当前状态并返回检查");
        const original = this._pendingCreationFiles.get(pending.path);
        if (original && original !== file) throw new Error("已创建文件已被替换，请打开文件检查");
        return this.withTargets([file], async () => {
            const content = await this.app.vault.read(file);
            this.assertCurrent(file);
            if (!pending.contentFingerprint || fastContentFingerprint(content) !== pending.contentFingerprint
                || (pending.ctime && Number(file.stat?.ctime) !== pending.ctime)) {
                throw new Error("已创建文件已发生变化，请打开文件检查，或保留文件并返回");
            }
            if (file.extension.toLowerCase() !== "md"
                && (typeof pending.propertyFingerprint !== "string"
                    || fastContentFingerprint(stableTimeProperties(this.plugin._nonMarkdownProperties(file.path))) !== pending.propertyFingerprint)) {
                throw new Error("已创建文件的属性已发生变化，请打开文件检查，或保留文件并返回");
            }
            try {
                await this._writeCreatedMetadata(file, content, pending.metadata, pending.createdAt, pending.propertyFingerprint);
            } catch (cause) {
                let currentContent = content;
                try { currentContent = await this.app.vault.read(file); } catch (_) {}
                const error = new Error(`文件已创建，但属性尚未完成：${cause?.message || cause}`);
                error.pendingCreation = { ...pending, contentFingerprint: fastContentFingerprint(currentContent) };
                error.createdFile = file;
                throw error;
            }
            this._pendingCreationFiles.delete(pending.path);
            return file;
        });
    }

    forgetPendingCreation(path) {
        this._pendingCreationFiles.delete(path);
    }

    _availablePath(file, targetFolder) {
        const prefix = targetFolder ? `${targetFolder}/` : "";
        const originalPath = `${prefix}${file.name}`;
        if (originalPath === file.path || !this.app.vault.getAbstractFileByPath(originalPath)) {
            return originalPath;
        }
        const extension = file.extension ? `.${file.extension}` : "";
        const basename = file.name.slice(0, file.name.length - extension.length);
        let suffix = 1;
        let candidate;
        do {
            const marker = suffix === 1 ? "-文件重名" : `-文件重名-${suffix}`;
            candidate = `${prefix}${basename}${marker}${extension}`;
            suffix++;
        } while (this.app.vault.getAbstractFileByPath(candidate));
        return candidate;
    }

    renameFile(file, newPath) {
        return this.withTargets([file], async () => {
            const oldPath = file.path;
            if (newPath === oldPath) return false;
            if (file instanceof TFolder) {
                if (file === this.app.vault.getRoot()) throw new Error("不能重命名或移动仓库根目录");
                if (isSameOrDescendantVaultPath(newPath, oldPath)) {
                    throw new Error("不能把文件夹移入自身或其子文件夹");
                }
            }
            const conflict = this.app.vault.getAbstractFileByPath(newPath);
            if (conflict && conflict !== file) throw new Error(`目标路径已被占用：${newPath}`);
            await this.app.fileManager.renameFile(file, newPath);
            if (!await this.plugin._settleRename(file, oldPath)) {
                new Notice("路径已更新，但搜索状态同步失败，请重新打开搜索");
            }
            return true;
        }, [newPath]);
    }

    async moveFiles(files, targetFolder) {
        const moved = [], failed = [];
        for (const file of new Set(files || [])) {
            const oldPath = file?.path || "";
            try {
                this.assertCurrent(file);
                const newPath = this._availablePath(file, targetFolder);
                if (await this.renameFile(file, newPath)) moved.push({ oldPath, newPath: file.path });
            } catch (error) {
                failed.push({ path: oldPath, reason: error?.message || String(error) });
            }
        }
        if (moved.length) {
            new Notice(`已移动 ${moved.length} 个文件到「${targetFolder || "仓库根目录"}」`);
        }
        return { moved, failed };
    }

    deleteFolder(folder) {
        return this.withTargets([folder], async () => {
            if (!(folder instanceof TFolder) || folder === this.app.vault.getRoot()) {
                throw new Error("不能删除仓库根目录");
            }
            if (typeof this.app.fileManager?.trashFile === "function") {
                await this.app.fileManager.trashFile(folder);
            } else {
                await this.app.vault.trash(folder, true);
            }
        });
    }

    async deleteFiles(files) {
        const processedPaths = [], failed = [];
        for (const file of new Set(files || [])) {
            const path = file?.path || "";
            try {
                await this.withTargets([file], async () => {
                    if (!(file instanceof TFile)) throw new Error("请选择文件");
                    if (typeof this.app.fileManager?.trashFile === "function") {
                        await this.app.fileManager.trashFile(file);
                    } else {
                        await this.app.vault.trash(file, true);
                    }
                    processedPaths.push(path);
                    this.plugin._queueFileIndex(path);
                });
            } catch (error) {
                failed.push({ path, reason: error?.message || String(error) });
            }
        }
        if (processedPaths.length) {
            try {
                await this.plugin._flushIndexQueueNow();
            } catch (error) {
                console.error("删除后的索引刷新失败", error);
                new Notice("文件已处理，但搜索索引刷新失败");
            }
        }
        return { processedPaths, failed };
    }
}

export class OperationOverlayController {
    constructor(app, plugin, file, kind) {
        this.app = app;
        this.plugin = plugin;
        this.file = file;
        this.kind = kind;
        this._closed = false;
        this._dialogSubmission = null;
        this._picked = false;
        this.overlayEl = null;
        this.surfaceEl = null;
        this._overlayHost = null;
    }

    open() {
        if (this._closed || this.overlayEl?.isConnected) return this;
        const current = this.app.vault.getAbstractFileByPath(this.file.path);
        if (!(current instanceof TFile)) {
            new Notice("当前文件已不存在");
            this.close();
            return this;
        }

        this._overlayHost = new LocalSearchOverlayHost({
            className: "local-search-command-overlay",
            ownerDocument: activeWorkspaceDocument(this.app),
            swipeBack: this.plugin.swipeBack,
            canClose: () => !this._dialogSubmission?.busy,
            onClose: () => {
                disposePickerCleanup(this.surfaceEl);
                this.plugin._hoverHintObserver?.forgetRoot(this.overlayEl);
                this._closed = true;
                this._dialogSubmission = null;
                this.overlayEl = null;
                this.surfaceEl = null;
                this._overlayHost = null;
                if (this.plugin?._currentFileOperationOverlay === this) {
                    this.plugin._currentFileOperationOverlay = null;
                }
            }
        });
        const overlay = this._overlayHost.open();
        this.overlayEl = overlay;

        if (this.kind === "delete") this._renderDelete(current);
        else this._renderMove(current);
        this.plugin._hoverHintObserver?.observeRoot(overlay);
        return this;
    }

    _createCloseButton(surface) {
        return this._overlayHost?.createCloseButton(surface, { positioned: true });
    }

    _renderMove(current) {
        const surface = this.overlayEl.createDiv({
            cls: "local-search-dropdown local-search-move-dropdown local-search-picker-dropdown local-search-centered-picker-surface local-search-command-shared-picker"
        });
        this.surfaceEl = surface;
        surface.createDiv({
            cls: "local-search-dropdown-title",
            text: `移动「${current.basename || current.name}」`
        });
        this._createCloseButton(surface);

        const expanded = new Set(sharedFolderAncestors(current.parent?.path || ""));
        const countInFolder = createSharedFolderCountProvider(
            Array.from(this.plugin.fileMetaCache.values())
        );
        renderSharedFolderTreePicker({
            app: this.app,
            plugin: this.plugin,
            panel: surface,
            expanded,
            selectedPath: current.parent?.path || "",
            rootPath: "",
            badgeFor: countInFolder,
            autoLocate: true,
            onChoose: async path => {
                if (this._picked || this._closed) return;
                this._picked = true;
                const latest = this.app.vault.getAbstractFileByPath(this.file.path);
                if (!(latest instanceof TFile)) {
                    new Notice("当前文件已不存在");
                    this.close();
                    return;
                }
                const result = await this.plugin.fileOperations.moveFiles([latest], path);
                if (result.failed.length) new Notice("文件移动失败");
                this.close();
            }
        });
    }

    _renderDelete(current) {
        const host = this.overlayEl.createDiv({ cls: "local-search-command-shared-confirm-host" });
        this.surfaceEl = host;
        const surface = createSharedDialogSurface(host, {
            title: "删除文件",
            message: `你确定要删除 “${current.basename || current.name}” 吗？`,
            detail: "将按照 Obsidian 当前删除设置处理。",
            confirmText: "删除",
            danger: true,
            closeable: true,
            optionLabel: "不再询问",
            onFinish: (confirmed, controls) => {
                if (!confirmed) { this.close(); return; }
                if (this._closed || this._dialogSubmission?.busy) return;
                void this._dialogSubmission?.submit(async () => {
                    if (controls.optionInput?.checked) {
                        this.plugin.settings.confirmBeforeDelete = false;
                        await this.plugin.saveSettings();
                    }
                    const latest = this.app.vault.getAbstractFileByPath(this.file.path);
                    if (!(latest instanceof TFile)) throw new Error("当前文件已不存在");
                    const result = await this.plugin.fileOperations.deleteFiles([latest]);
                    if (result.failed.length) throw new Error("文件删除失败");
                }, [controls.cancelButton, controls.confirmButton, controls.optionInput, controls.closeButton]
                    .filter(Boolean), "文件删除失败");
            }
        });
        surface.dialog.addClass("local-search-command-shared-confirm", "local-search-file-delete-dialog", "local-search-file-operation-dialog");
        this._dialogSubmission = createDialogSubmission(surface.dialog,
            () => !this._closed && surface.dialog.isConnected,
            () => this.close(),
            (error, fallback) => new Notice(error?.message || fallback));
        surface.cancelButton.focus({ preventScroll: true });
    }

    close() {
        if (this._closed) return;
        if (this._overlayHost?.close() === false) return false;
        this._closed = true;
        this.overlayEl = null;
        this.surfaceEl = null;
        this._overlayHost = null;
        if (this.plugin?._currentFileOperationOverlay === this) {
            this.plugin._currentFileOperationOverlay = null;
        }
    }
}

// Shared UI primitive, bundled identically for independent plugin loading.
// One observer per document; leases own only the real UI roots they register.
// BEGIN SHARED HOVER HINTS — generated from shared/hover-hints.js
// One document observer shared by independent plugin leases.
// Preserve accessible names while removing hover hints from owned desktop UI.
export function supportsPluginFineHover(root = null) {
    const win = root?.ownerDocument?.defaultView || globalThis.window;
    const query = win?.matchMedia?.("(hover: hover) and (pointer: fine)");
    return query ? query.matches : !(globalThis.navigator?.maxTouchPoints > 0);
}

export function installPluginHoverHintSuppression() {
    const key = Symbol.for("gls-dida-pwb.hover-hints.v1");
    let owner = globalThis[key];
    if (!owner) {
        const documents = new Map(), labels = new WeakMap();
        let sequence = 0;
        const element = node => node?.nodeType === 1;
        const suppress = node => {
            if (!element(node)) return;
            for (const name of ["title", "data-tooltip-position", "data-tooltip-delay"])
                if (node.hasAttribute(name)) node.removeAttribute(name);
            const incoming = node.getAttribute("aria-label");
            let saved = labels.get(node);
            const labelledBy = node.getAttribute("aria-labelledby");
            if (labelledBy && labelledBy !== saved?.id) {
                if (incoming !== null) node.removeAttribute("aria-label");
                return;
            }
            if (incoming) {
                if (!saved) { saved = { id: `plugin-ui-label-${++sequence}`, text: incoming }; labels.set(node, saved); }
                else saved.text = incoming;
            }
            if (!saved) return;
            const host = /^(INPUT|TEXTAREA|SELECT)$/.test(node.tagName) ? node.parentElement : node;
            if (!host) return;
            let label = saved.node;
            if (!label || !host.contains(label)) {
                label = node.ownerDocument.createElement("span");
                label.id = saved.id;
                label.hidden = true;
                saved.node = label;
                host.appendChild(label);
            }
            if (label.textContent !== saved.text) label.textContent = saved.text;
            if (labelledBy !== saved.id) node.setAttribute("aria-labelledby", saved.id);
            if (incoming !== null) node.removeAttribute("aria-label");
        };
        const scan = root => {
            if (!element(root)) return;
            suppress(root);
            root.querySelectorAll("[title], [aria-label], [data-tooltip-position], [data-tooltip-delay]").forEach(suppress);
        };
        const options = { subtree: true, childList: true, attributes: true,
            attributeFilter: ["title", "aria-label", "aria-labelledby", "data-tooltip-position", "data-tooltip-delay"] };
        owner = {
            observe(root) {
                if (!element(root)) return false;
                const doc = root.ownerDocument, win = doc.defaultView;
                if (!win?.MutationObserver || !supportsPluginFineHover(root)) return false;
                let record = documents.get(doc);
                if (!record) {
                    const roots = new Map();
                    const owns = node => {
                        for (const root of roots.keys())
                            if (root === node || root.contains(node)) return true;
                        return false;
                    };
                    const process = records => {
                        for (const change of records) {
                            // Removed/virtualized rows are no longer owned UI.
                            if (!owns(change.target)) continue;
                            suppress(change.target);
                            if (change.type === "childList") for (const node of change.addedNodes)
                                if (change.target.contains(node)) scan(node);
                        }
                    };
                    const observer = new win.MutationObserver(process);
                    record = { roots, observer, process };
                    documents.set(doc, record);
                }
                const count = record.roots.get(root) || 0;
                record.roots.set(root, count + 1);
                if (!count) { scan(root); record.observer.observe(root, options); }
                return true;
            },
            forget(root) {
                const doc = root?.ownerDocument, record = documents.get(doc);
                const count = record?.roots.get(root) || 0;
                if (!count) return;
                if (count > 1) { record.roots.set(root, count - 1); return; }
                record.roots.delete(root);
                // Drain pending changes for surviving roots before reconnecting.
                // Closing one surface must not rescan all other open surfaces.
                record.process(record.observer.takeRecords());
                record.observer.disconnect();
                if (!record.roots.size) documents.delete(doc);
                else for (const active of record.roots.keys()) record.observer.observe(active, options);
            },
        };
        globalThis[key] = owner;
    }
    const roots = new Set();
    return {
        observeRoot(root) { if (!roots.has(root) && owner.observe(root)) roots.add(root); },
        forgetRoot(root) { if (roots.delete(root)) owner.forget(root); },
        disconnect() { for (const root of roots) owner.forget(root); roots.clear(); },
    };
}

// END SHARED HOVER HINTS

// BEGIN SHARED DRAG FEEDBACK — generated from shared/drag-feedback.js
// Feedback only. Gesture ownership, drop validation and persistence stay with the sorter.
// One DOM allocation per drag; no listeners, timers, copied row DOM or business state.
export class SortFeedback {
    constructor(source) {
        this.source = source;
        this.doc = source.ownerDocument;
        this.root = this.doc.createElement("div");
        this.root.className = "ui-sort-feedback";
        this.root.dataset.uiSortOwner = "ls";
        this.root.setAttribute("aria-hidden", "true");
        this.line = this.doc.createElement("div");
        this.line.className = "ui-sort-feedback-line";
        this.target = this.doc.createElement("div");
        this.target.className = "ui-sort-feedback-target";
        this.badge = this.doc.createElement("div");
        this.badge.className = "ui-sort-feedback-badge";
        this.nameEl = this.doc.createElement("span");
        this.nameEl.className = "ui-sort-feedback-name";
        this.actionEl = this.doc.createElement("span");
        this.actionEl.className = "ui-sort-feedback-action";
        this.badge.append(this.nameEl, this.actionEl);
        this.root.append(this.line, this.target, this.badge);
        this.doc.body.append(this.root);
        const title = source.querySelector(".pwb-module-label,.pwb-project-name,.pwb-action-editor-name,.pwb-project-layout-label,.dida-bridge-view-label,.dida-bridge-view-row-main,.dida-bridge-view-section-toggle,.dida-bridge-picker-tree-label,.local-search-view-label,.local-search-view-row-main,.local-search-view-section-toggle,.local-search-row-label");
        this.name = (source.dataset.sortName || title?.textContent || source.textContent || "排序项").trim().replace(/\s+/g, " ");
        this.nameEl.textContent = this.name;
    }

    show({ bounds, clip = bounds, y = null, pointerY, label, target = null }) {
        if (!this.source?.isConnected || !this.root?.isConnected) return;
        const win = this.doc.defaultView;
        const viewport = win.visualViewport;
        const top = viewport?.offsetTop || 0;
        const left = viewport?.offsetLeft || 0;
        const width = viewport?.width || win.innerWidth;
        const height = viewport?.height || win.innerHeight;
        const x = Math.max(left, bounds.left, clip.left);
        const right = Math.min(left + width, bounds.right, clip.right);
        const upper = Math.max(top, clip.top), lower = Math.min(top + height, clip.bottom);
        const set = (name, value) => this.root.style.setProperty(name, `${Math.round(value)}px`);
        set("--ui-sort-left", x); set("--ui-sort-width", Math.max(0, right - x));
        set("--ui-sort-pointer-y", pointerY);
        set("--ui-sort-viewport-top", top); set("--ui-sort-viewport-bottom", top + height);
        this.line.hidden = y === null || y < upper || y > lower || right <= x;
        if (!this.line.hidden) set("--ui-sort-line-y", y);
        this.target.hidden = !target;
        if (target) {
            set("--ui-sort-target-top", Math.max(upper, target.top));
            set("--ui-sort-target-height", Math.max(0, Math.min(lower, target.bottom) - Math.max(upper, target.top)));
        }
        if (this.actionEl.textContent !== label) this.actionEl.textContent = label;
    }

    destroy() {
        this.root?.remove();
        this.root = this.source = this.doc = this.line = this.target = this.badge = this.nameEl = this.actionEl = null;
    }
}
